extern "C" void SetConvolutionKernel(float *h_KernelRow,float *h_KernelCol,int Kernel_Length)
{
    cudaMemcpyToSymbol(Cuda2DFilterRow, h_KernelRow, Kernel_Length * sizeof(float));
    cudaMemcpyToSymbol(Cuda2DFilterCol, h_KernelCol, Kernel_Length * sizeof(float));
}

//------------------------------------------------------------------------------//
//Round a / b to nearest higher integer value
int iDivUp(int a, int b){
    return (a % b != 0) ? (a / b + 1) : (a / b);
}
//------------------------------------------------------------------------------//
__device__ short CalcArctangent(int y, int x)//Kai-20161015
{
	int idx = (y + 512) * 1024 + (x + 512);
	if (idx < atan_table_size)
	{
		return atan_table[idx];
	}
	return 0;
}
