__global__ void DoCudaSolvePhaseKernel(unsigned char *ImgD1, unsigned char *ImgD2, unsigned char *ImgD3, unsigned char *ImgD4, unsigned char *pMergeD, short *pPhaseD, unsigned char *pMaskD, unsigned int ImageSize, unsigned char SaturationValue, unsigned char LowContrastValue, unsigned char PotentialValue, bool IsUsePotentialValue)
{
	unsigned int i=0;
//    const int tid = threadIdx.x;
//    const int bid = blockIdx.x;
	
	short d1=0, d2=0, d3=0, d4=0;
	short a=0, b=0;
	float phase=0;

//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	

	//ImageSize = 171000
    for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += /*16 * 96*/blockDim.x*gridDim.x) 
 //   for(i = bid * 96 + tid; i < ImageSize; i += /*16 * 96*/1536) 
	{
		
		d1 = ImgD1[i];
		d2 = ImgD2[i];
		d3 = ImgD3[i]; 
		d4 = ImgD4[i];

		pMergeD[i] = (d1+d2+d3+d4)>>2;
		a=d4-d2;
		b=d1-d3;
		
		if( IsUsePotentialValue == true )
		{
			if( (abs(a)+abs(b)) < PotentialValue )
			{ pMaskD[i] = PHASE_MASK_LOW_POTENTIAL; }
			else
			{ pMaskD[i] = PHASE_MASK_VALID; }
		}
		else	
		{
			if( d1>SaturationValue || d2>SaturationValue || d3>SaturationValue || d4>SaturationValue  )	//過飽合
			{
				pMaskD[i] = PHASE_MASK_OVER_SATURATED;		//標記無效點
			}	
			else if(abs(d1-d3)<LowContrastValue && abs(d2-d4)<LowContrastValue)			//對比不足
			{
				pMaskD[i] = PHASE_MASK_LOW_CONTRAST;		//標記無效點
			}
			else
			{ pMaskD[i] = PHASE_MASK_VALID; }
		}

		phase = atan2f((float)a, (float)b);
		if( phase < 0 )
		{ phase = PERIOD_RAD+phase; }

		pPhaseD[i] = phase * PHASE_RAD2SHORT;
	}
}
