__global__ void DoCudaSolvePhase_Three_Kernel(unsigned char *ImgD1, unsigned char *ImgD2, unsigned char *ImgD3, unsigned char *pMergeD, short *pPhaseD, unsigned char *pMaskD,const unsigned int ImageSize, unsigned char SaturationValue, unsigned char LowContrastValue, unsigned char PotentialValue, bool IsUsePotentialValue)
{
	unsigned int i=0;
	short d1=0, d2=0, d3=0;
	short a=0, b=0;
	float phase=0;
//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	

    for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{
		d1 = ImgD1[i];
		d2 = ImgD2[i];
		d3 = ImgD3[i]; 

		pMergeD[i] = (d1+d3)>>1;
		a=d3-d2;
		b=d1-d2;
		
		if( IsUsePotentialValue == true )
		{
			if( (abs(a)+abs(b)) < PotentialValue )
			{ pMaskD[i] = PHASE_MASK_LOW_POTENTIAL; }
			else
			{ pMaskD[i] = PHASE_MASK_VALID; }
		}
		else	
		{
			if( d1>SaturationValue || d2>SaturationValue || d3>SaturationValue )	//過飽合
			{
				pMaskD[i] = PHASE_MASK_OVER_SATURATED;		//標記無效點
			}
			else if(abs(d1-d2)<LowContrastValue && abs(d3-d2)<LowContrastValue)	//對比不足
			{
				pMaskD[i] = PHASE_MASK_LOW_CONTRAST;		//標記無效點
			}
			else
			{ pMaskD[i] = PHASE_MASK_VALID; }
		}

		phase = atan2f(a, b);
		if( phase < 0 )
		{ phase = PERIOD_RAD+phase; }
		pPhaseD[i] = phase * PHASE_RAD2SHORT;
	}
}
