//------------------------------------------------------------------------------//
__global__ void DoCudaSolvePhaseAndBasePhase_Four_Kernel2(unsigned char *ImgD1, unsigned char *ImgD2, unsigned char *ImgD3, unsigned char *ImgD4, unsigned char *pMergeD, short *pPhaseD, unsigned char *pMaskD, short *pBasePhaseD, const unsigned int ImageSize, unsigned char SaturationValue, unsigned char LowContrastValue, unsigned char PotentialValue, bool IsUsePotentialValue)
{
	short d1=0, d2=0, d3=0, d4=0;
	short a=0, b=0;
	float phase=0;
	short PhaseData=0;

//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	

  
	unsigned int index = (blockIdx.x*blockDim.x)+threadIdx.x;
	if( index < ImageSize  )
	{
		d1 = ImgD1[index];
		d2 = ImgD2[index];
		d3 = ImgD3[index]; 
		d4 = ImgD4[index];
		pMergeD[index] = (d1+d2+d3+d4)>>2;
		a=d4-d2;
		b=d1-d3;
		
		if( IsUsePotentialValue == true )
		{
			if( (abs(a)+abs(b)) < PotentialValue )
			{ pMaskD[index] = PHASE_MASK_LOW_POTENTIAL; }
			else
			{ pMaskD[index] = PHASE_MASK_VALID; }
		}
		else	
		{
			if( d1>SaturationValue || d2>SaturationValue || d3>SaturationValue || d4>SaturationValue  )	//過飽合
			{
				pMaskD[index] = PHASE_MASK_OVER_SATURATED;		//標記無效點
			}	
			else if(abs(d1-d3)<LowContrastValue && abs(d2-d4)<LowContrastValue)			//對比不足
			{
				pMaskD[index] = PHASE_MASK_LOW_CONTRAST;		//標記無效點
			}
			else
			{ pMaskD[index] = PHASE_MASK_VALID; }
		}
				
		phase = atan2f((float)a, (float)b);
		if( phase < 0 )
		{ phase = PERIOD_RAD+phase; }		
		
		PhaseData= (phase * PHASE_RAD2SHORT) - pBasePhaseD[index];
		if( PhaseData < 0 )
		{		
			pPhaseD[index] = PHASE_MAX + PhaseData;
		}
		else
		{
			pPhaseD[index] = PhaseData;
		}
	}
	
}
//------------------------------------------------------------------------------//
__global__ void DoCudaSolvePhase_Four_Kernel2(unsigned char *ImgD1, unsigned char *ImgD2, unsigned char *ImgD3, unsigned char *ImgD4, unsigned char *pMergeD, short *pPhaseD, unsigned char *pMaskD, const unsigned int ImageSize, unsigned char SaturationValue, unsigned char LowContrastValue, unsigned char PotentialValue, bool IsUsePotentialValue)
{
	short d1=0, d2=0, d3=0, d4=0;
	float phase=0;
//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	

	unsigned int i = (blockIdx.x*blockDim.x)+threadIdx.x;
	if( i < ImageSize )
	{
		d1 = ImgD1[i];
		d2 = ImgD2[i];
		d3 = ImgD3[i]; 
		d4 = ImgD4[i];

		pMergeD[i] = (d1+d2+d3+d4)>>2;
		
		if( IsUsePotentialValue == true )
		{
			if( (abs(d1-d3)+abs(d4-d2)) < PotentialValue )
			{ pMaskD[i] = PHASE_MASK_LOW_POTENTIAL; }
			else
			{ pMaskD[i] = PHASE_MASK_VALID; }
		}
		else	
		{
			if( d1>SaturationValue || d2>SaturationValue || d3>SaturationValue || d4>SaturationValue  )	//過飽合
			{
				pMaskD[i] = PHASE_MASK_OVER_SATURATED;		//標記無效點
			}	
			else if(abs(d1-d3)<LowContrastValue && abs(d2-d4)<LowContrastValue)			//對比不足
			{
				pMaskD[i] = PHASE_MASK_LOW_CONTRAST;		//標記無效點
			}
			else
			{ pMaskD[i] = PHASE_MASK_VALID; }
		}

		d4=d4-d2;
		d1=d1-d3;
		phase = atan2f((float)d4, (float)d1);
		if( phase < 0 )
		{ phase = PERIOD_RAD+phase; }

		pPhaseD[i] = phase * PHASE_RAD2SHORT;
	}
}
//------------------------------------------------------------------------------//
__global__ void DoCudaSolveMultiPhase_Kernel2(double TempRatio, short *pPhaseData1, unsigned char *pMaskMap1, short *pPhaseData2, unsigned char *pMaskMap2, const unsigned int ImageSize)
{	
    //__shared__ short block[GPU_BLOCK_SIZE];
    //__shared__ unsigned char ShareMask[GPU_BLOCK_SIZE];
	
	//計算結果回存到Phase1, Mask1

  	unsigned int index = (blockIdx.x*blockDim.x)+threadIdx.x;

	if( index < ImageSize )
	{
		double TempF=0, TempF1=0, TempF2=0, TempMulti=0;	
		double Phase=0, Phase1=0, Phase2=0;

		TempF1 = pPhaseData1[index]*PHASE_SHORT2ONE;
		TempF2 = pPhaseData2[index]*PHASE_SHORT2ONE;
		TempMulti = TempF1 - TempF2;		
		if( TempF2 > TempF1 ) { TempMulti += 1.0; }

		Phase = TempMulti*TempRatio;
		Phase2 = Phase-0.5;
		if( Phase2<0 )
		{ 
			Phase2=Phase2+1; 
		}

		//if( UsePhase1 == true )
		//{ Phase1 = (int)(TempMulti*TempRatio+100.0f)-100+TempF1; }
		//else
		//{ Phase1 = (int)(TempMulti*TempRatio+100.0f)-100+TempF2; }
		
		 Phase1 = (int)(TempMulti*TempRatio+100.0f)-100+TempF1; 
						
	//狀況1. 大於pi	
		if( fabs(Phase2-Phase1) >= 0.5 )
		{
			
			TempF = (Phase1-1);	
			if( TempF < 0 ) { TempF=TempF+1; }	
		}
		else
		{
		// 正常	
			TempF = (Phase1);
		}

	//結果回存到Phase1, Mask1
		pPhaseData1[index] = TempF/TempRatio;

		if( (pMaskMap1[index]&PHASE_MASK_VALID) == 0 )
		{ //無效點
			//pMaskMap1[index] |= pMaskMap1[index]; 
		}
		else if( (pMaskMap2[index]&PHASE_MASK_VALID) == 0 ) 
		{  //無效點
			pMaskMap1[index] |= pMaskMap2[index]; 
		}
		else 
		{ 
			pMaskMap1[index] = PHASE_MASK_VALID; 
		}
	}
}
//------------------------------------------------------------------------------//
__global__ void DoCudaSolveMultiPhase_Smooth_Kernel2(short *pMultiPhase, unsigned char *pMultiMaskMap, short *pSmoothPhase, unsigned char *pSmoothMaskMap, const unsigned int ImageSize, const unsigned int W, const unsigned int H )
{
	//double r=0, r1=0, r2=0, r3=0, r4=0;
	double d1=0, d2=0, d3=0;
	//double FilterRange = 0.5
	double FilterRange = 0.3;
	
	
  	unsigned int Index1 = (blockIdx.x*blockDim.x)+threadIdx.x;
	unsigned int Index2=0, Index3=0;
	unsigned int x = Index1%W;
	unsigned int y = Index1/W;

	if( Index1 < ImageSize )
	{
		pSmoothPhase[Index1] = pMultiPhase[Index1];
		pSmoothMaskMap[Index1] = pMultiMaskMap[Index1];
	//左上 中 右下	
		if( x>0 && x<(W-1) && y>0 && y<(H-1) )
		{
			Index2 = Index1-W-1;
			Index3 = Index1+W+1;
			d1 = pMultiPhase[Index1];
			d2 = pMultiPhase[Index2];	
			d3 = pMultiPhase[Index3];
			if( (pMultiMaskMap[Index2]==PHASE_MASK_VALID) || (pMultiMaskMap[Index3]==PHASE_MASK_VALID) )
			{
				if( fabs(d1-d2+d1-d3) > FilterRange ) 
				{ 
					if( fabs(d1-d2) < fabs(d1-d3) )
					{ pSmoothPhase[Index1] = pMultiPhase[Index2]; }
					else
					{ pSmoothPhase[Index1] = pMultiPhase[Index3]; }
				}	
			}
		}

		//左  中  右
		if( x>0 && x<(W-1))
		{
			Index2 = Index1-1;
			Index3 = Index1+1;
			d1 = pMultiPhase[Index1];
			d2 = pMultiPhase[Index2];	
			d3 = pMultiPhase[Index3];
			if( (pMultiMaskMap[Index2]==PHASE_MASK_VALID) || (pMultiMaskMap[Index3]==PHASE_MASK_VALID) )
			{
				if( fabs(d1-d2+d1-d3) > FilterRange ) 
				{ 
					if( fabs(d1-d2) < fabs(d1-d3) )
					{ pSmoothPhase[Index1] = pMultiPhase[Index2]; }
					else
					{ pSmoothPhase[Index1] = pMultiPhase[Index3]; }
				}	
			}
		}

		//上  中  下
		if( y>0 && y<(H-1))
		{
			Index2 = Index1-W;
			Index3 = Index1+W;
			d1 = pMultiPhase[Index1];
			d2 = pMultiPhase[Index2];	
			d3 = pMultiPhase[Index3];
			if( (pMultiMaskMap[Index2]==PHASE_MASK_VALID) || (pMultiMaskMap[Index3]==PHASE_MASK_VALID) )
			{
				if( fabs(d1-d2+d1-d3) > FilterRange ) 
				{ 
					if( fabs(d1-d2) < fabs(d1-d3) )
					{ pSmoothPhase[Index1] = pMultiPhase[Index2]; }
					else
					{ pSmoothPhase[Index1] = pMultiPhase[Index3]; }
				}	
			}
		}
	}
}
