__device__ bool GetCudaUseNewContrast_Kernel()//20190530
{
	return true;
}
//------------------------------------------------------------------------------//
__device__ int  CalcCudaGamma_Kernel(int Gray, float Gamma)//計算像素Gamma結果
{
	float v=Gray/255.0f;
	v=pow(v, Gamma)*255.0f;
	return (int)(v+0.5f);
}
//------------------------------------------------------------------------------//
__device__ bool DeductBasePhase_Kernel(int BasePhase, int &Phase)//扣除相平面
{
	const int Period = PHASE_MAX;//PHASE_MAX, PHASE_PERIOD
	Phase -= BasePhase;//注意若使用unsigned short則需要更大的整數來使用, 避免溢位			
	if ( Phase < 0 ) 
	{	Phase += Period; }
	else if ( Phase > Period ) 
	{	Phase -= Period; }	
	return true;
}
//------------------------------------------------------------------------------//
__device__ unsigned int CudaPow_Kernel(int Base, int Order)//計算指數
{
	int i=0;
	unsigned int uval=1;
	unsigned int uBase=Base;
	for ( i=1; i<=Order; i++ )
	{	uval *= uBase;	}
	return uval;
}
//------------------------------------------------------------------------------//
__device__ unsigned int CudaGrayCodetoDecimal_Kernel(unsigned int x)//GrayCode轉10進位//Kai-20210217
{
	unsigned int y = x;
	while ( x>>=1 )
	{	y ^= x;	};
	return y;
}
//------------------------------------------------------------------------------//
__device__ bool  BuildCudaGrayCodeMapTable_Kernel(int Order, int List[], int size)//取得GrayCode的映射表//Kai-20210217
{
	if ( Order < 1 ) 
	{	return false;	}

	unsigned int Value=0;
	unsigned int GrayCode=0;
	const size_t Count=(size_t)(CudaPow_Kernel(2, Order));	
	//const size_t Count=(size_t)(pow(double(2), (double)(Order)));	
	if ( Count > size )
	{	return false;	}

	for ( int i=0; i<Count; i++ )
	{
		Value = CudaGrayCodetoDecimal_Kernel(GrayCode);		
		List[GrayCode] = Value;
		GrayCode ++;
	}
	return true;	
}
//------------------------------------------------------------------------------//
__device__ bool  BuildCudaGrayCodeMapTable_Kernel(int Order, unsigned char List[], int size)//取得GrayCode的映射表//Kai-20210217
{
	if ( Order < 1 ) 
	{	return false;	}

	unsigned int Value=0;
	unsigned int GrayCode=0;
	const size_t Count=(size_t)(CudaPow_Kernel(2, Order));	
	//const size_t Count=(size_t)(pow(double(2), (double)(Order)));	
	if ( Count > size )
	{	return false;	}
	for ( int i=0; i<Count; i++ )
	{
		Value = CudaGrayCodetoDecimal_Kernel(GrayCode);
		if ( Value > 0xFF ) 
		{	return false;	}
		List[GrayCode] = Value;
		GrayCode ++;
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool ConvertPhaseToSpace_Kernel(int CvtMode, int Phase, float k1, float k2, float &Space)//相位轉成高度值
{
	if ( PHASE_CONVERT_HEIGHT_SCALE != CvtMode ) { return true; }
	float space=0.0f;	
	if ( 0.0f != k1 )
	{	space += (Phase*k1);	}
	if ( 0.0f != k2 ) 
	{	space += (Phase*Phase*k2); }	
	Space = (SPACE_DATA)(space/PHASE_HEIGHT_FACTOR_SCALE);
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool ConvertSpaceToPhase_Kernel(int CvtMode, float Space, float k1, float k2, int &Phase)//高度轉成相位值
{
	if ( PHASE_CONVERT_HEIGHT_SCALE != CvtMode ) { return true; }
	float phase=0.0f;	
	float space=Space;
	space = space*PHASE_HEIGHT_FACTOR_SCALE;	
	if ( 0.0f != k1 )
	{	phase = (space/k1);	}
	//if ( 0.0f != k2 ) 
	//{	space += (Phase*Phase*k2); }
	Phase = (int)(phase);
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool ConvertPhaseToSpaceMapFunc_Kernel(int CvtMode, double X, double Y, int Phase, const double* T0, const double* T1, const double* T2, float &Space)//相位轉成高度值
{	
	if ( PHASE_CONVERT_HEIGHT_SCALE == CvtMode ) { return true; }
	//求得對應XY的a值
	double a[4]={0};
	switch ( CvtMode )
	{	
	case PHASE_CONVERT_HEIGHT_MAPPING_FUNC_7://3階, a0+a1X+a2Y+a3XX+a4YY+a5XXX+a6YYY
	{
		double XX=X*X;
		double XXX=XX*X;
		double YY=Y*Y;
		double YYY=YY*Y;
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(XX*T0[3])+(YY*T0[4])+(XXX*T0[5])+(YYY*T0[6]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(XX*T1[3])+(YY*T1[4])+(XXX*T1[5])+(YYY*T1[6]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(XX*T2[3])+(YY*T2[4])+(XXX*T2[5])+(YYY*T2[6]);
	}
		break;
	case PHASE_CONVERT_HEIGHT_MAPPING_FUNC_6://2階, a0+a1X+a2Y+a3XY+a4XX+a5YY
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(X*Y*T0[3])+(X*X*T0[4])+(Y*Y*T0[5]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(X*Y*T1[3])+(X*X*T1[4])+(Y*Y*T1[5]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(X*Y*T2[3])+(X*X*T2[4])+(Y*Y*T2[5]);
		break;
	case PHASE_CONVERT_HEIGHT_MAPPING_FUNC_5://2階, a0+a1X+a2Y+a3XX+a4YY
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(X*X*T0[3])+(Y*Y*T0[4]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(X*X*T1[3])+(Y*Y*T1[4]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(X*X*T2[3])+(Y*Y*T2[4]);
		break;
	case PHASE_CONVERT_HEIGHT_MAPPING_FUNC_4://2階, a0+a1X+a2Y+a3XY
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(X*Y*T0[3]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(X*Y*T1[3]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(X*Y*T2[3]);
		break;
	case PHASE_CONVERT_HEIGHT_MAPPING_FUNC_3://2階, a0+a1X+a2Y
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2]);
		break;
	default:
		break;		
	}
	//Height;
	a[3] = a[0]+(Phase*a[1])+(Phase*Phase*a[2]);
	Space = (float)(a[3]);
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool  ConvertSpaceToPhaseMapFunc_Kernel(int CvtMode, double X, double Y, float Space, const double* T0, const double* T1, const double* T2, int &Phase)//高度轉成相位值
{	
	if ( PHASE_CONVERT_HEIGHT_SCALE == CvtMode ) { return true; }
	//求得對應XY的a值
	double a[4]={0};
	switch ( CvtMode )
	{	
	case 7://3階, a0+a1X+a2Y+a3XX+a4YY+a5XXX+a6YYY
	{
		double XX=X*X;
		double XXX=XX*X;
		double YY=Y*Y;
		double YYY=YY*Y;
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(XX*T0[3])+(YY*T0[4])+(XXX*T0[5])+(YYY*T0[6]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(XX*T1[3])+(YY*T1[4])+(XXX*T1[5])+(YYY*T1[6]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(XX*T2[3])+(YY*T2[4])+(XXX*T2[5])+(YYY*T2[6]);
	}
		break;
	case 6://2階, a0+a1X+a2Y+a3XY+a4XX+a5YY
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(X*Y*T0[3])+(X*X*T0[4])+(Y*Y*T0[5]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(X*Y*T1[3])+(X*X*T1[4])+(Y*Y*T1[5]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(X*Y*T2[3])+(X*X*T2[4])+(Y*Y*T2[5]);
		break;
	case 5://2階, a0+a1X+a2Y+a3XX+a4YY
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(X*X*T0[3])+(Y*Y*T0[4]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(X*X*T1[3])+(Y*Y*T1[4]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(X*X*T2[3])+(Y*Y*T2[4]);
		break;
	case 4://2階, a0+a1X+a2Y+a3XY
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2])+(X*Y*T0[3]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2])+(X*Y*T1[3]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2])+(X*Y*T2[3]);
		break;
	case 3://2階, a0+a1X+a2Y
		a[0] = T0[0]+(X*T0[1])+(Y*T0[2]);
		a[1] = T1[0]+(X*T1[1])+(Y*T1[2]);
		a[2] = T2[0]+(X*T2[1])+(Y*T2[2]);
		break;
	default:
		break;
	}
	//ax^2 + bx + c = 0, x=(-b+sqrt(D))/2a, D=b*b-4ac
	double A =  a[2];
	double B =  a[1];
	double C =  a[0]-Space;
	double D =  (B*B)-(4*A*C);
	double phase = (sqrt(D)-B)/(2*A);	
	Phase = (int)(phase);
	return true;
}
//------------------------------------------------------------------------------//
__device__ float GetPhaseNoiseMinB_Kernel(int val)//取得相位雜訊定義MinB
{
	return val*0.1f;
}
//------------------------------------------------------------------------------//
__device__ float GetPhaseNoiseMinCV_Kernel(int val)//取得相位雜訊定義MinCV
{
	return val*0.01f;
}
//------------------------------------------------------------------------------//
__device__ float GetPhaseNoiseMinB_Kernel(const TPhaseNoiseParam &NoiseParam)//取得相位雜訊定義MinB
{
	return GetPhaseNoiseMinB_Kernel(NoiseParam.PhaseLowPotentialA);
}
//------------------------------------------------------------------------------//
__device__ float GetPhaseNoiseMinCV_Kernel(const TPhaseNoiseParam &NoiseParam)//取得相位雜訊定義MinCV
{
	return GetPhaseNoiseMinCV_Kernel(NoiseParam.PhaseLowContrastA);
}
//------------------------------------------------------------------------------//
__device__ bool CalcCudaArctangent_Kernel(int a, int b, int &Phase)//計算反三角
{
	float Res = atan2f(a, b);
	if( Res < 0 )
	{	Res = PERIOD_RAD+Res; }	
	Phase = (int)((Res*PHASE_RAD2SHORT));
	return true;
}
