__device__ int  CheckCudaSpaceMaskValid_Kernel(unsigned char Mask)//確認是否為有效值
{
	if ( PHASE_MASK_VALID == Mask ) { return true; }
	if ( PHASE_MASK_VALID_BEST == Mask) { return true; }
	return false;
}
