	if ( PHASE_MASK_VALID_BEST == Mask) { return true; }
	return false;
}
//------------------------------------------------------------------------------//
__device__ int  CalcCudaPhaseContrast_Kernel(int a, int b, int c)
{
	if ( 0 == c ) { return 0; }
	return (int)(50*(abs(a)+abs(b))/sqrt((float)c));//20190529
	//return (int)(100*(abs(a)+abs(b))/c);	
}
//------------------------------------------------------------------------------//
__device__ int  CalcCuda3PhaseContrast_Kernel(int P1, int P2, int P3)//計算相位對比
{	//Test 尚未確認
	float Ave=(P1+P3)/2.0f;
	float Im=P3-P2;
	float Re=P1-P2;
	float Contrast=0.0f;
	if ( Ave != 0.0f )
	{	Contrast = (float)(100.0*(fabs(Im)+fabs(Re))/Ave);	}
	return Contrast;
}
//------------------------------------------------------------------------------//
__device__ int  CalcCuda21PhaseContrast_Kernel(int P1, int P2, int P3)//計算相位對比
{
	float Ave=P2;
	float Im=P3-P2;
	float Re=P1-P2;
	float Contrast=0.0f;
	if ( Ave != 0.0f )
	{	Contrast = (float)(100.0*(fabs(Im)+fabs(Re))/Ave);	}
	return Contrast;
}
//------------------------------------------------------------------------------//
__device__ int  CalcCuda4PhaseContrast_Kernel(int P1, int P2, int P3, int P4)//計算相位對比
{
	float Ave=(P1+P2+P3+P4)/2.0f;
	float Im=P4-P2;
	float Re=P1-P3;
	float Contrast=0.0f;
	if ( Ave != 0.0f )
	{	Contrast = (float)(100.0*(fabs(Im)+fabs(Re))/Ave);	}
	return Contrast;
}
//------------------------------------------------------------------------------//
__device__ int  CalcCuda3PhasePotential_Kernel(int P1, int P2, int P3)//計算相位潛能
{
	return (abs(P3-P2)+abs(P1-P2));	
}
//------------------------------------------------------------------------------//
__device__ int  CalcCuda21PhasePotential_Kernel(int P1, int P2, int P3)//計算相位潛能
{
	return 2*(abs(P3-P2)+abs(P1-P2));	
}
//------------------------------------------------------------------------------//
__device__ int  CalcCuda4PhasePotential_Kernel(int P1, int P2, int P3, int P4)
{
	return (abs(P1-P3)+abs(P2-P4));
}
//------------------------------------------------------------------------------//
__device__ int  CalcCuda3PhaseSaturated_Kernel(int P1, int P2, int P3, int SatTh)//計算相位過飽和
{
	int OverSaturatedCnt = 0;
	if ( P1>SatTh ) { OverSaturatedCnt++; }
	if ( P2>SatTh ) { OverSaturatedCnt++; }
	if ( P3>SatTh ) { OverSaturatedCnt++; }	
	return OverSaturatedCnt;
}
//------------------------------------------------------------------------------//
__device__ bool CheckCuda3PhaseSaturated_Kernel(int P1, int P2, int P3, int SatTh)//確認相位過飽和
{
	int OverSaturatedCnt = 0;
	if ( P1>SatTh ) { OverSaturatedCnt++; }
