__device__ bool CheckCuda4PhaseSaturated_Kernel(int P1, int P2, int P3, int P4, int SatTh)//確認相位過飽和
{
	int OverSaturatedCnt = 0;
	if ( P1>SatTh ) { OverSaturatedCnt++; }
