//------------------------------------------------------------------------------//
__device__ bool CalcCuda4PhaseMeanContrastRatio_Kernel(int P1, int P2, int P3, int P4, float &A, float &B, float &CV)
{
	const float Dif13=P1-P3;
	const float Dif24=P2-P4;	
	const float Sum=(P1+P2+P3+P4);

	B=sqrtf((Dif13*Dif13)+(Dif24*Dif24))*0.5f;
	if ( Sum > 0.01 )
	{
		A = Sum/4.0f;
		CV = B/A;
	}
	else
	{	A = CV = 0.0f; }
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool CalcCuda3PhaseParam_kernel(int P1, int P2, int P3, int &a, int &b, int &c)
{
	a = P3-P2;//-256 ~ 256 => 512
	b = P1-P2;//-256 ~ 256 => 512
	c = (P1+P3)/2;
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool CalcCuda21PhaseParam_kernel(int P1, int P2, int P3, int &a, int &b, int &c)//2+1Step
{
	a = P3-P2;//-256 ~ 256 => 512
	b = P1-P2;//-256 ~ 256 => 512
	c = P2;
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool CalcCuda4PhaseParam_kernel(int P1, int P2, int P3, int P4, int &a, int &b, int &c)
{
	a = P4-P2;//-256 ~ 256 => 512
	b = P1-P3;//-256 ~ 256 => 512
	c = (P1+P2+P3+P4)>>2;//全部平均		
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool CalcCuda3PhaseParamMask_kernel(int P1, int P2, int P3, int NoiseMask, int LowContrast, int LowPotential, int OverSaturated, int &Phase, unsigned char &Mask)//3Step
{
	int         Contrast=0;
	int         a=0, b=0, c=0;
	const bool  bNewContrast=GetCudaUseNewContrast_Kernel();//20190530
	const BOOL  bCheckLowContrast   = (BOOL)(NoiseMask&PHASE_NOSIE_LOW_CONTRAST);
	Mask = PHASE_MASK_VALID;
	CalcCuda3PhaseParam_kernel(P1, P2, P3, a, b, c);
	if ( CalcCudaArctangent_Kernel(a, b, Phase) == false )
	{	return false; }
	if ( bCheckLowContrast )//對比不足
	{
		if ( PHASE_MASK_VALID == Mask )
		{	
			if ( false == bNewContrast )
			{	Contrast = CalcCudaPhaseContrast_Kernel(a, b, c); }
			else
			{	Contrast = CalcCuda3PhaseContrast_Kernel(P1, P2, P3); }
			if ( Contrast < LowContrast )
			{	
				Mask = PHASE_MASK_LOW_CONTRAST;	
				return true;
			}
		}
	}

	int         Potential=0;	
	const BOOL  bCheckLowPotential  = (BOOL)(NoiseMask&PHASE_NOSIE_LOW_POTENTIAL);	
	if ( bCheckLowPotential )//潛能過低
	{
		if ( PHASE_MASK_VALID == Mask )
		{
			Potential=CalcCuda3PhasePotential_Kernel(P1, P2, P3);
			if ( Potential < LowPotential)
			{	
				Mask = PHASE_MASK_LOW_POTENTIAL;	
				return true;
			}
		}	
	}

	const BOOL  bCheckOverSaturated = (BOOL)(NoiseMask&PHASE_NOSIE_OVER_SATURATED);	
	if ( bCheckOverSaturated )//過飽合
	{
		if ( PHASE_MASK_VALID == Mask )
		{
			if ( CheckCuda3PhaseSaturated_Kernel(P1, P2, P3, OverSaturated) == true )
			{	
				Mask = PHASE_MASK_OVER_SATURATED;	
				return true;
			}	
		}
	}
	return true;
}
