//------------------------------------------------------------------------------//
__device__ bool CalcCuda4PhaseParamMask_kernel_2(int P1, int P2, int P3, int P4, int NoiseMask, int LowContrast, int LowPotential, int OverSaturated, int &Phase, unsigned char &Mask)//4Step
{		
	int         a=0, b=0, c=0;		
	float       A=0, B=0, CV=0;		
	Mask = PHASE_MASK_VALID;
	CalcCuda4PhaseParam_kernel(P1, P2, P3, P4, a, b, c);
	if ( CalcCudaArctangent_Kernel(a, b, Phase) == false )
	{	return false; }

	if ( CalcCuda4PhaseMeanContrastRatio_Kernel(P1, P2, P3, P4, A, B, CV) == false )
	{	return false; }

	//LowContrast = 30;//0.3
	float       Contrast=0;
	const float fLowContrast=GetPhaseNoiseMinCV_Kernel(LowContrast);	
	const BOOL  bCheckLowContrast   = (BOOL)(NoiseMask&PHASE_NOSIE_LOW_CONTRAST);
	if ( bCheckLowContrast )//對比不足
	{
		if ( PHASE_MASK_VALID == Mask )
		{	
			Contrast = (float)(CV);
			if ( Contrast < fLowContrast )
			{	
				Mask = PHASE_MASK_LOW_CONTRAST;	
				return true;
			}
		}
	}

	//LowPotential= 20;//2
	float       Potential=0;
	const float fLowPotential=GetPhaseNoiseMinB_Kernel(LowPotential);
	const BOOL  bCheckLowPotential  = (BOOL)(NoiseMask&PHASE_NOSIE_LOW_POTENTIAL);	
	if ( bCheckLowPotential )//潛能過低
	{
		if ( PHASE_MASK_VALID == Mask )
		{
			Potential=(float)(B);
			if ( Potential < fLowPotential)
			{	
				Mask = PHASE_MASK_LOW_POTENTIAL;	
				return true;
			}
		}	
	}

	//OverSaturated = 250;
	const BOOL  bCheckOverSaturated = (BOOL)(NoiseMask&PHASE_NOSIE_OVER_SATURATED);	
	if ( bCheckOverSaturated )//過飽合
	{
		if ( PHASE_MASK_VALID == Mask )
		{
			if ( CheckCuda4PhaseSaturated_Kernel(P1, P2, P3, P4, OverSaturated) == true )
			{	
				Mask = PHASE_MASK_OVER_SATURATED;	
				return true;
			}	
		}
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool CalcCuda4PhaseParamMask_kernel(int P1, int P2, int P3, int P4, int NoiseMask, int LowContrast, int LowPotential, int OverSaturated, int &Phase, unsigned char &Mask, int Mode)//4Step
{
	if ( PHASE_NOISE_DEF_MODE_2 == Mode ) 
	{	return CalcCuda4PhaseParamMask_kernel_2(P1, P2, P3, P4, NoiseMask, LowContrast, LowPotential, OverSaturated, Phase, Mask);	}
	return CalcCuda4PhaseParamMask_kernel_1(P1, P2, P3, P4, NoiseMask, LowContrast, LowPotential, OverSaturated, Phase, Mask);
}
//------------------------------------------------------------------------------//
__device__ bool CalcCuda4GrayCodeParam_kernel_1(int P1, int P2, int P3, int P4, float Th, const unsigned char *Map1, const unsigned char *Map2, int &k1, int &k2)//4階GrayCode解碼
{
	int Code1 = 0;
	int Code2 = 0;
	const bool bGrayCodeInvert = false;//16G->32G->64G->128B
	if ( P1 > Th)
	{	Code2 |= 0x01;	}
	if ( P2 > Th)
	{
		Code1 |= 0x01;
		Code2 |= 0x02;
	}
	if ( P3 > Th)
	{
		Code1 |= 0x02;
		Code2 |= 0x04;
	}
	if ( P4 > Th)
	{
		Code1 |= 0x04;
		Code2 |= 0x08;
	}	
	k1 = Map1[Code1];
	k2 = Map2[Code2];
	k2 = (k2+1)/2;
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool CalcCuda4GrayCodeParam_kernel_2(int P1, int P2, int P3, int P4, float Th, const unsigned char *Map1, const unsigned char *Map2, int &k1, int &k2)//4階GrayCode解碼
{
	int PMax=P1;
	int PMin=P1;
	int Code1 = 0;
	int Code2 = 0;
	float Ratio=0.1;
	const float RatioPitch=0.5f/4.0f;
	const bool bGrayCodeInvert = false;//16G->32G->64G->128B
	if ( PMax < P2 ) { PMax=P2; }
	if ( PMin > P2 ) { PMin=P2; }
	if ( PMax < P3 ) { PMax=P3; }
	if ( PMin > P3 ) { PMin=P3; }
	if ( PMax < P4 ) { PMax=P4; }
	if ( PMin > P4 ) { PMin=P4; }	
	const float PAve=Th;
	const float PMid=(PMax+PMin)/2.0f;

	Ratio = RatioPitch;
	Th = (float)((PMid*Ratio)+(PAve*(1.0-Ratio)));
	if ( P1 > Th)
	{	Code2 |= 0x01;	}
	Ratio += RatioPitch;
	Th = (float)((PMid*Ratio)+(PAve*(1.0-Ratio)));
	if ( P2 > Th)
	{
		Code1 |= 0x01;
		Code2 |= 0x02;
	}
	Ratio += RatioPitch;
	Th = (float)((PMid*Ratio)+(PAve*(1.0-Ratio)));
	if ( P3 > Th)
	{
		Code1 |= 0x02;
		Code2 |= 0x04;
	}
	Ratio += RatioPitch;
	Th = (float)((PMid*Ratio)+(PAve*(1.0-Ratio)));
	if ( P4 > Th)
	{
		Code1 |= 0x04;
		Code2 |= 0x08;
	}	
	k1 = Map1[Code1];
	k2 = Map2[Code2];
	k2 = (k2+1)/2;
	return true;
}
