__device__ bool CalcCuda4GrayCodeParam_kernel(int P1, int P2, int P3, int P4, float Th, const unsigned char *Map1, const unsigned char *Map2, int &k1, int &k2)//4階GrayCode解碼
{
	if ( glUseNewGrayCodeThreshold )
	{	return CalcCuda4GrayCodeParam_kernel_2(P1, P2, P3, P4, Th, Map1, Map2, k1, k2); }
	return CalcCuda4GrayCodeParam_kernel_1(P1, P2, P3, P4, Th, Map1, Map2, k1, k2);	
}
