//------------------------------------------------------------------------------//
__device__ unsigned char CombineCudaPhaseMask_Kernel(unsigned char Mask1, unsigned char Mask2)//合併大小週期遮罩
{
	MASK_DATA Mask=0;
	if ( (Mask1&PHASE_MASK_LOW_CONTRAST)!=0 || (Mask2&PHASE_MASK_LOW_CONTRAST)!=0 )
	{	Mask |= PHASE_MASK_LOW_CONTRAST;	}	
	else if ( (Mask1&PHASE_MASK_LOW_POTENTIAL)!=0 || (Mask2&PHASE_MASK_LOW_POTENTIAL)!=0 )
	{	Mask |= PHASE_MASK_LOW_POTENTIAL;	}
	else if ( (Mask1&PHASE_MASK_OVER_SATURATED)!=0 || (Mask2&PHASE_MASK_OVER_SATURATED)!=0 )
	{	Mask |= PHASE_MASK_OVER_SATURATED;	}
	else
	{	Mask = PHASE_MASK_VALID; }
	return Mask;
}
//------------------------------------------------------------------------------//
__device__ int  CombineCudaPhasePeriod_MaxMin_Kernel(int Phase1, int Phase2, double Ratio)
{
	const int PhaseDummy = PHASE_PERIOD_HALF;//增加特定周期
	const int FullPeriodM = (int)(Ratio*PHASE_PERIOD);//以第1週期為主的大週期	

	//基本公式如下
	//1.相位差=相位1-相位2
	//2.如果相位差<0，則相位差加上周期
	//3.將相位差x比例1則可得到還原後的相位1
	//4.將相位差x比例2則可得到還原後的相位2

	//Kai-20161006-直接將週期2打成大週期, 因此合成的週期為相位2, 改成以短周期相位為主的合成相位
	int PhaseM = Phase2;
	//Kai-20161005-改成以短周期相位為主的合成相位
	int PhaseMT = PhaseM;
	int PhaseMFull = (int)(PhaseMT*Ratio);//將合併相位轉到以小週期下的相位
	//計算落於小週期下第幾個週期
	double dPeriod = (PhaseMFull-Phase1+PhaseDummy+0.0)/PHASE_PERIOD;//加上0.0是轉成浮點數			
	int    nPeriod = floor(dPeriod);//使用此函數主要是當dPeriod為負數時的計算
	int    PhaseMFullNew = Phase1+(nPeriod*PHASE_PERIOD);//使用小週期計算出的新相位
	if ( PhaseMFullNew < 0 ) //當新相位小於0, 則需要補足整各小週期的週期
	{	PhaseMFullNew += FullPeriodM; }
	if ( PhaseMFullNew > FullPeriodM )
	{	PhaseMFullNew -= FullPeriodM; }
	//double dValue = (PhaseMFullNew/Ratio);
	int PhaseMNew  = (int)(PhaseMFullNew/Ratio);//將新相位轉落於合併週期的座標系裡
	PhaseM  = PhaseMNew;
	return PhaseM;
}
//------------------------------------------------------------------------------//
__device__ int  CombineCudaPhasePeriod_Sibling_Kernel(int Phase1, int Phase2, double Ratio)//合併鄰近週期
{
	int PhaseM = 0;
	int PhaseMT = 0;
	int PhaseMNew = 0;
	int PhaseMFull = 0;
	int PhaseMFullNew = 0;
	int nPeriod = 0;	
	double dPeriod = 0.0;
	const int PhaseDummy = PHASE_PERIOD_HALF;//增加特定周期
	const int FullPeriodM1 = (int)(Ratio*PHASE_PERIOD);//以第1週期為主的大週期
	if ( Phase2 > Phase1 )
	{	PhaseM = static_cast<int>(Phase1-Phase2+PHASE_PERIOD);	}
	else
	{	PhaseM = Phase1-Phase2;	}

	//Kai-20161005-改成以短周期相位為主的合成相位
	PhaseMT = PhaseM;
	PhaseMFull = (int)(PhaseMT*Ratio);//將合併相位轉到以小週期下的相位
	//計算落於小週期下第幾個週期
	dPeriod = (PhaseMFull-Phase1+PhaseDummy+0.0)/PHASE_PERIOD;
	nPeriod = floor(dPeriod);//使用此函數主要是當dPeriod為負數時的計算
	PhaseMFullNew = Phase1+(nPeriod*PHASE_PERIOD);//使用小週期計算出的新相位
	if ( PhaseMFullNew < 0 ) //當新相位小於0, 則需要補足整各小週期的週期
	{	PhaseMFullNew += FullPeriodM1; }
	if ( PhaseMFullNew > FullPeriodM1 )
	{	PhaseMFullNew -= FullPeriodM1; }
	PhaseMNew  = (int)(PhaseMFullNew/Ratio);//將新相位轉落於合併週期的座標系裡
	PhaseM  = PhaseMNew;	
	return PhaseM;
}
//------------------------------------------------------------------------------//
__device__ int  CombineCudaPhasePeriod_Kernel(int Mode, int Phase1, int Phase2, double Ratio)//合併兩個週期
{
	if ( COMBINE_PHASE_SIBLING_PERIOD == Mode )
	{	return CombineCudaPhasePeriod_Sibling_Kernel(Phase1, Phase2, Ratio); }
	return CombineCudaPhasePeriod_MaxMin_Kernel(Phase1, Phase2, Ratio); 
}
//------------------------------------------------------------------------------//
__device__ bool CalcCudaCombinePhasePeriodRatio_Kernel(int Mode, float P1, float P2, float &Ratio)//計算合併兩個週期比例
{
	const double PP1 = MIN(P1, P2);
	const double PP2 = MAX(P1, P2);
	if ( COMBINE_PHASE_SIBLING_PERIOD == Mode )
	{
		double Ratio1=0.0;
		double Ratio2=0.0;
		if ( P2 > P1 )//P2 為主
		{	
			//dRatio = PP1*Precision/(PP2-PP1); 		
			Ratio1 = PP2/(PP2-PP1);
			Ratio2 = PP1/(PP2-PP1);
			Ratio = Ratio1;
		}
		else //P1為主 
		{	
			//dRatio = PP2*Precision/(PP2-PP1);	
			Ratio1 = PP1/(PP2-PP1);
			Ratio2 = PP2/(PP2-PP1);
			Ratio = Ratio2;
		}	
	}
	else
	{	
		if ( P2 > P1 )//P2 為主
		{	Ratio = P2/P1;	}
		else //P1為主 
		{	Ratio = 1;	}		
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ int  CombineCudaPhasePeriod_GrayCode_Kernel(int Phase, int Period, int NPeriod, int k1, int k2)//合併相位與GrayCode
{	
	int PhaseM;
	const int PeriodQart1 =   Period/4;//90
	const int PeriodQart3 = 3*Period/4;//270
	if ( Phase <= PeriodQart1 ) 
	{	PhaseM=Phase+(Period*k2); }
	else if ( Phase >= PeriodQart3 ) 
	{	PhaseM=Phase+(Period*k2)-(Period); }
	else
	{	PhaseM=Phase+(Period*k1); }		
	PhaseM = (PhaseM/NPeriod);
	if ( PhaseM > Period )
	{	PhaseM -= Period; }
	return PhaseM;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda2ExpPhaseData_Kernel(unsigned char Mask1, int Phase1, unsigned char Mask2, int Phase2, unsigned char &Mask, int &Phase)//合併雙曝光相位
{
	int        useCount=0;	
	int        PhaseSum=0;
	int        PhaseH = 0;
	int        PhaseL = 0;
	int        PhaseErr=0;		
	MASK_DATA  MaskValid[4];	
	int        PhaseValid[4];
	const int  MaxError=500;

	if ( Phase1 > Phase2 ) 
	{
		PhaseH = Phase1; 
		PhaseL = Phase2; 
	}
	else
	{ 
		PhaseH = Phase2; 
		PhaseL = Phase1; 
	}
	PhaseErr = PhaseH-PhaseL;

	Mask = PHASE_MASK_VALID;
	if ( (Mask1&PHASE_MASK_NOISE)!=NULL )
	{	Mask = Mask1; }
	else
	{
		MaskValid[useCount] = Mask1;
		PhaseValid[useCount] = Phase1;
		PhaseSum += PhaseValid[useCount];
		useCount ++;
	}
	if ( (Mask2&PHASE_MASK_NOISE)!=NULL )
	{	Mask = Mask2; }
	else
	{
		MaskValid[useCount] = Mask2;
		PhaseValid[useCount] = Phase2;
		PhaseSum += PhaseValid[useCount];
		useCount ++;
	}
	if ( 0 == useCount )
	{
		//Phase = (Phase1+Phase2)/2;		
		if ( PhaseErr < MaxError )
		{	Phase = (PhaseH+PhaseL)/2;  }
		else
		{	Phase = PhaseH;		}
		return true;
	}
	Mask = PHASE_MASK_VALID;
	if ( 1 == useCount )
	{	Phase = PhaseSum; }
	else
	{	
		if ( PhaseErr < MaxError )
		{	Phase = PhaseSum/useCount;  }
		else
		{	Phase = PhaseH;		}
		//Phase = PhaseSum/useCount;
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda2ExpPhaseData_Kernel_II(unsigned char Mask1, int Phase1, unsigned char Mask2, int Phase2, unsigned char &Mask, int &Phase, int ZeroPhase)//合併雙曝光相位
{
	return MergeCuda2ExpPhaseData_Kernel(Mask1, Phase1, Mask2, Phase2, Mask, Phase);

	int        useCount=0;	
	PHASE_DATA PhaseSum=0;
	MASK_DATA  MaskValid[4];	
	PHASE_DATA PhaseValid[4];

	Mask = PHASE_MASK_VALID;
	if ( (Mask1&PHASE_MASK_NOISE)!=NULL )
	{	Mask = Mask1; }
	else
	{
		MaskValid[useCount] = Mask1;
		PhaseValid[useCount] = Phase1;
		PhaseSum += PhaseValid[useCount];
		useCount ++;
	}
	if ( (Mask2&PHASE_MASK_NOISE)!=NULL )
	{	Mask = Mask2; }
	else
	{
		MaskValid[useCount] = Mask2;
		PhaseValid[useCount] = Phase2;
		PhaseSum += PhaseValid[useCount];
		useCount ++;
	}
	if ( 0 == useCount )
	{
		Phase = (Phase1+Phase2)/2;
		return true;
	}
	Mask = PHASE_MASK_VALID;
	if ( 1 == useCount )
	{	Phase = PhaseSum; }
	else
	{	
		int PhaseH = 0;
		int PhaseL = 0;
		int PhaseErr=0;		
		if ( Phase1 > Phase2 ) 
		{
			PhaseH = Phase1; 
			PhaseL = Phase2; 
		}
		else
		{ 
			PhaseH = Phase2; 
			PhaseL = Phase1; 
		}
		PhaseErr = PhaseH-PhaseL;
		if ( PhaseErr < 500 )
		{	Phase = PhaseSum/useCount;  }
		else
		{	
			//Phase = PhaseH;	
			ZeroPhase += 200;
			if ( PhaseL > ZeroPhase )
			{	Phase = PhaseL;	 }
			else
			{	Phase = PhaseH;	 }
		}
		//Phase = PhaseSum/useCount;
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda2ExpPhaseDataByMean_Kernel(unsigned char Mask1, int Phase1, float Mean1, unsigned char Mask2, int Phase2, float Mean2, unsigned char &Mask, int &Phase)//合併雙曝光相位
{	
	if ( PHASE_MASK_VALID==Mask1 ||  PHASE_MASK_VALID==Mask2 )
	{	//濾除過飽和
		if ( PHASE_MASK_OVER_SATURATED==Mask1 )
		{
			Mask = Mask2; 
			Phase = Phase2;
			return true;
		}
		if ( PHASE_MASK_OVER_SATURATED==Mask2 )
		{
			Mask = Mask1; 
			Phase = Phase1;
			return true;
		}
	}
	//找最接近128灰階的
	const int Target=glMerge2ExpPhaseDataMeanTarget;//目標灰階
	float Dif1=Mean1-Target;
	float Dif2=Mean2-Target;
	if ( Dif1 < 0 ) { Dif1=-Dif1; }
	if ( Dif2 < 0 ) { Dif2=-Dif2; }
	if ( Dif2 < Dif1 ) 
	{
		Mask = Mask2; 
		Phase = Phase2;
	}
	else
	{
		Mask = Mask1; 
		Phase = Phase1;
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda2ExpPhaseDataByMaxB_Kernel(unsigned char Mask1, int Phase1, float A1, float B1, unsigned char Mask2, int Phase2, float A2, float B2, unsigned char &Mask, int &Phase)//合併雙曝光相位
{
	if ( B2 > B1 )
	{
		Mask = Mask2;
		Phase = Phase2;
		return true;
	}
	if ( B1 > B2 )
	{
		Mask = Mask1;
		Phase = Phase1;
		return true;
	}	

	const float Sat = 250.0f;
	if ( A2>Sat || A1>=A2 )
	{
		Mask = Mask1;
		Phase = Phase1;
		return true;
	}
	if ( A1>Sat || A2>A1 )
	{
		Mask = Mask2;
		Phase = Phase2;
		return true;
	}	
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda2ExpPhaseDataByMaxCV_Jun_Kernel(float A[], float B[], float CV[], int nBrightness, int nSaturated, int &nIdx)//合併2個曝光的相位-軍達提供
{
	nIdx = -1;
	for (int k = 0; k < nBrightness; ++k)
	{
		if (A[k] < 0 || A[k]>255 || B[k]<0 || B[k]>255.0 || CV[k] < 0)
		{	return false;	}
	}

	float fMaxCV = 0.0;
	float fMaxA = 0.0;

	//判斷在B值大於2時, 最大的CV值是哪一組
	for (int k = 0; k < nBrightness; ++k)
	{
		if ((B[k] > 2.0) && (CV[k] > fMaxCV))
		{
			fMaxCV = CV[k];
			nIdx = k;
		}
		else if ((fMaxCV != 0.0) && (CV[k] == fMaxCV))
		{
			// 2組的CV值一樣大, 再判斷A在nSaturated值以下最亮的那一組
			for (int h = 0; h < nBrightness; ++h)
			{
				if (A[h]<nSaturated && A[h] > fMaxA)
				{
					fMaxA = A[h];
					nIdx = h;
				}
			}
		}
	}

	float fMaxB = 0.0;
	float fMinA = 255.0;
	// 2組的B值都小於2, 選A值250以下的最大B值
	if (nIdx == -1)
	{
		for (int h = 0; h < nBrightness; ++h)
		{
			if (A[h]<nSaturated && B[h]>fMaxB)
			{
				fMaxB = B[h];
				nIdx = h;
			}
		}

		// 2組的A值都大於250, 選A值最小的
		if (nIdx == -1)
		{
			for (int h = 0; h < nBrightness; ++h)
			{
				if (A[h] < fMinA)
				{
					fMinA = A[h];
					nIdx = h;
				}
			}
		}
	}

	if (nIdx == -1)
	{	nIdx = 0;	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda2ExpPhaseDataByMaxCV_Kernel(unsigned char Mask1, int Phase1, float A1, float B1, unsigned char Mask2, int Phase2, float A2, float B2, unsigned char &Mask, int &Phase)//合併雙曝光相位
{
	int idx=0;
	const int Count = 2;
	const int Saturated=250;
	float A[Count]={A1, A2};
	float B[Count]={B1, B2};
	float CV[Count]={0, 0};		
	if ( 0 != A[0] ) { CV[0] = B[0]/A[0]; }
	if ( 0 != A[1] ) { CV[1] = B[1]/A[1]; }
	if (MergeCuda2ExpPhaseDataByMaxCV_Jun_Kernel(A, B, CV, Count, Saturated, idx)==false )
	{
		Mask = Mask1;
		Phase = Phase1;
		return true;
	}
	if ( 1 == idx ) 
	{
		Mask = Mask2;
		Phase = Phase2;
	}
	else
	{
		Mask = Mask1;
		Phase = Phase1;
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool GeometryMedianCudaSpaceHeightIter_Kernel(const float SpaceList[], int SpaceCnt, float &Space)//幾何中值法
{
	int   i=0;
	float A=0, B=0;
	float Len=0;
	float Len2=0;
	float SumA=0;
	float SumB=0;
	for ( i=0; i<SpaceCnt; i++ )
	{
		Len = (SpaceList[i]-Space);		
		Len2 = Len*Len; 
		if ( Len2 < 0.0001 ) //剛好落於本身點上
		{	continue; }

		A = SpaceList[i]/Len2;
		B = 1.0f/Len2;
		SumA += A;
		SumB += B;
	}
	Space = SumA/SumB;
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool GeometryMedianCudaSpaceHeight_Kernel(const float SpaceList[], int SpaceCnt, float ZeroPlane, float &Space)//幾何中值法
{
	int   i=0;
	int   IterCnt=0;
	float SpaceCur=0;
	float SpaceNxt=0;
	float SpaceAve=0;
	float SpaceErr=0;
	const int MaxIterCnt=10;
	float SpaceErrList[MaxIterCnt+1];
	float SpaceResList[MaxIterCnt+1];
	if ( 0 == SpaceCnt )
	{
		Space = 0.0f;
		return true;
	}
	if ( 1 == SpaceCnt )
	{
		Space = SpaceList[0];
		return true;
	}
	for ( i=0; i<=MaxIterCnt; i++ )
	{	
		SpaceResList[i] = 0.0; 
		SpaceErrList[i] = FLT_MAX;
	}
	for ( i=0; i<SpaceCnt; i++ )
	{	SpaceAve += SpaceList[i]; }
	SpaceAve /= SpaceCnt;
	SpaceResList[0] = SpaceNxt = SpaceCur = SpaceAve;
	SpaceResList[0] = SpaceNxt = SpaceCur = ZeroPlane;//ZeroPlane;
	while ( true )
	{
		if ( GeometryMedianCudaSpaceHeightIter_Kernel(SpaceList, SpaceCnt, SpaceNxt) == false )
		{	return false;  }
		SpaceErr =  SpaceNxt-SpaceCur;
		if ( SpaceErr < 0 ) { SpaceErr=-SpaceErr; }
		if ( SpaceErr < 10.001f ) 
		{	break; }
		IterCnt ++;
		if ( IterCnt > MaxIterCnt ) 
		{	break; }
		SpaceErrList[IterCnt] = SpaceErr;
		SpaceResList[IterCnt] = SpaceCur = SpaceNxt;
	};

	if ( IterCnt > MaxIterCnt ) 
	{
		float MinErr=FLT_MAX;
		SpaceNxt = SpaceResList[0];
		for ( i=1; i<MaxIterCnt; i++ )
		{
			if ( MinErr > SpaceErrList[i] ) 
			{
				MinErr = SpaceErrList[i];
				SpaceNxt = SpaceResList[i];
			}
		}		
	}
	Space = SpaceNxt;
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool CompareCuda4OppositeGray_Kernel(const TPhaseNoiseParam &NoiseParam, int P1, int P2, int P3, int P4, unsigned char &Mask1, unsigned char &Mask2, unsigned char &Mask3, unsigned char &Mask4)//比較相對打燈灰階
{	                                       
	const int OppositeMaxGray = NoiseParam.SpaceMultiCastOppositeMaxGray;
	if ( 0 == OppositeMaxGray ) { return true; }

	int MaxID = 1;
	int DifGray=0;
	int MaxGray=P1;
	if ( MaxGray < P2 ) 
	{
		MaxID = 2;
		MaxGray = P2;
	}
	if ( MaxGray < P3 ) 
	{
		MaxID = 3;
		MaxGray = P3;
	}
	if ( MaxGray < P4 ) 
	{
		MaxID = 4;
		MaxGray = P4;
	}
	switch ( MaxID )
	{
	case 1:
	case 2:
		DifGray = abs(P1-P2);
		if ( DifGray > OppositeMaxGray )
		{
			if ( (Mask1&PHASE_MASK_NOISE)==NULL )
			{	Mask1 = PHASE_MASK_HEIGHT_UNEXPECTED; }
			if ( (Mask2&PHASE_MASK_NOISE)==NULL )
			{	Mask2 = PHASE_MASK_HEIGHT_UNEXPECTED; }
		}
		break;
	case 3:
	case 4:
		DifGray = abs(P3-P4);
		if ( DifGray > OppositeMaxGray )
		{
			if ( (Mask3&PHASE_MASK_NOISE)==NULL )
			{	Mask3 = PHASE_MASK_HEIGHT_UNEXPECTED; }
			if ( (Mask4&PHASE_MASK_NOISE)==NULL )
			{	Mask4 = PHASE_MASK_HEIGHT_UNEXPECTED; }
		}
		break;
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ int GetCudaMassGroupIndex_Kernel(int GroupCnt[], int Count)//取得群組數量最多的引數
{		
	int i=0;
	int index = 0;
	int MaxCnt=-1;
	for ( i=0; i<Count; i++ )
	{
		if ( 0==i || MaxCnt<GroupCnt[i])
		{
			index = i;
			MaxCnt=GroupCnt[i]; 
			//if ( MaxCnt == Count )
			//{	break; }
		}
	}
	return index;	
}
//------------------------------------------------------------------------------//
__device__ bool GetCudaMinValueIndex_Kernel(float SpaceList[], int StartIdx, int SpaceCnt)//取得最低值引數
{
	int i=0;
	int idx=StartIdx;	
	for ( i=StartIdx+1; i<SpaceCnt; i++ )
	{	
		if ( SpaceList[idx] > SpaceList[i] )
		{	idx = i;	}		
	}
	return idx;
}
//------------------------------------------------------------------------------//
__device__ bool CudaMergeSortMerge_Kernel(float array[], int front, int mid, int end)//合併排序-合併
{
	// 利用 std::vector 的constructor, 
    // 把array[front]~array[mid]放進 LeftSub[]
    // 把array[mid+1]~array[end]放進 RightSub[]
	const int LeftSize =mid-front+1;
	const int RightSize=end-mid;
	const int MaxSize = MULTI_CAST_PATCH_MAX_COUNT;
	if ( (LeftSize+1)>MaxSize || (RightSize+1)>MaxSize )
	{	return false; }

	int   i=0;
    float LeftSub[MaxSize];
	float RightSub[MaxSize];
	for ( i=0; i<LeftSize; i++ )
	{	LeftSub[i] = array[front+i]; }
	for ( i=0; i<RightSize; i++ )
	{	RightSub[i] = array[mid+1+i]; }	
	LeftSub[LeftSize] = FLT_MAX;// 在LeftSub[]尾端加入值為 Max 的元素
	RightSub[RightSize] = FLT_MAX;// 在RightSub[]尾端加入值為 Max 的元素

    int idxLeft = 0, idxRight = 0;
    for (i=front; i<=end; i++) 
	{
        if (LeftSub[idxLeft] <= RightSub[idxRight] ) 
		{
            array[i] = LeftSub[idxLeft];
            idxLeft++;
        }
        else
		{
            array[i] = RightSub[idxRight];
            idxRight++;
        }
    }
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool CudaMergeSortRecursion_Kernel(float array[], int front, int end)//合併排序-遞迴
{
	if (front < end)  // 表示目前的矩陣範圍是有效的
	{                   
        int mid = (front+end)/2;         // mid即是將矩陣對半分的index
		if ( CudaMergeSortRecursion_Kernel(array, front, mid) == false )// 繼續divide矩陣的前半段subarray
		{	return false; }        
        if ( CudaMergeSortRecursion_Kernel(array, mid+1, end) == false ) // 繼續divide矩陣的後半段subarray
		{	return false; }
        if ( CudaMergeSortMerge_Kernel(array, front, mid, end) == false )// 將兩個subarray做比較, 並合併出排序後的矩陣
		{	return false; }
    }
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool CudaMergeSortIterative_Kernel(float array[], int count)//合併排序-疊代
{
	int curr_size;  // For current size of subarrays to be merged 
                   // curr_size varies from 1 to n/2 
	int left_start; // For picking starting index of left subarray 
                   // to be merged 
  
   // Merge subarrays in bottom up manner.  First merge subarrays of 
   // size 1 to create sorted subarrays of size 2, then merge subarrays 
   // of size 2 to create sorted subarrays of size 4, and so on. 
   for (curr_size=1; curr_size<=count-1; curr_size = 2*curr_size) 
   { 
       // Pick starting point of different subarrays of current size 
       for (left_start=0; left_start<count-1; left_start += 2*curr_size) 
       { 
           // Find ending point of left subarray. mid+1 is starting  
           // point of right 
           int mid = MIN(left_start + curr_size - 1, count-1); 
  
           int right_end = MIN(left_start + 2*curr_size - 1, count-1); 
  
           // Merge Subarrays arr[left_start...mid] & arr[mid+1...right_end] 
           if ( CudaMergeSortMerge_Kernel(array, left_start, mid, right_end) == false )
		   {	return false; }
       } 
   } 
   return true;
}
//------------------------------------------------------------------------------//
__device__ void CudaQuickSortSwap_Kernel(float &a, float &b)//快速排序-交換
{
	float tmp = a;
	a = b;
	b = tmp;
}
//------------------------------------------------------------------------------//
__device__ int  CudaQuickSortPartition_Kernel(float array[], int front, int end)//快速排序-分割
{	
	int   i = front -1;
	float Pivot = array[end];    
    for (int j=front; j<end; j++)
	{
        if (array[j] < Pivot)
		{
            i++;
            CudaQuickSortSwap_Kernel(array[i], array[j]);			
        }
    }
    i++;
    CudaQuickSortSwap_Kernel(array[i], array[end]);	
    return i;
}
//------------------------------------------------------------------------------//
__device__ bool CudaQuickSortRecursion_Kernel(float array[], int front, int end)//快速排序-分割
{
	if (front < end) 
	{
        int Pivot = CudaQuickSortPartition_Kernel(array, front, end);
        CudaQuickSortRecursion_Kernel(array, front, Pivot-1);
        CudaQuickSortRecursion_Kernel(array, Pivot+1, end);
    }
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool CudaQuickSortIterative_Kernel(float array[], int front, int end)//快速排序-疊代
{
	int h = end;
	int l = front;
	const int Size = h-l + 1;
	const int MaxSize = MULTI_CAST_PATCH_MAX_COUNT;
	if ( Size > MaxSize )
	{	return false; }

	// Create an auxiliary stack 
    int stack[MaxSize]; 
  
    // initialize top of stack 
    int top = -1; 
  
    // push initial values of l and h to stack 
    stack[++top] = l; 
    stack[++top] = h; 
  
    // Keep popping from stack while is not empty 
    while (top >= 0) 
	{ 
        // Pop h and l 
        h = stack[top--]; 
        l = stack[top--]; 
  
        // Set pivot element at its correct position 
        // in sorted array 
        int p = CudaQuickSortPartition_Kernel(array, l, h); 
  
        // If there are elements on left side of pivot, 
        // then push left side to stack 
        if ( (p-1) > l)
		{ 
            stack[++top] = l; 
            stack[++top] = p - 1; 
        } 

        // If there are elements on right side of pivot, 
        // then push right side to stack 
        if ( (p+1) < h) 
		{ 
            stack[++top] = p + 1; 
            stack[++top] = h; 
        } 
    } ;
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool SortCudaSpcaeHeightMergeSort_Kernel(float SpaceList[], int SpaceCnt)//高度排序-合併排序
{
	//return CudaMergeSortRecursion_Kernel(SpaceList, 0, SpaceCnt-1);	
	return CudaMergeSortIterative_Kernel(SpaceList, SpaceCnt);	
}
//------------------------------------------------------------------------------//
__device__ bool SortCudaSpcaeHeightQuickSort_Kernel(float SpaceList[], int SpaceCnt)//高度排序-快速排序
{
	//return CudaQuickSortRecursion_Kernel(SpaceList, 0, SpaceCnt-1);	
	return CudaQuickSortIterative_Kernel(SpaceList, 0, SpaceCnt-1);	
}
//------------------------------------------------------------------------------//
__device__ bool SortCudaSpcaeHeightInsertion_Kernel(float SpaceList[], int SpaceCnt)//高度排序-插入法
{
	int   i=0,j=0;
	float key=0.0f;	
	for (i=1; i <SpaceCnt; i++) 
	{
		j = i-1;
		key = SpaceList[i];		
		while (key<SpaceList[j] && j>=0) 
		{
			SpaceList[j+1] = SpaceList[j];
			j--;
		}
		SpaceList[j+1] = key;
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool SortCudaSpcaeHeightSelection_Kernel(float SpaceList[], int SpaceCnt)//高度排序-選擇法
{
	int idx=0;	
	int i=0,j=0;
	float Temp=0.0f;
	//選擇排序法
	for ( int i=0; i<SpaceCnt-1; i++ )
	{	
		//idx = GetCudaMinValueIndex_Kernel(SpaceList, i, SpaceCnt);//不知為何會有計算錯誤				
		idx = i;		
		for ( j=i+1; j<SpaceCnt; j++ )
		{
			if ( SpaceList[idx] > SpaceList[j] )
			{	idx = j;	}
		}
		Temp = SpaceList[i];
		SpaceList[i] = SpaceList[idx];
		SpaceList[idx] = Temp;		
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool SortCudaSpcaeHeight_Kernel(float SpaceList[], int SpaceCnt)//高度排序
{
//	return SortCudaSpcaeHeightQuickSort_Kernel(SpaceList, SpaceCnt);
//	return SortCudaSpcaeHeightMergeSort_Kernel(SpaceList, SpaceCnt);
//	return SortCudaSpcaeHeightSelection_Kernel(SpaceList, SpaceCnt);
//	return SortCudaSpcaeHeightInsertion_Kernel(SpaceList, SpaceCnt);
	//if ( SpaceCnt > 32 )
	//{	return SortCudaSpcaeHeightMergeSort_Kernel(SpaceList, SpaceCnt); }
	return SortCudaSpcaeHeightInsertion_Kernel(SpaceList, SpaceCnt);
}
//------------------------------------------------------------------------------//
__device__ float AverageCudaSpcaeHeight_Kernel(const float SpaceList[], int SpaceCnt)//平均高度
{
	if ( 0 == SpaceCnt ) { return 0.0f; }
	int i=0;
	float Ave=0.0f;
	for ( i=0; i<SpaceCnt; i++ )
	{	Ave += SpaceList[i];	}
	Ave /= SpaceCnt;
	return Ave;
}
//------------------------------------------------------------------------------//
__device__ bool AddCudaGroupSpcaeHeightByMean_Kernel(float Space, float Range, float &Group, int &GroupCnt)//加入高度分群-依照平均值	
{
	const float SpaceDif = ::fabsf(Space-Group);
	if ( SpaceDif > Range ) { return false; }
	const float Sum = (Group*GroupCnt)+Space; 
	GroupCnt ++;
	Group = Sum/GroupCnt;
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool AddCudaGroupSpcaeHeightByRange_Kernel(float Space, float Range, float &GroupMin, float &GroupMax, float &GroupAve, int &GroupCnt)//加入高度分群-依照範圍值
{
	const float SpaceDifMin = ::fabsf(Space-GroupMin);
	const float SpaceDifMax = ::fabsf(Space-GroupMax);
	const float SpaceDif = MIN(SpaceDifMin, SpaceDifMax);
	if ( SpaceDif > Range )
	{	return false; }

	const float Sum = (GroupAve*GroupCnt)+Space; 
	GroupCnt ++;
	GroupAve = Sum/GroupCnt;
	if ( Space < GroupMin ) { GroupMin = Space; }
	if ( Space > GroupMax ) { GroupMax = Space; }
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool GroupCudaSpcaeHeightByMean_Kernel(float SpaceList[], float Range, float GroupAveList[], int GroupCntList[], int SpaceCnt, int &GoupCount)//高度分群-依照平均值
{
	int i=0, j=0;
	GoupCount = 0;
	if ( 0 == SpaceCnt ) { return false; }
	
	for ( i=0; i<SpaceCnt; i++ )
	{
		for ( j=0; j<GoupCount; j++ )
		{
			if ( AddCudaGroupSpcaeHeightByMean_Kernel(SpaceList[i], Range, GroupAveList[j], GroupCntList[j]) == true ) 
			{	break; }
		}
		if ( j == GoupCount ) 
		{
			GroupAveList[GoupCount] = SpaceList[i];
			GroupCntList[GoupCount] = 1;
			GoupCount ++ ;
		}
	}	
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool GroupCudaSpcaeHeightByRange_Kernel(float SpaceList[], float Range, float GroupMinList[], float GroupMaxList[], float GroupAveList[], int GroupCntList[], int SpaceCnt, int &GoupCount)//高度分群-依照範圍值
{
	int i=0, j=0;
	GoupCount = 0;
	if ( 0 == SpaceCnt ) { return false; }

	for ( i=0; i<SpaceCnt; i++ )
	{
		for ( j=0; j<GoupCount; j++ )
		{
			if ( AddCudaGroupSpcaeHeightByRange_Kernel(SpaceList[i], Range, GroupMinList[j], GroupMaxList[j], GroupAveList[j], GroupCntList[j]) == true ) 
			{	break; }
		}
		if ( j == GoupCount ) 
		{
			GroupMinList[GoupCount] = SpaceList[i];
			GroupMaxList[GoupCount] = SpaceList[i];
			GroupAveList[GoupCount] = SpaceList[i];
			GroupCntList[GoupCount] = 1;
			GoupCount ++ ;
		}
	}	
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool CompareCuda2SpaceHeight_Kernel(const TPhaseNoiseParam &NoiseParam, unsigned char &Mask1, float Space1, unsigned char &Mask2, float Space2, unsigned char &Mask, float &Space)//比較空間高度
{		
	const float CastValidDifference = NoiseParam.SpaceMultiCastValidDifference;
	const float CastValidBestRatio = NoiseParam.SpaceMultiCastValidBestRatio/100.0f;
	if ( CastValidDifference < 0.5 ) { return false; }
	
	float SpaceDif = 0;
	float SpaceMax = -FLT_MAX;
	float SpaceMin =  FLT_MAX;
	const unsigned char Mask_Valid=PHASE_MASK_VALID;
	const unsigned char Mask_ValidBest=PHASE_MASK_VALID_BEST;

	SpaceMax = MAX(Space1, Space2);
	SpaceMin = MIN(Space1, Space2);	
	SpaceDif = SpaceMax-SpaceMin;
	if ( SpaceDif > CastValidDifference )
	{	return false; }	
	if ( SpaceDif < (CastValidDifference*CastValidBestRatio) )
	{	Mask  = Mask_ValidBest; }
	else
	{	Mask  = Mask_Valid; }
	Space = (Space1+Space2)/2;
	return true;
}
