__device__ bool CompareCuda3SpaceHeight_Kernel(const TPhaseNoiseParam &NoiseParam, unsigned char &Mask1, float Space1, unsigned char &Mask2, float Space2, unsigned char &Mask3, float Space3, unsigned char &Mask, float &Space)//比較空間高度
{	
	const float CastValidDifference = NoiseParam.SpaceMultiCastValidDifference;
	const float CastValidBestRatio = NoiseParam.SpaceMultiCastValidBestRatio/100.0f;
	if ( CastValidDifference < 0.5 ) { return false; }
	
	float SpaceDif = 0;
	float SpaceMax = -FLT_MAX;
	float SpaceMin =  FLT_MAX;
	const unsigned char Mask_Valid=PHASE_MASK_VALID;
	const unsigned char Mask_ValidBest=PHASE_MASK_VALID_BEST;

	SpaceMax = MAX(Space1, SpaceMax);
	SpaceMin = MIN(Space1, SpaceMin);
	SpaceMax = MAX(Space2, SpaceMax);
	SpaceMin = MIN(Space2, SpaceMin);
	SpaceMax = MAX(Space3, SpaceMax);
	SpaceMin = MIN(Space3, SpaceMin);	
	SpaceDif = SpaceMax-SpaceMin;
	if ( SpaceDif > CastValidDifference )
	{
		int   ValidCnt=0;
		float ValidSpace[3]={0.0f, 0.0f, 0.0f};
		if ( CheckCudaSpaceMaskValid_Kernel(Mask1) == true ) 
		{	
			ValidSpace[ValidCnt] = Space1; 
			ValidCnt ++;
		}
		if ( CheckCudaSpaceMaskValid_Kernel(Mask2) == true ) 
		{	
			ValidSpace[ValidCnt] = Space2; 
			ValidCnt ++;
		}
		if ( CheckCudaSpaceMaskValid_Kernel(Mask3) == true ) 
		{	
			ValidSpace[ValidCnt] = Space3; 
			ValidCnt ++;
		}
		if ( ValidCnt != 2 ) { return false; }		
		SpaceMax = ValidSpace[0];
		SpaceMin = ValidSpace[0];
		SpaceMax = MAX(ValidSpace[1], SpaceMax);
		SpaceMin = MIN(ValidSpace[1], SpaceMin);		
		SpaceDif = SpaceMax-SpaceMin;
		if ( SpaceDif > CastValidDifference )
		{	return false; }
		if ( SpaceDif < (CastValidDifference*CastValidBestRatio) )
		{	Mask  = Mask_ValidBest; }
		else
		{	Mask  = Mask_Valid; }
		Space = (ValidSpace[0]+ValidSpace[1])/2;
		return true;
	}
	
	if ( SpaceDif < (CastValidDifference*CastValidBestRatio) )
	{	Mask  = Mask_ValidBest; }
	else
	{	Mask  = Mask_Valid; }
	Space = (Space1+Space2+Space3)/3;
	return true;
}
