//------------------------------------------------------------------------------//
__device__ bool CompareCuda4SpaceHeight_Kernel_2(const TPhaseNoiseParam &NoiseParam, unsigned char &Mask1, float Space1, unsigned char &Mask2, float Space2, unsigned char &Mask3, float Space3, unsigned char &Mask4, float Space4, unsigned char &Mask, float &Space, bool bChkMask)//比較空間高度
{	
	const int   CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const float CastValidDifference = NoiseParam.SpaceMultiCastValidDifference;
	const float CastValidBestRatio = NoiseParam.SpaceMultiCastValidBestRatio/100.0f;
	const float CastValidBestVal = CastValidDifference*CastValidBestRatio;
	if ( CastValidDifference < 0.5 ) { return false; }

	bool  Mached=false;	
	float SpaceDif = 0;
	float SpaceNew = 0;
	float SpaceDif12 = 0;
	float SpaceAve12 = 0;
	float SpaceDif34 = 0;
	float SpaceAve34 = 0;
	float SpaceDif1234 = 0;
	const int SpaceCnt = 4;
	int   TotalGoupCount = 0;	
	int   SpaceGroupCnt[SpaceCnt]={0};
	float SpaceGroupMin[SpaceCnt]={0.0f};
	float SpaceGroupMax[SpaceCnt]={0.0f};
	float SpaceGroupAve[SpaceCnt]={0.0f};
	float SortList[SpaceCnt]={Space1, Space2, Space3, Space4};
	//float SpaceList[SpaceCnt]={Space1, Space2, Space3, Space4}
	const float CastGroupRange = CastValidDifference*1.5;;	
	const unsigned char Mask_Valid=PHASE_MASK_VALID;
	const unsigned char Mask_ValidBest=PHASE_MASK_VALID_BEST;//PHASE_MASK_VALID_BEST;//20190530

	SpaceDif12 = ::fabs(Space1-Space2);	
	SpaceDif34 = ::fabs(Space3-Space4);
	SpaceAve12 = (Space1+Space2)*0.5f;
	SpaceAve34 = (Space3+Space4)*0.5f;
	SpaceDif1234 = ::fabs(SpaceAve12-SpaceAve34);

	//for Type I 
	Mached=false;
	if ( SpaceDif12>CastValidDifference || SpaceDif34>CastValidDifference )
	{	Mached = false;	}
	else
	{
		const float CastValidBestVal2 = CastValidBestVal/2.0f;
		if ( SpaceDif1234 < CastValidBestVal2 ) 
		{	Mached = true;	}
	}
	if ( true == Mached ) 
	{
		int index = 0;
		float GroupRange = 200;
		SortCudaSpcaeHeight_Kernel(SortList, SpaceCnt);
		if ( MULTI_CAST_MERGE_MODE_MASS_4 == CastMergeMode )
		{
			GroupRange = CastGroupRange;
			GroupCudaSpcaeHeightByMean_Kernel(SortList, GroupRange, SpaceGroupAve, SpaceGroupCnt, SpaceCnt, TotalGoupCount); 
		}
		else
		{
			GroupRange = 200;
			GroupCudaSpcaeHeightByRange_Kernel(SortList, GroupRange, SpaceGroupMin, SpaceGroupMax, SpaceGroupAve, SpaceGroupCnt, SpaceCnt, TotalGoupCount); 
		}
		index = GetCudaMassGroupIndex_Kernel(SpaceGroupCnt, TotalGoupCount);		
		Mask  = Mask_ValidBest;
		Space = SpaceGroupAve[index];
		if ( MULTI_CAST_MERGE_MODE_MASS_3 == CastMergeMode )
		{
			if ( TotalGoupCount == SpaceCnt )
			{
				Mask  = Mask_ValidBest;
				Space = AverageCudaSpcaeHeight_Kernel(SortList, SpaceCnt);
			}
		}
		return true;
	}

	//for Type II	
	float SpaceDifMin = MIN(SpaceDif12, SpaceDif34);
	if ( SpaceDifMin < CastValidDifference )
	{
		if ( true == bChkMask )
		{
			int ValidCnt=0;
			if ( Mask1 == Mask_Valid ) { ValidCnt ++; }
			if ( Mask2 == Mask_Valid ) { ValidCnt ++; }
			if ( Mask3 == Mask_Valid ) { ValidCnt ++; }
			if ( Mask4 == Mask_Valid ) { ValidCnt ++; }
			if ( 4 != ValidCnt ) { return false; }//有雜訊就跳回	
		}
		if ( ::fabs(Space3-Space1)<CastValidDifference ) 
		{	Mached = true; }
		else if ( ::fabs(Space4-Space1)<CastValidDifference ) 
		{	Mached = true; }
		else if ( ::fabs(Space3-Space2)<CastValidDifference ) 
		{	Mached = true; }
		else if ( ::fabs(Space4-Space2)<CastValidDifference ) 
		{	Mached = true; }			
		if ( true == Mached )
		{
			int index = 0;
			float GroupRange = 200;
			SortCudaSpcaeHeight_Kernel(SortList, SpaceCnt);
			if ( MULTI_CAST_MERGE_MODE_MASS_4 == CastMergeMode )
			{
				GroupRange = CastGroupRange;
				GroupCudaSpcaeHeightByMean_Kernel(SortList, GroupRange, SpaceGroupAve, SpaceGroupCnt, SpaceCnt, TotalGoupCount); 
			}
			else
			{
				GroupRange = 200;
				GroupCudaSpcaeHeightByRange_Kernel(SortList, GroupRange, SpaceGroupMin, SpaceGroupMax, SpaceGroupAve, SpaceGroupCnt, SpaceCnt, TotalGoupCount); 
			}
			index = GetCudaMassGroupIndex_Kernel(SpaceGroupCnt, TotalGoupCount);
			Mask  = Mask_ValidBest;
			Space = SpaceGroupAve[index];
			if ( MULTI_CAST_MERGE_MODE_MASS_3 == CastMergeMode )
			{
				if ( TotalGoupCount == SpaceCnt )
				{
					Mask  = Mask_ValidBest;
					Space = AverageCudaSpcaeHeight_Kernel(SortList, SpaceCnt);
				}
			}
			return true;
		}
	}	
	return false;
}
