//------------------------------------------------------------------------------//
__device__ bool CompareCuda4SpaceHeight_Kernel(const TPhaseNoiseParam &NoiseParam, unsigned char &Mask1, float Space1, unsigned char &Mask2, float Space2, unsigned char &Mask3, float Space3, unsigned char &Mask4, float Space4, unsigned char &Mask, float &Space)//比較空間高度
{	
	bool  IsOK=false;
	bool  bChkMask=false;
	const int   CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int   CastMergeBestMode = NoiseParam.SpaceMultiCastMergeBestMode;
	switch ( CastMergeMode )
	{
	case MULTI_CAST_MERGE_MODE_MASS:
	case MULTI_CAST_MERGE_MODE_LOWEST:
	case MULTI_CAST_MERGE_MODE_MASS_2:
		IsOK = CompareCuda4SpaceHeight_Kernel_1(NoiseParam, Mask1, Space1, Mask2, Space2, Mask3, Space3, Mask4, Space4, Mask, Space);//比較空間高度-1
		break;
	case MULTI_CAST_MERGE_MODE_MASS_3:
	case MULTI_CAST_MERGE_MODE_MASS_4:
		if ( MULTI_CAST_MERGE_BEST_MODE_03 == CastMergeBestMode )//比較空間高度-3
		{	bChkMask = true;	}
		else//比較空間高度-2
		{	bChkMask = false;	}
		IsOK = CompareCuda4SpaceHeight_Kernel_2(NoiseParam, Mask1, Space1, Mask2, Space2, Mask3, Space3, Mask4, Space4, Mask, Space, bChkMask);//比較空間高度-2
		break;
	case MULTI_CAST_MERGE_MODE_MEDIAN:
		if ( MULTI_CAST_MERGE_BEST_MODE_03 == CastMergeBestMode )//比較空間高度-3
		{	bChkMask = true;	}
		else//比較空間高度-2
		{	bChkMask = false;	}
		IsOK = CompareCuda4SpaceHeight_Kernel_2(NoiseParam, Mask1, Space1, Mask2, Space2, Mask3, Space3, Mask4, Space4, Mask, Space, bChkMask);//比較空間高度-2
		//IsOK = CompareCuda4SpaceHeight_Kernel_3(NoiseParam, Mask1, Space1, Mask2, Space2, Mask3, Space3, Mask4, Space4, Mask, Space);//比較空間高度-3
		break;
	}
	return IsOK;
}
//------------------------------------------------------------------------------//
__device__ bool CompareCudaNSpaceHeight_Kernel_1(const TPhaseNoiseParam &NoiseParam, const unsigned char MaskList[], const float SpaceList[], int SpaceCount, unsigned char &Mask, float &Space)//比較空間高度
{
	const int SpaceCnt = SpaceCount;
	const int MaxSpaceCount = MULTI_CAST_PATCH_MAX_COUNT;
	if ( SpaceCnt > MaxSpaceCount ) { return false; }
	const float CastValidDifference = NoiseParam.SpaceMultiCastValidDifference;
	const float CastValidBestRatio = NoiseParam.SpaceMultiCastValidBestRatio/100.0f;
	if ( CastValidDifference < 0.5 ) { return false; }

	int   i=0;
	float SpaceDif = 0;
	float SpaceMax = -FLT_MAX;
	float SpaceMin =  FLT_MAX;
	const unsigned char Mask_Valid=PHASE_MASK_VALID;
	const unsigned char Mask_ValidBest=PHASE_MASK_VALID_BEST;
	for ( i=0; i<SpaceCount; i++ )
	{
		if ( SpaceMax < SpaceList[i] ) { SpaceMax=SpaceList[i]; }
		if ( SpaceMin > SpaceList[i] ) { SpaceMin=SpaceList[i]; }
	}	
	SpaceDif = SpaceMax-SpaceMin;
	if ( SpaceDif > CastValidDifference )
	{
		int   ValidCnt=0;
		float ValidSpace[MaxSpaceCount];
		for ( i=0; i<SpaceCount; i++ )
		{
			ValidSpace[i] = 0;
			if ( CheckCudaSpaceMaskValid_Kernel(MaskList[i]) == false ) 
			{	continue; }
			ValidSpace[ValidCnt] = SpaceList[i]; 
			ValidCnt ++;			
		}
		if ( 0 == SpaceCount ) { return false; }
		if ( 1 == SpaceCount ) { return false; }
		if ( (SpaceCount-1) != ValidCnt ) { return false; }		
		
		SpaceMax = ValidSpace[0];
		SpaceMin = ValidSpace[0];
		for ( i=1; i<ValidCnt; i++ )
		{
			if ( SpaceMax < ValidSpace[i] ) { SpaceMax=ValidSpace[i]; }
			if ( SpaceMin > ValidSpace[i] ) { SpaceMin=ValidSpace[i]; }
		}
		SpaceDif = SpaceMax-SpaceMin;
		if ( SpaceDif > CastValidDifference )
		{	return false; }
		if ( SpaceDif < (CastValidDifference*CastValidBestRatio) )
		{	Mask  = Mask_ValidBest; }
		else
		{	Mask  = Mask_Valid; }
		Space = AverageCudaSpcaeHeight_Kernel(ValidSpace, ValidCnt);		
		return true;
	}	
	if ( SpaceDif < (CastValidDifference*CastValidBestRatio) )
	{	Mask  = Mask_ValidBest; }
	else
	{	Mask  = Mask_Valid; }
	Space = AverageCudaSpcaeHeight_Kernel(SpaceList, SpaceCount);
	return true;
}
