			}
			else
			{
				GroupRange = 200;
				GroupCudaSpcaeHeightByRange_Kernel(SortList, GroupRange, SpaceGroupMin, SpaceGroupMax, SpaceGroupAve, SpaceGroupCnt, SpaceCnt, TotalGoupCount); 
