__device__ bool CompareCudaNSpaceHeight_Kernel(const TPhaseNoiseParam &NoiseParam, const unsigned char MaskList[], const float SpaceList[], int SpaceCount, unsigned char &Mask, float &Space)//比較空間高度
{
	bool  IsOK=false;
	const int   CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	switch ( CastMergeMode )
	{
	case MULTI_CAST_MERGE_MODE_MASS:
	case MULTI_CAST_MERGE_MODE_LOWEST:
	case MULTI_CAST_MERGE_MODE_MASS_2:
		IsOK = CompareCudaNSpaceHeight_Kernel_1(NoiseParam, MaskList, SpaceList, SpaceCount, Mask, Space);//比較空間高度-1
		break;
	case MULTI_CAST_MERGE_MODE_MASS_3:
	case MULTI_CAST_MERGE_MODE_MASS_4:
		IsOK = CompareCudaNSpaceHeight_Kernel_2(NoiseParam, MaskList, SpaceList, SpaceCount, Mask, Space);//比較空間高度-2
		break;
	}
	return IsOK;
}
