	float GroupDif=0, GroupMax=0, GroupMin=0;
	float SpaceU=0, SpaceL=0, SpaceOther=0, SpaceULDif=0;	
	float SpaceMin=0, SpaceMax=0, SpaceAve=0, SpaceDif=0, SpaceSum=0;
	const int   CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int   MinValidCount = NoiseParam.SpaceMultiCastMinValidCount;
	const float CastMaxDifference = NoiseParam.SpaceMultiCastMaxDifference;
	const float CastLimitDifference = NoiseParam.SpaceMultiCastLimitDifference;	
	const int   CastOppositeMaxGray = NoiseParam.SpaceMultiCastOppositeMaxGray;
	const float SpaceLowLimit = NoiseParam.SpaceSingleCastLowLimit;
	const float CastLimitDifference2 = CastLimitDifference*2;		
	const float CastGroupRange = CastMaxDifference*1.0;
	const float ZeroPlaneOffset = NoiseParam.PhaseZeroPlaneOffsetPosZ/2;

	SpaceList[0] = Space1;
	SpaceList[1] = Space2;
	

	useCount = 0;		
	SpaceMin = FLT_MAX;
	SpaceMax =-FLT_MAX;
	Mask = PHASE_MASK_VALID;
	if ( (Mask1&PHASE_MASK_NOISE) != NULL || Space1<SpaceLowLimit)
	{	Mask = Mask1;	}
	else
	{	
		SpaceValid[useCount] = Space1;
		if ( SpaceMax < SpaceValid[useCount] ) { SpaceMax = SpaceValid[useCount]; }
		if ( SpaceMin > SpaceValid[useCount] ) { SpaceMin = SpaceValid[useCount]; }
		SpaceSum += SpaceValid[useCount];
		useCount ++;	
	}

	if ( (Mask2&PHASE_MASK_NOISE) != NULL || Space2<SpaceLowLimit)
	{	Mask = Mask2;	}
	else
	{
		SpaceValid[useCount] = Space2;
		if ( SpaceMax < SpaceValid[useCount] ) { SpaceMax = SpaceValid[useCount]; }
		if ( SpaceMin > SpaceValid[useCount] ) { SpaceMin = SpaceValid[useCount]; }
		SpaceSum += SpaceValid[useCount];
		useCount ++;	
	}						
					
	if ( useCount == 0 ) 
	{
		if ( PHASE_MASK_VALID == Mask )
		{	Mask = PHASE_MASK_OVER_LOW;	}
		if ( MULTI_CAST_MERGE_MODE_MASS_3==CastMergeMode ||MULTI_CAST_MERGE_MODE_MASS_4==CastMergeMode)
		{	Space = 0; }
		else if ( MULTI_CAST_MERGE_MODE_MEDIAN==CastMergeMode )
		{	GeometryMedianCudaSpaceHeight_Kernel(SpaceList, 2, ZeroPlaneOffset, Space);	}
		else
		{	Space = (Space1+Space2)/2; }
		return true;
	}	
	SpaceDif = SpaceMax-SpaceMin;
	SpaceAve = SpaceSum/useCount;
	Space = SpaceAve;
	Mask= PHASE_MASK_VALID;

	if ( useCount < MinValidCount )
	{
		Mask = PHASE_MASK_HEIGHT_UNEXPECTED;
		if ( MULTI_CAST_MERGE_MODE_MASS_3==CastMergeMode ||MULTI_CAST_MERGE_MODE_MASS_4==CastMergeMode)
		{	Space = 0; }
		else if ( MULTI_CAST_MERGE_MODE_MEDIAN==CastMergeMode )
		{	GeometryMedianCudaSpaceHeight_Kernel(SpaceList, 2, ZeroPlaneOffset, Space);	}
		else
		{	Space = SpaceAve; }
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_LOWEST == CastMergeMode )
	{
		Space = SpaceMin;
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_MASS_3 == CastMergeMode )
	{			
		if ( 2 == useCount )
		{
			Space = MIN(SpaceValid[0], SpaceValid[1]);
			return true;
		}		
		Space = SpaceValid[0];
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_MASS_4 == CastMergeMode )
	{			
		if ( 2 == useCount )
		{
			Space = MIN(SpaceValid[0], SpaceValid[1]);
			return true;
		}		
		Space = SpaceValid[0];
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_MEDIAN == CastMergeMode )
	{	
		GeometryMedianCudaSpaceHeight_Kernel(SpaceValid, useCount, ZeroPlaneOffset, Space);
		return true;
	}

	if ( SpaceDif<CastMaxDifference )
	{	Space = SpaceAve;	}
	else
	{			
		if ( 1==useCount )
		{
			if ( MULTI_CAST_MERGE_MODE_MASS_2 == CastMergeMode )
			{	Space = SpaceMin;	}
			else
			{	Space = SpaceAve;	}
		}
		else
		{
			if ( SpaceDif > CastLimitDifference )
			{	Space = SpaceMin;	}
			else
			{	Space = SpaceAve;	}
		}
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda2SpaceData_Joe_Kernel_01(const TPhaseNoiseParam &NoiseParam, int Raw1[], unsigned char Mask1, float Space1, int Raw2[], unsigned char Mask2, float Space2, unsigned char &Mask, float &Space)//合併2個高度
{
	int i=0, j=0;	
	float Range=0.0f;
	int MaxGroupCnt=0;
	float MinSpace=FLT_MAX;
	const int Count=2;
	int GroupCnt[Count]={0, 0};
	float GroupAve[Count]={0, 0};
	const MASK_DATA MaskList[Count]={Mask1, Mask2};
	const float SpaceList[Count]={Space1, Space2};
	const float CastValidDifference = NoiseParam.SpaceMultiCastValidDifference;

	for ( i=0; i<Count; i++ )
	{
		GroupCnt[i] = 1;
		GroupAve[i] = SpaceList[i];
		for ( j=0; j<Count; j++ )
		{
			if ( j == i ) { continue; }
			if ( SpaceList[j] < 0 ) { continue; }			
			if ( CheckCudaSpaceMaskValid_Kernel(MaskList[j]) == false ) { continue; }
			if ( fabs(SpaceList[j]-SpaceList[i]) < CastValidDifference )
			{
				GroupCnt[i] ++;
				GroupAve[i] += SpaceList[j];
			}
		}		
		//找群組內數量最多
		if ( MaxGroupCnt < GroupCnt[i] )
		{	MaxGroupCnt = GroupCnt[i];	}
		//平均群組高度
		GroupAve[i] = GroupAve[i]/GroupCnt[i];
	}

	if ( MaxGroupCnt > 1 )//群組內有2個以上
	{		
		//找群組數量相同以上但最低的平均高度
		MinSpace=FLT_MAX;
		for ( i=0; i<Count; i++ )
		{
			if ( MaxGroupCnt != GroupCnt[i] ) { continue; }
			if ( MinSpace > GroupAve[i] ) 
			{	MinSpace = GroupAve[i];	}
		}		
		Space = MinSpace;		
		Mask = PHASE_MASK_VALID_BEST;
		return true;		
	}

	float AList[Count]={0,0};
	float BList[Count]={0,0};
	float CVList[Count]={0,0};	
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw1[0], Raw1[1], Raw1[2], Raw1[3], AList[0], BList[0], CVList[0]);
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw2[0], Raw2[1], Raw2[2], Raw2[3], AList[1], BList[1], CVList[1]);	

	float MaxA=0, MaxB=0, MaxCV=0;
	int   idxMaxA=0, idxMaxB=0, idxMaxCV=0;

	MinSpace=FLT_MAX;
	for ( i=0; i<Count; i++ )
	{
		if ( MinSpace > SpaceList[i] ) 
		{	MinSpace = SpaceList[i];	}
		if ( 0==i || MaxA < AList[i] ) 
		{
			idxMaxA = i;
			MaxA = AList[i];
		}
		if ( 0==i || MaxB < BList[i] ) 
		{
			idxMaxB = i;
			MaxB = BList[i];
		}
		if ( 0==i || MaxCV < CVList[i] ) 
		{
			idxMaxCV = i;
			MaxCV = CVList[i];
		}
	}

	const float fLowPotential=GetPhaseNoiseMinB_Kernel(NoiseParam);
	if ( MaxB > fLowPotential )
	{
		Mask = PHASE_MASK_VALID;
		//Mask = MaskList[idxMaxCV];		
		Space = SpaceList[idxMaxCV];//注意不是使用MaxB的引數		
	}
	else
	{
		Space = MinSpace;
		Mask = PHASE_MASK_LOW_CONTRAST;		
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda2SpaceData_Joe_Kernel_02(const TPhaseNoiseParam &NoiseParam, int Raw1[], unsigned char Mask1, float Space1, int Raw2[], unsigned char Mask2, float Space2, unsigned char &Mask, float &Space)//合併2個高度
{
	//參數初始化
	int i = 0, j = 0;
	float Range = 0.0f;
	int MaxGroupCnt = 0;
	float MinSpace = FLT_MAX;
	const int Count = 2;									//-------數量必須確認-------
	int GroupCnt[Count] = { 0, 0 };							//-------數量必須確認-------
	float GroupAve[Count] = { 0, 0 };						//-------數量必須確認-------
	const MASK_DATA MaskList[Count] = { Mask1, Mask2 };		//-------數量必須確認-------
	const float SpaceList[Count] = { Space1, Space2 };		//-------數量必須確認-------

	//獲取高度融合參數
	const float CastValidDifference = NoiseParam.SpaceMultiCastValidDifference;	//高度分群範圍
	const float fLowPotential = GetPhaseNoiseMinB_Kernel(NoiseParam);			//B值
	const int ThreSaturated = NoiseParam.PhaseOverSaturatedA;					//飽和度
	const float thre_LessLight = fLowPotential * 10;							//弱光區

#pragma region 獲取A, B, CV, IsSat資訊
	float AList[Count] = { 0,0 };
	float BList[Count] = { 0,0 };
	float CVList[Count] = { 0,0 };
	bool IsSatList[Count] = { false,false };
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw1[0], Raw1[1], Raw1[2], Raw1[3], AList[0], BList[0], CVList[0]);
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw2[0], Raw2[1], Raw2[2], Raw2[3], AList[1], BList[1], CVList[1]);
	IsSatList[0] = CheckCuda4PhaseSaturated_Kernel(Raw1[0], Raw1[1], Raw1[2], Raw1[3], ThreSaturated);
	IsSatList[1] = CheckCuda4PhaseSaturated_Kernel(Raw2[0], Raw2[1], Raw2[2], Raw2[3], ThreSaturated);
#pragma endregion

#pragma region 尋找最大A, B, CV以及最小H, B
	float MaxA = 0, MaxB = 0, MaxCV = 0;
	float MinB = FLT_MAX;
	int   idxMaxA = 0, idxMaxB = 0, idxMaxCV = 0;
	int   idxMinH = 0, idxMinB = 0;
	MinSpace = FLT_MAX;
	for (i = 0; i<Count; i++)
	{
		if (MinSpace > SpaceList[i])
		{
			MinSpace = SpaceList[i];
			idxMinH = i;
		}
		if (0 == i || MaxA < AList[i])
		{
			idxMaxA = i;
			MaxA = AList[i];
		}
		if (0 == i || MaxB < BList[i])
		{
			idxMaxB = i;
			MaxB = BList[i];
		}
		if (0 == i || MaxCV < CVList[i])
		{
			idxMaxCV = i;
			MaxCV = CVList[i];
		}
		if (BList[i] > 0 && (0 == i || MinB > BList[i]))
		{
			idxMinB = i;
			MinB = BList[i];
		}
	}
#pragma endregion

#pragma region 高度分群
	for (i = 0; i<Count; i++)
	{
		GroupCnt[i] = 1;
		GroupAve[i] = SpaceList[i];
		for (j = 0; j<Count; j++)
		{
			if (j == i) { continue; }
			if (SpaceList[j] < 0) { continue; }
			if (CheckCudaSpaceMaskValid_Kernel(MaskList[j]) == false) { continue; }
			if (BList[idxMinB] < fLowPotential && fabs(SpaceList[j] - SpaceList[idxMinB]) < CastValidDifference) { continue; } //最小B為雜訊時，此高度不可進行分群
			if (fabs(SpaceList[j] - SpaceList[i]) < CastValidDifference)
			{
				GroupCnt[i] ++;
				GroupAve[i] += SpaceList[j];
			}
		}
		//找群組內數量最多
		if (MaxGroupCnt < GroupCnt[i])
		{
			MaxGroupCnt = GroupCnt[i];
		}
		//平均群組高度
		GroupAve[i] = GroupAve[i] / GroupCnt[i];
	}
#pragma endregion

	//如果最小高度不為雜訊就使用
	if (CheckCudaSpaceMaskValid_Kernel(MaskList[idxMinH]) == true &&	//最小高度不為雜訊(B、S、CV)
		//idxMinH != idxMinB &&											//最小高度不為最低B值(不穩定故不使用 - 20210423 Joe
		MaxGroupCnt < 1 &&												//高度分群可靠度低
		BList[idxMinB] < thre_LessLight &&								//此點位於弱光處
		!IsSatList[idxMinB]												//此點不為高反光處
		)
	{
		Mask = PHASE_MASK_VALID;
		Space = SpaceList[idxMinH];
	}
	else if (MaxGroupCnt > 1)//群組內有2個以上
	{
		//找群組數量相同以上但最低的平均高度
		MinSpace = FLT_MAX;
		for (i = 0; i<Count; i++)
		{
			if (MaxGroupCnt != GroupCnt[i]) { continue; }
			if (MinSpace > GroupAve[i])
			{
				MinSpace = GroupAve[i];
			}
		}
		Space = MinSpace;
		Mask = PHASE_MASK_VALID_BEST;
		return true;
	}
	else if (MaxB > fLowPotential)//如果最大B的含量 > 閥值fLowPotential，表示有高度資訊可用
	{
		Mask = PHASE_MASK_VALID;
		if (BList[idxMaxCV] < fLowPotential)
		{
			Space = SpaceList[idxMaxB];
		}
		else
		{
			//Mask = MaskList[idxMaxCV];		
			Space = SpaceList[idxMaxCV];//注意不是使用MaxB的引數		
		}
	}
	else
	{
		Space = MinSpace;
		//Space = 0.0f;
		Mask = PHASE_MASK_LOW_CONTRAST;
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda2SpaceData_Joe_Kernel(const TPhaseNoiseParam &NoiseParam, int Raw1[], unsigned char Mask1, float Space1, int Raw2[], unsigned char Mask2, float Space2, unsigned char &Mask, float &Space)//合併2個高度
{
	if ( glUseNewMergeSpaceDataJoe )
	{	return MergeCuda2SpaceData_Joe_Kernel_02(NoiseParam, Raw1, Mask1, Space1, Raw2, Mask2, Space2, Mask, Space); }
	return MergeCuda2SpaceData_Joe_Kernel_01(NoiseParam, Raw1, Mask1, Space1, Raw2, Mask2, Space2, Mask, Space);
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda3SpaceData_Kernel(const TPhaseNoiseParam &NoiseParam, unsigned char Mask1, float Space1, unsigned char Mask2, float Space2, unsigned char Mask3, float Space3, unsigned char &Mask, float &Space)//合併3個高度
{	
	int   i=0, j=0;
	int   index = 0;
	int   useCount = 0;
	int   Count=0;	
	int   groupUseCount = 0;
	int   GroupCntList[3]={0,0,0};		
	float SpaceList[3]={0,0,0};
	float SpaceValid[3]={0,0,0};	
	float GroupSumList[3]={0,0,0};
	float GroupMinList[3]={0,0,0};	
	float GroupMaxList[3]={0,0,0};	
	float GroupAveList[3]={0,0,0};	
	float SpaceSortList[3]={0,0,0};	
	float GroupDif=0, GroupMax=0, GroupMin=0;
	float SpaceU=0, SpaceL=0, SpaceOther=0, SpaceULDif=0;	
	float SpaceMin=0, SpaceMax=0, SpaceAve=0, SpaceDif=0, SpaceSum=0;
	const int   CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int   MinValidCount = NoiseParam.SpaceMultiCastMinValidCount;	
	const float CastMaxDifference = NoiseParam.SpaceMultiCastMaxDifference;
	const float CastLimitDifference = NoiseParam.SpaceMultiCastLimitDifference;		
	const int   CastOppositeMaxGray = NoiseParam.SpaceMultiCastOppositeMaxGray;
	const float SpaceLowLimit = NoiseParam.SpaceSingleCastLowLimit;
	const float CastLimitDifference2 = CastLimitDifference*2;		
	const float CastGroupRange = CastMaxDifference*1.0;
	const float ZeroPlaneOffset = NoiseParam.PhaseZeroPlaneOffsetPosZ/2;

	SpaceList[0] = Space1;
	SpaceList[1] = Space2;
	SpaceList[2] = Space3;

	useCount = 0;
	SpaceSum = 0;
	SpaceMin = FLT_MAX;
	SpaceMax =-FLT_MAX;
	Mask = PHASE_MASK_VALID;
	if ( (Mask1&PHASE_MASK_NOISE) != NULL || Space1<SpaceLowLimit)
	{	Mask = Mask1;	}
	else
	{		
		SpaceValid[useCount] = Space1;
		if ( SpaceMax < SpaceValid[useCount] ) { SpaceMax = SpaceValid[useCount]; }
		if ( SpaceMin > SpaceValid[useCount] ) { SpaceMin = SpaceValid[useCount]; }
		SpaceSum += SpaceValid[useCount];
		useCount ++;	
	}
		
	if ( (Mask2&PHASE_MASK_NOISE) != NULL || Space2<SpaceLowLimit)
	{	Mask = Mask2;	}
	else
	{		
		SpaceValid[useCount] = Space2;
		if ( SpaceMax < SpaceValid[useCount] ) { SpaceMax = SpaceValid[useCount]; }
		if ( SpaceMin > SpaceValid[useCount] ) { SpaceMin = SpaceValid[useCount]; }
		SpaceSum += SpaceValid[useCount];
		useCount ++;			
	}

	if ( (Mask3&PHASE_MASK_NOISE) != NULL || Space3<SpaceLowLimit)
	{	Mask = Mask3;	}
	else
	{
		SpaceValid[useCount] = Space3;
		if ( SpaceMax < SpaceValid[useCount] ) { SpaceMax = SpaceValid[useCount]; }
		if ( SpaceMin > SpaceValid[useCount] ) { SpaceMin = SpaceValid[useCount]; }
		SpaceSum += SpaceValid[useCount];
		useCount ++;	
	}
				
	if ( useCount == 0 ) 
	{
		if ( PHASE_MASK_VALID == Mask )
		{	Mask = PHASE_MASK_OVER_LOW;	}			
		if ( MULTI_CAST_MERGE_MODE_MASS_3==CastMergeMode ||MULTI_CAST_MERGE_MODE_MASS_4==CastMergeMode)
		{	Space = 0; }
		else if ( MULTI_CAST_MERGE_MODE_MEDIAN==CastMergeMode )
		{	GeometryMedianCudaSpaceHeight_Kernel(SpaceList, 3, ZeroPlaneOffset, Space);	}
		else
		{	Space = (Space1+Space2+Space3)/3; }
		return true;
	}
	Mask = PHASE_MASK_VALID;
	SpaceDif = SpaceMax-SpaceMin;
	SpaceAve = (SpaceSum)/useCount;
	if ( useCount < MinValidCount )
	{
		Mask = PHASE_MASK_HEIGHT_UNEXPECTED;
		if ( MULTI_CAST_MERGE_MODE_MASS_3==CastMergeMode ||MULTI_CAST_MERGE_MODE_MASS_4==CastMergeMode)
		{	Space = 0; }
		else if ( MULTI_CAST_MERGE_MODE_MEDIAN==CastMergeMode )
		{	GeometryMedianCudaSpaceHeight_Kernel(SpaceList, 3, ZeroPlaneOffset, Space);	}
		else
		{	Space = SpaceAve; }
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_LOWEST == CastMergeMode )
	{
		Space = SpaceMin;
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_MASS_3 == CastMergeMode )
	{	
		if ( 2 == useCount )
		{
			Space = MIN(SpaceValid[0], SpaceValid[1]);
			return true;
		}
		for ( j=0; j<useCount; j++ )
		{	SpaceSortList[j] = SpaceValid[j]; }
		SortCudaSpcaeHeight_Kernel(SpaceSortList, useCount);		
		//GroupCudaSpcaeHeightByMean_Kernel(SpaceSortList, CastGroupRange, GroupAveList, GroupCntList, useCount, groupUseCount);
		GroupCudaSpcaeHeightByRange_Kernel(SpaceSortList, CastGroupRange, GroupMinList, GroupMaxList, GroupAveList, GroupCntList, useCount, groupUseCount);
		index = GetCudaMassGroupIndex_Kernel(GroupCntList, groupUseCount);		
		Space = GroupAveList[index];
		if ( groupUseCount == useCount )//群組數等同於有效數
		{	Space = SpaceAve;	}
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_MASS_4 == CastMergeMode )
	{	
		if ( 2 == useCount )
		{
			Space = MIN(SpaceValid[0], SpaceValid[1]);
			return true;
		}
		for ( j=0; j<useCount; j++ )
		{	SpaceSortList[j] = SpaceValid[j]; }
		SortCudaSpcaeHeight_Kernel(SpaceSortList, useCount);		
		GroupCudaSpcaeHeightByMean_Kernel(SpaceSortList, CastGroupRange, GroupAveList, GroupCntList, useCount, groupUseCount);
		//GroupCudaSpcaeHeightByRange_Kernel(SpaceSortList, CastGroupRange, GroupMinList, GroupMaxList, GroupAveList, GroupCntList, useCount, groupUseCount);
		index = GetCudaMassGroupIndex_Kernel(GroupCntList, groupUseCount);		
		Space = GroupAveList[index];		
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_MEDIAN == CastMergeMode )
	{	
		if ( useCount < 3 ) 
		{	GeometryMedianCudaSpaceHeight_Kernel(SpaceList, 3, ZeroPlaneOffset, Space);	}
		else
		{	GeometryMedianCudaSpaceHeight_Kernel(SpaceValid, useCount, ZeroPlaneOffset, Space);	}
		return true;
	}

	if ( SpaceDif<CastMaxDifference )
	{	Space = SpaceAve;	}
	else
	{	
		if ( 1==useCount )
		{
			if ( MULTI_CAST_MERGE_MODE_MASS_2 == CastMergeMode )
			{	Space = SpaceMin; }
			else
			{	Space = SpaceAve;	}
		}
		else if ( 2==useCount )
		{
			if ( SpaceDif > CastLimitDifference )
			{	Space = SpaceMin;	}
			else
			{	Space = SpaceAve;	}
		}
		else
		{					
			if ( SpaceDif > CastLimitDifference2 )
			{	
				//Space = SpaceMin;	
				if ( MULTI_CAST_MERGE_MODE_MASS_2 == CastMergeMode )
				{	Space = SpaceMin;	}
				else
				{	Space = (SpaceSum-SpaceMin-SpaceMax)/(useCount-2); }
			}
			else if ( SpaceDif > CastLimitDifference )
			{	Space = (SpaceSum-SpaceMin-SpaceMax)/(useCount-2);	}
			else
			{
				SpaceU = SpaceMax-SpaceAve;
				SpaceL = SpaceAve-SpaceMin;
				SpaceULDif = fabs(SpaceU-SpaceL);
				SpaceOther = SpaceSum-SpaceMax-SpaceMin;
				if ( SpaceULDif < (CastMaxDifference/2) )
				{	Space = SpaceAve;	}
				else
				{
					if ( SpaceU > SpaceL )//平均以上差距較大, 剔除最大值
					{
						GroupMin = SpaceMin;
						GroupDif = SpaceOther-SpaceMin;
						Space = (SpaceSum-SpaceMax)/(useCount-1);	
					}
					else
					{
						GroupMin = SpaceOther;
						GroupDif = SpaceMax-SpaceOther;
						Space = (SpaceSum-SpaceMin)/(useCount-1);	
					}
					if ( GroupDif > CastLimitDifference )
					{	Space = GroupMin;	}
				}
				//Space = (Space1+Space2+Space3-SpaceMax-SpaceMin)/(useCount-2); 
			}
		}
		//Space = SpaceMin;
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda3SpaceData_Joe_Kernel_01(const TPhaseNoiseParam &NoiseParam, int Raw1[], unsigned char Mask1, float Space1, int Raw2[], unsigned char Mask2, float Space2, int Raw3[], unsigned char Mask3, float Space3, unsigned char &Mask, float &Space)//合併3個高度
{
	int i=0, j=0;	
	float Range=0.0f;
	int MaxGroupCnt=0;
	float MinSpace=FLT_MAX;
	const int Count=3;
	int GroupCnt[Count]={0, 0, 0};
	float GroupAve[Count]={0, 0, 0};
	const MASK_DATA MaskList[Count]={Mask1, Mask2, Mask3};
	const float SpaceList[Count]={Space1, Space2, Space3};
	const float CastValidDifference = NoiseParam.SpaceMultiCastValidDifference;

	for ( i=0; i<Count; i++ )
	{
		GroupCnt[i] = 1;
		GroupAve[i] = SpaceList[i];
		for ( j=0; j<Count; j++ )
		{
			if ( j == i ) { continue; }
			if ( SpaceList[j] < 0 ) { continue; }			
			if ( CheckCudaSpaceMaskValid_Kernel(MaskList[j]) == false ) { continue; }
			if ( fabs(SpaceList[j]-SpaceList[i]) < CastValidDifference )
			{
				GroupCnt[i] ++;
				GroupAve[i] += SpaceList[j];
			}
		}		
		//找群組內數量最多
		if ( MaxGroupCnt < GroupCnt[i] )
		{	MaxGroupCnt = GroupCnt[i];	}
		//平均群組高度
		GroupAve[i] = GroupAve[i]/GroupCnt[i];
	}

	if ( MaxGroupCnt > 1 )//群組內有2個以上
	{		
		//找群組數量相同以上但最低的平均高度
		MinSpace=FLT_MAX;
		for ( i=0; i<Count; i++ )
		{
			if ( MaxGroupCnt != GroupCnt[i] ) { continue; }
			if ( MinSpace > GroupAve[i] ) 
			{	MinSpace = GroupAve[i];	}
		}		
		Space = MinSpace;		
		Mask = PHASE_MASK_VALID_BEST;
		return true;		
	}

	float AList[Count]={0,0,0};
	float BList[Count]={0,0,0};
	float CVList[Count]={0,0,0};	
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw1[0], Raw1[1], Raw1[2], Raw1[3], AList[0], BList[0], CVList[0]);
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw2[0], Raw2[1], Raw2[2], Raw2[3], AList[1], BList[1], CVList[1]);
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw3[0], Raw3[1], Raw3[2], Raw3[3], AList[2], BList[2], CVList[2]);	

	float MaxA=0, MaxB=0, MaxCV=0;
	int   idxMaxA=0, idxMaxB=0, idxMaxCV=0;

	MinSpace=FLT_MAX;
	for ( i=0; i<Count; i++ )
	{
		if ( MinSpace > SpaceList[i] ) 
		{	MinSpace = SpaceList[i];	}
		if ( 0==i || MaxA < AList[i] ) 
		{
			idxMaxA = i;
			MaxA = AList[i];
		}
		if ( 0==i || MaxB < BList[i] ) 
		{
			idxMaxB = i;
			MaxB = BList[i];
		}
		if ( 0==i || MaxCV < CVList[i] ) 
		{
			idxMaxCV = i;
			MaxCV = CVList[i];
		}
	}
	
	const float fLowPotential=GetPhaseNoiseMinB_Kernel(NoiseParam);
	if ( MaxB > fLowPotential )
	{
		Mask = PHASE_MASK_VALID;
		//Mask = MaskList[idxMaxCV];		
		Space = SpaceList[idxMaxCV];//注意不是使用MaxB的引數		
	}
	else
	{
		Space = MinSpace;
		Mask = PHASE_MASK_LOW_CONTRAST;		
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda3SpaceData_Joe_Kernel_02(const TPhaseNoiseParam &NoiseParam, int Raw1[], unsigned char Mask1, float Space1, int Raw2[], unsigned char Mask2, float Space2, int Raw3[], unsigned char Mask3, float Space3, unsigned char &Mask, float &Space)//合併3個高度
{
	//參數初始化
	int i = 0, j = 0;
	float Range = 0.0f;
	int MaxGroupCnt = 0;
	float MinSpace = FLT_MAX;
	const int Count = 3;												//-------數量必須確認-------
	int GroupCnt[Count] = { 0, 0, 0 };									//-------數量必須確認-------
	float GroupAve[Count] = { 0, 0, 0 };								//-------數量必須確認-------
	const MASK_DATA MaskList[Count] = { Mask1, Mask2, Mask3 };			//-------數量必須確認-------
	const float SpaceList[Count] = { Space1, Space2, Space3 };			//-------數量必須確認-------

	//獲取高度融合參數
	const float CastValidDifference = NoiseParam.SpaceMultiCastValidDifference;	//高度分群範圍
	const float fLowPotential = GetPhaseNoiseMinB_Kernel(NoiseParam);			//B值
	const int ThreSaturated = NoiseParam.PhaseOverSaturatedA;					//飽和度
	const float thre_LessLight = fLowPotential * 10;							//弱光區

#pragma region 獲取A, B, CV, IsSat資訊
	float AList[Count] = { 0,0,0 };
	float BList[Count] = { 0,0,0 };
	float CVList[Count] = { 0,0,0 };
	bool IsSatList[Count] = { false,false,false };
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw1[0], Raw1[1], Raw1[2], Raw1[3], AList[0], BList[0], CVList[0]);
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw2[0], Raw2[1], Raw2[2], Raw2[3], AList[1], BList[1], CVList[1]);
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw3[0], Raw3[1], Raw3[2], Raw3[3], AList[2], BList[2], CVList[2]);
	IsSatList[0] = CheckCuda4PhaseSaturated_Kernel(Raw1[0], Raw1[1], Raw1[2], Raw1[3], ThreSaturated);
	IsSatList[1] = CheckCuda4PhaseSaturated_Kernel(Raw2[0], Raw2[1], Raw2[2], Raw2[3], ThreSaturated);
	IsSatList[2] = CheckCuda4PhaseSaturated_Kernel(Raw3[0], Raw3[1], Raw3[2], Raw3[3], ThreSaturated);
#pragma endregion

#pragma region 尋找最大A, B, CV以及最小H, B
	float MaxA = 0, MaxB = 0, MaxCV = 0;
	float MinB = FLT_MAX;
	int   idxMaxA = 0, idxMaxB = 0, idxMaxCV = 0;
	int   idxMinH = 0, idxMinB = 0;
	MinSpace = FLT_MAX;
	for (i = 0; i<Count; i++)
	{
		if (MinSpace > SpaceList[i])
		{
			MinSpace = SpaceList[i];
			idxMinH = i;
		}
		if (0 == i || MaxA < AList[i])
		{
			idxMaxA = i;
			MaxA = AList[i];
		}
		if (0 == i || MaxB < BList[i])
		{
			idxMaxB = i;
			MaxB = BList[i];
		}
		if (0 == i || MaxCV < CVList[i])
		{
			idxMaxCV = i;
			MaxCV = CVList[i];
		}
		if (BList[i] > 0 && (0 == i || MinB > BList[i]))
		{
			idxMinB = i;
			MinB = BList[i];
		}
	}
#pragma endregion

#pragma region 高度分群
	for (i = 0; i<Count; i++)
	{
		GroupCnt[i] = 1;
		GroupAve[i] = SpaceList[i];
		for (j = 0; j<Count; j++)
		{
			if (j == i) { continue; }
			if (SpaceList[j] < 0) { continue; }
			if (CheckCudaSpaceMaskValid_Kernel(MaskList[j]) == false) { continue; }
			if (BList[idxMinB] < fLowPotential && fabs(SpaceList[j] - SpaceList[idxMinB]) < CastValidDifference) { continue; } //最小B為雜訊時，此高度不可進行分群
			if (fabs(SpaceList[j] - SpaceList[i]) < CastValidDifference)
			{
				GroupCnt[i] ++;
				GroupAve[i] += SpaceList[j];
			}
		}
		//找群組內數量最多
		if (MaxGroupCnt < GroupCnt[i])
		{
			MaxGroupCnt = GroupCnt[i];
		}
		//平均群組高度
		GroupAve[i] = GroupAve[i] / GroupCnt[i];
	}
#pragma endregion

	//如果最小高度不為雜訊就使用
	if (CheckCudaSpaceMaskValid_Kernel(MaskList[idxMinH]) == true &&	//最小高度不為雜訊(B、S、CV)
		//idxMinH != idxMinB &&											//最小高度不為最低B值(不穩定故不使用 - 20210423 Joe
		MaxGroupCnt < 2 &&												//高度分群可靠度低
		BList[idxMinB] < thre_LessLight &&								//此點位於弱光處
		!IsSatList[idxMinB]												//此點不為高反光處
		)
	{
		Mask = PHASE_MASK_VALID;
		Space = SpaceList[idxMinH];
	}
	else if (MaxGroupCnt > 1)//群組內有2個以上
	{
		//找群組數量相同以上但最低的平均高度
		MinSpace = FLT_MAX;
		for (i = 0; i<Count; i++)
		{
			if (MaxGroupCnt != GroupCnt[i]) { continue; }
			if (MinSpace > GroupAve[i])
			{
				MinSpace = GroupAve[i];
			}
		}
		Space = MinSpace;
		Mask = PHASE_MASK_VALID_BEST;
		return true;
	}
	else if (MaxB > fLowPotential)//如果最大B的含量 > 閥值fLowPotential，表示有高度資訊可用
	{
		Mask = PHASE_MASK_VALID;
		if (BList[idxMaxCV] < fLowPotential)
		{
			Space = SpaceList[idxMaxB];
		}
		else
		{
			//Mask = MaskList[idxMaxCV];		
			Space = SpaceList[idxMaxCV];//注意不是使用MaxB的引數		
		}
	}
	else
	{
		Space = MinSpace;
		//Space = 0.0f;
		Mask = PHASE_MASK_LOW_CONTRAST;
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda3SpaceData_Joe_Kernel(const TPhaseNoiseParam &NoiseParam, int Raw1[], unsigned char Mask1, float Space1, int Raw2[], unsigned char Mask2, float Space2, int Raw3[], unsigned char Mask3, float Space3, unsigned char &Mask, float &Space)//合併3個高度
{
	if ( glUseNewMergeSpaceDataJoe )
	{	return MergeCuda3SpaceData_Joe_Kernel_02(NoiseParam, Raw1, Mask1, Space1, Raw2, Mask2, Space2, Raw3, Mask3, Space3, Mask, Space); }
	return MergeCuda3SpaceData_Joe_Kernel_01(NoiseParam, Raw1, Mask1, Space1, Raw2, Mask2, Space2, Raw3, Mask3, Space3, Mask, Space);
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda4SpaceData_Kernel(const TPhaseNoiseParam &NoiseParam, unsigned char Mask1, float Space1, unsigned char Mask2, float Space2, unsigned char Mask3, float Space3, unsigned char Mask4, float Space4, unsigned char &Mask, float &Space)//合併4個高度
{		
	int   i=0, j=0;
	int   index = 0;
	int   useCount = 0;
	int   Count=0;
	int   groupUseCount = 0;
	int   GroupCntList[4]={0,0,0,0};		
	float SpaceList[4]={0,0,0,0};
	float SpaceValid[4]={0,0,0,0};	
	float GroupSumList[4]={0,0,0,0};
	float GroupMinList[4]={0,0,0,0};	
	float GroupMaxList[4]={0,0,0,0};	
	float GroupAveList[4]={0,0,0,0};	
	float SpaceSortList[4]={0,0,0,0};			
	float GroupDif=0, GroupMax=0, GroupMin=0;	
	float SpaceU=0, SpaceL=0, SpaceOther=0, SpaceULDif=0;	
	float SpaceMin=0, SpaceMax=0, SpaceAve=0, SpaceDif=0, SpaceSum=0;
	const int   CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int   MinValidCount = NoiseParam.SpaceMultiCastMinValidCount;	
	const float CastMaxDifference = NoiseParam.SpaceMultiCastMaxDifference;
	const float CastLimitDifference = NoiseParam.SpaceMultiCastLimitDifference;		
	const int   CastOppositeMaxGray = NoiseParam.SpaceMultiCastOppositeMaxGray;
	const float SpaceLowLimit = NoiseParam.SpaceSingleCastLowLimit;
	const float CastLimitDifference2 = CastLimitDifference*2;		
	const float CastGroupRange = CastMaxDifference*1.0;
	const float ZeroPlaneOffset = NoiseParam.PhaseZeroPlaneOffsetPosZ/2;

	SpaceList[0] = Space1;
	SpaceList[1] = Space2;
	SpaceList[2] = Space3;
	SpaceList[3] = Space4;

	useCount = 0;
	SpaceSum = 0;
	SpaceMin = FLT_MAX;
	SpaceMax =-FLT_MAX;
	Mask = PHASE_MASK_VALID;
	if ( (Mask1&PHASE_MASK_NOISE) != NULL || Space1<SpaceLowLimit)
	{	Mask = Mask1;	}
	else
	{
		SpaceValid[useCount] = Space1;
		if ( SpaceMax < SpaceValid[useCount] ) { SpaceMax = SpaceValid[useCount]; }
		if ( SpaceMin > SpaceValid[useCount] ) { SpaceMin = SpaceValid[useCount]; }
		SpaceSum += SpaceValid[useCount];
		useCount ++;		
	}

	if ( (Mask2&PHASE_MASK_NOISE) != NULL || Space2<SpaceLowLimit)
	{	Mask = Mask2;	}
	else
	{
		SpaceValid[useCount] = Space2;
		if ( SpaceMax < SpaceValid[useCount] ) { SpaceMax = SpaceValid[useCount]; }
		if ( SpaceMin > SpaceValid[useCount] ) { SpaceMin = SpaceValid[useCount]; }
		SpaceSum += SpaceValid[useCount];
		useCount ++;
	}
		
	if ( (Mask3&PHASE_MASK_NOISE) != NULL || Space3<SpaceLowLimit)
	{	Mask = Mask3;	}
	else
	{		
		SpaceValid[useCount] = Space3;
		if ( SpaceMax < SpaceValid[useCount] ) { SpaceMax = SpaceValid[useCount]; }
		if ( SpaceMin > SpaceValid[useCount] ) { SpaceMin = SpaceValid[useCount]; }
		SpaceSum += SpaceValid[useCount];
		useCount ++;
	}
		
	if ( (Mask4&PHASE_MASK_NOISE) != NULL || Space4<SpaceLowLimit)
	{	Mask = Mask4;	}
	else
	{		
		SpaceValid[useCount] = Space4;
		if ( SpaceMax < SpaceValid[useCount] ) { SpaceMax = SpaceValid[useCount]; }
		if ( SpaceMin > SpaceValid[useCount] ) { SpaceMin = SpaceValid[useCount]; }
		SpaceSum += SpaceValid[useCount];
		useCount ++;
	}	
	if ( useCount == 0 ) 
	{
		if ( PHASE_MASK_VALID == Mask )
		{	Mask = PHASE_MASK_OVER_LOW;	}
		if ( MULTI_CAST_MERGE_MODE_MASS_3==CastMergeMode ||MULTI_CAST_MERGE_MODE_MASS_4==CastMergeMode)
		{	Space = 0; }
		else if ( MULTI_CAST_MERGE_MODE_MEDIAN==CastMergeMode )
		{	GeometryMedianCudaSpaceHeight_Kernel(SpaceList, 4, ZeroPlaneOffset, Space);	}
		else
		{	Space = (Space1+Space2+Space3+Space4)/4; }		
		return true;
	}

	Mask = PHASE_MASK_VALID;
	SpaceDif = SpaceMax-SpaceMin;
	SpaceAve = (SpaceSum)/useCount;
	if ( useCount < MinValidCount )
	{
		Mask = PHASE_MASK_HEIGHT_UNEXPECTED;
		if ( MULTI_CAST_MERGE_MODE_MASS_3==CastMergeMode ||MULTI_CAST_MERGE_MODE_MASS_4==CastMergeMode)
		{	Space = 0; }
		else if ( MULTI_CAST_MERGE_MODE_MEDIAN==CastMergeMode )
		{	GeometryMedianCudaSpaceHeight_Kernel(SpaceList, 4, ZeroPlaneOffset, Space);	}
		else
		{	Space = SpaceAve; }
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_LOWEST == CastMergeMode )
	{
		Space = SpaceMin;
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_MASS_3 == CastMergeMode )
	{	
		if ( 2 == useCount )
		{
			Space = MIN(SpaceValid[0], SpaceValid[1]);
			return true;
		}
		for ( j=0; j<useCount; j++ )
		{	SpaceSortList[j] = SpaceValid[j]; }
		SortCudaSpcaeHeight_Kernel(SpaceSortList, useCount);		
		//GroupCudaSpcaeHeightByMean_Kernel(SpaceSortList, CastGroupRange, GroupAveList, GroupCntList, useCount, groupUseCount);
		GroupCudaSpcaeHeightByRange_Kernel(SpaceSortList, CastGroupRange, GroupMinList, GroupMaxList, GroupAveList, GroupCntList, useCount, groupUseCount);
		index = GetCudaMassGroupIndex_Kernel(GroupCntList, groupUseCount);		
		Space = GroupAveList[index];
		if ( groupUseCount == useCount )//群組數等同於有效數
		{	Space = SpaceAve;	}
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_MASS_4 == CastMergeMode )
	{	
		if ( 2 == useCount )
		{
			Space = MIN(SpaceValid[0], SpaceValid[1]);
			return true;
		}
		for ( j=0; j<useCount; j++ )
		{	SpaceSortList[j] = SpaceValid[j]; }
		SortCudaSpcaeHeight_Kernel(SpaceSortList, useCount);		
		GroupCudaSpcaeHeightByMean_Kernel(SpaceSortList, CastGroupRange, GroupAveList, GroupCntList, useCount, groupUseCount);
		//GroupCudaSpcaeHeightByRange_Kernel(SpaceSortList, CastGroupRange, GroupMinList, GroupMaxList, GroupAveList, GroupCntList, useCount, groupUseCount);
		index = GetCudaMassGroupIndex_Kernel(GroupCntList, groupUseCount);		
		Space = GroupAveList[index];		
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_MEDIAN == CastMergeMode )
	{	
		if ( useCount < 3 ) 
		{	GeometryMedianCudaSpaceHeight_Kernel(SpaceList, 4, ZeroPlaneOffset, Space);	}
		else
		{	GeometryMedianCudaSpaceHeight_Kernel(SpaceValid, useCount, ZeroPlaneOffset, Space);	}
		return true;
	}
	if ( SpaceDif<CastMaxDifference )
	{	Space = SpaceAve;	}
	else
	{
		if ( 1==useCount )
		{
			if ( MULTI_CAST_MERGE_MODE_MASS_2 == CastMergeMode )
			{	Space = SpaceMin;	}
			else
			{	Space = SpaceAve;	}
		}
	    else if ( 2==useCount )
		{
			if ( MULTI_CAST_MERGE_MODE_MASS_2 == CastMergeMode )
			{	Space = SpaceMin;	}
			else
			{
				if ( SpaceDif > CastLimitDifference2 )
				{	Space = SpaceMin;	}
				else if ( SpaceDif > CastLimitDifference )
				{	Space = SpaceMin;	}
				else
				{	Space = SpaceAve; }
			}
		}
		else if ( 3 == useCount )
		{
			if ( SpaceDif > CastLimitDifference2 )
			{	
				//Space = SpaceMin;	
				if ( MULTI_CAST_MERGE_MODE_MASS_2 == CastMergeMode )
				{	Space = SpaceMin;	}
				else
				{	Space = (SpaceSum-SpaceMin-SpaceMax)/(useCount-2);}
			}
			else if ( SpaceDif > CastLimitDifference )
			{	Space = (SpaceSum-SpaceMin-SpaceMax)/(useCount-2);	}
			else
			{
				SpaceU = SpaceMax-SpaceAve;
				SpaceL = SpaceAve-SpaceMin;
				SpaceULDif = fabs(SpaceU-SpaceL);
				SpaceOther = SpaceSum-SpaceMax-SpaceMin;
				if ( SpaceULDif < (CastMaxDifference/2) )
				{	Space = SpaceAve;	}
				else
				{
					if ( SpaceU > SpaceL )//平均以上差距較大, 剔除最大值
					{
						GroupMin = SpaceMin;
						GroupDif = SpaceOther-SpaceMin;
						Space = (SpaceSum-SpaceMax)/(useCount-1);	
					}
					else
					{
						GroupMin = SpaceOther;
						GroupDif = SpaceMax-SpaceOther;
						Space = (SpaceSum-SpaceMin)/(useCount-1);	
					}
					if ( GroupDif > CastLimitDifference )
					{	Space = GroupMin;	}
				}					
			}
		}
		else
		{	
			SpaceSortList[0] = SpaceMin;
			SpaceSortList[1] = -1;
			SpaceSortList[2] = -1;
			SpaceSortList[3] = SpaceMax;
			for ( j=0; j<useCount; j++ )
			{
				if ( SpaceValid[j] == SpaceMin ) { continue; }
				if ( SpaceValid[j] == SpaceMax ) { continue; }
				if ( SpaceSortList[1] < 0 )
				{	SpaceSortList[1] = SpaceValid[j];	}
				else
				{
					if ( SpaceSortList[1] < SpaceValid[j] )
					{	SpaceSortList[2] = SpaceValid[j];	}
					else
					{
						SpaceSortList[2] = SpaceSortList[1];
						SpaceSortList[1] = SpaceValid[j];
					}
				}					
			}
			//分群
			GroupCntList[0]=GroupCntList[1]=GroupCntList[2]=GroupCntList[3]=0;
			GroupSumList[0]=GroupSumList[1]=GroupSumList[2]=GroupSumList[3]=0;
			GroupAveList[0]=GroupAveList[1]=GroupAveList[2]=GroupAveList[3]=0;	
				
			groupUseCount = 0;
			GroupCntList[groupUseCount] = 1;
			GroupSumList[groupUseCount] = SpaceSortList[0];
			GroupAveList[groupUseCount] = GroupSumList[groupUseCount]/GroupCntList[groupUseCount];
			for ( j=1; j<useCount; j++ )
			{
				GroupDif = SpaceSortList[j]-GroupAveList[groupUseCount];
				if ( GroupDif < CastGroupRange )
				{
					GroupCntList[groupUseCount] ++;
					GroupSumList[groupUseCount] += SpaceSortList[j];
					GroupAveList[groupUseCount] = GroupSumList[groupUseCount]/GroupCntList[groupUseCount];
				}
				else
				{
					groupUseCount ++;
					GroupCntList[groupUseCount] = 1;
					GroupSumList[groupUseCount] = SpaceSortList[j];
					GroupAveList[groupUseCount] = GroupSumList[groupUseCount]/GroupCntList[groupUseCount];
				}
			}
			groupUseCount ++;
				
			if ( 4 == groupUseCount )//表示各自群組, 取中間兩個平均
			{
				if ( SpaceDif > CastLimitDifference2 )
				{	
					//Space = SpaceMin;	
					Space = (SpaceSum-SpaceMax-SpaceMin)/(useCount-2);//剃除過高跟過低
				}
				else if ( SpaceDif > CastLimitDifference )
				{						
					Space = (SpaceSum-SpaceMax-SpaceMin)/(useCount-2);//剃除過高跟過低
				}
				else
				{	Space = SpaceAve;	 }				
			}
			else
			{
				//找眾數的群組				
				Count = GroupCntList[0];
				Space = GroupAveList[0];
				for ( j=1; j<groupUseCount; j++ )
				{
					if ( Count < GroupCntList[j] ) 
					{
						Count = GroupCntList[j];
						Space = GroupAveList[j];
					}
				}					
			}
			//Space = (SpaceSum-SpaceMax-SpaceMin)/(useCount-2); 
		}
		//Space = SpaceMin;
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda4SpaceData_Joe_Kernel_01(const TPhaseNoiseParam &NoiseParam, int Raw1[], unsigned char Mask1, float Space1, int Raw2[], unsigned char Mask2, float Space2, int Raw3[], unsigned char Mask3, float Space3, int Raw4[], unsigned char Mask4, float Space4, unsigned char &Mask, float &Space)//合併4個高度
{
	int i=0, j=0;	
	float Range=0.0f;
	int MaxGroupCnt=0;
	float MinSpace=FLT_MAX;
	const int Count=4;
	int GroupCnt[Count]={0, 0, 0, 0};
	float GroupAve[Count]={0, 0, 0, 0};
	const MASK_DATA MaskList[Count]={Mask1, Mask2, Mask3, Mask4};
	const float SpaceList[Count]={Space1, Space2, Space3, Space4};
	const float CastValidDifference = NoiseParam.SpaceMultiCastValidDifference;

	for ( i=0; i<Count; i++ )
	{
		GroupCnt[i] = 1;
		GroupAve[i] = SpaceList[i];
		for ( j=0; j<Count; j++ )
		{
			if ( j == i ) { continue; }
			if ( SpaceList[j] < 0 ) { continue; }			
			if ( CheckCudaSpaceMaskValid_Kernel(MaskList[j]) == false ) { continue; }
			if ( fabs(SpaceList[j]-SpaceList[i]) < CastValidDifference )
			{
				GroupCnt[i] ++;
				GroupAve[i] += SpaceList[j];
			}
		}		
		//找群組內數量最多
		if ( MaxGroupCnt < GroupCnt[i] )
		{	MaxGroupCnt = GroupCnt[i];	}
		//平均群組高度
		GroupAve[i] = GroupAve[i]/GroupCnt[i];
	}

	if ( MaxGroupCnt > 1 )//群組內有2個以上
	{		
		//找群組數量相同以上但最低的平均高度
		MinSpace=FLT_MAX;
		for ( i=0; i<Count; i++ )
		{
			if ( MaxGroupCnt != GroupCnt[i] ) { continue; }
			if ( MinSpace > GroupAve[i] ) 
			{	MinSpace = GroupAve[i];	}
		}		
		Space = MinSpace;		
		Mask = PHASE_MASK_VALID_BEST;
		return true;		
	}

	float AList[Count]={0,0,0,0};
	float BList[Count]={0,0,0,0};
	float CVList[Count]={0,0,0,0};	
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw1[0], Raw1[1], Raw1[2], Raw1[3], AList[0], BList[0], CVList[0]);
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw2[0], Raw2[1], Raw2[2], Raw2[3], AList[1], BList[1], CVList[1]);
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw3[0], Raw3[1], Raw3[2], Raw3[3], AList[2], BList[2], CVList[2]);
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw4[0], Raw4[1], Raw4[2], Raw4[3], AList[3], BList[3], CVList[3]);

	float MaxA=0, MaxB=0, MaxCV=0;
	int   idxMaxA=0, idxMaxB=0, idxMaxCV=0;

	MinSpace=FLT_MAX;
	for ( i=0; i<Count; i++ )
	{
		if ( MinSpace > SpaceList[i] ) 
		{	MinSpace = SpaceList[i];	}
		if ( 0==i || MaxA < AList[i] ) 
		{
			idxMaxA = i;
			MaxA = AList[i];
		}
		if ( 0==i || MaxB < BList[i] ) 
		{
			idxMaxB = i;
			MaxB = BList[i];
		}
		if ( 0==i || MaxCV < CVList[i] ) 
		{
			idxMaxCV = i;
			MaxCV = CVList[i];
		}
	}
	
	const float fLowPotential=GetPhaseNoiseMinB_Kernel(NoiseParam);
	if ( MaxB > fLowPotential )
	{
		Mask = PHASE_MASK_VALID;
		//Mask = MaskList[idxMaxCV];		
		Space = SpaceList[idxMaxCV];//注意不是使用MaxB的引數		
	}
	else
	{
		Space = MinSpace;
		Mask = PHASE_MASK_LOW_CONTRAST;		
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda4SpaceData_Joe_Kernel_02(const TPhaseNoiseParam &NoiseParam, int Raw1[], unsigned char Mask1, float Space1, int Raw2[], unsigned char Mask2, float Space2, int Raw3[], unsigned char Mask3, float Space3, int Raw4[], unsigned char Mask4, float Space4, unsigned char &Mask, float &Space)//合併4個高度
{
	//參數初始化
	int i = 0, j = 0;
	float Range = 0.0f;
	int MaxGroupCnt = 0;
	float MinSpace = FLT_MAX;
	const int Count = 4;												//-------數量必須確認-------
	int GroupCnt[Count] = { 0, 0, 0, 0 };								//-------數量必須確認-------
	float GroupAve[Count] = { 0, 0, 0, 0 };								//-------數量必須確認-------
	const MASK_DATA MaskList[Count] = { Mask1, Mask2, Mask3, Mask4 };	//-------數量必須確認-------
	const float SpaceList[Count] = { Space1, Space2, Space3, Space4 };	//-------數量必須確認-------

	//獲取高度融合參數
	const float CastValidDifference = NoiseParam.SpaceMultiCastValidDifference;	//高度分群範圍
	const float fLowPotential = GetPhaseNoiseMinB_Kernel(NoiseParam);			//B值
	const int ThreSaturated = NoiseParam.PhaseOverSaturatedA;					//飽和度
	const float thre_LessLight = fLowPotential * 10;							//弱光區

#pragma region 獲取A, B, CV, IsSat資訊
	float AList[Count] = { 0,0,0,0 };
	float BList[Count] = { 0,0,0,0 };
	float CVList[Count] = { 0,0,0,0 };
	bool IsSatList[Count] = { false,false,false,false };
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw1[0], Raw1[1], Raw1[2], Raw1[3], AList[0], BList[0], CVList[0]);
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw2[0], Raw2[1], Raw2[2], Raw2[3], AList[1], BList[1], CVList[1]);
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw3[0], Raw3[1], Raw3[2], Raw3[3], AList[2], BList[2], CVList[2]);
	CalcCuda4PhaseMeanContrastRatio_Kernel(Raw4[0], Raw4[1], Raw4[2], Raw4[3], AList[3], BList[3], CVList[3]);
	IsSatList[0] = CheckCuda4PhaseSaturated_Kernel(Raw1[0], Raw1[1], Raw1[2], Raw1[3], ThreSaturated);
	IsSatList[1] = CheckCuda4PhaseSaturated_Kernel(Raw2[0], Raw2[1], Raw2[2], Raw2[3], ThreSaturated);
	IsSatList[2] = CheckCuda4PhaseSaturated_Kernel(Raw3[0], Raw3[1], Raw3[2], Raw3[3], ThreSaturated);
	IsSatList[3] = CheckCuda4PhaseSaturated_Kernel(Raw4[0], Raw4[1], Raw4[2], Raw4[3], ThreSaturated);
#pragma endregion

#pragma region 尋找最大A, B, CV以及最小H, B
	float MaxA = 0, MaxB = 0, MaxCV = 0;
	float MinB = FLT_MAX;
	int   idxMaxA = 0, idxMaxB = 0, idxMaxCV = 0;
	int   idxMinH = 0, idxMinB = 0;
	MinSpace = FLT_MAX;
	for (i = 0; i<Count; i++)
	{
		if (MinSpace > SpaceList[i])
		{
			MinSpace = SpaceList[i];
			idxMinH = i;
		}
		if (0 == i || MaxA < AList[i])
		{
			idxMaxA = i;
			MaxA = AList[i];
		}
		if (0 == i || MaxB < BList[i])
		{
			idxMaxB = i;
			MaxB = BList[i];
		}
		if (0 == i || MaxCV < CVList[i])
		{
			idxMaxCV = i;
			MaxCV = CVList[i];
		}
		if (BList[i] > 0 && (0 == i || MinB > BList[i]))
		{
			idxMinB = i;
			MinB = BList[i];
		}
	}
#pragma endregion

#pragma region 高度分群
	for (i = 0; i<Count; i++)
	{
		GroupCnt[i] = 1;
		GroupAve[i] = SpaceList[i];
		for (j = 0; j<Count; j++)
		{
			if (j == i) { continue; }
			if (SpaceList[j] < 0) { continue; }
			if (CheckCudaSpaceMaskValid_Kernel(MaskList[j]) == false) { continue; }
			if (BList[idxMinB] < fLowPotential && fabs(SpaceList[j] - SpaceList[idxMinB]) < CastValidDifference) { continue; } //最小B為雜訊時，此高度不可進行分群
			if (fabs(SpaceList[j] - SpaceList[i]) < CastValidDifference)
			{
				GroupCnt[i] ++;
				GroupAve[i] += SpaceList[j];
			}
		}
		//找群組內數量最多
		if (MaxGroupCnt < GroupCnt[i])
		{
			MaxGroupCnt = GroupCnt[i];
		}
		//平均群組高度
		GroupAve[i] = GroupAve[i] / GroupCnt[i];
	}
#pragma endregion

	//如果最小高度不為雜訊就使用
	if (CheckCudaSpaceMaskValid_Kernel(MaskList[idxMinH]) == true &&	//最小高度不為雜訊(B、S、CV)
		//idxMinH != idxMinB &&											//最小高度不為最低B值(不穩定故不使用 - 20210423 Joe
		MaxGroupCnt < 3 &&												//高度分群可靠度低
		BList[idxMinB] < thre_LessLight &&								//此點位於弱光處
		!IsSatList[idxMinB]												//此點不為高反光處
		)
	{
		Mask = PHASE_MASK_VALID;
		Space = SpaceList[idxMinH];
	}
	else if (MaxGroupCnt > 1)//群組內有2個以上
	{
		//找群組數量相同以上但最低的平均高度
		MinSpace = FLT_MAX;
		for (i = 0; i<Count; i++)
		{
			if (MaxGroupCnt != GroupCnt[i]) { continue; }
			if (MinSpace > GroupAve[i])
			{
				MinSpace = GroupAve[i];
			}
		}
		Space = MinSpace;
		Mask = PHASE_MASK_VALID_BEST;
		return true;
	}
	else if (MaxB > fLowPotential)//如果最大B的含量 > 閥值fLowPotential，表示有高度資訊可用
	{
		Mask = PHASE_MASK_VALID;
		if (BList[idxMaxCV] < fLowPotential)
		{
			Space = SpaceList[idxMaxB];
		}
		else
		{
			//Mask = MaskList[idxMaxCV];		
			Space = SpaceList[idxMaxCV];//注意不是使用MaxB的引數		
		}
	}
	else
	{
		Space = MinSpace;
		//Space = 0.0f;
		Mask = PHASE_MASK_LOW_CONTRAST;
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCuda4SpaceData_Joe_Kernel(const TPhaseNoiseParam &NoiseParam, int Raw1[], unsigned char Mask1, float Space1, int Raw2[], unsigned char Mask2, float Space2, int Raw3[], unsigned char Mask3, float Space3, int Raw4[], unsigned char Mask4, float Space4, unsigned char &Mask, float &Space)//合併4個高度
{
	if ( glUseNewMergeSpaceDataJoe )
	{	return MergeCuda4SpaceData_Joe_Kernel_02(NoiseParam, Raw1, Mask1, Space1, Raw2, Mask2, Space2, Raw3, Mask3, Space3, Raw4, Mask4, Space4, Mask, Space); }
	return MergeCuda4SpaceData_Joe_Kernel_01(NoiseParam, Raw1, Mask1, Space1, Raw2, Mask2, Space2, Raw3, Mask3, Space3, Raw4, Mask4, Space4, Mask, Space);
}
//------------------------------------------------------------------------------//
__device__ bool MergeCudaNSpaceData_Debug_Kernel(unsigned int idx, const TPhaseNoiseParam &NoiseParam, const unsigned char MaskList[], const float SpaceList[], int SpaceCount, unsigned char &Mask, float &Space)//合併N個高度
{
	const int SpaceCnt=SpaceCount;	
	const int MaxSpaceCount = MULTI_CAST_PATCH_MAX_COUNT;	
	if ( SpaceCnt > MaxSpaceCount ) { return false; }	
//#ifdef _CUDA_USE_DEBUG_PARAM
	if ( 6293504 == idx )
	{		
		debugIntList[0] = SpaceCnt;
		debugIntList[1] = MaxSpaceCount;
	}
//#endif//_CUDA_USE_DEBUG_PARAM

	int       i=0;
	int       Count=0;
	int       j=0;
	int       index=0;
	int       useCount=0;	
	int       groupUseCount=0;
	int       SpaceMaxID=0;
	int       SpaceMinID=0;	
	float     GroupDif=0, GroupMax=0, GroupMin=0;	
	float     SpaceU=0, SpaceL=0, SpaceOther=0, SpaceULDif=0;	
	float     SpaceMax=-FLT_MAX, SpaceMin=FLT_MAX, SpaceAve=0, SpaceDif=0, SpaceSum=0;		
	
	MASK_DATA MaskValid[MaxSpaceCount];
	float     SpaceValid[MaxSpaceCount];
	int       GroupCntList[MaxSpaceCount];	
	float     GroupMinList[MaxSpaceCount];
	float     GroupMaxList[MaxSpaceCount];
	float     GroupSumList[MaxSpaceCount];
	float     GroupAveList[MaxSpaceCount];
	float     SpaceSortList[MaxSpaceCount];

	const int   CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int   MinValidCount = NoiseParam.SpaceMultiCastMinValidCount;	
	const float CastMaxDifference = NoiseParam.SpaceMultiCastMaxDifference;
	const float CastLimitDifference = NoiseParam.SpaceMultiCastLimitDifference;		
	const int   CastOppositeMaxGray = NoiseParam.SpaceMultiCastOppositeMaxGray;
	const float SpaceLowLimit = NoiseParam.SpaceSingleCastLowLimit;
	const float CastLimitDifference2 = CastLimitDifference*2;		
	const float CastGroupRange = CastMaxDifference*1.0;

	useCount = 0;
	SpaceDif = 0;
	SpaceMax = -FLT_MAX;
	SpaceMin =  FLT_MAX;
	Mask = PHASE_MASK_VALID;
	for ( i=0; i<SpaceCount; i++ )
	{
		MaskValid[i] = 0;
		SpaceValid[i] = 0;
		//SpaceSortList[i] = 0.0;
		GroupCntList[i] = 0;
		GroupMinList[i] = GroupMaxList[i] = GroupSumList[i] = GroupAveList[i] = SpaceSortList[i] = 0.0;
		
		if ( (MaskList[i]&PHASE_MASK_NOISE)!=NULL || SpaceList[i]<SpaceLowLimit )
		{	Mask = MaskList[i];	}
		else
		{			
			MaskValid[useCount] = MaskList[i];
			SpaceValid[useCount] = SpaceList[i];
			if ( SpaceMax < SpaceValid[useCount] ) { SpaceMax = SpaceValid[useCount]; }
			if ( SpaceMin > SpaceValid[useCount] ) { SpaceMin = SpaceValid[useCount]; }						
			SpaceSum += SpaceValid[useCount];
			SpaceSortList[useCount] = SpaceValid[useCount];
			useCount ++;			
		}		
	}		
	if ( useCount == 0 ) 
	{
		if ( PHASE_MASK_VALID == Mask )
		{	Mask = PHASE_MASK_OVER_LOW;	}
		if ( MULTI_CAST_MERGE_MODE_MASS_3==CastMergeMode ||MULTI_CAST_MERGE_MODE_MASS_4==CastMergeMode)
		{	Space = 0; }
		else
		{	Space = AverageCudaSpcaeHeight_Kernel(SpaceList, SpaceCnt);	}
		return true;
	}	

	Mask = PHASE_MASK_VALID;
	SpaceDif = SpaceMax-SpaceMin;
	SpaceAve = (SpaceSum)/useCount;
	Space = SpaceAve ;		
	if ( useCount < MinValidCount )
	{
		Mask = PHASE_MASK_HEIGHT_UNEXPECTED;
		if ( MULTI_CAST_MERGE_MODE_MASS_3==CastMergeMode ||MULTI_CAST_MERGE_MODE_MASS_4==CastMergeMode)
		{	Space = 0; }
		else
		{	Space = SpaceAve; }	
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_LOWEST == CastMergeMode )
	{
		Space = SpaceMin;
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_MASS_3 == CastMergeMode )
	{	
		if ( 2 == useCount )
		{
			Space = MIN(SpaceValid[0], SpaceValid[1]);
			return true;
		}				
		SortCudaSpcaeHeight_Kernel(SpaceSortList, useCount);		
		//GroupCudaSpcaeHeightByMean_Kernel(SpaceSortList, CastGroupRange, GroupAveList, GroupCntList, useCount, groupUseCount);
		GroupCudaSpcaeHeightByRange_Kernel(SpaceSortList, CastGroupRange, GroupMinList, GroupMaxList, GroupAveList, GroupCntList, useCount, groupUseCount);
		index = GetCudaMassGroupIndex_Kernel(GroupCntList, groupUseCount);		
		Space = GroupAveList[index];
		if ( groupUseCount == useCount )//群組數等同於有效數
		{	Space = SpaceAve;	}		
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_MASS_4 == CastMergeMode )
	{	
		if ( 2 == useCount )
		{
			Space = MIN(SpaceValid[0], SpaceValid[1]);					
			return true;
		}
		SortCudaSpcaeHeight_Kernel(SpaceSortList, useCount);		
		GroupCudaSpcaeHeightByMean_Kernel(SpaceSortList, CastGroupRange, GroupAveList, GroupCntList, useCount, groupUseCount);
		//GroupCudaSpcaeHeightByRange_Kernel(SpaceSortList, CastGroupRange, GroupMinList, GroupMaxList, GroupAveList, GroupCntList, useCount, groupUseCount);
		index = GetCudaMassGroupIndex_Kernel(GroupCntList, groupUseCount);		
		Space = GroupAveList[index];		
		return true;
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCudaNSpaceData_General_Kernel(unsigned int idx, const TPhaseNoiseParam &NoiseParam, const unsigned char MaskList[], const float SpaceList[], int SpaceCount, unsigned char &Mask, float &Space)//合併N個高度
{
	const int SpaceCnt=SpaceCount;	
	const int MaxSpaceCount = MULTI_CAST_PATCH_MAX_COUNT;	
	if ( SpaceCnt > MaxSpaceCount ) { return false; }	

	size_t    i=0;
	size_t    Count=0;
	int       j=0;
	int       index=0;
	int       useCount=0;	
	int       groupUseCount=0;
	int       SpaceMaxID=0;
	int       SpaceMinID=0;	
	float     GroupDif=0, GroupMax=0, GroupMin=0;	
	float     SpaceU=0, SpaceL=0, SpaceOther=0, SpaceULDif=0;	
	float     SpaceMax=-FLT_MAX, SpaceMin=FLT_MAX, SpaceAve=0, SpaceDif=0, SpaceSum=0;		
	
	MASK_DATA MaskValid[MaxSpaceCount];
	float     SpaceValid[MaxSpaceCount];
	int       GroupCntList[MaxSpaceCount];	
	float     GroupMinList[MaxSpaceCount];
	float     GroupMaxList[MaxSpaceCount];
	float     GroupSumList[MaxSpaceCount];
	float     GroupAveList[MaxSpaceCount];
	float     SpaceSortList[MaxSpaceCount];

	const int   CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int   MinValidCount = NoiseParam.SpaceMultiCastMinValidCount;	
	const float CastMaxDifference = NoiseParam.SpaceMultiCastMaxDifference;
	const float CastLimitDifference = NoiseParam.SpaceMultiCastLimitDifference;		
	const int   CastOppositeMaxGray = NoiseParam.SpaceMultiCastOppositeMaxGray;
	const float SpaceLowLimit = NoiseParam.SpaceSingleCastLowLimit;
	const float CastLimitDifference2 = CastLimitDifference*2;		
	const float CastGroupRange = CastMaxDifference*1.0;

	SpaceDif = 0;
	SpaceMax = -FLT_MAX;
	SpaceMin =  FLT_MAX;
	Mask = PHASE_MASK_VALID;	
	for ( i=0; i<SpaceCount; i++ )
	{
		MaskValid[i] = 0;
		SpaceValid[i] = 0;
		GroupCntList[i] = 0;
		GroupMinList[i] = GroupMaxList[i] = GroupSumList[i] = GroupAveList[i] = SpaceSortList[i] = 0.0;

		if ( (MaskList[i]&PHASE_MASK_NOISE)!=NULL || SpaceList[i]<SpaceLowLimit )
		{	Mask = MaskList[i];	}
		else
		{
			MaskValid[useCount] = MaskList[i];
			SpaceValid[useCount] = SpaceList[i];
			if ( SpaceMax < SpaceValid[useCount] ) { SpaceMax = SpaceValid[useCount]; }
			if ( SpaceMin > SpaceValid[useCount] ) { SpaceMin = SpaceValid[useCount]; }						
			SpaceSum += SpaceValid[useCount];
			SpaceSortList[useCount] = SpaceValid[useCount];

			useCount ++;
		}		
	}

	if ( useCount == 0 ) 
	{
		if ( PHASE_MASK_VALID == Mask )
		{	Mask = PHASE_MASK_OVER_LOW;	}
		if ( MULTI_CAST_MERGE_MODE_MASS_3==CastMergeMode ||MULTI_CAST_MERGE_MODE_MASS_4==CastMergeMode)
		{	Space = 0; }
		else
		{	Space = AverageCudaSpcaeHeight_Kernel(SpaceList, SpaceCnt);	}			
		return true;
	}	

	Mask = PHASE_MASK_VALID;
	SpaceDif = SpaceMax-SpaceMin;
	SpaceAve = (SpaceSum)/useCount;
	Space = SpaceAve ;	
	if ( useCount < MinValidCount )
	{
		Mask = PHASE_MASK_HEIGHT_UNEXPECTED;
		if ( MULTI_CAST_MERGE_MODE_MASS_3==CastMergeMode ||MULTI_CAST_MERGE_MODE_MASS_4==CastMergeMode)
		{	Space = 0; }
		else
		{	Space = SpaceAve; }
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_LOWEST == CastMergeMode )
	{
		Space = SpaceMin;
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_MASS_3 == CastMergeMode )
	{	
		if ( 2 == useCount )
		{
			Space = MIN(SpaceValid[0], SpaceValid[1]);
			return true;
		}				
		SortCudaSpcaeHeight_Kernel(SpaceSortList, useCount);		
		//GroupCudaSpcaeHeightByMean_Kernel(SpaceSortList, CastGroupRange, GroupAveList, GroupCntList, useCount, groupUseCount);
		GroupCudaSpcaeHeightByRange_Kernel(SpaceSortList, CastGroupRange, GroupMinList, GroupMaxList, GroupAveList, GroupCntList, useCount, groupUseCount);
		index = GetCudaMassGroupIndex_Kernel(GroupCntList, groupUseCount);		
		Space = GroupAveList[index];
		if ( groupUseCount == useCount )//群組數等同於有效數
		{	Space = SpaceAve;	}		
		return true;
	}
	if ( MULTI_CAST_MERGE_MODE_MASS_4 == CastMergeMode )
	{	
		if ( 2 == useCount )
		{
			Space = MIN(SpaceValid[0], SpaceValid[1]);
			return true;
		}
		SortCudaSpcaeHeight_Kernel(SpaceSortList, useCount);		
		GroupCudaSpcaeHeightByMean_Kernel(SpaceSortList, CastGroupRange, GroupAveList, GroupCntList, useCount, groupUseCount);
		//GroupCudaSpcaeHeightByRange_Kernel(SpaceSortList, CastGroupRange, GroupMinList, GroupMaxList, GroupAveList, GroupCntList, useCount, groupUseCount);
		index = GetCudaMassGroupIndex_Kernel(GroupCntList, groupUseCount);		
		Space = GroupAveList[index];		
		return true;
	}
	if ( SpaceDif<CastMaxDifference )
	{	Space = SpaceAve;	}
	else
	{
		if ( 1==useCount )
		{
			if ( MULTI_CAST_MERGE_MODE_MASS_2 == CastMergeMode )
			{	Space = SpaceMin;	}
			else
			{	Space = SpaceAve;	}
		}
	    else if ( 2==useCount )
		{
			if ( MULTI_CAST_MERGE_MODE_MASS_2 == CastMergeMode )
			{	Space = SpaceMin;	}
			else
			{
				if ( SpaceDif > CastLimitDifference2 )
				{	Space = SpaceMin;	}
				else if ( SpaceDif > CastLimitDifference )
				{	Space = SpaceMin;	}
				else
				{	Space = SpaceAve; }
			}
		}
		else if ( 3 == useCount )
		{
			if ( SpaceDif > CastLimitDifference2 )
			{	
				//Space = SpaceMin;	
				if ( MULTI_CAST_MERGE_MODE_MASS_2 == CastMergeMode )
				{	Space = SpaceMin;	}
				else
				{	Space = (SpaceSum-SpaceMin-SpaceMax)/(useCount-2);}
			}
			else if ( SpaceDif > CastLimitDifference )
			{	Space = (SpaceSum-SpaceMin-SpaceMax)/(useCount-2);	}
			else
			{
				SpaceU = SpaceMax-SpaceAve;
				SpaceL = SpaceAve-SpaceMin;
				SpaceULDif = fabs(SpaceU-SpaceL);
				SpaceOther = SpaceSum-SpaceMax-SpaceMin;
				if ( SpaceULDif < (CastMaxDifference/2) )
				{	Space = SpaceAve;	}
				else
				{
					if ( SpaceU > SpaceL )//平均以上差距較大, 剔除最大值
					{
						GroupMin = SpaceMin;
						GroupDif = SpaceOther-SpaceMin;
						Space = (SpaceSum-SpaceMax)/(useCount-1);	
					}
					else
					{
						GroupMin = SpaceOther;
						GroupDif = SpaceMax-SpaceOther;
						Space = (SpaceSum-SpaceMin)/(useCount-1);	
					}
					if ( GroupDif > CastLimitDifference )
					{	Space = GroupMin;	}
				}					
			}
		}
		else
		{				
			SortCudaSpcaeHeight_Kernel(SpaceSortList, useCount);		
			GroupCudaSpcaeHeightByMean_Kernel(SpaceSortList, CastGroupRange, GroupAveList, GroupCntList, useCount, groupUseCount);
			//GroupCudaSpcaeHeightByRange_Kernel(SpaceSortList, CastGroupRange, GroupMinList, GroupMaxList, GroupAveList, GroupCntList, useCount, groupUseCount);
			if ( SpaceCount == groupUseCount )//表示各自群組, 取中間兩個平均			
			{
				if ( SpaceDif > CastLimitDifference2 )
				{	
					//Space = SpaceMin;	
					Space = (SpaceSum-SpaceMax-SpaceMin)/(useCount-2);//剃除過高跟過低
				}
				else if ( SpaceDif > CastLimitDifference )
				{						
					Space = (SpaceSum-SpaceMax-SpaceMin)/(useCount-2);//剃除過高跟過低
				}
				else
				{	Space = SpaceAve;	 }				
			}
			else
			{
				//找眾數的群組				
				Count = GroupCntList[0];
				Space = GroupAveList[0];
				for ( j=1; j<groupUseCount; j++ )
				{
					if ( Count < GroupCntList[j] ) 
					{
						Count = GroupCntList[j];
						Space = GroupAveList[j];
					}
				}					
			}
			//Space = (SpaceSum-SpaceMax-SpaceMin)/(useCount-2); 
		}
		//Space = SpaceMin;
	}	
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCudaNSpaceData_Median_Kernel(unsigned int idx, const TPhaseNoiseParam &NoiseParam, const unsigned char MaskList[], const float SpaceList[], int SpaceCount, unsigned char &Mask, float &Space)//合併N個高度
{
	const int SpaceCnt=SpaceCount;
	const int MaxSpaceCount = MULTI_CAST_PATCH_MAX_COUNT;	
	if ( SpaceCnt > MaxSpaceCount ) { return false; }

	int    i=0;
	int    Count=0;	
	int    useCount=0;		

	MASK_DATA MaskValid[MaxSpaceCount];
	float     SpaceValid[MaxSpaceCount];	

	const int   CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int   MinValidCount = NoiseParam.SpaceMultiCastMinValidCount;	
	const float CastMaxDifference = NoiseParam.SpaceMultiCastMaxDifference;
	const float CastLimitDifference = NoiseParam.SpaceMultiCastLimitDifference;		
	const int   CastOppositeMaxGray = NoiseParam.SpaceMultiCastOppositeMaxGray;
	const float SpaceLowLimit = NoiseParam.SpaceSingleCastLowLimit;
	const float CastLimitDifference2 = CastLimitDifference*2;		
	const float CastGroupRange = CastMaxDifference*1.0;
	const float ZeroPlaneOffset = NoiseParam.PhaseZeroPlaneOffsetPosZ/2;
	
	Mask = PHASE_MASK_VALID;
	for ( i=0; i<SpaceCount; i++ )
	{
		MaskValid[i] = 0;
		SpaceValid[i] = 0;
		if ( (MaskList[i]&PHASE_MASK_NOISE)!=NULL || SpaceList[i]<SpaceLowLimit )
		{	Mask = MaskList[i];	}
		else
		{
			MaskValid[useCount] = MaskList[i];
			SpaceValid[useCount] = SpaceList[i];
			useCount ++;
		}		
	}
	if ( useCount == 0 ) 	
	{
		if ( PHASE_MASK_VALID == Mask )
		{	Mask = PHASE_MASK_OVER_LOW;	}		
		if ( GeometryMedianCudaSpaceHeight_Kernel(SpaceList, SpaceCnt, ZeroPlaneOffset, Space) == false )
		{	return false; }
		return true;
	}
	Mask = PHASE_MASK_VALID;
	if ( useCount < 3 )//1, 2, 
	{
		if ( GeometryMedianCudaSpaceHeight_Kernel(SpaceList, SpaceCnt, ZeroPlaneOffset, Space) == false )
		{	return false; }
	}
	else
	{
		if ( GeometryMedianCudaSpaceHeight_Kernel(SpaceValid, useCount, ZeroPlaneOffset, Space) == false )
		{	return false; }
	}
	return true;
}
//------------------------------------------------------------------------------//
__device__ bool MergeCudaNSpaceData_Kernel(unsigned int idx, const TPhaseNoiseParam &NoiseParam, const unsigned char MaskList[], const float SpaceList[], int SpaceCount, unsigned char &Mask, float &Space)//合併N個高度
{
	bool        bIsOK = true;
	const int   CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	//bIsOK = MergeCudaNSpaceData_Debug_Kernel(idx, NoiseParam, MaskList, SpaceList, SpaceCount, Mask, Space);
	if ( MULTI_CAST_MERGE_MODE_MEDIAN == CastMergeMode ) 
	{	bIsOK = MergeCudaNSpaceData_Median_Kernel(idx, NoiseParam, MaskList, SpaceList, SpaceCount, Mask, Space); }
	else
	{	bIsOK = MergeCudaNSpaceData_General_Kernel(idx, NoiseParam, MaskList, SpaceList, SpaceCount, Mask, Space); }
	return bIsOK;
}
