			dB4 = GammaTable[dB4];		
		}

		BinThreshold=(dA1+dA2+dA3+dA4)/4.0f;
		BinThreshold=(float)(BinThreshold*ExpTimeRatio);
		CalcCuda4GrayCodeParam_kernel(dB1, dB2, dB3, dB4, BinThreshold, CodeMap1, CodeMap2, k1, k2);	
		/*
		Code = 0x00;
