__global__ void ExecCudaSolvePhase45GCFrames2Phase_Kernel(const unsigned char *ImgDA1, const unsigned char *ImgDA2, const unsigned char *ImgDA3, const unsigned char *ImgDA4, const unsigned char *ImgDB1, const unsigned char *ImgDB2, const unsigned char *ImgDB3, const unsigned char *ImgDB4, const unsigned char *ImgDB5, const short *pBasePhaseD, double PA, double PB, int ExpTimeA, int ExpTimeB, unsigned int ImageSize, float Gamma, TPhaseNoiseParam NoiseParam, unsigned char *pMaskD, short *pPhaseD)//4步+GC雙相位
{
	unsigned int i=0;	
	int   dA1=0, dA2=0, dA3=0, dA4=0;
	int   dB1=0, dB2=0, dB3=0, dB4=0, dB5=0;	
	int   phaseA=0;	
	unsigned char MaskA=0;
	
	int Phase1 = 0;
	int Phase2 = 0;
	int PhaseM = 0;
	int PhaseMT = 0;		
	int PhaseMNew = 0;
	int PhaseMFull = 0;
	int PhaseMFullNew = 0;		
	float BinThreshold=0;
	float dRatio1 = 0;	
	//double dRatio2 = 0;
	float dGamma=1.0f;	
	unsigned char GammaTable[256];
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;		
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;	
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const float ExpTimeRatio = (float)(ExpTimeB*1.0f/ExpTimeA);

	int           k1=0, k2=0;
	//unsigned char Code=0x00;
	//unsigned char Code1=0x00;
	//unsigned char Code2=0x00;
	const int MaxN=16;//最多16個16週期			
	const int Period=PHASE_PERIOD;
	const int PeriodQar1=Period/4;
	const int PeriodQar3=3*Period/4;
	const int FullPeriodM = (int)(MaxN*Period);//以第1週期為主的大週期	
	const bool bGrayCodeInvert=false;//16G->32G->64G->128G->256B	
	const int CodeMapSize=32;
	unsigned char CodeMap1[CodeMapSize];
	unsigned char CodeMap2[CodeMapSize];
	for ( i=0; i<CodeMapSize; i++ )
	{	CodeMap1[i] = CodeMap2[i] = 0;	}	
	BuildCudaGrayCodeMapTable_Kernel(4, CodeMap1, CodeMapSize);
	BuildCudaGrayCodeMapTable_Kernel(5, CodeMap2, CodeMapSize);	

	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用	
	short *PPtrM = pPhaseD;	
	unsigned char *MPtrM = pMaskD;
	const int ShortPeriod = PHASE_MAX;

	const double NewP = PA*MaxN;
	//CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1, P2, dRatio1);
	if ( true == bUseGamma )
	{
		for ( i=0; i<256; i++ )
		{
			dGamma = i;		
			dGamma = dGamma/255.0f;
			dGamma = pow(dGamma, Gamma);		
			dGamma = dGamma*255.0f;
			GammaTable[i] = (unsigned char)(dGamma);
		}
	}
//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{
		if ( i >= ImageSize ) { continue; }

		dA1 = ImgDA1[i];
		dA2 = ImgDA2[i];
		dA3 = ImgDA3[i]; 
		dA4 = ImgDA4[i];

		dB1 = ImgDB1[i];
		dB2 = ImgDB2[i];
		dB3 = ImgDB3[i];
		dB4 = ImgDB4[i];
		dB5 = ImgDB5[i];		

		if ( true == bUseGamma )
		{
			dA1 = GammaTable[dA1];
			dA2 = GammaTable[dA2];
			dA3 = GammaTable[dA3];
			dA4 = GammaTable[dA4];

			dB1 = GammaTable[dB1];
			dB2 = GammaTable[dB2];
			dB3 = GammaTable[dB3];
			dB4 = GammaTable[dB4];
			dB5 = GammaTable[dB5];
		}

		BinThreshold=(dA1+dA2+dA3+dA4)/4.0f;
		BinThreshold=(float)(BinThreshold*ExpTimeRatio);
		CalcCuda5GrayCodeParam_kernel(dB1, dB2, dB3, dB4, dB5, BinThreshold, CodeMap1, CodeMap2, k1, k2);	
		/*
		Code = 0x00;
		Code1 = Code2 = Code;		
		if ( dB1 > BinThreshold ) 
		{	Code2 |= 0x01;	}
		if ( dB2 > BinThreshold ) 
		{	
			Code1 |= 0x01;	
			Code2 |= 0x02;	
		}		
		if ( dB3 > BinThreshold ) 
		{	
			Code1 |= 0x02;	
			Code2 |= 0x04;	
		}
		if ( dB4 > BinThreshold ) 
		{	
			Code1 |= 0x04;	
			Code2 |= 0x08;	
		}
		if ( dB5 > BinThreshold ) 
		{	
			Code1 |= 0x08;	
			Code2 |= 0x10;	
		}
		k1 = CodeMap1[Code1];
		k2 = CodeMap2[Code2];
		k2 = (k2+1)/2;
		*/
		CalcCuda4PhaseParamMask_kernel(dA1, dA2, dA3, dA4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA, MaskA, PhaseNoiseDefMode);
		
		PhaseMT = phaseA;		
		if ( PhaseMT < PeriodQar1 ) 
		{	PhaseM=PhaseMT+(Period*k2); }
		else if ( PhaseMT > PeriodQar3 ) 
		{	PhaseM=PhaseMT+(Period*k2)-(Period); }
		else
		{	PhaseM=PhaseMT+(Period*k1); }		
		PhaseM = (PhaseM/MaxN);
		if ( PhaseM > Period )
		{	PhaseM -= Period; }
		
		//PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseB, phaseA, dRatio1);
		if ( NULL != pBasePhaseD )
		{
			PhaseM -= pBasePhaseD[i];
			if ( PhaseM < 0 ) 
			{	PhaseM += ShortPeriod; }
			else if ( PhaseM >= ShortPeriod ) 
			{	PhaseM -= ShortPeriod; }	
		}
		MPtrM[i] = MaskA;
		PPtrM[i] = static_cast<PHASE_DATA>(PhaseM);		
	}
}
