__global__ void ExecCudaSolvePhase4Frames_Kernel(const unsigned char *ImgD1, const unsigned char *ImgD2, const unsigned char *ImgD3, const unsigned char *ImgD4, short *pPhaseD, unsigned char *pMaskD, unsigned int ImageSize, int PatternID, float Gamma, TPhaseNoiseParam NoiseParam)
{
	unsigned int i=0;	
	int   d1=0, d2=0, d3=0, d4=0;
	int   usePhase=0;		
	//short    phase=0;
//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	int   Contrast=0;
	float dGamma=1.0f;	
	unsigned char GammaTable[256];
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;		
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	int LowContrast = NoiseParam.PhaseLowContrastA;
	int LowPotential = NoiseParam.PhaseLowPotentialA;
	int Saturation = NoiseParam.PhaseOverSaturatedA;
	if ( PHASE_PATTERN_B == PatternID )
	{
		LowContrast = NoiseParam.PhaseLowContrastB;
		LowPotential = NoiseParam.PhaseLowPotentialB;
		Saturation = NoiseParam.PhaseOverSaturatedB;
	}
	if ( PHASE_PATTERN_C == PatternID )
	{
		LowContrast = NoiseParam.PhaseLowContrastC;
		LowPotential = NoiseParam.PhaseLowPotentialC;
		Saturation = NoiseParam.PhaseOverSaturatedC;
	}
	if ( true == bUseGamma )
	{
		for ( i=0; i<256; i++ )
		{
			dGamma = i;		
			dGamma = dGamma/255.0f;
			dGamma = pow(dGamma, Gamma);		
			dGamma = dGamma*255.0f;
			GammaTable[i] = (unsigned char)(dGamma);
		}
	}
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{
		if ( i >= ImageSize ) { continue; }

		d1 = ImgD1[i];
		d2 = ImgD2[i];
		d3 = ImgD3[i]; 
		d4 = ImgD4[i];

		if ( true == bUseGamma )
		{
			d1 = GammaTable[d1];
			d2 = GammaTable[d2];
			d3 = GammaTable[d3];
			d4 = GammaTable[d4];
		}
		CalcCuda4PhaseParamMask_kernel(d1, d2, d3, d4, PhaseNoiseDef, LowContrast, LowPotential, Saturation, usePhase, pMaskD[i], PhaseNoiseDefMode);		
		pPhaseD[i] = (PHASE_DATA)(usePhase);
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSolvePhase4Frames2Phase_Kernel(const unsigned char *ImgDA1, const unsigned char *ImgDA2, const unsigned char *ImgDA3, const unsigned char *ImgDA4, const unsigned char *ImgDB1, const unsigned char *ImgDB2, const unsigned char *ImgDB3, const unsigned char *ImgDB4, const short *pBasePhaseD, double PA, double PB, unsigned int ImageSize, float Gamma, TPhaseNoiseParam NoiseParam, unsigned char *pMaskD, short *pPhaseD)//四步雙相位
{
	unsigned int i=0;	
	int   dA1=0, dA2=0, dA3=0, dA4=0;
	int   dB1=0, dB2=0, dB3=0, dB4=0;	
	int   phaseA=0;
	int   phaseB=0;
	unsigned char MaskA=0, MaskB=0;
	
	int Phase1 = 0;
	int Phase2 = 0;
	int PhaseM = 0;
	int PhaseMT = 0;		
	int PhaseMNew = 0;
	int PhaseMFull = 0;
	int PhaseMFullNew = 0;		
	float dRatio1 = 0;	
	//double dRatio2 = 0;
	float dGamma=1.0f;	
	unsigned char GammaTable[256];
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;		
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;

	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用
	const float P1 = (float)(PA);
	const float P2 = (float)(PB);	
	short *PPtrM = pPhaseD;	
	unsigned char *MPtrM = pMaskD;
	const int ShortPeriod = PHASE_MAX;
	if ( P2 > P1 )//P2 為主
	{	
		dRatio1 = P2/P1;
		//dRatio2 = 1;
	}
	else //P1為主 
	{	
		dRatio1 = 1;
		//dRatio2 = P1/P2;
	}	
	double NewP = P1*P2/fabs(P2-P1);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1, P2, dRatio1);
	//基本公式如下
	//1.相位差=相位1-相位2
	//2.如果相位差<0，則相位差加上周期
	//3.將相位差x比例1則可得到還原後的相位1
	//4.將相位差x比例2則可得到還原後的相位2	

	if ( true == bUseGamma )
	{
		for ( i=0; i<256; i++ )
		{
			dGamma = i;		
			dGamma = dGamma/255.0f;
			dGamma = pow(dGamma, Gamma);		
			dGamma = dGamma*255.0f;
			GammaTable[i] = (unsigned char)(dGamma);
		}
	}
//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{
		if ( i >= ImageSize ) { continue; }

		dA1 = ImgDA1[i];
		dA2 = ImgDA2[i];
		dA3 = ImgDA3[i]; 
		dA4 = ImgDA4[i];

		dB1 = ImgDB1[i];
		dB2 = ImgDB2[i];
		dB3 = ImgDB3[i]; 
		dB4 = ImgDB4[i];

		if ( true == bUseGamma )
		{
			dA1 = GammaTable[dA1];
			dA2 = GammaTable[dA2];
			dA3 = GammaTable[dA3];
			dA4 = GammaTable[dA4];

			dB1 = GammaTable[dB1];
			dB2 = GammaTable[dB2];
			dB3 = GammaTable[dB3];
			dB4 = GammaTable[dB4];
		}

		CalcCuda4PhaseParamMask_kernel(dA1, dA2, dA3, dA4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA, MaskA, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dB1, dB2, dB3, dB4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB, MaskB, PhaseNoiseDefMode);
		//pPhaseD[i] = phaseA * PHASE_RAD2SHORT;

		if ( P1 < P2 )
		{	PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseA, phaseB, dRatio1);	}
		else//注意相位次序
		{	PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseB, phaseA, dRatio1);	}
		if ( NULL != pBasePhaseD )
		{
			PhaseM -= pBasePhaseD[i];
			if ( PhaseM < 0 ) 
			{	PhaseM += ShortPeriod; }
			else if ( PhaseM >= ShortPeriod ) 
			{	PhaseM -= ShortPeriod; }	
		}
		PPtrM[i] = static_cast<PHASE_DATA>(PhaseM);
		MPtrM[i] = CombineCudaPhaseMask_Kernel(MaskA, MaskB);
	}
}
