__global__ void ExecCudaSolve2PhasePeriod_Kernel(double PA, const short *pPhaseDA, const unsigned char *pMaskDA, double PB, const short *pPhaseDB, const unsigned char *pMaskDB, const short *pBasePhaseD, unsigned char *pMaskD, short *pPhaseD, unsigned int ImageSize, int CombineMode)//解雙相位-大小相位
{
	unsigned int i=0;
	int PhaseM = 0;		
	float dRatio1 = 0;
	//double dRatio2 = 0;

	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用
	const float P1 = (float)(PA);
	const float P2 = (float)(PB);
	short *PPtrM = pPhaseD;
	const short* PPtr1 = pPhaseDA;
	const short* PPtr2 = pPhaseDB;	
	unsigned char *MPtrM = pMaskD;
	const unsigned char *MPtr1 = pMaskDA;
	const unsigned char *MPtr2 = pMaskDB;		
	if ( P2 > P1 )//P2 為主
	{	
		dRatio1 = P2/P1;
		//dRatio2 = 1;
	}
	else //P1為主 
	{	
		dRatio1 = 1;
		//dRatio2 = P1/P2;
	}	
	double NewP = P1*P2/fabs(P2-P1);	
	CalcCudaCombinePhasePeriodRatio_Kernel(CombineMode, P1, P2, dRatio1);
//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	if ( P1 < P2 )
	{
		for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
		{
			PhaseM = CombineCudaPhasePeriod_Kernel(CombineMode, PPtr1[i], PPtr2[i], dRatio1);
			if ( NULL != pBasePhaseD )
			{	DeductBasePhase_Kernel(pBasePhaseD[i], PhaseM);	}
			PPtrM[i] = static_cast<PHASE_DATA>(PhaseM);
			MPtrM[i] = CombineCudaPhaseMask_Kernel(MPtr1[i], MPtr2[i]);			
		}	
	}
	else
	{
		for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
		{
			PhaseM = CombineCudaPhasePeriod_Kernel(CombineMode, PPtr2[i], PPtr1[i], dRatio1);//注意相位次序
			if ( NULL != pBasePhaseD )
			{	DeductBasePhase_Kernel(pBasePhaseD[i], PhaseM);	}
			PPtrM[i] = static_cast<PHASE_DATA>(PhaseM);
			MPtrM[i] = CombineCudaPhaseMask_Kernel(MPtr1[i], MPtr2[i]);			
		}	
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaMergeSpace4Frames2Period2Cast_Kernel(TCastParam *pCastParamD1, TCastParam *pCastParamD2, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//合併2投光
{	
	unsigned int i=0, j=0;		
	unsigned int ImageX=0;
	unsigned int ImageY=0;	
	unsigned int SpaceCount=0;		
	bool         bUsePatchX=false;
	bool         bUsePatchY=false;
	const bool   bCrossMask=glbCrossMask;
	unsigned int SpaceW = pCastParamD1->ImageW;
	unsigned int SpaceH = pCastParamD1->ImageH;
	unsigned int SpaceStep = pCastParamD1->ImageStep;	
	const int MaxSpaceCount = MULTI_CAST_PATCH_MAX_COUNT;
	const int PatchSize=NoiseParam.SpaceMultiCastPatchSize;	
	const int PatchSpaceCount=(PatchSize*2+1)*(PatchSize*2+1)*4;		
	const int PatchArrayUsedSize=MIN(MaxSpaceCount, PatchSpaceCount);

	float        Space=0;
	unsigned char Mask=0;
	float        Space_1=0;
	unsigned char Mask_1=0;
	float        Space_2=0;
	unsigned char Mask_2=0;	

	float        SpaceList[MaxSpaceCount];
	unsigned char MaskList[MaxSpaceCount];
	//cudaMalloc((void**) &Ptr, sizeof(unsigned char)*size_min)
	
//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{	
		if ( i >= ImageSize ) { continue; }

		ImageX = i%SpaceStep;
		ImageY = i/SpaceStep;
		if ( ImageY<PatchSize || ImageY>=(SpaceH-PatchSize) )
		{	bUsePatchY = false; }
		else
		{	bUsePatchY = true; }
		if ( ImageX<PatchSize || ImageX>=(SpaceW-PatchSize)  )
		{	bUsePatchX = false; }
		else
		{	bUsePatchX = true; }
		Mask_1=pCastParamD1->PtrMask[i];	Space_1=pCastParamD1->PtrSpace[i];
		Mask_2=pCastParamD2->PtrMask[i];	Space_2=pCastParamD2->PtrSpace[i];
		if ( CompareCuda2SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask, Space) == true )
		{
			MaskPtrD[i] = Mask;
			SpacePtrD[i] = Space;
			continue;
		}
		if ( false==bUsePatchX || false==bUsePatchY || 0==PatchSize )
		{			
			MergeCuda2SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask, Space);
			MaskPtrD[i] = Mask;
			SpacePtrD[i] = Space;			
		}
		else
		{	
			SpaceCount = 0;
			for ( j=0; j<PatchArrayUsedSize; j++ )
			{
				MaskList[j] = 0;
				SpaceList[j] = 0.0f;
			}
			
			for ( int v=-PatchSize; v<=PatchSize; v++ )
			{	
				for ( int u=-PatchSize; u<=PatchSize; u++ )
				{
					if ( true == bCrossMask )//十字遮罩
					{
						if ( u<0 && u<(abs(v)-PatchSize) ) 
						{	continue;	}
						else if ( u>0 && u>(PatchSize-abs(v)) ) 
						{	continue;	}
					}
					unsigned int t = (unsigned int)(v+ImageY);
					unsigned int s = (unsigned int)(u+ImageX);
					j = (t*SpaceStep)+s;					
					MaskList[SpaceCount]=pCastParamD1->PtrMask[j];	SpaceList[SpaceCount]=pCastParamD1->PtrSpace[j];	SpaceCount++;
					MaskList[SpaceCount]=pCastParamD2->PtrMask[j];	SpaceList[SpaceCount]=pCastParamD2->PtrSpace[j];	SpaceCount++;					
					if ( (SpaceCount+2) > MaxSpaceCount )
					{	break; }
				}
				if ( (SpaceCount+2) > MaxSpaceCount )
				{	break; }
			}
			MergeCudaNSpaceData_Kernel(i, NoiseParam, MaskList, SpaceList, SpaceCount, Mask, Space);
			MaskPtrD[i] = Mask;
			SpacePtrD[i] = (SPACE_DATA)(Space);
		}
	}
}
