__global__ void ExecCudaSolveSpace4Frames2Period1Cast_4_2_Kernel(TCastParam *pCastParamD, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//4+2步雙相位-單投光
{
	unsigned int i=0;	
	int   PhaseBase = 0;
	int   dA1=0, dA2=0, dA3=0, dA4=0;
	int   dB1=0, dB2=0, dB3=0;	
	int   phaseA=0;
	int   phaseB=0;	
	float KValue=0.0f;
	float KValue_2=0.0f;
	unsigned char MaskA=0, MaskB=0;
	
	int Phase1 = 0;
	int Phase2 = 0;				
	int PhaseM = 0;
	float dRatio1 = 0.0f;	
	//float dRatio2 = 0.0f;	
	const bool bUseGamma = USE_GAMMA_CALIBRATION;		
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	

	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用
	const float P1 = (float)(pCastParamD->PerA);
	const float P2 = (float)(pCastParamD->PerB);		
	const float Gamma=(float)(pCastParamD->Gamma);	
	const float ExpTimeRatio = (float)(pCastParamD->ExpTimeB*1.0f/pCastParamD->ExpTimeA);	
	double NewP = P1*P2/fabs(P2-P1);

	const int ImageStep = pCastParamD->ImageStep;	
	const int FactorCnt=sizeof(pCastParamD->HeightFactor0)/(sizeof(pCastParamD->HeightFactor0[0]));	
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];	
	for ( i=0; i<CUDA_HEIGHT_FACTOR_SIZE; i++ )
	{	HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;	}
	for ( i=0; i<FactorCnt; i++ )
	{
		if ( i>=CUDA_HEIGHT_FACTOR_SIZE ) { break; }
		HeightFactor0_1[i] = pCastParamD->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD->HeightFactor2[i];				
	}	
	__syncthreads();//同1個Block多個Thread同步化

	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1, P2, dRatio1);
//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{
		if ( i >= ImageSize ) { continue; }
		const int x = i%ImageStep;
		const int y = i/ImageStep;

		dA1 = pCastParamD->PtrA1[i];
		dA2 = pCastParamD->PtrA2[i];
		dA3 = pCastParamD->PtrA3[i]; 
		dA4 = pCastParamD->PtrA4[i];
		dB1 = pCastParamD->PtrB1[i];
		dB3 = pCastParamD->PtrB2[i];
		dB2 = (dA1+dA2+dA3+dA4)>>2; 
		dB2 = (int)((ExpTimeRatio*dB2)+0.5f);
		if ( true == bUseGamma )
		{
			dA1 = CalcCudaGamma_Kernel(dA1, Gamma);
			dA2 = CalcCudaGamma_Kernel(dA2, Gamma);
			dA3 = CalcCudaGamma_Kernel(dA3, Gamma);
			dA4 = CalcCudaGamma_Kernel(dA4, Gamma);
			dB1 = CalcCudaGamma_Kernel(dB1, Gamma);
			dB2 = CalcCudaGamma_Kernel(dB2, Gamma);
			dB3 = CalcCudaGamma_Kernel(dB3, Gamma);			
		}
		PhaseBase = pCastParamD->ZeroPhasePtr[i];
		if ( NULL != pCastParamD->HeightFactorPtr ) { KValue    = pCastParamD->HeightFactorPtr[i]; }		

		CalcCuda4PhaseParamMask_kernel(dA1, dA2, dA3, dA4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA, MaskA, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dB1, dB2, dB3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB, MaskB);
		//pPhaseD[i] = phaseA * PHASE_RAD2SHORT;

		if ( P1 < P2 )
		{			
			Phase1 = phaseA;
			Phase2 = phaseB;			
		}
		else
		{	
			Phase1 = phaseB;//注意相位次序
			Phase2 = phaseA;//						
		}			
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1);		
		DeductBasePhase_Kernel(PhaseBase, PhaseM);		
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue, KValue_2, SpacePtrD[i]);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, SpacePtrD[i]);
		MaskPtrD[i] = CombineCudaPhaseMask_Kernel(MaskA, MaskB);

		pCastParamD->PtrMask[i] = MaskPtrD[i];
		pCastParamD->PtrSpace[i] = SpacePtrD[i];
	}
}
