			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);
			dB4_1 = CalcCudaGamma_Kernel(dB4_1, Gamma_1);
		}
		
		Threshold_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;
		Threshold_1=(float)(Threshold_1*ExpTimeRatio_1);		
		
		CalcCuda4GrayCodeParam_kernel(dB1_1, dB2_1, dB3_1, dB4_1, Threshold_1, CodeMap1, CodeMap2, k1_1, k2_1);
		CalcCuda4PhaseParamMask_kernel(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1, PhaseNoiseDefMode);
				
		//Cast 1
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_1, Period, MaxN, k1_1, k2_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		Mask_1 = MaskA_1;

		pCastParamD->PtrMask[i] = Mask_1;	pCastParamD->PtrSpace[i] = Space_1;		
		MaskPtrD[i] = Mask_1;
		SpacePtrD[i] = Space_1;	
	}
}
