__global__ void ExecCudaSolveSpace221Frames2Period3Cast_2_2_Kernel(TCastParam *pCastParamD1, TCastParam *pCastParamD2, TCastParam *pCastParamD3, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//2+2步雙相位-3投光
{
	unsigned int i=0, j=0;	
	int Phase1 = 0;
	int Phase2 = 0;	
	int PhaseM = 0;		
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;		
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	

	#pragma region Cast 1 - Param
	int   PhaseBase_1 = 0;	
	int   dA1_1=0, dA2_1=0;
	int   dB1_1=0, dB2_1=0, dB3_1=0;

	float Space_1=0;
	float KValue_1=0.0f;
	float KValue_1_2=0.0f;
	int   phaseA_1=0, phaseB_1=0;
	float dRatio1_1=0;//, dRatio2_1=0;
	unsigned char Mask_1=0, MaskA_1=0, MaskB_1=0;
	const float P1_1 = (float)(pCastParamD1->PerA);
	const float P2_1 = (float)(pCastParamD1->PerB);	
	const float Gamma_1=(float)(pCastParamD1->Gamma);		
	const float ExpTimeRatio_1 = (float)(pCastParamD1->ExpTimeB*1.0f/pCastParamD1->ExpTimeA);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_1, P2_1, dRatio1_1);
#pragma endregion
	#pragma region Cast 2 - Param
	int   PhaseBase_2 = 0;	
	int   dA1_2=0, dA2_2=0;
	int   dB1_2=0, dB2_2=0, dB3_2=0;

	float Space_2=0;
	float KValue_2=0.0f;
	float KValue_2_2=0.0f;
	int   phaseA_2=0, phaseB_2=0;
	float dRatio1_2=0;//, dRatio2_2=0;
	unsigned char Mask_2=0, MaskA_2=0, MaskB_2=0;
	const float P1_2 = (float)(pCastParamD2->PerA);
	const float P2_2 = (float)(pCastParamD2->PerB);	
	const float Gamma_2=(float)(pCastParamD2->Gamma);	
	const float ExpTimeRatio_2 = (float)(pCastParamD2->ExpTimeB*1.0f/pCastParamD2->ExpTimeA);	
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_2, P2_2, dRatio1_2);
#pragma endregion
	#pragma region Cast 3 - Param
	int   PhaseBase_3 = 0;	
	int   dA1_3=0, dA2_3=0;
	int   dB1_3=0, dB2_3=0, dB3_3=0;

	float Space_3=0;
	float KValue_3=0.0f;
	float KValue_3_2=0.0f;
	int   phaseA_3=0, phaseB_3=0;
	float dRatio1_3=0;//, dRatio2_3=0;
	unsigned char Mask_3=0, MaskA_3=0, MaskB_3=0;
	const float P1_3 = (float)(pCastParamD3->PerA);
	const float P2_3 = (float)(pCastParamD3->PerB);	
	const float Gamma_3=(float)(pCastParamD3->Gamma);	
	const float ExpTimeRatio_3 = (float)(pCastParamD3->ExpTimeB*1.0f/pCastParamD3->ExpTimeA);		
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_3, P2_3, dRatio1_3);
#pragma endregion
	
	const int ImageStep = pCastParamD1->ImageStep;	
	const int FactorCnt=sizeof(pCastParamD1->HeightFactor0)/(sizeof(pCastParamD1->HeightFactor0[0]));	
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_2[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_3[CUDA_HEIGHT_FACTOR_SIZE];
	for ( i=0; i<CUDA_HEIGHT_FACTOR_SIZE; i++ )
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;		
		HeightFactor0_2[i] = HeightFactor1_2[i] = HeightFactor2_2[i] = 0;		
		HeightFactor0_3[i] = HeightFactor1_3[i] = HeightFactor2_3[i] = 0;				
	}
	for ( i=0; i<FactorCnt; i++ )
	{
		if ( i>=CUDA_HEIGHT_FACTOR_SIZE ) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];		
		HeightFactor0_2[i] = pCastParamD2->HeightFactor0[i];	HeightFactor1_2[i] = pCastParamD2->HeightFactor1[i];	HeightFactor2_2[i] = pCastParamD2->HeightFactor2[i];
		HeightFactor0_3[i] = pCastParamD3->HeightFactor0[i];	HeightFactor1_3[i] = pCastParamD3->HeightFactor1[i];	HeightFactor2_3[i] = pCastParamD3->HeightFactor2[i];		
	}	
	__syncthreads();//同1個Block多個Thread同步化

	//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
	//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{		
		if ( i >= ImageSize ) { continue; }
		const int x = i%ImageStep;
		const int y = i/ImageStep;

		#pragma region dA_1
		dA1_1 = pCastParamD1->PtrA1[i];
		dA2_1 = pCastParamD1->PtrA2[i];
		dB1_1 = pCastParamD1->PtrB1[i];
		dB2_1 = pCastParamD1->PtrB2[i];
		dB3_1 = pCastParamD1->PtrB3[i];
		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if ( NULL != pCastParamD1->HeightFactorPtr ) { KValue_1    = pCastParamD1->HeightFactorPtr[i]; }
		if ( true == bUseGamma )
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);	
		}
#pragma endregion
		#pragma region dA_2
		dA1_2 = pCastParamD2->PtrA1[i];
		dA2_2 = pCastParamD2->PtrA2[i];
		dB1_2 = pCastParamD2->PtrB1[i];
		dB2_2 = pCastParamD2->PtrB2[i];
		dB3_2 = pCastParamD2->PtrB3[i];
		PhaseBase_2 = pCastParamD2->ZeroPhasePtr[i];
		if ( NULL != pCastParamD2->HeightFactorPtr ) { KValue_2    = pCastParamD2->HeightFactorPtr[i]; }
		if ( true == bUseGamma )
		{
			dA1_2 = CalcCudaGamma_Kernel(dA1_2, Gamma_2);
			dA2_2 = CalcCudaGamma_Kernel(dA2_2, Gamma_2);
			dB1_2 = CalcCudaGamma_Kernel(dB1_2, Gamma_2);
			dB2_2 = CalcCudaGamma_Kernel(dB2_2, Gamma_2);
			dB3_2 = CalcCudaGamma_Kernel(dB3_2, Gamma_2);	
		}
#pragma endregion
		#pragma region dA_3
		dA1_3 = pCastParamD3->PtrA1[i];
		dA2_3 = pCastParamD3->PtrA2[i];
		dB1_3 = pCastParamD3->PtrB1[i];
		dB2_3 = pCastParamD3->PtrB2[i];
		dB3_3 = pCastParamD3->PtrB3[i];
		PhaseBase_3 = pCastParamD3->ZeroPhasePtr[i];
		if ( NULL != pCastParamD3->HeightFactorPtr ) { KValue_3    = pCastParamD3->HeightFactorPtr[i]; }
		if ( true == bUseGamma )
		{
			dA1_3 = CalcCudaGamma_Kernel(dA1_3, Gamma_3);
			dA2_3 = CalcCudaGamma_Kernel(dA2_3, Gamma_3);
			dB1_3 = CalcCudaGamma_Kernel(dB1_3, Gamma_3);
			dB2_3 = CalcCudaGamma_Kernel(dB2_3, Gamma_3);
			dB3_3 = CalcCudaGamma_Kernel(dB3_3, Gamma_3);	
		}
#pragma endregion

		#pragma region Cast 1 - Phase
		CalcCuda21PhaseParamMask_kernel(dA1_1, dB3_1, dA2_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1);
		CalcCuda21PhaseParamMask_kernel(dB1_1, dB3_1, dB2_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_1, MaskB_1);		
		if ( P1_1 < P2_1 )
		{			
			Phase1 = phaseA_1;
			Phase2 = phaseB_1;			
		}
		else
		{	
			Phase1 = phaseB_1;//注意相位次序
			Phase2 = phaseA_1;//
		}
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		Mask_1 = CombineCudaPhaseMask_Kernel(MaskA_1, MaskB_1);
#pragma endregion
		#pragma region Cast 2 - Phase
		CalcCuda21PhaseParamMask_kernel(dA1_2, dB3_2, dA2_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_2, MaskA_2);
		CalcCuda21PhaseParamMask_kernel(dB1_2, dB3_2, dB2_2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_2, MaskB_2);		
		if ( P1_2 < P2_2 )
		{			
			Phase1 = phaseA_2;
			Phase2 = phaseB_2;			
		}
		else
		{	
			Phase1 = phaseB_2;//注意相位次序
			Phase2 = phaseA_2;//
		}
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_2);
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_2, KValue_2_2, Space_2);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		Mask_2 = CombineCudaPhaseMask_Kernel(MaskA_2, MaskB_2);
#pragma endregion
		#pragma region Cast 3 - Phase
		CalcCuda21PhaseParamMask_kernel(dA1_3, dB3_3, dA2_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_3, MaskA_3);
		CalcCuda21PhaseParamMask_kernel(dB1_3, dB3_3, dB2_3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_3, MaskB_3);		
		if ( P1_3 < P2_3 )
		{			
			Phase1 = phaseA_3;
			Phase2 = phaseB_3;			
		}
		else
		{	
			Phase1 = phaseB_3;//注意相位次序
			Phase2 = phaseA_3;//
		}
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_3);
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_3, KValue_3_2, Space_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		Mask_3 = CombineCudaPhaseMask_Kernel(MaskA_3, MaskB_3);
#pragma endregion

		//CompareCuda3OppositeGray_Kernel(NoiseParam, cA_1, cA_2, cA_3, Mask_1, Mask_2, Mask_3);		
		if ( CompareCuda3SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, MaskPtrD[i], SpacePtrD[i]) == false )		
		{	MergeCuda3SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, MaskPtrD[i], SpacePtrD[i]);		}
		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;
		pCastParamD2->PtrMask[i] = Mask_2;	pCastParamD2->PtrSpace[i] = Space_2;
		pCastParamD3->PtrMask[i] = Mask_3;	pCastParamD3->PtrSpace[i] = Space_3;
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSolveSpace4Frames2Period3Cast_4_2_Kernel(TCastParam *pCastParamD1, TCastParam *pCastParamD2, TCastParam *pCastParamD3, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//4+2步雙相位-3投光
{
	unsigned int i=0;
	//Cast 1
	int   PhaseBase_1 = 0;	
	int   dA1_1=0, dA2_1=0, dA3_1=0, dA4_1=0;
	int   dB1_1=0, dB2_1=0, dB3_1=0;

	float Space_1=0;		
	float KValue_1=0.0f;
	float KValue_1_2=0.0f;
	int   phaseA_1=0, phaseB_1=0;
	float dRatio1_1=0;//, dRatio2_1=0;
	unsigned char Mask_1=0, MaskA_1=0, MaskB_1=0;
	const float P1_1 = (float)(pCastParamD1->PerA);
	const float P2_1 = (float)(pCastParamD1->PerB);	
	const float Gamma_1=(float)(pCastParamD1->Gamma);
	
	//Cast 2 
	int   PhaseBase_2 = 0;	
	int   dA1_2=0, dA2_2=0, dA3_2=0, dA4_2=0;
	int   dB1_2=0, dB2_2=0, dB3_2=0;

	float Space_2=0;		
	float KValue_2=0.0f;
	float KValue_2_2=0.0f;
	int   phaseA_2=0, phaseB_2=0;		
	float dRatio1_2=0;//, dRatio2_2=0;
	unsigned char Mask_2, MaskA_2=0, MaskB_2=0;
	const float P1_2 = (float)(pCastParamD2->PerA);
	const float P2_2 = (float)(pCastParamD2->PerB);	
	const float Gamma_2=(float)(pCastParamD2->Gamma);

	//Cast 3
	int   PhaseBase_3 = 0;	
	int   dA1_3=0, dA2_3=0, dA3_3=0, dA4_3=0;
	int   dB1_3=0, dB2_3=0, dB3_3=0;

	float Space_3=0;
	float KValue_3=0.0f;
	float KValue_3_2=0.0f;
	int   phaseA_3=0, phaseB_3=0;		
	float dRatio1_3=0;//, dRatio2_3=0;
	unsigned char Mask_3, MaskA_3=0, MaskB_3=0;
	const float P1_3 = (float)(pCastParamD3->PerA);
	const float P2_3 = (float)(pCastParamD3->PerB);		
	const float Gamma_3=(float)(pCastParamD3->Gamma);

	int Phase1 = 0;
	int Phase2 = 0;	
	int PhaseM = 0;		
	const bool bUseGamma = USE_GAMMA_CALIBRATION;		
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;	
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	

	const float ExpTimeRatio_1 = (float)(pCastParamD1->ExpTimeB*1.0f/pCastParamD1->ExpTimeA);
	const float ExpTimeRatio_2 = (float)(pCastParamD2->ExpTimeB*1.0f/pCastParamD2->ExpTimeA);
	const float ExpTimeRatio_3 = (float)(pCastParamD3->ExpTimeB*1.0f/pCastParamD3->ExpTimeA);
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用			
	
	const int ImageStep = pCastParamD1->ImageStep;	
	const int FactorCnt=sizeof(pCastParamD1->HeightFactor0)/(sizeof(pCastParamD1->HeightFactor0[0]));	
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_2[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_3[CUDA_HEIGHT_FACTOR_SIZE];	
	for ( i=0; i<CUDA_HEIGHT_FACTOR_SIZE; i++ )
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;
		HeightFactor0_2[i] = HeightFactor1_2[i] = HeightFactor2_2[i] = 0;
		HeightFactor0_3[i] = HeightFactor1_3[i] = HeightFactor2_3[i] = 0;		
	}
	for ( i=0; i<FactorCnt; i++ )
	{
		if ( i>=CUDA_HEIGHT_FACTOR_SIZE ) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];
		HeightFactor0_2[i] = pCastParamD2->HeightFactor0[i];	HeightFactor1_2[i] = pCastParamD2->HeightFactor1[i];	HeightFactor2_2[i] = pCastParamD2->HeightFactor2[i];
		HeightFactor0_3[i] = pCastParamD3->HeightFactor0[i];	HeightFactor1_3[i] = pCastParamD3->HeightFactor1[i];	HeightFactor2_3[i] = pCastParamD3->HeightFactor2[i];		
	}	
	__syncthreads();//同1個Block多個Thread同步化

	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_1, P2_1, dRatio1_1);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_2, P2_2, dRatio1_2);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_3, P2_3, dRatio1_3);

//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{		
		if ( i >= ImageSize ) { continue; }
		const int x = i%ImageStep;
		const int y = i/ImageStep;

		dA1_1 = pCastParamD1->PtrA1[i];
		dA2_1 = pCastParamD1->PtrA2[i];
		dA3_1 = pCastParamD1->PtrA3[i]; 
		dA4_1 = pCastParamD1->PtrA4[i];
		dB1_1 = pCastParamD1->PtrB1[i];
		dB3_1 = pCastParamD1->PtrB2[i];
		dB2_1 = (dA1_1+dA2_1+dA3_1+dA4_1)>>2; 
		dB2_1 = (int)((ExpTimeRatio_1*dB2_1)+0.5f);		
		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if ( NULL != pCastParamD1->HeightFactorPtr ) { KValue_1    = pCastParamD1->HeightFactorPtr[i]; }

		dA1_2 = pCastParamD2->PtrA1[i];
		dA2_2 = pCastParamD2->PtrA2[i];
		dA3_2 = pCastParamD2->PtrA3[i]; 
		dA4_2 = pCastParamD2->PtrA4[i];
		dB1_2 = pCastParamD2->PtrB1[i];
		dB3_2 = pCastParamD2->PtrB2[i];
		dB2_2 = (dA1_2+dA2_2+dA3_2+dA4_2)>>2; 
		dB2_2 = (int)((ExpTimeRatio_2*dB2_2)+0.5f);
		PhaseBase_2 = pCastParamD2->ZeroPhasePtr[i];
		if ( NULL != pCastParamD2->HeightFactorPtr ) { KValue_2    = pCastParamD2->HeightFactorPtr[i]; }

		dA1_3 = pCastParamD3->PtrA1[i];
		dA2_3 = pCastParamD3->PtrA2[i];
		dA3_3 = pCastParamD3->PtrA3[i]; 
		dA4_3 = pCastParamD3->PtrA4[i];
		dB1_3 = pCastParamD3->PtrB1[i];
		dB3_3 = pCastParamD3->PtrB2[i];
		dB2_3 = (dA1_3+dA2_3+dA3_3+dA4_3)>>2; 
		dB2_3 = (int)((ExpTimeRatio_3*dB2_3)+0.5f);
		PhaseBase_3 = pCastParamD3->ZeroPhasePtr[i];
		if ( NULL != pCastParamD3->HeightFactorPtr ) { KValue_3    = pCastParamD3->HeightFactorPtr[i]; }
		if ( true == bUseGamma )
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dA3_1 = CalcCudaGamma_Kernel(dA3_1, Gamma_1);
			dA4_1 = CalcCudaGamma_Kernel(dA4_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);			

			dA1_2 = CalcCudaGamma_Kernel(dA1_2, Gamma_2);
			dA2_2 = CalcCudaGamma_Kernel(dA2_2, Gamma_2);
			dA3_2 = CalcCudaGamma_Kernel(dA3_2, Gamma_2);
			dA4_2 = CalcCudaGamma_Kernel(dA4_2, Gamma_2);
			dB1_2 = CalcCudaGamma_Kernel(dB1_2, Gamma_2);
			dB2_2 = CalcCudaGamma_Kernel(dB2_2, Gamma_2);
			dB3_2 = CalcCudaGamma_Kernel(dB3_2, Gamma_2);			

			dA1_3 = CalcCudaGamma_Kernel(dA1_3, Gamma_3);
			dA2_3 = CalcCudaGamma_Kernel(dA2_3, Gamma_3);
			dA3_3 = CalcCudaGamma_Kernel(dA3_3, Gamma_3);
			dA4_3 = CalcCudaGamma_Kernel(dA4_3, Gamma_3);
			dB1_3 = CalcCudaGamma_Kernel(dB1_3, Gamma_3);
			dB2_3 = CalcCudaGamma_Kernel(dB2_3, Gamma_3);
			dB3_3 = CalcCudaGamma_Kernel(dB3_3, Gamma_3);			
		}

		CalcCuda4PhaseParamMask_kernel(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dB1_1, dB2_1, dB3_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_1, MaskB_1);
		CalcCuda4PhaseParamMask_kernel(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_2, MaskA_2, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dB1_2, dB2_2, dB3_2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_2, MaskB_2);
		CalcCuda4PhaseParamMask_kernel(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_3, MaskA_3, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dB1_3, dB2_3, dB3_3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_3, MaskB_3);
		
		//Cast 1		
		if ( P1_1 < P2_1 )
		{			
			Phase1 = phaseA_1;
			Phase2 = phaseB_1;			
		}
		else
		{	
			Phase1 = phaseB_1;//注意相位次序
			Phase2 = phaseA_1;//
		}		
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		Mask_1 = CombineCudaPhaseMask_Kernel(MaskA_1, MaskB_1);

		//Cast 2		
		if ( P1_2 < P2_2 )
		{			
			Phase1 = phaseA_2;
			Phase2 = phaseB_2;
		}
		else
		{	
			Phase1 = phaseB_2;//注意相位次序
			Phase2 = phaseA_2;//
		}		
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_2);
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM);		
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_2, KValue_2_2, Space_2);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		Mask_2 = CombineCudaPhaseMask_Kernel(MaskA_2, MaskB_2);

		//Cast 3
		if ( P1_3 < P2_3 )
		{			
			Phase1 = phaseA_3;
			Phase2 = phaseB_3;
		}
		else
		{	
			Phase1 = phaseB_3;//注意相位次序
			Phase2 = phaseA_3;//
		}		
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_3);
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_3, KValue_3_2, Space_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		Mask_3 = CombineCudaPhaseMask_Kernel(MaskA_3, MaskB_3);

		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;
		pCastParamD2->PtrMask[i] = Mask_2;	pCastParamD2->PtrSpace[i] = Space_2;
		pCastParamD3->PtrMask[i] = Mask_3;	pCastParamD3->PtrSpace[i] = Space_3;

		if ( CompareCuda3SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, MaskPtrD[i], SpacePtrD[i]) == false )		
		{	MergeCuda3SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, MaskPtrD[i], SpacePtrD[i]);	}
	}		
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSolveSpace4Frames2Period3Cast_4_4_Kernel(TCastParam *pCastParamD1, TCastParam *pCastParamD2, TCastParam *pCastParamD3, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//4+4步雙相位-3投光
{	
	unsigned int i=0;
	//Cast 1
	int   PhaseBase_1 = 0;	
	int   dA1_1=0, dA2_1=0, dA3_1=0, dA4_1=0;
	int   dB1_1=0, dB2_1=0, dB3_1=0, dB4_1=0;

	float Space_1=0;		
	float KValue_1=0.0f;
	float KValue_1_2=0.0f;
	int   phaseA_1=0, phaseB_1=0;
	float dRatio1_1=0;//, dRatio2_1=0;
	unsigned char Mask_1=0, MaskA_1=0, MaskB_1=0;
	const float P1_1 = (float)(pCastParamD1->PerA);
	const float P2_1 = (float)(pCastParamD1->PerB);	
	const float Gamma_1=(float)(pCastParamD1->Gamma);
	
	//Cast 2 
	int   PhaseBase_2 = 0;	
	int   dA1_2=0, dA2_2=0, dA3_2=0, dA4_2=0;
	int   dB1_2=0, dB2_2=0, dB3_2=0, dB4_2=0;

	float Space_2=0;		
	float KValue_2=0.0f;
	float KValue_2_2=0.0f;
	int   phaseA_2=0, phaseB_2=0;		
	float dRatio1_2=0;//, dRatio2_2=0;
	unsigned char Mask_2, MaskA_2=0, MaskB_2=0;
	const float P1_2 = (float)(pCastParamD2->PerA);
	const float P2_2 = (float)(pCastParamD2->PerB);	
	const float Gamma_2=(float)(pCastParamD2->Gamma);

	//Cast 3
	int   PhaseBase_3 = 0;	
	int   dA1_3=0, dA2_3=0, dA3_3=0, dA4_3=0;
	int   dB1_3=0, dB2_3=0, dB3_3=0, dB4_3=0;

	float Space_3=0;
	float KValue_3=0.0f;
	float KValue_3_2=0.0f;
	int   phaseA_3=0, phaseB_3=0;		
	float dRatio1_3=0;//, dRatio2_3=0;
	unsigned char Mask_3, MaskA_3=0, MaskB_3=0;
	const float P1_3 = (float)(pCastParamD3->PerA);
	const float P2_3 = (float)(pCastParamD3->PerB);		
	const float Gamma_3=(float)(pCastParamD3->Gamma);

	int Phase1 = 0;
	int Phase2 = 0;	
	int PhaseM = 0;		
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;	
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用			
	
	const int ImageStep = pCastParamD1->ImageStep;	
	const int FactorCnt=sizeof(pCastParamD1->HeightFactor0)/(sizeof(pCastParamD1->HeightFactor0[0]));	
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_2[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_3[CUDA_HEIGHT_FACTOR_SIZE];	
	for ( i=0; i<CUDA_HEIGHT_FACTOR_SIZE; i++ )
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;
		HeightFactor0_2[i] = HeightFactor1_2[i] = HeightFactor2_2[i] = 0;
		HeightFactor0_3[i] = HeightFactor1_3[i] = HeightFactor2_3[i] = 0;		
	}
	for ( i=0; i<FactorCnt; i++ )
	{
		if ( i>=CUDA_HEIGHT_FACTOR_SIZE ) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];
		HeightFactor0_2[i] = pCastParamD2->HeightFactor0[i];	HeightFactor1_2[i] = pCastParamD2->HeightFactor1[i];	HeightFactor2_2[i] = pCastParamD2->HeightFactor2[i];
		HeightFactor0_3[i] = pCastParamD3->HeightFactor0[i];	HeightFactor1_3[i] = pCastParamD3->HeightFactor1[i];	HeightFactor2_3[i] = pCastParamD3->HeightFactor2[i];		
	}	
	__syncthreads();//同1個Block多個Thread同步化

	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_1, P2_1, dRatio1_1);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_2, P2_2, dRatio1_2);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_3, P2_3, dRatio1_3);

//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{		
		if ( i >= ImageSize ) { continue; }
		const int x = i%ImageStep;
		const int y = i/ImageStep;

		dA1_1 = pCastParamD1->PtrA1[i];
		dA2_1 = pCastParamD1->PtrA2[i];
		dA3_1 = pCastParamD1->PtrA3[i]; 
		dA4_1 = pCastParamD1->PtrA4[i];
		dB1_1 = pCastParamD1->PtrB1[i];
		dB2_1 = pCastParamD1->PtrB2[i];
		dB3_1 = pCastParamD1->PtrB3[i]; 
		dB4_1 = pCastParamD1->PtrB4[i];
		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if ( NULL != pCastParamD1->HeightFactorPtr ) { KValue_1    = pCastParamD1->HeightFactorPtr[i]; }

		dA1_2 = pCastParamD2->PtrA1[i];
		dA2_2 = pCastParamD2->PtrA2[i];
		dA3_2 = pCastParamD2->PtrA3[i]; 
		dA4_2 = pCastParamD2->PtrA4[i];
		dB1_2 = pCastParamD2->PtrB1[i];
		dB2_2 = pCastParamD2->PtrB2[i];
		dB3_2 = pCastParamD2->PtrB3[i]; 
		dB4_2 = pCastParamD2->PtrB4[i];
		PhaseBase_2 = pCastParamD2->ZeroPhasePtr[i];
		if ( NULL != pCastParamD2->HeightFactorPtr ) { KValue_2    = pCastParamD2->HeightFactorPtr[i]; }

		dA1_3 = pCastParamD3->PtrA1[i];
		dA2_3 = pCastParamD3->PtrA2[i];
		dA3_3 = pCastParamD3->PtrA3[i]; 
		dA4_3 = pCastParamD3->PtrA4[i];
		dB1_3 = pCastParamD3->PtrB1[i];
		dB2_3 = pCastParamD3->PtrB2[i];
		dB3_3 = pCastParamD3->PtrB3[i]; 
		dB4_3 = pCastParamD3->PtrB4[i];
		PhaseBase_3 = pCastParamD3->ZeroPhasePtr[i];
		if ( NULL != pCastParamD3->HeightFactorPtr ) { KValue_3    = pCastParamD3->HeightFactorPtr[i]; }

		if ( true == bUseGamma )
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dA3_1 = CalcCudaGamma_Kernel(dA3_1, Gamma_1);
			dA4_1 = CalcCudaGamma_Kernel(dA4_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);
			dB4_1 = CalcCudaGamma_Kernel(dB4_1, Gamma_1);

			dA1_2 = CalcCudaGamma_Kernel(dA1_2, Gamma_2);
			dA2_2 = CalcCudaGamma_Kernel(dA2_2, Gamma_2);
			dA3_2 = CalcCudaGamma_Kernel(dA3_2, Gamma_2);
			dA4_2 = CalcCudaGamma_Kernel(dA4_2, Gamma_2);
			dB1_2 = CalcCudaGamma_Kernel(dB1_2, Gamma_2);
			dB2_2 = CalcCudaGamma_Kernel(dB2_2, Gamma_2);
			dB3_2 = CalcCudaGamma_Kernel(dB3_2, Gamma_2);
			dB4_2 = CalcCudaGamma_Kernel(dB4_2, Gamma_2);

			dA1_3 = CalcCudaGamma_Kernel(dA1_3, Gamma_3);
			dA2_3 = CalcCudaGamma_Kernel(dA2_3, Gamma_3);
			dA3_3 = CalcCudaGamma_Kernel(dA3_3, Gamma_3);
			dA4_3 = CalcCudaGamma_Kernel(dA4_3, Gamma_3);
			dB1_3 = CalcCudaGamma_Kernel(dB1_3, Gamma_3);
			dB2_3 = CalcCudaGamma_Kernel(dB2_3, Gamma_3);
			dB3_3 = CalcCudaGamma_Kernel(dB3_3, Gamma_3);
			dB4_3 = CalcCudaGamma_Kernel(dB4_3, Gamma_3);
		}

		CalcCuda4PhaseParamMask_kernel(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dB1_1, dB2_1, dB3_1, dB4_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_1, MaskB_1, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_2, MaskA_2, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dB1_2, dB2_2, dB3_2, dB4_2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_2, MaskB_2, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_3, MaskA_3, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dB1_3, dB2_3, dB3_3, dB4_3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_3, MaskB_3, PhaseNoiseDefMode);

		//Cast 1		
		if ( P1_1 < P2_1 )
		{			
			Phase1 = phaseA_1;
			Phase2 = phaseB_1;			
		}
		else
		{	
			Phase1 = phaseB_1;//注意相位次序
			Phase2 = phaseA_1;//
		}		
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		Mask_1 = CombineCudaPhaseMask_Kernel(MaskA_1, MaskB_1);

		//Cast 2		
		if ( P1_2 < P2_2 )
		{			
			Phase1 = phaseA_2;
			Phase2 = phaseB_2;
		}
		else
		{	
			Phase1 = phaseB_2;//注意相位次序
			Phase2 = phaseA_2;//
		}		
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_2);
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM);		
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_2, KValue_2_2, Space_2);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		Mask_2 = CombineCudaPhaseMask_Kernel(MaskA_2, MaskB_2);

		//Cast 3
		if ( P1_3 < P2_3 )
		{			
			Phase1 = phaseA_3;
			Phase2 = phaseB_3;
		}
		else
		{	
			Phase1 = phaseB_3;//注意相位次序
			Phase2 = phaseA_3;//
		}		
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_3);
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_3, KValue_3_2, Space_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		Mask_3 = CombineCudaPhaseMask_Kernel(MaskA_3, MaskB_3);

		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;
		pCastParamD2->PtrMask[i] = Mask_2;	pCastParamD2->PtrSpace[i] = Space_2;
		pCastParamD3->PtrMask[i] = Mask_3;	pCastParamD3->PtrSpace[i] = Space_3;

		if ( CompareCuda3SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, MaskPtrD[i], SpacePtrD[i]) == false )		
		{	MergeCuda3SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, MaskPtrD[i], SpacePtrD[i]);	}
	}		
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSolveSpace4Frames2Period3Cast_4_4GC_Kernel(TCastParam *pCastParamD1, TCastParam *pCastParamD2, TCastParam *pCastParamD3, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//4步+4GC雙相位-3投光
{
	unsigned int i = 0, j = 0;

	//Cast 1
	int   PhaseBase_1 = 0;
	int   k1_1 =0, k2_1 = 0;
	int   dA1_1 = 0, dA2_1 = 0, dA3_1 = 0, dA4_1 = 0;
	int   dB1_1 = 0, dB2_1 = 0, dB3_1 = 0, dB4_1 = 0;

	float Space_1 = 0;
	float KValue_1 = 0.0f;
	float KValue_1_2 = 0.0f;
	int   phaseA_1 = 0, phaseB_1 = 0;
	float dRatio1_1 = 0;//, dRatio2_1=0;
	unsigned char Mask_1 = 0, MaskA_1 = 0, MaskB_1 = 0;
	const float P1_1 = (float)(pCastParamD1->PerA);
	const float P2_1 = (float)(pCastParamD1->PerB);
	const float Gamma_1 = (float)(pCastParamD1->Gamma);

	//Cast 2 
	int   PhaseBase_2 = 0;
	int   k1_2 = 0, k2_2 = 0;
	int   dA1_2 = 0, dA2_2 = 0, dA3_2 = 0, dA4_2 = 0;
	int   dB1_2 = 0, dB2_2 = 0, dB3_2 = 0, dB4_2 = 0;

	float Space_2 = 0;
	float KValue_2 = 0.0f;
	float KValue_2_2 = 0.0f;
	int   phaseA_2 = 0, phaseB_2 = 0;
	float dRatio1_2 = 0;//, dRatio2_2=0;
	unsigned char Mask_2, MaskA_2 = 0, MaskB_2 = 0;
	const float P1_2 = (float)(pCastParamD2->PerA);
	const float P2_2 = (float)(pCastParamD2->PerB);
	const float Gamma_2 = (float)(pCastParamD1->Gamma);

	//Cast 3
	int   PhaseBase_3 = 0;
	int   k1_3 = 0, k2_3 = 0;
	int   dA1_3 = 0, dA2_3 = 0, dA3_3 = 0, dA4_3 = 0;
	int   dB1_3 = 0, dB2_3 = 0, dB3_3 = 0, dB4_3 = 0;

	float Space_3 = 0;
	float KValue_3 = 0.0f;
	float KValue_3_2 = 0.0f;
	int   phaseA_3 = 0, phaseB_3 = 0;
	float dRatio1_3 = 0;//, dRatio2_3=0;
	unsigned char Mask_3, MaskA_3 = 0, MaskB_3 = 0;
	const float P1_3 = (float)(pCastParamD3->PerA);
	const float P2_3 = (float)(pCastParamD3->PerB);
	const float Gamma_3 = (float)(pCastParamD3->Gamma);

	int Phase1 = 0;
	int Phase2 = 0;
	int PhaseM = 0;
	int Raw_1[4], Raw_2[4], Raw_3[4];
	float Threshold_1=0.0f, Threshold_2=0.0f, Threshold_3=0.0f;
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;	
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用

	const int MaxN = 8;//最多8個16週期			
	const int CodeMapSize = 16;	
	const int Period = PHASE_PERIOD;		
	__shared__ unsigned char CodeMap1[CodeMapSize];
	__shared__ unsigned char CodeMap2[CodeMapSize];
	for (i = 0; i<CodeMapSize; i++)
	{	CodeMap1[i] = CodeMap2[i] = 0;	}
	BuildCudaGrayCodeMapTable_Kernel(3, CodeMap1, CodeMapSize);
	BuildCudaGrayCodeMapTable_Kernel(4, CodeMap2, CodeMapSize);

	const float ExpTimeRatio_1 = (float)(pCastParamD1->ExpTimeB*1.0f/pCastParamD1->ExpTimeA);
	const float ExpTimeRatio_2 = (float)(pCastParamD2->ExpTimeB*1.0f/pCastParamD2->ExpTimeA);
	const float ExpTimeRatio_3 = (float)(pCastParamD3->ExpTimeB*1.0f/pCastParamD3->ExpTimeA);	

	const int ImageStep = pCastParamD1->ImageStep;
	const int FactorCnt = sizeof(pCastParamD1->HeightFactor0) / (sizeof(pCastParamD1->HeightFactor0[0]));
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_2[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_3[CUDA_HEIGHT_FACTOR_SIZE];	
	for (i = 0; i<CUDA_HEIGHT_FACTOR_SIZE; i++)
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;
		HeightFactor0_2[i] = HeightFactor1_2[i] = HeightFactor2_2[i] = 0;
		HeightFactor0_3[i] = HeightFactor1_3[i] = HeightFactor2_3[i] = 0;
	}
	for (i = 0; i<FactorCnt; i++)
	{
		if (i >= CUDA_HEIGHT_FACTOR_SIZE) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];
		HeightFactor0_2[i] = pCastParamD2->HeightFactor0[i];	HeightFactor1_2[i] = pCastParamD2->HeightFactor1[i];	HeightFactor2_2[i] = pCastParamD2->HeightFactor2[i];
		HeightFactor0_3[i] = pCastParamD3->HeightFactor0[i];	HeightFactor1_3[i] = pCastParamD3->HeightFactor1[i];	HeightFactor2_3[i] = pCastParamD3->HeightFactor2[i];		
	}
	__syncthreads();//同1個Block多個Thread同步化	

	//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
	//  gridDim		網格大小   (網格包含的區塊數目)	
	for (i = (blockIdx.x*blockDim.x) + threadIdx.x; i < ImageSize; i += blockDim.x*gridDim.x)
	{
		if (i >= ImageSize) { continue; }
		const int x = i%ImageStep;
		const int y = i / ImageStep;

		dA1_1 = pCastParamD1->PtrA1[i];
		dA2_1 = pCastParamD1->PtrA2[i];
		dA3_1 = pCastParamD1->PtrA3[i];
		dA4_1 = pCastParamD1->PtrA4[i];
		dB1_1 = pCastParamD1->PtrB1[i];
		dB2_1 = pCastParamD1->PtrB2[i];
		dB3_1 = pCastParamD1->PtrB3[i];
		dB4_1 = pCastParamD1->PtrB4[i];		
		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if (NULL != pCastParamD1->HeightFactorPtr) { KValue_1 = pCastParamD1->HeightFactorPtr[i]; }

		dA1_2 = pCastParamD2->PtrA1[i];
		dA2_2 = pCastParamD2->PtrA2[i];
		dA3_2 = pCastParamD2->PtrA3[i];
		dA4_2 = pCastParamD2->PtrA4[i];
		dB1_2 = pCastParamD2->PtrB1[i];
		dB2_2 = pCastParamD2->PtrB2[i];
		dB3_2 = pCastParamD2->PtrB3[i];
		dB4_2 = pCastParamD2->PtrB4[i];
		PhaseBase_2 = pCastParamD2->ZeroPhasePtr[i];
		if (NULL != pCastParamD2->HeightFactorPtr) { KValue_2 = pCastParamD2->HeightFactorPtr[i]; }

		dA1_3 = pCastParamD3->PtrA1[i];
		dA2_3 = pCastParamD3->PtrA2[i];
		dA3_3 = pCastParamD3->PtrA3[i];
		dA4_3 = pCastParamD3->PtrA4[i];
		dB1_3 = pCastParamD3->PtrB1[i];
		dB2_3 = pCastParamD3->PtrB2[i];
		dB3_3 = pCastParamD3->PtrB3[i];
		dB4_3 = pCastParamD3->PtrB4[i];
		PhaseBase_3 = pCastParamD3->ZeroPhasePtr[i];
		if (NULL != pCastParamD3->HeightFactorPtr) { KValue_3 = pCastParamD3->HeightFactorPtr[i]; }
		
		if (true == bUseGamma)
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dA3_1 = CalcCudaGamma_Kernel(dA3_1, Gamma_1);
			dA4_1 = CalcCudaGamma_Kernel(dA4_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);
			dB4_1 = CalcCudaGamma_Kernel(dB4_1, Gamma_1);			

			dA1_2 = CalcCudaGamma_Kernel(dA1_2, Gamma_2);
			dA2_2 = CalcCudaGamma_Kernel(dA2_2, Gamma_2);
			dA3_2 = CalcCudaGamma_Kernel(dA3_2, Gamma_2);
			dA4_2 = CalcCudaGamma_Kernel(dA4_2, Gamma_2);
			dB1_2 = CalcCudaGamma_Kernel(dB1_2, Gamma_2);
			dB2_2 = CalcCudaGamma_Kernel(dB2_2, Gamma_2);
			dB3_2 = CalcCudaGamma_Kernel(dB3_2, Gamma_2);
			dB4_2 = CalcCudaGamma_Kernel(dB4_2, Gamma_2);			

			dA1_3 = CalcCudaGamma_Kernel(dA1_3, Gamma_3);
			dA2_3 = CalcCudaGamma_Kernel(dA2_3, Gamma_3);
			dA3_3 = CalcCudaGamma_Kernel(dA3_3, Gamma_3);
			dA4_3 = CalcCudaGamma_Kernel(dA4_3, Gamma_3);
			dB1_3 = CalcCudaGamma_Kernel(dB1_3, Gamma_3);
			dB2_3 = CalcCudaGamma_Kernel(dB2_3, Gamma_3);
			dB3_3 = CalcCudaGamma_Kernel(dB3_3, Gamma_3);
			dB4_3 = CalcCudaGamma_Kernel(dB4_3, Gamma_3);
		}
		
		Threshold_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;
		Threshold_1=(float)(Threshold_1*ExpTimeRatio_1);
		Threshold_2=(dA1_2+dA2_2+dA3_2+dA4_2)/4.0f;
		Threshold_2=(float)(Threshold_2*ExpTimeRatio_2);
		Threshold_3=(dA1_3+dA2_3+dA3_3+dA4_3)/4.0f;
		Threshold_3=(float)(Threshold_3*ExpTimeRatio_3);
		
		CalcCuda4GrayCodeParam_kernel(dB1_1, dB2_1, dB3_1, dB4_1, Threshold_1, CodeMap1, CodeMap2, k1_1, k2_1);
		CalcCuda4GrayCodeParam_kernel(dB1_2, dB2_2, dB3_2, dB4_2, Threshold_2, CodeMap1, CodeMap2, k1_2, k2_2);
		CalcCuda4GrayCodeParam_kernel(dB1_3, dB2_3, dB3_3, dB4_3, Threshold_3, CodeMap1, CodeMap2, k1_3, k2_3);
		
		CalcCuda4PhaseParamMask_kernel(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_2, MaskA_2, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_3, MaskA_3, PhaseNoiseDefMode);
		
		//Cast 1
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_1, Period, MaxN, k1_1, k2_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		Mask_1 = MaskA_1;

		//Cast 2		
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_2, Period, MaxN, k1_2, k2_2);
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_2, KValue_2_2, Space_2);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		Mask_2 = MaskA_2;

		//Cast 3
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_3, Period, MaxN, k1_3, k2_3);
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_3, KValue_3_2, Space_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		Mask_3 = MaskA_3;

		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;
		pCastParamD2->PtrMask[i] = Mask_2;	pCastParamD2->PtrSpace[i] = Space_2;
		pCastParamD3->PtrMask[i] = Mask_3;	pCastParamD3->PtrSpace[i] = Space_3;

		if ( MULTI_CAST_MERGE_MODE_JOE_1 == CastMergeMode )
		{
			Raw_1[0]=dA1_1;	Raw_1[1]=dA2_1;	Raw_1[2]=dA3_1;	Raw_1[3]=dA4_1;
			Raw_2[0]=dA1_2;	Raw_2[1]=dA2_2;	Raw_2[2]=dA3_2;	Raw_2[3]=dA4_2;
			Raw_3[0]=dA1_3;	Raw_3[1]=dA2_3;	Raw_3[2]=dA3_3;	Raw_3[3]=dA4_3;			
			MergeCuda3SpaceData_Joe_Kernel(NoiseParam, Raw_1, Mask_1, Space_1, Raw_2, Mask_2, Space_2, Raw_3, Mask_3, Space_3, MaskPtrD[i], SpacePtrD[i]);
		}
		else
		{
			if ( CompareCuda3SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, MaskPtrD[i], SpacePtrD[i]) == false )		
			{	MergeCuda3SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, MaskPtrD[i], SpacePtrD[i]);	}
		}
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSolveSpace4Frames2Period3Cast_4_5GC_Kernel(TCastParam *pCastParamD1, TCastParam *pCastParamD2, TCastParam *pCastParamD3, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//4步+GC雙相位-3投光
{
	unsigned int i = 0, j = 0;

	//Cast 1
	int   PhaseBase_1 = 0;
	int   k1_1 =0, k2_1 = 0;
	int   dA1_1 = 0, dA2_1 = 0, dA3_1 = 0, dA4_1 = 0;
	int   dB1_1 = 0, dB2_1 = 0, dB3_1 = 0, dB4_1 = 0, dB5_1 = 0;

	float Space_1 = 0;
	float KValue_1 = 0.0f;
	float KValue_1_2 = 0.0f;
	int   phaseA_1 = 0, phaseB_1 = 0;
	float dRatio1_1 = 0;//, dRatio2_1=0;
	unsigned char Mask_1 = 0, MaskA_1 = 0, MaskB_1 = 0;
	const float P1_1 = (float)(pCastParamD1->PerA);
	const float P2_1 = (float)(pCastParamD1->PerB);
	const float Gamma_1 = (float)(pCastParamD1->Gamma);

	//Cast 2 
	int   PhaseBase_2 = 0;
	int   k1_2 = 0, k2_2 = 0;
	int   dA1_2 = 0, dA2_2 = 0, dA3_2 = 0, dA4_2 = 0;
	int   dB1_2 = 0, dB2_2 = 0, dB3_2 = 0, dB4_2 = 0, dB5_2 = 0;

	float Space_2 = 0;
	float KValue_2 = 0.0f;
	float KValue_2_2 = 0.0f;
	int   phaseA_2 = 0, phaseB_2 = 0;
	float dRatio1_2 = 0;//, dRatio2_2=0;
	unsigned char Mask_2, MaskA_2 = 0, MaskB_2 = 0;
	const float P1_2 = (float)(pCastParamD2->PerA);
	const float P2_2 = (float)(pCastParamD2->PerB);
	const float Gamma_2 = (float)(pCastParamD1->Gamma);

	//Cast 3
	int   PhaseBase_3 = 0;
	int   k1_3 = 0, k2_3 = 0;
	int   dA1_3 = 0, dA2_3 = 0, dA3_3 = 0, dA4_3 = 0;
	int   dB1_3 = 0, dB2_3 = 0, dB3_3 = 0, dB4_3 = 0, dB5_3 = 0;

	float Space_3 = 0;
	float KValue_3 = 0.0f;
	float KValue_3_2 = 0.0f;
	int   phaseA_3 = 0, phaseB_3 = 0;
	float dRatio1_3 = 0;//, dRatio2_3=0;
	unsigned char Mask_3, MaskA_3 = 0, MaskB_3 = 0;
	const float P1_3 = (float)(pCastParamD3->PerA);
	const float P2_3 = (float)(pCastParamD3->PerB);
	const float Gamma_3 = (float)(pCastParamD3->Gamma);

	int Phase1 = 0;
	int Phase2 = 0;
	int PhaseM = 0;
	int Raw_1[4], Raw_2[4], Raw_3[4];
	float Threshold_1=0.0f, Threshold_2=0.0f, Threshold_3=0.0f;
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;	
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用

	const int MaxN = 16;//最多16個16週期			
	const int CodeMapSize = 32;	
	const int Period = PHASE_PERIOD;		
	__shared__ unsigned char CodeMap1[CodeMapSize];
	__shared__ unsigned char CodeMap2[CodeMapSize];
	for (i = 0; i<CodeMapSize; i++)
	{	CodeMap1[i] = CodeMap2[i] = 0;	}
	BuildCudaGrayCodeMapTable_Kernel(4, CodeMap1, CodeMapSize);
	BuildCudaGrayCodeMapTable_Kernel(5, CodeMap2, CodeMapSize);

	const float ExpTimeRatio_1 = (float)(pCastParamD1->ExpTimeB*1.0f/pCastParamD1->ExpTimeA);
	const float ExpTimeRatio_2 = (float)(pCastParamD2->ExpTimeB*1.0f/pCastParamD2->ExpTimeA);
	const float ExpTimeRatio_3 = (float)(pCastParamD3->ExpTimeB*1.0f/pCastParamD3->ExpTimeA);	

	const int ImageStep = pCastParamD1->ImageStep;
	const int FactorCnt = sizeof(pCastParamD1->HeightFactor0) / (sizeof(pCastParamD1->HeightFactor0[0]));
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_2[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_3[CUDA_HEIGHT_FACTOR_SIZE];	
	for (i = 0; i<CUDA_HEIGHT_FACTOR_SIZE; i++)
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;
		HeightFactor0_2[i] = HeightFactor1_2[i] = HeightFactor2_2[i] = 0;
		HeightFactor0_3[i] = HeightFactor1_3[i] = HeightFactor2_3[i] = 0;		
	}
	for (i = 0; i<FactorCnt; i++)
	{
		if (i >= CUDA_HEIGHT_FACTOR_SIZE) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];
		HeightFactor0_2[i] = pCastParamD2->HeightFactor0[i];	HeightFactor1_2[i] = pCastParamD2->HeightFactor1[i];	HeightFactor2_2[i] = pCastParamD2->HeightFactor2[i];
		HeightFactor0_3[i] = pCastParamD3->HeightFactor0[i];	HeightFactor1_3[i] = pCastParamD3->HeightFactor1[i];	HeightFactor2_3[i] = pCastParamD3->HeightFactor2[i];		
	}
	__syncthreads();//同1個Block多個Thread同步化	

	//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
	//  gridDim		網格大小   (網格包含的區塊數目)	
	for (i = (blockIdx.x*blockDim.x) + threadIdx.x; i < ImageSize; i += blockDim.x*gridDim.x)
	{
		if (i >= ImageSize) { continue; }
		const int x = i%ImageStep;
		const int y = i / ImageStep;

		dA1_1 = pCastParamD1->PtrA1[i];
		dA2_1 = pCastParamD1->PtrA2[i];
		dA3_1 = pCastParamD1->PtrA3[i];
		dA4_1 = pCastParamD1->PtrA4[i];
		dB1_1 = pCastParamD1->PtrB1[i];
		dB2_1 = pCastParamD1->PtrB2[i];
		dB3_1 = pCastParamD1->PtrB3[i];
		dB4_1 = pCastParamD1->PtrB4[i];
		dB5_1 = pCastParamD1->PtrB5[i];
		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if (NULL != pCastParamD1->HeightFactorPtr) { KValue_1 = pCastParamD1->HeightFactorPtr[i]; }

		dA1_2 = pCastParamD2->PtrA1[i];
		dA2_2 = pCastParamD2->PtrA2[i];
		dA3_2 = pCastParamD2->PtrA3[i];
		dA4_2 = pCastParamD2->PtrA4[i];
		dB1_2 = pCastParamD2->PtrB1[i];
		dB2_2 = pCastParamD2->PtrB2[i];
		dB3_2 = pCastParamD2->PtrB3[i];
		dB4_2 = pCastParamD2->PtrB4[i];
		dB5_2 = pCastParamD2->PtrB5[i];
		PhaseBase_2 = pCastParamD2->ZeroPhasePtr[i];
		if (NULL != pCastParamD2->HeightFactorPtr) { KValue_2 = pCastParamD2->HeightFactorPtr[i]; }

		dA1_3 = pCastParamD3->PtrA1[i];
		dA2_3 = pCastParamD3->PtrA2[i];
		dA3_3 = pCastParamD3->PtrA3[i];
		dA4_3 = pCastParamD3->PtrA4[i];
		dB1_3 = pCastParamD3->PtrB1[i];
		dB2_3 = pCastParamD3->PtrB2[i];
		dB3_3 = pCastParamD3->PtrB3[i];
		dB4_3 = pCastParamD3->PtrB4[i];
		dB5_3 = pCastParamD3->PtrB5[i];
		PhaseBase_3 = pCastParamD3->ZeroPhasePtr[i];
		if (NULL != pCastParamD3->HeightFactorPtr) { KValue_3 = pCastParamD3->HeightFactorPtr[i]; }

		if (true == bUseGamma)
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dA3_1 = CalcCudaGamma_Kernel(dA3_1, Gamma_1);
			dA4_1 = CalcCudaGamma_Kernel(dA4_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);
			dB4_1 = CalcCudaGamma_Kernel(dB4_1, Gamma_1);
			dB5_1 = CalcCudaGamma_Kernel(dB5_1, Gamma_1);

			dA1_2 = CalcCudaGamma_Kernel(dA1_2, Gamma_2);
			dA2_2 = CalcCudaGamma_Kernel(dA2_2, Gamma_2);
			dA3_2 = CalcCudaGamma_Kernel(dA3_2, Gamma_2);
			dA4_2 = CalcCudaGamma_Kernel(dA4_2, Gamma_2);
			dB1_2 = CalcCudaGamma_Kernel(dB1_2, Gamma_2);
			dB2_2 = CalcCudaGamma_Kernel(dB2_2, Gamma_2);
			dB3_2 = CalcCudaGamma_Kernel(dB3_2, Gamma_2);
			dB4_2 = CalcCudaGamma_Kernel(dB4_2, Gamma_2);
			dB5_2 = CalcCudaGamma_Kernel(dB5_2, Gamma_2);

			dA1_3 = CalcCudaGamma_Kernel(dA1_3, Gamma_3);
			dA2_3 = CalcCudaGamma_Kernel(dA2_3, Gamma_3);
			dA3_3 = CalcCudaGamma_Kernel(dA3_3, Gamma_3);
			dA4_3 = CalcCudaGamma_Kernel(dA4_3, Gamma_3);
			dB1_3 = CalcCudaGamma_Kernel(dB1_3, Gamma_3);
			dB2_3 = CalcCudaGamma_Kernel(dB2_3, Gamma_3);
			dB3_3 = CalcCudaGamma_Kernel(dB3_3, Gamma_3);
			dB4_3 = CalcCudaGamma_Kernel(dB4_3, Gamma_3);
			dB5_3 = CalcCudaGamma_Kernel(dB5_3, Gamma_3);
		}

		Threshold_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;
		Threshold_1=(float)(Threshold_1*ExpTimeRatio_1);
		Threshold_2=(dA1_2+dA2_2+dA3_2+dA4_2)/4.0f;
		Threshold_2=(float)(Threshold_2*ExpTimeRatio_2);
		Threshold_3=(dA1_3+dA2_3+dA3_3+dA4_3)/4.0f;
		Threshold_3=(float)(Threshold_3*ExpTimeRatio_3);		

		CalcCuda5GrayCodeParam_kernel(dB1_1, dB2_1, dB3_1, dB4_1, dB5_1, Threshold_1, CodeMap1, CodeMap2, k1_1, k2_1);
		CalcCuda5GrayCodeParam_kernel(dB1_2, dB2_2, dB3_2, dB4_2, dB5_2, Threshold_2, CodeMap1, CodeMap2, k1_2, k2_2);
		CalcCuda5GrayCodeParam_kernel(dB1_3, dB2_3, dB3_3, dB4_3, dB5_3, Threshold_3, CodeMap1, CodeMap2, k1_3, k2_3);		

		CalcCuda4PhaseParamMask_kernel(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_2, MaskA_2, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_3, MaskA_3, PhaseNoiseDefMode);

		//Cast 1
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_1, Period, MaxN, k1_1, k2_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		Mask_1 = MaskA_1;

		//Cast 2		
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_2, Period, MaxN, k1_2, k2_2);
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_2, KValue_2_2, Space_2);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		Mask_2 = MaskA_2;

		//Cast 3
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_3, Period, MaxN, k1_3, k2_3);
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_3, KValue_3_2, Space_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		Mask_3 = MaskA_3;		
		
		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;
		pCastParamD2->PtrMask[i] = Mask_2;	pCastParamD2->PtrSpace[i] = Space_2;
		pCastParamD3->PtrMask[i] = Mask_3;	pCastParamD3->PtrSpace[i] = Space_3;

		if ( MULTI_CAST_MERGE_MODE_JOE_1 == CastMergeMode )
		{
			Raw_1[0]=dA1_1;	Raw_1[1]=dA2_1;	Raw_1[2]=dA3_1;	Raw_1[3]=dA4_1;
			Raw_2[0]=dA1_2;	Raw_2[1]=dA2_2;	Raw_2[2]=dA3_2;	Raw_2[3]=dA4_2;
			Raw_3[0]=dA1_3;	Raw_3[1]=dA2_3;	Raw_3[2]=dA3_3;	Raw_3[3]=dA4_3;			
			MergeCuda3SpaceData_Joe_Kernel(NoiseParam, Raw_1, Mask_1, Space_1, Raw_2, Mask_2, Space_2, Raw_3, Mask_3, Space_3, MaskPtrD[i], SpacePtrD[i]);
		}
		else
		{
			if ( CompareCuda3SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, MaskPtrD[i], SpacePtrD[i]) == false )		
			{	MergeCuda3SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, MaskPtrD[i], SpacePtrD[i]);	}
		}
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSolveSpace4Frames2Period3Cast_4_6GC_Kernel(TCastParam *pCastParamD1, TCastParam *pCastParamD2, TCastParam *pCastParamD3, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//4步+6GC雙相位-3投光
{
	unsigned int i = 0, j = 0;

	//Cast 1
	int   PhaseBase_1 = 0;
	int   k1_1 =0, k2_1 = 0;
	int   dA1_1 = 0, dA2_1 = 0, dA3_1 = 0, dA4_1 = 0;
	int   dB1_1 = 0, dB2_1 = 0, dB3_1 = 0, dB4_1 = 0, dB5_1 = 0, dB6_1 = 0;

	float Space_1 = 0;
	float KValue_1 = 0.0f;
	float KValue_1_2 = 0.0f;
	int   phaseA_1 = 0, phaseB_1 = 0;
	float dRatio1_1 = 0;//, dRatio2_1=0;
	unsigned char Mask_1 = 0, MaskA_1 = 0, MaskB_1 = 0;
	const float P1_1 = (float)(pCastParamD1->PerA);
	const float P2_1 = (float)(pCastParamD1->PerB);
	const float Gamma_1 = (float)(pCastParamD1->Gamma);

	//Cast 2 
	int   PhaseBase_2 = 0;
	int   k1_2 = 0, k2_2 = 0;
	int   dA1_2 = 0, dA2_2 = 0, dA3_2 = 0, dA4_2 = 0;
	int   dB1_2 = 0, dB2_2 = 0, dB3_2 = 0, dB4_2 = 0, dB5_2 = 0, dB6_2 = 0;

	float Space_2 = 0;
	float KValue_2 = 0.0f;
	float KValue_2_2 = 0.0f;
	int   phaseA_2 = 0, phaseB_2 = 0;
	float dRatio1_2 = 0;//, dRatio2_2=0;
	unsigned char Mask_2, MaskA_2 = 0, MaskB_2 = 0;
	const float P1_2 = (float)(pCastParamD2->PerA);
	const float P2_2 = (float)(pCastParamD2->PerB);
	const float Gamma_2 = (float)(pCastParamD1->Gamma);

	//Cast 3
	int   PhaseBase_3 = 0;
	int   k1_3 = 0, k2_3 = 0;
	int   dA1_3 = 0, dA2_3 = 0, dA3_3 = 0, dA4_3 = 0;
	int   dB1_3 = 0, dB2_3 = 0, dB3_3 = 0, dB4_3 = 0, dB5_3 = 0, dB6_3 = 0;

	float Space_3 = 0;
	float KValue_3 = 0.0f;
	float KValue_3_2 = 0.0f;
	int   phaseA_3 = 0, phaseB_3 = 0;
	float dRatio1_3 = 0;//, dRatio2_3=0;
	unsigned char Mask_3, MaskA_3 = 0, MaskB_3 = 0;
	const float P1_3 = (float)(pCastParamD3->PerA);
	const float P2_3 = (float)(pCastParamD3->PerB);
	const float Gamma_3 = (float)(pCastParamD3->Gamma);

	int Phase1 = 0;
	int Phase2 = 0;
	int PhaseM = 0;
	int Raw_1[4], Raw_2[4], Raw_3[4];
	float Threshold_1=0.0f, Threshold_2=0.0f, Threshold_3=0.0f;
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;	
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用

	const int MaxN = 32;//最多32個16週期			
	const int CodeMapSize = 64;	
	const int Period = PHASE_PERIOD;		
	__shared__ unsigned char CodeMap1[CodeMapSize];
	__shared__ unsigned char CodeMap2[CodeMapSize];
	for (i = 0; i<CodeMapSize; i++)
	{	CodeMap1[i] = CodeMap2[i] = 0;	}
	BuildCudaGrayCodeMapTable_Kernel(5, CodeMap1, CodeMapSize);
	BuildCudaGrayCodeMapTable_Kernel(6, CodeMap2, CodeMapSize);

	const float ExpTimeRatio_1 = (float)(pCastParamD1->ExpTimeB*1.0f/pCastParamD1->ExpTimeA);
	const float ExpTimeRatio_2 = (float)(pCastParamD2->ExpTimeB*1.0f/pCastParamD2->ExpTimeA);
	const float ExpTimeRatio_3 = (float)(pCastParamD3->ExpTimeB*1.0f/pCastParamD3->ExpTimeA);	

	const int ImageStep = pCastParamD1->ImageStep;
	const int FactorCnt = sizeof(pCastParamD1->HeightFactor0) / (sizeof(pCastParamD1->HeightFactor0[0]));
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_2[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_3[CUDA_HEIGHT_FACTOR_SIZE];	
	for (i = 0; i<CUDA_HEIGHT_FACTOR_SIZE; i++)
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;
		HeightFactor0_2[i] = HeightFactor1_2[i] = HeightFactor2_2[i] = 0;
		HeightFactor0_3[i] = HeightFactor1_3[i] = HeightFactor2_3[i] = 0;
	}
	for (i = 0; i<FactorCnt; i++)
	{
		if (i >= CUDA_HEIGHT_FACTOR_SIZE) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];
		HeightFactor0_2[i] = pCastParamD2->HeightFactor0[i];	HeightFactor1_2[i] = pCastParamD2->HeightFactor1[i];	HeightFactor2_2[i] = pCastParamD2->HeightFactor2[i];
		HeightFactor0_3[i] = pCastParamD3->HeightFactor0[i];	HeightFactor1_3[i] = pCastParamD3->HeightFactor1[i];	HeightFactor2_3[i] = pCastParamD3->HeightFactor2[i];		
	}
	__syncthreads();//同1個Block多個Thread同步化	

	//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
	//  gridDim		網格大小   (網格包含的區塊數目)	
	for (i = (blockIdx.x*blockDim.x) + threadIdx.x; i < ImageSize; i += blockDim.x*gridDim.x)
	{
		if (i >= ImageSize) { continue; }
		const int x = i%ImageStep;
		const int y = i / ImageStep;

		dA1_1 = pCastParamD1->PtrA1[i];
		dA2_1 = pCastParamD1->PtrA2[i];
		dA3_1 = pCastParamD1->PtrA3[i];
		dA4_1 = pCastParamD1->PtrA4[i];
		dB1_1 = pCastParamD1->PtrB1[i];
		dB2_1 = pCastParamD1->PtrB2[i];
		dB3_1 = pCastParamD1->PtrB3[i];
		dB4_1 = pCastParamD1->PtrB4[i];
		dB5_1 = pCastParamD1->PtrB5[i];
		dB6_1 = pCastParamD1->PtrB6[i];
		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if (NULL != pCastParamD1->HeightFactorPtr) { KValue_1 = pCastParamD1->HeightFactorPtr[i]; }

		dA1_2 = pCastParamD2->PtrA1[i];
		dA2_2 = pCastParamD2->PtrA2[i];
		dA3_2 = pCastParamD2->PtrA3[i];
		dA4_2 = pCastParamD2->PtrA4[i];
		dB1_2 = pCastParamD2->PtrB1[i];
		dB2_2 = pCastParamD2->PtrB2[i];
		dB3_2 = pCastParamD2->PtrB3[i];
		dB4_2 = pCastParamD2->PtrB4[i];
		dB5_2 = pCastParamD2->PtrB5[i];
		dB6_2 = pCastParamD2->PtrB6[i];
		PhaseBase_2 = pCastParamD2->ZeroPhasePtr[i];
		if (NULL != pCastParamD2->HeightFactorPtr) { KValue_2 = pCastParamD2->HeightFactorPtr[i]; }

		dA1_3 = pCastParamD3->PtrA1[i];
		dA2_3 = pCastParamD3->PtrA2[i];
		dA3_3 = pCastParamD3->PtrA3[i];
		dA4_3 = pCastParamD3->PtrA4[i];
		dB1_3 = pCastParamD3->PtrB1[i];
		dB2_3 = pCastParamD3->PtrB2[i];
		dB3_3 = pCastParamD3->PtrB3[i];
		dB4_3 = pCastParamD3->PtrB4[i];
		dB5_3 = pCastParamD3->PtrB5[i];
		dB6_3 = pCastParamD3->PtrB6[i];
		PhaseBase_3 = pCastParamD3->ZeroPhasePtr[i];
		if (NULL != pCastParamD3->HeightFactorPtr) { KValue_3 = pCastParamD3->HeightFactorPtr[i]; }

		if (true == bUseGamma)
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dA3_1 = CalcCudaGamma_Kernel(dA3_1, Gamma_1);
			dA4_1 = CalcCudaGamma_Kernel(dA4_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);
			dB4_1 = CalcCudaGamma_Kernel(dB4_1, Gamma_1);
			dB5_1 = CalcCudaGamma_Kernel(dB5_1, Gamma_1);
			dB6_1 = CalcCudaGamma_Kernel(dB6_1, Gamma_1);

			dA1_2 = CalcCudaGamma_Kernel(dA1_2, Gamma_2);
			dA2_2 = CalcCudaGamma_Kernel(dA2_2, Gamma_2);
			dA3_2 = CalcCudaGamma_Kernel(dA3_2, Gamma_2);
			dA4_2 = CalcCudaGamma_Kernel(dA4_2, Gamma_2);
			dB1_2 = CalcCudaGamma_Kernel(dB1_2, Gamma_2);
			dB2_2 = CalcCudaGamma_Kernel(dB2_2, Gamma_2);
			dB3_2 = CalcCudaGamma_Kernel(dB3_2, Gamma_2);
			dB4_2 = CalcCudaGamma_Kernel(dB4_2, Gamma_2);
			dB5_2 = CalcCudaGamma_Kernel(dB5_2, Gamma_2);
			dB6_2 = CalcCudaGamma_Kernel(dB6_2, Gamma_2);

			dA1_3 = CalcCudaGamma_Kernel(dA1_3, Gamma_3);
			dA2_3 = CalcCudaGamma_Kernel(dA2_3, Gamma_3);
			dA3_3 = CalcCudaGamma_Kernel(dA3_3, Gamma_3);
			dA4_3 = CalcCudaGamma_Kernel(dA4_3, Gamma_3);
			dB1_3 = CalcCudaGamma_Kernel(dB1_3, Gamma_3);
			dB2_3 = CalcCudaGamma_Kernel(dB2_3, Gamma_3);
			dB3_3 = CalcCudaGamma_Kernel(dB3_3, Gamma_3);
			dB4_3 = CalcCudaGamma_Kernel(dB4_3, Gamma_3);
			dB5_3 = CalcCudaGamma_Kernel(dB5_3, Gamma_3);
			dB6_3 = CalcCudaGamma_Kernel(dB6_3, Gamma_3);
		}
		
		Threshold_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;
		Threshold_1=(float)(Threshold_1*ExpTimeRatio_1);
		Threshold_2=(dA1_2+dA2_2+dA3_2+dA4_2)/4.0f;
		Threshold_2=(float)(Threshold_2*ExpTimeRatio_2);
		Threshold_3=(dA1_3+dA2_3+dA3_3+dA4_3)/4.0f;
		Threshold_3=(float)(Threshold_3*ExpTimeRatio_3);		

		CalcCuda6GrayCodeParam_kernel(dB1_1, dB2_1, dB3_1, dB4_1, dB5_1, dB6_1, Threshold_1, CodeMap1, CodeMap2, k1_1, k2_1);
		CalcCuda6GrayCodeParam_kernel(dB1_2, dB2_2, dB3_2, dB4_2, dB5_2, dB6_2, Threshold_2, CodeMap1, CodeMap2, k1_2, k2_2);
		CalcCuda6GrayCodeParam_kernel(dB1_3, dB2_3, dB3_3, dB4_3, dB5_3, dB6_3, Threshold_3, CodeMap1, CodeMap2, k1_3, k2_3);		
		
		CalcCuda4PhaseParamMask_kernel(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_2, MaskA_2, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_3, MaskA_3, PhaseNoiseDefMode);

		//Cast 1
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_1, Period, MaxN, k1_1, k2_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		Mask_1 = MaskA_1;

		//Cast 2		
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_2, Period, MaxN, k1_2, k2_2);
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_2, KValue_2_2, Space_2);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		Mask_2 = MaskA_2;

		//Cast 3
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_3, Period, MaxN, k1_3, k2_3);
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_3, KValue_3_2, Space_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		Mask_3 = MaskA_3;

		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;
		pCastParamD2->PtrMask[i] = Mask_2;	pCastParamD2->PtrSpace[i] = Space_2;
		pCastParamD3->PtrMask[i] = Mask_3;	pCastParamD3->PtrSpace[i] = Space_3;

		if ( MULTI_CAST_MERGE_MODE_JOE_1 == CastMergeMode )
		{
			Raw_1[0]=dA1_1;	Raw_1[1]=dA2_1;	Raw_1[2]=dA3_1;	Raw_1[3]=dA4_1;
			Raw_2[0]=dA1_2;	Raw_2[1]=dA2_2;	Raw_2[2]=dA3_2;	Raw_2[3]=dA4_2;
			Raw_3[0]=dA1_3;	Raw_3[1]=dA2_3;	Raw_3[2]=dA3_3;	Raw_3[3]=dA4_3;			
			MergeCuda3SpaceData_Joe_Kernel(NoiseParam, Raw_1, Mask_1, Space_1, Raw_2, Mask_2, Space_2, Raw_3, Mask_3, Space_3, MaskPtrD[i], SpacePtrD[i]);
		}
		else
		{
			if ( CompareCuda3SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, MaskPtrD[i], SpacePtrD[i]) == false )		
			{	MergeCuda3SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, MaskPtrD[i], SpacePtrD[i]);	}
		}
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSolveSpace221Frames2Period4Cast_2_2_Kernel(TCastParam *pCastParamD1, TCastParam *pCastParamD2, TCastParam *pCastParamD3, TCastParam *pCastParamD4, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//2+2步雙相位-4投光
{
	unsigned int i=0, j=0;	
	int Phase1 = 0;
	int Phase2 = 0;	
	int PhaseM = 0;		
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;		
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	

	#pragma region Cast 1 - Param
	int   PhaseBase_1 = 0;	
	int   dA1_1=0, dA2_1=0;
	int   dB1_1=0, dB2_1=0, dB3_1=0;

	float Space_1=0;
	float KValue_1=0.0f;
	float KValue_1_2=0.0f;
	int   phaseA_1=0, phaseB_1=0;
	float dRatio1_1=0;//, dRatio2_1=0;
	unsigned char Mask_1=0, MaskA_1=0, MaskB_1=0;
	const float P1_1 = (float)(pCastParamD1->PerA);
	const float P2_1 = (float)(pCastParamD1->PerB);	
	const float Gamma_1=(float)(pCastParamD1->Gamma);	
	const float ExpTimeRatio_1 = (float)(pCastParamD1->ExpTimeB*1.0f/pCastParamD1->ExpTimeA);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_1, P2_1, dRatio1_1);
#pragma endregion
	#pragma region Cast 2 - Param
	int   PhaseBase_2 = 0;	
	int   dA1_2=0, dA2_2=0;
	int   dB1_2=0, dB2_2=0, dB3_2=0;

	float Space_2=0;
	float KValue_2=0.0f;
	float KValue_2_2=0.0f;
	int   phaseA_2=0, phaseB_2=0;
	float dRatio1_2=0;//, dRatio2_2=0;
	unsigned char Mask_2=0, MaskA_2=0, MaskB_2=0;
	const float P1_2 = (float)(pCastParamD2->PerA);
	const float P2_2 = (float)(pCastParamD2->PerB);	
	const float Gamma_2=(float)(pCastParamD2->Gamma);	
	const float ExpTimeRatio_2 = (float)(pCastParamD2->ExpTimeB*1.0f/pCastParamD2->ExpTimeA);	
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_2, P2_2, dRatio1_2);
#pragma endregion
	#pragma region Cast 3 - Param
	int   PhaseBase_3 = 0;	
	int   dA1_3=0, dA2_3=0;
	int   dB1_3=0, dB2_3=0, dB3_3=0;

	float Space_3=0;
	float KValue_3=0.0f;
	float KValue_3_2=0.0f;
	int   phaseA_3=0, phaseB_3=0;
	float dRatio1_3=0;//, dRatio2_3=0;
	unsigned char Mask_3=0, MaskA_3=0, MaskB_3=0;
	const float P1_3 = (float)(pCastParamD3->PerA);
	const float P2_3 = (float)(pCastParamD3->PerB);	
	const float Gamma_3=(float)(pCastParamD3->Gamma);	
	const float ExpTimeRatio_3 = (float)(pCastParamD3->ExpTimeB*1.0f/pCastParamD3->ExpTimeA);		
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_3, P2_3, dRatio1_3);
#pragma endregion
	#pragma region Cast 4 - Param
	int   PhaseBase_4 = 0;	
	int   dA1_4=0, dA2_4=0;
	int   dB1_4=0, dB2_4=0, dB3_4=0;

	float Space_4=0;
	float KValue_4=0.0f;
	float KValue_4_2=0.0f;
	int   phaseA_4=0, phaseB_4=0;
	float dRatio1_4=0;//, dRatio2_4=0;
	unsigned char Mask_4=0, MaskA_4=0, MaskB_4=0;
	const float P1_4 = (float)(pCastParamD4->PerA);
	const float P2_4 = (float)(pCastParamD4->PerB);	
	const float Gamma_4=(float)(pCastParamD4->Gamma);	
	const float ExpTimeRatio_4 = (float)(pCastParamD4->ExpTimeB*1.0f/pCastParamD4->ExpTimeA);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_4, P2_4, dRatio1_4);
#pragma endregion
	
	const int ImageStep = pCastParamD1->ImageStep;	
	const int FactorCnt=sizeof(pCastParamD1->HeightFactor0)/(sizeof(pCastParamD1->HeightFactor0[0]));	
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_2[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_3[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_4[CUDA_HEIGHT_FACTOR_SIZE];
	for ( i=0; i<CUDA_HEIGHT_FACTOR_SIZE; i++ )
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;		
		HeightFactor0_2[i] = HeightFactor1_2[i] = HeightFactor2_2[i] = 0;		
		HeightFactor0_3[i] = HeightFactor1_3[i] = HeightFactor2_3[i] = 0;		
		HeightFactor0_4[i] = HeightFactor1_4[i] = HeightFactor2_4[i] = 0;		
	}
	for ( i=0; i<FactorCnt; i++ )
	{
		if ( i>=CUDA_HEIGHT_FACTOR_SIZE ) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];		
		HeightFactor0_2[i] = pCastParamD2->HeightFactor0[i];	HeightFactor1_2[i] = pCastParamD2->HeightFactor1[i];	HeightFactor2_2[i] = pCastParamD2->HeightFactor2[i];
		HeightFactor0_3[i] = pCastParamD3->HeightFactor0[i];	HeightFactor1_3[i] = pCastParamD3->HeightFactor1[i];	HeightFactor2_3[i] = pCastParamD3->HeightFactor2[i];
		HeightFactor0_4[i] = pCastParamD4->HeightFactor0[i];	HeightFactor1_4[i] = pCastParamD4->HeightFactor1[i];	HeightFactor2_4[i] = pCastParamD4->HeightFactor2[i];
	}	
	__syncthreads();//同1個Block多個Thread同步化

	//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
	//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{		
		if ( i >= ImageSize ) { continue; }
		const int x = i%ImageStep;
		const int y = i/ImageStep;

		#pragma region dA_1
		dA1_1 = pCastParamD1->PtrA1[i];
		dA2_1 = pCastParamD1->PtrA2[i];
		dB1_1 = pCastParamD1->PtrB1[i];
		dB2_1 = pCastParamD1->PtrB2[i];
		dB3_1 = pCastParamD1->PtrB3[i];
		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if ( NULL != pCastParamD1->HeightFactorPtr ) { KValue_1    = pCastParamD1->HeightFactorPtr[i]; }
		if ( true == bUseGamma )
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);	
		}
#pragma endregion
		#pragma region dA_2
		dA1_2 = pCastParamD2->PtrA1[i];
		dA2_2 = pCastParamD2->PtrA2[i];
		dB1_2 = pCastParamD2->PtrB1[i];
		dB2_2 = pCastParamD2->PtrB2[i];
		dB3_2 = pCastParamD2->PtrB3[i];
		PhaseBase_2 = pCastParamD2->ZeroPhasePtr[i];
		if ( NULL != pCastParamD2->HeightFactorPtr ) { KValue_2    = pCastParamD2->HeightFactorPtr[i]; }
		if ( true == bUseGamma )
		{
			dA1_2 = CalcCudaGamma_Kernel(dA1_2, Gamma_2);
			dA2_2 = CalcCudaGamma_Kernel(dA2_2, Gamma_2);
			dB1_2 = CalcCudaGamma_Kernel(dB1_2, Gamma_2);
			dB2_2 = CalcCudaGamma_Kernel(dB2_2, Gamma_2);
			dB3_2 = CalcCudaGamma_Kernel(dB3_2, Gamma_2);	
		}
#pragma endregion
		#pragma region dA_3
		dA1_3 = pCastParamD3->PtrA1[i];
		dA2_3 = pCastParamD3->PtrA2[i];
		dB1_3 = pCastParamD3->PtrB1[i];
		dB2_3 = pCastParamD3->PtrB2[i];
		dB3_3 = pCastParamD3->PtrB3[i];
		PhaseBase_3 = pCastParamD3->ZeroPhasePtr[i];
		if ( NULL != pCastParamD3->HeightFactorPtr ) { KValue_3    = pCastParamD3->HeightFactorPtr[i]; }
		if ( true == bUseGamma )
		{
			dA1_3 = CalcCudaGamma_Kernel(dA1_3, Gamma_3);
			dA2_3 = CalcCudaGamma_Kernel(dA2_3, Gamma_3);
			dB1_3 = CalcCudaGamma_Kernel(dB1_3, Gamma_3);
			dB2_3 = CalcCudaGamma_Kernel(dB2_3, Gamma_3);
			dB3_3 = CalcCudaGamma_Kernel(dB3_3, Gamma_3);	
		}
#pragma endregion
		#pragma region dA_4
		dA1_4 = pCastParamD4->PtrA1[i];
		dA2_4 = pCastParamD4->PtrA2[i];
		dB1_4 = pCastParamD4->PtrB1[i];
		dB2_4 = pCastParamD4->PtrB2[i];
		dB3_4 = pCastParamD4->PtrB3[i];
		PhaseBase_4 = pCastParamD4->ZeroPhasePtr[i];
		if ( NULL != pCastParamD4->HeightFactorPtr ) { KValue_4    = pCastParamD4->HeightFactorPtr[i]; }
		if ( true == bUseGamma )
		{
			dA1_4 = CalcCudaGamma_Kernel(dA1_4, Gamma_4);
			dA2_4 = CalcCudaGamma_Kernel(dA2_4, Gamma_4);
			dB1_4 = CalcCudaGamma_Kernel(dB1_4, Gamma_4);
			dB2_4 = CalcCudaGamma_Kernel(dB2_4, Gamma_4);
			dB3_4 = CalcCudaGamma_Kernel(dB3_4, Gamma_4);	
		}
#pragma endregion

		#pragma region Cast 1 - Phase
		CalcCuda21PhaseParamMask_kernel(dA1_1, dB3_1, dA2_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1);
		CalcCuda21PhaseParamMask_kernel(dB1_1, dB3_1, dB2_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_1, MaskB_1);		
		if ( P1_1 < P2_1 )
		{			
			Phase1 = phaseA_1;
			Phase2 = phaseB_1;			
		}
		else
		{	
			Phase1 = phaseB_1;//注意相位次序
			Phase2 = phaseA_1;//
		}
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		Mask_1 = CombineCudaPhaseMask_Kernel(MaskA_1, MaskB_1);
#pragma endregion
		#pragma region Cast 2 - Phase
		CalcCuda21PhaseParamMask_kernel(dA1_2, dB3_2, dA2_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_2, MaskA_2);
		CalcCuda21PhaseParamMask_kernel(dB1_2, dB3_2, dB2_2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_2, MaskB_2);		
		if ( P1_2 < P2_2 )
		{			
			Phase1 = phaseA_2;
			Phase2 = phaseB_2;			
		}
		else
		{	
			Phase1 = phaseB_2;//注意相位次序
			Phase2 = phaseA_2;//
		}
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_2);
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_2, KValue_2_2, Space_2);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		Mask_2 = CombineCudaPhaseMask_Kernel(MaskA_2, MaskB_2);
#pragma endregion
		#pragma region Cast 3 - Phase
		CalcCuda21PhaseParamMask_kernel(dA1_3, dB3_3, dA2_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_3, MaskA_3);
		CalcCuda21PhaseParamMask_kernel(dB1_3, dB3_3, dB2_3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_3, MaskB_3);		
		if ( P1_3 < P2_3 )
		{			
			Phase1 = phaseA_3;
			Phase2 = phaseB_3;			
		}
		else
		{	
			Phase1 = phaseB_3;//注意相位次序
			Phase2 = phaseA_3;//
		}
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_3);
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_3, KValue_3_2, Space_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		Mask_3 = CombineCudaPhaseMask_Kernel(MaskA_3, MaskB_3);
#pragma endregion
		#pragma region Cast 4 - Phase
		CalcCuda21PhaseParamMask_kernel(dA1_4, dB3_4, dA2_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_4, MaskA_4);
		CalcCuda21PhaseParamMask_kernel(dB1_4, dB3_4, dB2_4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_4, MaskB_4);		
		if ( P1_4 < P2_4 )
		{			
			Phase1 = phaseA_4;
			Phase2 = phaseB_4;			
		}
		else
		{	
			Phase1 = phaseB_4;//注意相位次序
			Phase2 = phaseA_4;//
		}
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_4);
		DeductBasePhase_Kernel(PhaseBase_4, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_4, KValue_4_2, Space_4);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);
		Mask_4 = CombineCudaPhaseMask_Kernel(MaskA_4, MaskB_4);
#pragma endregion		

		//CompareCuda4OppositeGray_Kernel(NoiseParam, cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);		
		if ( CompareCuda4SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]) == false )		
		{	MergeCuda4SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]);		}
		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;
		pCastParamD2->PtrMask[i] = Mask_2;	pCastParamD2->PtrSpace[i] = Space_2;
		pCastParamD3->PtrMask[i] = Mask_3;	pCastParamD3->PtrSpace[i] = Space_3;
		pCastParamD4->PtrMask[i] = Mask_4;	pCastParamD4->PtrSpace[i] = Space_4;		
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSolveSpace4Frames2Period4Cast_4_2_Kernel(TCastParam *pCastParamD1, TCastParam *pCastParamD2, TCastParam *pCastParamD3, TCastParam *pCastParamD4, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//4+2步雙相位-4投光
{
	unsigned int i=0, j=0;	
	
	//Cast 1
	int   PhaseBase_1 = 0;	
	int   dA1_1=0, dA2_1=0, dA3_1=0, dA4_1=0;
	int   dB1_1=0, dB2_1=0, dB3_1=0;

	float Space_1=0;
	float KValue_1=0.0f;
	float KValue_1_2=0.0f;
	int   phaseA_1=0, phaseB_1=0;
	float dRatio1_1=0;//, dRatio2_1=0;
	unsigned char Mask_1=0, MaskA_1=0, MaskB_1=0;
	const float P1_1 = (float)(pCastParamD1->PerA);
	const float P2_1 = (float)(pCastParamD1->PerB);	
	const float Gamma_1=(float)(pCastParamD1->Gamma);
	
	//Cast 2 
	int   PhaseBase_2 = 0;	
	int   dA1_2=0, dA2_2=0, dA3_2=0, dA4_2=0;
	int   dB1_2=0, dB2_2=0, dB3_2=0;

	float Space_2=0;
	float KValue_2=0.0f;
	float KValue_2_2=0.0f;
	int   phaseA_2=0, phaseB_2=0;		
	float dRatio1_2=0;//, dRatio2_2=0;
	unsigned char Mask_2, MaskA_2=0, MaskB_2=0;
	const float P1_2 = (float)(pCastParamD2->PerA);
	const float P2_2 = (float)(pCastParamD2->PerB);	
	const float Gamma_2=(float)(pCastParamD1->Gamma);

	//Cast 3
	int   PhaseBase_3 = 0;	
	int   dA1_3=0, dA2_3=0, dA3_3=0, dA4_3=0;
	int   dB1_3=0, dB2_3=0, dB3_3=0;

	float Space_3=0;
	float KValue_3=0.0f;
	float KValue_3_2=0.0f;
	int   phaseA_3=0, phaseB_3=0;		
	float dRatio1_3=0;//, dRatio2_3=0;
	unsigned char Mask_3, MaskA_3=0, MaskB_3=0;
	const float P1_3 = (float)(pCastParamD3->PerA);
	const float P2_3 = (float)(pCastParamD3->PerB);	
	const float Gamma_3=(float)(pCastParamD3->Gamma);
	
	//Cast 4
	int   PhaseBase_4 = 0;	
	int   dA1_4=0, dA2_4=0, dA3_4=0, dA4_4=0;
	int   dB1_4=0, dB2_4=0, dB3_4=0;

	float Space_4=0;
	float KValue_4=0.0f;
	float KValue_4_2=0.0f;
	int   phaseA_4=0, phaseB_4=0;		
	float dRatio1_4=0;//, dRatio2_4=0;
	unsigned char Mask_4, MaskA_4=0, MaskB_4=0;
	const float P1_4 = (float)(pCastParamD4->PerA);
	const float P2_4 = (float)(pCastParamD4->PerB);	
	const float Gamma_4=(float)(pCastParamD4->Gamma);

	int Phase1 = 0;
	int Phase2 = 0;	
	int PhaseM = 0;		
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;	
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	

	const float ExpTimeRatio_1 = (float)(pCastParamD1->ExpTimeB*1.0f/pCastParamD1->ExpTimeA);
	const float ExpTimeRatio_2 = (float)(pCastParamD2->ExpTimeB*1.0f/pCastParamD2->ExpTimeA);
	const float ExpTimeRatio_3 = (float)(pCastParamD3->ExpTimeB*1.0f/pCastParamD3->ExpTimeA);
	const float ExpTimeRatio_4 = (float)(pCastParamD4->ExpTimeB*1.0f/pCastParamD4->ExpTimeA);
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用			

	const int ImageStep = pCastParamD1->ImageStep;	
	const int FactorCnt=sizeof(pCastParamD1->HeightFactor0)/(sizeof(pCastParamD1->HeightFactor0[0]));	
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_2[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_3[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_4[CUDA_HEIGHT_FACTOR_SIZE];		
	for ( i=0; i<CUDA_HEIGHT_FACTOR_SIZE; i++ )
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;
		HeightFactor0_2[i] = HeightFactor1_2[i] = HeightFactor2_2[i] = 0;
		HeightFactor0_3[i] = HeightFactor1_3[i] = HeightFactor2_3[i] = 0;
		HeightFactor0_4[i] = HeightFactor1_4[i] = HeightFactor2_4[i] = 0;
	}
	for ( i=0; i<FactorCnt; i++ )
	{
		if ( i>=CUDA_HEIGHT_FACTOR_SIZE ) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];
		HeightFactor0_2[i] = pCastParamD2->HeightFactor0[i];	HeightFactor1_2[i] = pCastParamD2->HeightFactor1[i];	HeightFactor2_2[i] = pCastParamD2->HeightFactor2[i];
		HeightFactor0_3[i] = pCastParamD3->HeightFactor0[i];	HeightFactor1_3[i] = pCastParamD3->HeightFactor1[i];	HeightFactor2_3[i] = pCastParamD3->HeightFactor2[i];
		HeightFactor0_4[i] = pCastParamD4->HeightFactor0[i];	HeightFactor1_4[i] = pCastParamD4->HeightFactor1[i];	HeightFactor2_4[i] = pCastParamD4->HeightFactor2[i];
	}	
	__syncthreads();//同1個Block多個Thread同步化

	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_1, P2_1, dRatio1_1);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_2, P2_2, dRatio1_2);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_3, P2_3, dRatio1_3);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_4, P2_4, dRatio1_4);

//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{		
		if ( i >= ImageSize ) { continue; }
		const int x = i%ImageStep;
		const int y = i/ImageStep;

		dA1_1 = pCastParamD1->PtrA1[i];
		dA2_1 = pCastParamD1->PtrA2[i];
		dA3_1 = pCastParamD1->PtrA3[i]; 
		dA4_1 = pCastParamD1->PtrA4[i];
		dB1_1 = pCastParamD1->PtrB1[i];
		dB3_1 = pCastParamD1->PtrB2[i];
		dB2_1 = (dA1_1+dA2_1+dA3_1+dA4_1)>>2; 
		dB2_1 = (int)((ExpTimeRatio_1*dB2_1)+0.5f);		
		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if ( NULL != pCastParamD1->HeightFactorPtr ) { KValue_1    = pCastParamD1->HeightFactorPtr[i]; }

		dA1_2 = pCastParamD2->PtrA1[i];
		dA2_2 = pCastParamD2->PtrA2[i];
		dA3_2 = pCastParamD2->PtrA3[i]; 
		dA4_2 = pCastParamD2->PtrA4[i];
		dB1_2 = pCastParamD2->PtrB1[i];
		dB3_2 = pCastParamD2->PtrB2[i];
		dB2_2 = (dA1_2+dA2_2+dA3_2+dA4_2)>>2; 
		dB2_2 = (int)((ExpTimeRatio_2*dB2_2)+0.5f);
		PhaseBase_2 = pCastParamD2->ZeroPhasePtr[i];
		if ( NULL != pCastParamD2->HeightFactorPtr ) { KValue_2    = pCastParamD2->HeightFactorPtr[i]; }

		dA1_3 = pCastParamD3->PtrA1[i];
		dA2_3 = pCastParamD3->PtrA2[i];
		dA3_3 = pCastParamD3->PtrA3[i]; 
		dA4_3 = pCastParamD3->PtrA4[i];
		dB1_3 = pCastParamD3->PtrB1[i];
		dB3_3 = pCastParamD3->PtrB2[i];
		dB2_3 = (dA1_3+dA2_3+dA3_3+dA4_3)>>2; 
		dB2_3 = (int)((ExpTimeRatio_3*dB2_3)+0.5f);
		PhaseBase_3 = pCastParamD3->ZeroPhasePtr[i];
		if ( NULL != pCastParamD3->HeightFactorPtr ) { KValue_3    = pCastParamD3->HeightFactorPtr[i]; }
		
		dA1_4 = pCastParamD4->PtrA1[i];
		dA2_4 = pCastParamD4->PtrA2[i];
		dA3_4 = pCastParamD4->PtrA3[i]; 
		dA4_4 = pCastParamD4->PtrA4[i];
		dB1_4 = pCastParamD4->PtrB1[i];
		dB3_4 = pCastParamD4->PtrB2[i];
		dB2_4 = (dA1_4+dA2_4+dA3_4+dA4_4)>>2; 
		dB2_4 = (int)((ExpTimeRatio_4*dB2_4)+0.5f);
		PhaseBase_4 = pCastParamD4->ZeroPhasePtr[i];
		if ( NULL != pCastParamD4->HeightFactorPtr ) { KValue_4    = pCastParamD4->HeightFactorPtr[i]; }
		
		if ( true == bUseGamma )
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dA3_1 = CalcCudaGamma_Kernel(dA3_1, Gamma_1);
			dA4_1 = CalcCudaGamma_Kernel(dA4_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);			

			dA1_2 = CalcCudaGamma_Kernel(dA1_2, Gamma_2);
			dA2_2 = CalcCudaGamma_Kernel(dA2_2, Gamma_2);
			dA3_2 = CalcCudaGamma_Kernel(dA3_2, Gamma_2);
			dA4_2 = CalcCudaGamma_Kernel(dA4_2, Gamma_2);
			dB1_2 = CalcCudaGamma_Kernel(dB1_2, Gamma_2);
			dB2_2 = CalcCudaGamma_Kernel(dB2_2, Gamma_2);
			dB3_2 = CalcCudaGamma_Kernel(dB3_2, Gamma_2);

			dA1_3 = CalcCudaGamma_Kernel(dA1_3, Gamma_3);
			dA2_3 = CalcCudaGamma_Kernel(dA2_3, Gamma_3);
			dA3_3 = CalcCudaGamma_Kernel(dA3_3, Gamma_3);
			dA4_3 = CalcCudaGamma_Kernel(dA4_3, Gamma_3);
			dB1_3 = CalcCudaGamma_Kernel(dB1_3, Gamma_3);
			dB2_3 = CalcCudaGamma_Kernel(dB2_3, Gamma_3);
			dB3_3 = CalcCudaGamma_Kernel(dB3_3, Gamma_3);

			dA1_4 = CalcCudaGamma_Kernel(dA1_4, Gamma_4);
			dA2_4 = CalcCudaGamma_Kernel(dA2_4, Gamma_4);
			dA3_4 = CalcCudaGamma_Kernel(dA3_4, Gamma_4);
			dA4_4 = CalcCudaGamma_Kernel(dA4_4, Gamma_4);
			dB1_4 = CalcCudaGamma_Kernel(dB1_4, Gamma_4);
			dB2_4 = CalcCudaGamma_Kernel(dB2_4, Gamma_4);
			dB3_4 = CalcCudaGamma_Kernel(dB3_4, Gamma_4);
		}
	
		CalcCuda4PhaseParamMask_kernel(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dB1_1, dB2_1, dB3_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_1, MaskB_1);
		CalcCuda4PhaseParamMask_kernel(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_2, MaskA_2, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dB1_2, dB2_2, dB3_2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_2, MaskB_2);
		CalcCuda4PhaseParamMask_kernel(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_3, MaskA_3, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dB1_3, dB2_3, dB3_3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_3, MaskB_3);
		CalcCuda4PhaseParamMask_kernel(dA1_4, dA2_4, dA3_4, dA4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_4, MaskA_4, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dB1_4, dB2_4, dB3_4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_4, MaskB_4);		
		
		//Cast 1		
		if ( P1_1 < P2_1 )
		{			
			Phase1 = phaseA_1;
			Phase2 = phaseB_1;			
		}
		else
		{	
			Phase1 = phaseB_1;//注意相位次序
			Phase2 = phaseA_1;//
		}
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		Mask_1 = CombineCudaPhaseMask_Kernel(MaskA_1, MaskB_1);

		//Cast 2		
		if ( P1_2 < P2_2 )
		{			
			Phase1 = phaseA_2;
			Phase2 = phaseB_2;
		}
		else
		{	
			Phase1 = phaseB_2;//注意相位次序
			Phase2 = phaseA_2;//
		}
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_2);
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_2, KValue_2_2, Space_2);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		Mask_2 = CombineCudaPhaseMask_Kernel(MaskA_2, MaskB_2);

		//Cast 3
		if ( P1_3 < P2_3 )
		{			
			Phase1 = phaseA_3;
			Phase2 = phaseB_3;
		}
		else
		{	
			Phase1 = phaseB_3;//注意相位次序
			Phase2 = phaseA_3;//
		}
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_3);
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_3, KValue_3_2, Space_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		Mask_3 = CombineCudaPhaseMask_Kernel(MaskA_3, MaskB_3);

		//Cast 4
		if ( P1_4 < P2_4 )
		{			
			Phase1 = phaseA_4;
			Phase2 = phaseB_4;
		}
		else
		{	
			Phase1 = phaseB_4;//注意相位次序
			Phase2 = phaseA_4;//
		}
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_4);		
		DeductBasePhase_Kernel(PhaseBase_4, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_4, KValue_4_2, Space_4);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);
		Mask_4 = CombineCudaPhaseMask_Kernel(MaskA_4, MaskB_4);

		//CompareCuda4OppositeGray_Kernel(NoiseParam, cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);		
		if ( CompareCuda4SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]) == false )		
		{	MergeCuda4SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]);		}
		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;
		pCastParamD2->PtrMask[i] = Mask_2;	pCastParamD2->PtrSpace[i] = Space_2;
		pCastParamD3->PtrMask[i] = Mask_3;	pCastParamD3->PtrSpace[i] = Space_3;
		pCastParamD4->PtrMask[i] = Mask_4;	pCastParamD4->PtrSpace[i] = Space_4;		
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSolveSpace4Frames2Period4Cast_4_4_Kernel(TCastParam *pCastParamD1, TCastParam *pCastParamD2, TCastParam *pCastParamD3, TCastParam *pCastParamD4, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//4+4步雙相位-4投光

{	
	unsigned int i=0, j=0;	
	
	//Cast 1
	int   PhaseBase_1 = 0;	
	int   dA1_1=0, dA2_1=0, dA3_1=0, dA4_1=0;
	int   dB1_1=0, dB2_1=0, dB3_1=0, dB4_1=0;

	float Space_1=0;
	float KValue_1=0.0f;
	float KValue_1_2=0.0f;
	int   phaseA_1=0, phaseB_1=0;
	float dRatio1_1=0;//, dRatio2_1=0;
	unsigned char Mask_1=0, MaskA_1=0, MaskB_1=0;
	const float P1_1 = (float)(pCastParamD1->PerA);
	const float P2_1 = (float)(pCastParamD1->PerB);	
	const float Gamma_1=(float)(pCastParamD1->Gamma);
	
	//Cast 2 
	int   PhaseBase_2 = 0;	
	int   dA1_2=0, dA2_2=0, dA3_2=0, dA4_2=0;
	int   dB1_2=0, dB2_2=0, dB3_2=0, dB4_2=0;

	float Space_2=0;
	float KValue_2=0.0f;
	float KValue_2_2=0.0f;
	int   phaseA_2=0, phaseB_2=0;		
	float dRatio1_2=0;//, dRatio2_2=0;
	unsigned char Mask_2, MaskA_2=0, MaskB_2=0;
	const float P1_2 = (float)(pCastParamD2->PerA);
	const float P2_2 = (float)(pCastParamD2->PerB);	
	const float Gamma_2=(float)(pCastParamD1->Gamma);

	//Cast 3
	int   PhaseBase_3 = 0;	
	int   dA1_3=0, dA2_3=0, dA3_3=0, dA4_3=0;
	int   dB1_3=0, dB2_3=0, dB3_3=0, dB4_3=0;

	float Space_3=0;
	float KValue_3=0.0f;
	float KValue_3_2=0.0f;
	int   phaseA_3=0, phaseB_3=0;		
	float dRatio1_3=0;//, dRatio2_3=0;
	unsigned char Mask_3, MaskA_3=0, MaskB_3=0;
	const float P1_3 = (float)(pCastParamD3->PerA);
	const float P2_3 = (float)(pCastParamD3->PerB);	
	const float Gamma_3=(float)(pCastParamD3->Gamma);
	
	//Cast 4
	int   PhaseBase_4 = 0;	
	int   dA1_4=0, dA2_4=0, dA3_4=0, dA4_4=0;
	int   dB1_4=0, dB2_4=0, dB3_4=0, dB4_4=0;

	float Space_4=0;
	float KValue_4=0.0f;
	float KValue_4_2=0.0f;
	int   phaseA_4=0, phaseB_4=0;		
	float dRatio1_4=0;//, dRatio2_4=0;
	unsigned char Mask_4, MaskA_4=0, MaskB_4=0;
	const float P1_4 = (float)(pCastParamD4->PerA);
	const float P2_4 = (float)(pCastParamD4->PerB);	
	const float Gamma_4=(float)(pCastParamD4->Gamma);

	int Phase1 = 0;
	int Phase2 = 0;	
	int PhaseM = 0;		
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;	
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用
	
	const int ImageStep = pCastParamD1->ImageStep;	
	const int FactorCnt=sizeof(pCastParamD1->HeightFactor0)/(sizeof(pCastParamD1->HeightFactor0[0]));	
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_2[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_3[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_4[CUDA_HEIGHT_FACTOR_SIZE];		
	for ( i=0; i<CUDA_HEIGHT_FACTOR_SIZE; i++ )
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;
		HeightFactor0_2[i] = HeightFactor1_2[i] = HeightFactor2_2[i] = 0;
		HeightFactor0_3[i] = HeightFactor1_3[i] = HeightFactor2_3[i] = 0;
		HeightFactor0_4[i] = HeightFactor1_4[i] = HeightFactor2_4[i] = 0;
	}
	for ( i=0; i<FactorCnt; i++ )
	{
		if ( i>=CUDA_HEIGHT_FACTOR_SIZE ) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];
		HeightFactor0_2[i] = pCastParamD2->HeightFactor0[i];	HeightFactor1_2[i] = pCastParamD2->HeightFactor1[i];	HeightFactor2_2[i] = pCastParamD2->HeightFactor2[i];
		HeightFactor0_3[i] = pCastParamD3->HeightFactor0[i];	HeightFactor1_3[i] = pCastParamD3->HeightFactor1[i];	HeightFactor2_3[i] = pCastParamD3->HeightFactor2[i];
		HeightFactor0_4[i] = pCastParamD4->HeightFactor0[i];	HeightFactor1_4[i] = pCastParamD4->HeightFactor1[i];	HeightFactor2_4[i] = pCastParamD4->HeightFactor2[i];
	}	
	__syncthreads();//同1個Block多個Thread同步化

	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_1, P2_1, dRatio1_1);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_2, P2_2, dRatio1_2);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_3, P2_3, dRatio1_3);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_4, P2_4, dRatio1_4);

//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{		
		if ( i >= ImageSize ) { continue; }
		const int x = i%ImageStep;
		const int y = i/ImageStep;

		dA1_1 = pCastParamD1->PtrA1[i];
		dA2_1 = pCastParamD1->PtrA2[i];
		dA3_1 = pCastParamD1->PtrA3[i]; 
		dA4_1 = pCastParamD1->PtrA4[i];
		dB1_1 = pCastParamD1->PtrB1[i];
		dB2_1 = pCastParamD1->PtrB2[i];
		dB3_1 = pCastParamD1->PtrB3[i]; 
		dB4_1 = pCastParamD1->PtrB4[i];
		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if ( NULL != pCastParamD1->HeightFactorPtr ) { KValue_1    = pCastParamD1->HeightFactorPtr[i]; }

		dA1_2 = pCastParamD2->PtrA1[i];
		dA2_2 = pCastParamD2->PtrA2[i];
		dA3_2 = pCastParamD2->PtrA3[i]; 
		dA4_2 = pCastParamD2->PtrA4[i];
		dB1_2 = pCastParamD2->PtrB1[i];
		dB2_2 = pCastParamD2->PtrB2[i];
		dB3_2 = pCastParamD2->PtrB3[i]; 
		dB4_2 = pCastParamD2->PtrB4[i];
		PhaseBase_2 = pCastParamD2->ZeroPhasePtr[i];
		if ( NULL != pCastParamD2->HeightFactorPtr ) { KValue_2    = pCastParamD2->HeightFactorPtr[i]; }

		dA1_3 = pCastParamD3->PtrA1[i];
		dA2_3 = pCastParamD3->PtrA2[i];
		dA3_3 = pCastParamD3->PtrA3[i]; 
		dA4_3 = pCastParamD3->PtrA4[i];
		dB1_3 = pCastParamD3->PtrB1[i];
		dB2_3 = pCastParamD3->PtrB2[i];
		dB3_3 = pCastParamD3->PtrB3[i]; 
		dB4_3 = pCastParamD3->PtrB4[i];
		PhaseBase_3 = pCastParamD3->ZeroPhasePtr[i];
		if ( NULL != pCastParamD3->HeightFactorPtr ) { KValue_3    = pCastParamD3->HeightFactorPtr[i]; }
		
		dA1_4 = pCastParamD4->PtrA1[i];
		dA2_4 = pCastParamD4->PtrA2[i];
		dA3_4 = pCastParamD4->PtrA3[i]; 
		dA4_4 = pCastParamD4->PtrA4[i];
		dB1_4 = pCastParamD4->PtrB1[i];
		dB2_4 = pCastParamD4->PtrB2[i];
		dB3_4 = pCastParamD4->PtrB3[i]; 
		dB4_4 = pCastParamD4->PtrB4[i];
		PhaseBase_4 = pCastParamD4->ZeroPhasePtr[i];
		if ( NULL != pCastParamD4->HeightFactorPtr ) { KValue_4    = pCastParamD4->HeightFactorPtr[i]; }
		
		if ( true == bUseGamma )
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dA3_1 = CalcCudaGamma_Kernel(dA3_1, Gamma_1);
			dA4_1 = CalcCudaGamma_Kernel(dA4_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);
			dB4_1 = CalcCudaGamma_Kernel(dB4_1, Gamma_1);

			dA1_2 = CalcCudaGamma_Kernel(dA1_2, Gamma_2);
			dA2_2 = CalcCudaGamma_Kernel(dA2_2, Gamma_2);
			dA3_2 = CalcCudaGamma_Kernel(dA3_2, Gamma_2);
			dA4_2 = CalcCudaGamma_Kernel(dA4_2, Gamma_2);
			dB1_2 = CalcCudaGamma_Kernel(dB1_2, Gamma_2);
			dB2_2 = CalcCudaGamma_Kernel(dB2_2, Gamma_2);
			dB3_2 = CalcCudaGamma_Kernel(dB3_2, Gamma_2);
			dB4_2 = CalcCudaGamma_Kernel(dB4_2, Gamma_2);

			dA1_3 = CalcCudaGamma_Kernel(dA1_3, Gamma_3);
			dA2_3 = CalcCudaGamma_Kernel(dA2_3, Gamma_3);
			dA3_3 = CalcCudaGamma_Kernel(dA3_3, Gamma_3);
			dA4_3 = CalcCudaGamma_Kernel(dA4_3, Gamma_3);
			dB1_3 = CalcCudaGamma_Kernel(dB1_3, Gamma_3);
			dB2_3 = CalcCudaGamma_Kernel(dB2_3, Gamma_3);
			dB3_3 = CalcCudaGamma_Kernel(dB3_3, Gamma_3);
			dB4_3 = CalcCudaGamma_Kernel(dB4_3, Gamma_3);

			dA1_4 = CalcCudaGamma_Kernel(dA1_4, Gamma_4);
			dA2_4 = CalcCudaGamma_Kernel(dA2_4, Gamma_4);
			dA3_4 = CalcCudaGamma_Kernel(dA3_4, Gamma_4);
			dA4_4 = CalcCudaGamma_Kernel(dA4_4, Gamma_4);
			dB1_4 = CalcCudaGamma_Kernel(dB1_4, Gamma_4);
			dB2_4 = CalcCudaGamma_Kernel(dB2_4, Gamma_4);
			dB3_4 = CalcCudaGamma_Kernel(dB3_4, Gamma_4);
			dB4_4 = CalcCudaGamma_Kernel(dB4_4, Gamma_4);
		}
	
		CalcCuda4PhaseParamMask_kernel(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dB1_1, dB2_1, dB3_1, dB4_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_1, MaskB_1, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_2, MaskA_2, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dB1_2, dB2_2, dB3_2, dB4_2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_2, MaskB_2, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_3, MaskA_3, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dB1_3, dB2_3, dB3_3, dB4_3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_3, MaskB_3, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dA1_4, dA2_4, dA3_4, dA4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_4, MaskA_4, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dB1_4, dB2_4, dB3_4, dB4_4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_4, MaskB_4, PhaseNoiseDefMode);		
		
		//Cast 1		
		if ( P1_1 < P2_1 )
		{			
			Phase1 = phaseA_1;
			Phase2 = phaseB_1;			
		}
		else
		{	
			Phase1 = phaseB_1;//注意相位次序
			Phase2 = phaseA_1;//
		}
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		Mask_1 = CombineCudaPhaseMask_Kernel(MaskA_1, MaskB_1);

		//Cast 2		
		if ( P1_2 < P2_2 )
		{			
			Phase1 = phaseA_2;
			Phase2 = phaseB_2;
		}
		else
		{	
			Phase1 = phaseB_2;//注意相位次序
			Phase2 = phaseA_2;//
		}
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_2);
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_2, KValue_2_2, Space_2);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		Mask_2 = CombineCudaPhaseMask_Kernel(MaskA_2, MaskB_2);

		//Cast 3
		if ( P1_3 < P2_3 )
		{			
			Phase1 = phaseA_3;
			Phase2 = phaseB_3;
		}
		else
		{	
			Phase1 = phaseB_3;//注意相位次序
			Phase2 = phaseA_3;//
		}
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_3);
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM);		
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_3, KValue_3_2, Space_3);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		Mask_3 = CombineCudaPhaseMask_Kernel(MaskA_3, MaskB_3);

		//Cast 4
		if ( P1_4 < P2_4 )
		{			
			Phase1 = phaseA_4;
			Phase2 = phaseB_4;
		}
		else
		{	
			Phase1 = phaseB_4;//注意相位次序
			Phase2 = phaseA_4;//
		}
		PhaseM = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, Phase1, Phase2, dRatio1_4);		
		DeductBasePhase_Kernel(PhaseBase_4, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_4, KValue_4_2, Space_4);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);
		Mask_4 = CombineCudaPhaseMask_Kernel(MaskA_4, MaskB_4);

		//CompareCuda4OppositeGray_Kernel(NoiseParam, cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);		
		if ( CompareCuda4SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]) == false )		
		{	MergeCuda4SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]);		}
		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;
		pCastParamD2->PtrMask[i] = Mask_2;	pCastParamD2->PtrSpace[i] = Space_2;
		pCastParamD3->PtrMask[i] = Mask_3;	pCastParamD3->PtrSpace[i] = Space_3;
		pCastParamD4->PtrMask[i] = Mask_4;	pCastParamD4->PtrSpace[i] = Space_4;		
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSolveSpace4Frames2Period4Cast_4_4GC_Kernel(TCastParam *pCastParamD1, TCastParam *pCastParamD2, TCastParam *pCastParamD3, TCastParam *pCastParamD4, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//4步+4GC雙相位-4投光
{
	unsigned int i = 0, j = 0;

	//Cast 1
	int   PhaseBase_1 = 0;
	int   k1_1 =0, k2_1 = 0;
	int   dA1_1 = 0, dA2_1 = 0, dA3_1 = 0, dA4_1 = 0;
	int   dB1_1 = 0, dB2_1 = 0, dB3_1 = 0, dB4_1 = 0;

	float Space_1 = 0;
	float KValue_1 = 0.0f;
	float KValue_1_2 = 0.0f;
	int   phaseA_1 = 0, phaseB_1 = 0;
	float dRatio1_1 = 0;//, dRatio2_1=0;
	unsigned char Mask_1 = 0, MaskA_1 = 0, MaskB_1 = 0;
	const float P1_1 = (float)(pCastParamD1->PerA);
	const float P2_1 = (float)(pCastParamD1->PerB);
	const float Gamma_1 = (float)(pCastParamD1->Gamma);

	//Cast 2 
	int   PhaseBase_2 = 0;
	int   k1_2 = 0, k2_2 = 0;
	int   dA1_2 = 0, dA2_2 = 0, dA3_2 = 0, dA4_2 = 0;
	int   dB1_2 = 0, dB2_2 = 0, dB3_2 = 0, dB4_2 = 0;

	float Space_2 = 0;
	float KValue_2 = 0.0f;
	float KValue_2_2 = 0.0f;
	int   phaseA_2 = 0, phaseB_2 = 0;
	float dRatio1_2 = 0;//, dRatio2_2=0;
	unsigned char Mask_2, MaskA_2 = 0, MaskB_2 = 0;
	const float P1_2 = (float)(pCastParamD2->PerA);
	const float P2_2 = (float)(pCastParamD2->PerB);
	const float Gamma_2 = (float)(pCastParamD1->Gamma);

	//Cast 3
	int   PhaseBase_3 = 0;
	int   k1_3 = 0, k2_3 = 0;
	int   dA1_3 = 0, dA2_3 = 0, dA3_3 = 0, dA4_3 = 0;
	int   dB1_3 = 0, dB2_3 = 0, dB3_3 = 0, dB4_3 = 0;

	float Space_3 = 0;
	float KValue_3 = 0.0f;
	float KValue_3_2 = 0.0f;
	int   phaseA_3 = 0, phaseB_3 = 0;
	float dRatio1_3 = 0;//, dRatio2_3=0;
	unsigned char Mask_3, MaskA_3 = 0, MaskB_3 = 0;
	const float P1_3 = (float)(pCastParamD3->PerA);
	const float P2_3 = (float)(pCastParamD3->PerB);
	const float Gamma_3 = (float)(pCastParamD3->Gamma);

	//Cast 4
	int   PhaseBase_4 = 0;
	int   k1_4 = 0, k2_4 = 0;
	int   dA1_4 = 0, dA2_4 = 0, dA3_4 = 0, dA4_4 = 0;
	int   dB1_4 = 0, dB2_4 = 0, dB3_4 = 0, dB4_4 = 0;

	float Space_4 = 0;
	float KValue_4 = 0.0f;
	float KValue_4_2 = 0.0f;	
	int   phaseA_4 = 0, phaseB_4 = 0;
	float dRatio1_4 = 0;//, dRatio2_4=0;
	unsigned char Mask_4, MaskA_4 = 0, MaskB_4 = 0;
	const float P1_4 = (float)(pCastParamD4->PerA);
	const float P2_4 = (float)(pCastParamD4->PerB);
	const float Gamma_4 = (float)(pCastParamD4->Gamma);

	int Phase1 = 0;
	int Phase2 = 0;
	int PhaseM = 0;
	int Raw_1[4], Raw_2[4], Raw_3[4], Raw_4[4];
	float Threshold_1=0.0f, Threshold_2=0.0f, Threshold_3=0.0f, Threshold_4=0.0f;
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;	
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用

	const int MaxN = 8;//最多8個16週期			
	const int CodeMapSize = 16;	
	const int Period = PHASE_PERIOD;		
	__shared__ unsigned char CodeMap1[CodeMapSize];
	__shared__ unsigned char CodeMap2[CodeMapSize];
	for (i = 0; i<CodeMapSize; i++)
	{	CodeMap1[i] = CodeMap2[i] = 0;	}
	BuildCudaGrayCodeMapTable_Kernel(3, CodeMap1, CodeMapSize);
	BuildCudaGrayCodeMapTable_Kernel(4, CodeMap2, CodeMapSize);

	const float ExpTimeRatio_1 = (float)(pCastParamD1->ExpTimeB*1.0f/pCastParamD1->ExpTimeA);
	const float ExpTimeRatio_2 = (float)(pCastParamD2->ExpTimeB*1.0f/pCastParamD2->ExpTimeA);
	const float ExpTimeRatio_3 = (float)(pCastParamD3->ExpTimeB*1.0f/pCastParamD3->ExpTimeA);
	const float ExpTimeRatio_4 = (float)(pCastParamD4->ExpTimeB*1.0f/pCastParamD4->ExpTimeA);

	const int ImageStep = pCastParamD1->ImageStep;
	const int FactorCnt = sizeof(pCastParamD1->HeightFactor0) / (sizeof(pCastParamD1->HeightFactor0[0]));
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_2[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_3[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_4[CUDA_HEIGHT_FACTOR_SIZE];
	for (i = 0; i<CUDA_HEIGHT_FACTOR_SIZE; i++)
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;
		HeightFactor0_2[i] = HeightFactor1_2[i] = HeightFactor2_2[i] = 0;
		HeightFactor0_3[i] = HeightFactor1_3[i] = HeightFactor2_3[i] = 0;
		HeightFactor0_4[i] = HeightFactor1_4[i] = HeightFactor2_4[i] = 0;
	}
	for (i = 0; i<FactorCnt; i++)
	{
		if (i >= CUDA_HEIGHT_FACTOR_SIZE) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];
		HeightFactor0_2[i] = pCastParamD2->HeightFactor0[i];	HeightFactor1_2[i] = pCastParamD2->HeightFactor1[i];	HeightFactor2_2[i] = pCastParamD2->HeightFactor2[i];
		HeightFactor0_3[i] = pCastParamD3->HeightFactor0[i];	HeightFactor1_3[i] = pCastParamD3->HeightFactor1[i];	HeightFactor2_3[i] = pCastParamD3->HeightFactor2[i];
		HeightFactor0_4[i] = pCastParamD4->HeightFactor0[i];	HeightFactor1_4[i] = pCastParamD4->HeightFactor1[i];	HeightFactor2_4[i] = pCastParamD4->HeightFactor2[i];
	}
	__syncthreads();//同1個Block多個Thread同步化	

	//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
	//  gridDim		網格大小   (網格包含的區塊數目)	
	for (i = (blockIdx.x*blockDim.x) + threadIdx.x; i < ImageSize; i += blockDim.x*gridDim.x)
	{
		if (i >= ImageSize) { continue; }
		const int x = i%ImageStep;
		const int y = i / ImageStep;

		dA1_1 = pCastParamD1->PtrA1[i];
		dA2_1 = pCastParamD1->PtrA2[i];
		dA3_1 = pCastParamD1->PtrA3[i];
		dA4_1 = pCastParamD1->PtrA4[i];
		dB1_1 = pCastParamD1->PtrB1[i];
		dB2_1 = pCastParamD1->PtrB2[i];
		dB3_1 = pCastParamD1->PtrB3[i];
		dB4_1 = pCastParamD1->PtrB4[i];		
		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if (NULL != pCastParamD1->HeightFactorPtr) { KValue_1 = pCastParamD1->HeightFactorPtr[i]; }

		dA1_2 = pCastParamD2->PtrA1[i];
		dA2_2 = pCastParamD2->PtrA2[i];
		dA3_2 = pCastParamD2->PtrA3[i];
		dA4_2 = pCastParamD2->PtrA4[i];
		dB1_2 = pCastParamD2->PtrB1[i];
		dB2_2 = pCastParamD2->PtrB2[i];
		dB3_2 = pCastParamD2->PtrB3[i];
		dB4_2 = pCastParamD2->PtrB4[i];
		PhaseBase_2 = pCastParamD2->ZeroPhasePtr[i];
		if (NULL != pCastParamD2->HeightFactorPtr) { KValue_2 = pCastParamD2->HeightFactorPtr[i]; }

		dA1_3 = pCastParamD3->PtrA1[i];
		dA2_3 = pCastParamD3->PtrA2[i];
		dA3_3 = pCastParamD3->PtrA3[i];
		dA4_3 = pCastParamD3->PtrA4[i];
		dB1_3 = pCastParamD3->PtrB1[i];
		dB2_3 = pCastParamD3->PtrB2[i];
		dB3_3 = pCastParamD3->PtrB3[i];
		dB4_3 = pCastParamD3->PtrB4[i];
		PhaseBase_3 = pCastParamD3->ZeroPhasePtr[i];
		if (NULL != pCastParamD3->HeightFactorPtr) { KValue_3 = pCastParamD3->HeightFactorPtr[i]; }

		dA1_4 = pCastParamD4->PtrA1[i];
		dA2_4 = pCastParamD4->PtrA2[i];
		dA3_4 = pCastParamD4->PtrA3[i];
		dA4_4 = pCastParamD4->PtrA4[i];
		dB1_4 = pCastParamD4->PtrB1[i];
		dB2_4 = pCastParamD4->PtrB2[i];
		dB3_4 = pCastParamD4->PtrB3[i];
		dB4_4 = pCastParamD4->PtrB4[i];
		PhaseBase_4 = pCastParamD4->ZeroPhasePtr[i];
		if (NULL != pCastParamD4->HeightFactorPtr) { KValue_4 = pCastParamD4->HeightFactorPtr[i]; }

		if (true == bUseGamma)
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dA3_1 = CalcCudaGamma_Kernel(dA3_1, Gamma_1);
			dA4_1 = CalcCudaGamma_Kernel(dA4_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);
			dB4_1 = CalcCudaGamma_Kernel(dB4_1, Gamma_1);			

			dA1_2 = CalcCudaGamma_Kernel(dA1_2, Gamma_2);
			dA2_2 = CalcCudaGamma_Kernel(dA2_2, Gamma_2);
			dA3_2 = CalcCudaGamma_Kernel(dA3_2, Gamma_2);
			dA4_2 = CalcCudaGamma_Kernel(dA4_2, Gamma_2);
			dB1_2 = CalcCudaGamma_Kernel(dB1_2, Gamma_2);
			dB2_2 = CalcCudaGamma_Kernel(dB2_2, Gamma_2);
			dB3_2 = CalcCudaGamma_Kernel(dB3_2, Gamma_2);
			dB4_2 = CalcCudaGamma_Kernel(dB4_2, Gamma_2);			

			dA1_3 = CalcCudaGamma_Kernel(dA1_3, Gamma_3);
			dA2_3 = CalcCudaGamma_Kernel(dA2_3, Gamma_3);
			dA3_3 = CalcCudaGamma_Kernel(dA3_3, Gamma_3);
			dA4_3 = CalcCudaGamma_Kernel(dA4_3, Gamma_3);
			dB1_3 = CalcCudaGamma_Kernel(dB1_3, Gamma_3);
			dB2_3 = CalcCudaGamma_Kernel(dB2_3, Gamma_3);
			dB3_3 = CalcCudaGamma_Kernel(dB3_3, Gamma_3);
			dB4_3 = CalcCudaGamma_Kernel(dB4_3, Gamma_3);			

			dA1_4 = CalcCudaGamma_Kernel(dA1_4, Gamma_4);
			dA2_4 = CalcCudaGamma_Kernel(dA2_4, Gamma_4);
			dA3_4 = CalcCudaGamma_Kernel(dA3_4, Gamma_4);
			dA4_4 = CalcCudaGamma_Kernel(dA4_4, Gamma_4);
			dB1_4 = CalcCudaGamma_Kernel(dB1_4, Gamma_4);
			dB2_4 = CalcCudaGamma_Kernel(dB2_4, Gamma_4);
			dB3_4 = CalcCudaGamma_Kernel(dB3_4, Gamma_4);
			dB4_4 = CalcCudaGamma_Kernel(dB4_4, Gamma_4);			
		}
		
		Threshold_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;
		Threshold_1=(float)(Threshold_1*ExpTimeRatio_1);
		Threshold_2=(dA1_2+dA2_2+dA3_2+dA4_2)/4.0f;
		Threshold_2=(float)(Threshold_2*ExpTimeRatio_2);
		Threshold_3=(dA1_3+dA2_3+dA3_3+dA4_3)/4.0f;
		Threshold_3=(float)(Threshold_3*ExpTimeRatio_3);
		Threshold_4=(dA1_4+dA2_4+dA3_4+dA4_4)/4.0f;
		Threshold_4=(float)(Threshold_4*ExpTimeRatio_4);

		CalcCuda4GrayCodeParam_kernel(dB1_1, dB2_1, dB3_1, dB4_1, Threshold_1, CodeMap1, CodeMap2, k1_1, k2_1);
		CalcCuda4GrayCodeParam_kernel(dB1_2, dB2_2, dB3_2, dB4_2, Threshold_2, CodeMap1, CodeMap2, k1_2, k2_2);
		CalcCuda4GrayCodeParam_kernel(dB1_3, dB2_3, dB3_3, dB4_3, Threshold_3, CodeMap1, CodeMap2, k1_3, k2_3);
		CalcCuda4GrayCodeParam_kernel(dB1_4, dB2_4, dB3_4, dB4_4, Threshold_4, CodeMap1, CodeMap2, k1_4, k2_4);
		
		CalcCuda4PhaseParamMask_kernel(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_2, MaskA_2, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_3, MaskA_3, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_4, dA2_4, dA3_4, dA4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_4, MaskA_4, PhaseNoiseDefMode);		

		//Cast 1
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_1, Period, MaxN, k1_1, k2_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		Mask_1 = MaskA_1;

		//Cast 2		
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_2, Period, MaxN, k1_2, k2_2);
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_2, KValue_2_2, Space_2);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		Mask_2 = MaskA_2;

		//Cast 3
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_3, Period, MaxN, k1_3, k2_3);
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_3, KValue_3_2, Space_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		Mask_3 = MaskA_3;

		//Cast 4
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_4, Period, MaxN, k1_4, k2_4);
		DeductBasePhase_Kernel(PhaseBase_4, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_4, KValue_4_2, Space_4);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);
		Mask_4 = MaskA_4;

		if ( MULTI_CAST_MERGE_MODE_JOE_1 == CastMergeMode )
		{
			Raw_1[0]=dA1_1;	Raw_1[1]=dA2_1;	Raw_1[2]=dA3_1;	Raw_1[3]=dA4_1;
			Raw_2[0]=dA1_2;	Raw_2[1]=dA2_2;	Raw_2[2]=dA3_2;	Raw_2[3]=dA4_2;
			Raw_3[0]=dA1_3;	Raw_3[1]=dA2_3;	Raw_3[2]=dA3_3;	Raw_3[3]=dA4_3;
			Raw_4[0]=dA1_4;	Raw_4[1]=dA2_4;	Raw_4[2]=dA3_4;	Raw_4[3]=dA4_4;
			MergeCuda4SpaceData_Joe_Kernel(NoiseParam, Raw_1, Mask_1, Space_1, Raw_2, Mask_2, Space_2, Raw_3, Mask_3, Space_3, Raw_4, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]);
		}
		else
		{
			//CompareCuda4OppositeGray_Kernel(NoiseParam, cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);		
			if (CompareCuda4SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]) == false)
			{	MergeCuda4SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]);	}
		}
		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;
		pCastParamD2->PtrMask[i] = Mask_2;	pCastParamD2->PtrSpace[i] = Space_2;
		pCastParamD3->PtrMask[i] = Mask_3;	pCastParamD3->PtrSpace[i] = Space_3;
		pCastParamD4->PtrMask[i] = Mask_4;	pCastParamD4->PtrSpace[i] = Space_4;
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSolveSpace4Frames2Period4Cast_4_5GC_Kernel(TCastParam *pCastParamD1, TCastParam *pCastParamD2, TCastParam *pCastParamD3, TCastParam *pCastParamD4, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//4步+GC雙相位-4投光
{
	unsigned int i = 0, j = 0;

	//Cast 1
	int   PhaseBase_1 = 0;
	int   k1_1 =0, k2_1 = 0;
	int   dA1_1 = 0, dA2_1 = 0, dA3_1 = 0, dA4_1 = 0;
	int   dB1_1 = 0, dB2_1 = 0, dB3_1 = 0, dB4_1 = 0, dB5_1 = 0;

	float Space_1 = 0;
	float KValue_1 = 0.0f;
	float KValue_1_2 = 0.0f;
	int   phaseA_1 = 0, phaseB_1 = 0;
	float dRatio1_1 = 0;//, dRatio2_1=0;
	unsigned char Mask_1 = 0, MaskA_1 = 0, MaskB_1 = 0;
	const float P1_1 = (float)(pCastParamD1->PerA);
	const float P2_1 = (float)(pCastParamD1->PerB);
	const float Gamma_1 = (float)(pCastParamD1->Gamma);

	//Cast 2 
	int   PhaseBase_2 = 0;
	int   k1_2 = 0, k2_2 = 0;
	int   dA1_2 = 0, dA2_2 = 0, dA3_2 = 0, dA4_2 = 0;
	int   dB1_2 = 0, dB2_2 = 0, dB3_2 = 0, dB4_2 = 0, dB5_2 = 0;

	float Space_2 = 0;
	float KValue_2 = 0.0f;
	float KValue_2_2 = 0.0f;
	int   phaseA_2 = 0, phaseB_2 = 0;
	float dRatio1_2 = 0;//, dRatio2_2=0;
	unsigned char Mask_2, MaskA_2 = 0, MaskB_2 = 0;
	const float P1_2 = (float)(pCastParamD2->PerA);
	const float P2_2 = (float)(pCastParamD2->PerB);
	const float Gamma_2 = (float)(pCastParamD1->Gamma);

	//Cast 3
	int   PhaseBase_3 = 0;
	int   k1_3 = 0, k2_3 = 0;
	int   dA1_3 = 0, dA2_3 = 0, dA3_3 = 0, dA4_3 = 0;
	int   dB1_3 = 0, dB2_3 = 0, dB3_3 = 0, dB4_3 = 0, dB5_3 = 0;

	float Space_3 = 0;
	float KValue_3 = 0.0f;
	float KValue_3_2 = 0.0f;
	int   phaseA_3 = 0, phaseB_3 = 0;
	float dRatio1_3 = 0;//, dRatio2_3=0;
	unsigned char Mask_3, MaskA_3 = 0, MaskB_3 = 0;
	const float P1_3 = (float)(pCastParamD3->PerA);
	const float P2_3 = (float)(pCastParamD3->PerB);
	const float Gamma_3 = (float)(pCastParamD3->Gamma);

	//Cast 4
	int   PhaseBase_4 = 0;
	int   k1_4 = 0, k2_4 = 0;
	int   dA1_4 = 0, dA2_4 = 0, dA3_4 = 0, dA4_4 = 0;
	int   dB1_4 = 0, dB2_4 = 0, dB3_4 = 0, dB4_4 = 0, dB5_4 = 0;

	float Space_4 = 0;
	float KValue_4 = 0.0f;
	float KValue_4_2 = 0.0f;
	int   phaseA_4 = 0, phaseB_4 = 0;
	float dRatio1_4 = 0;//, dRatio2_4=0;
	unsigned char Mask_4, MaskA_4 = 0, MaskB_4 = 0;
	const float P1_4 = (float)(pCastParamD4->PerA);
	const float P2_4 = (float)(pCastParamD4->PerB);
	const float Gamma_4 = (float)(pCastParamD4->Gamma);

	int Phase1 = 0;
	int Phase2 = 0;
	int PhaseM = 0;
	int Raw_1[4], Raw_2[4], Raw_3[4], Raw_4[4];
	float Threshold_1=0.0f, Threshold_2=0.0f, Threshold_3=0.0f, Threshold_4=0.0f;
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;	
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用

	const int MaxN = 16;//最多16個16週期			
	const int CodeMapSize = 32;	
	const int Period = PHASE_PERIOD;		
	__shared__ unsigned char CodeMap1[CodeMapSize];
	__shared__ unsigned char CodeMap2[CodeMapSize];
	for (i = 0; i<CodeMapSize; i++)
	{	CodeMap1[i] = CodeMap2[i] = 0;	}
	BuildCudaGrayCodeMapTable_Kernel(4, CodeMap1, CodeMapSize);
	BuildCudaGrayCodeMapTable_Kernel(5, CodeMap2, CodeMapSize);

	const float ExpTimeRatio_1 = (float)(pCastParamD1->ExpTimeB*1.0f/pCastParamD1->ExpTimeA);
	const float ExpTimeRatio_2 = (float)(pCastParamD2->ExpTimeB*1.0f/pCastParamD2->ExpTimeA);
	const float ExpTimeRatio_3 = (float)(pCastParamD3->ExpTimeB*1.0f/pCastParamD3->ExpTimeA);
	const float ExpTimeRatio_4 = (float)(pCastParamD4->ExpTimeB*1.0f/pCastParamD4->ExpTimeA);

	const int ImageStep = pCastParamD1->ImageStep;
	const int FactorCnt = sizeof(pCastParamD1->HeightFactor0) / (sizeof(pCastParamD1->HeightFactor0[0]));
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_2[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_3[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_4[CUDA_HEIGHT_FACTOR_SIZE];
	for (i = 0; i<CUDA_HEIGHT_FACTOR_SIZE; i++)
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;
		HeightFactor0_2[i] = HeightFactor1_2[i] = HeightFactor2_2[i] = 0;
		HeightFactor0_3[i] = HeightFactor1_3[i] = HeightFactor2_3[i] = 0;
		HeightFactor0_4[i] = HeightFactor1_4[i] = HeightFactor2_4[i] = 0;
	}
	for (i = 0; i<FactorCnt; i++)
	{
		if (i >= CUDA_HEIGHT_FACTOR_SIZE) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];
		HeightFactor0_2[i] = pCastParamD2->HeightFactor0[i];	HeightFactor1_2[i] = pCastParamD2->HeightFactor1[i];	HeightFactor2_2[i] = pCastParamD2->HeightFactor2[i];
		HeightFactor0_3[i] = pCastParamD3->HeightFactor0[i];	HeightFactor1_3[i] = pCastParamD3->HeightFactor1[i];	HeightFactor2_3[i] = pCastParamD3->HeightFactor2[i];
		HeightFactor0_4[i] = pCastParamD4->HeightFactor0[i];	HeightFactor1_4[i] = pCastParamD4->HeightFactor1[i];	HeightFactor2_4[i] = pCastParamD4->HeightFactor2[i];
	}
	__syncthreads();//同1個Block多個Thread同步化	

	//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
	//  gridDim		網格大小   (網格包含的區塊數目)	
	for (i = (blockIdx.x*blockDim.x) + threadIdx.x; i < ImageSize; i += blockDim.x*gridDim.x)
	{
		if (i >= ImageSize) { continue; }
		const int x = i%ImageStep;
		const int y = i / ImageStep;

		dA1_1 = pCastParamD1->PtrA1[i];
		dA2_1 = pCastParamD1->PtrA2[i];
		dA3_1 = pCastParamD1->PtrA3[i];
		dA4_1 = pCastParamD1->PtrA4[i];
		dB1_1 = pCastParamD1->PtrB1[i];
		dB2_1 = pCastParamD1->PtrB2[i];
		dB3_1 = pCastParamD1->PtrB3[i];
		dB4_1 = pCastParamD1->PtrB4[i];
		dB5_1 = pCastParamD1->PtrB5[i];
		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if (NULL != pCastParamD1->HeightFactorPtr) { KValue_1 = pCastParamD1->HeightFactorPtr[i]; }

		dA1_2 = pCastParamD2->PtrA1[i];
		dA2_2 = pCastParamD2->PtrA2[i];
		dA3_2 = pCastParamD2->PtrA3[i];
		dA4_2 = pCastParamD2->PtrA4[i];
		dB1_2 = pCastParamD2->PtrB1[i];
		dB2_2 = pCastParamD2->PtrB2[i];
		dB3_2 = pCastParamD2->PtrB3[i];
		dB4_2 = pCastParamD2->PtrB4[i];
		dB5_2 = pCastParamD2->PtrB5[i];
		PhaseBase_2 = pCastParamD2->ZeroPhasePtr[i];
		if (NULL != pCastParamD2->HeightFactorPtr) { KValue_2 = pCastParamD2->HeightFactorPtr[i]; }

		dA1_3 = pCastParamD3->PtrA1[i];
		dA2_3 = pCastParamD3->PtrA2[i];
		dA3_3 = pCastParamD3->PtrA3[i];
		dA4_3 = pCastParamD3->PtrA4[i];
		dB1_3 = pCastParamD3->PtrB1[i];
		dB2_3 = pCastParamD3->PtrB2[i];
		dB3_3 = pCastParamD3->PtrB3[i];
		dB4_3 = pCastParamD3->PtrB4[i];
		dB5_3 = pCastParamD3->PtrB5[i];
		PhaseBase_3 = pCastParamD3->ZeroPhasePtr[i];
		if (NULL != pCastParamD3->HeightFactorPtr) { KValue_3 = pCastParamD3->HeightFactorPtr[i]; }

		dA1_4 = pCastParamD4->PtrA1[i];
		dA2_4 = pCastParamD4->PtrA2[i];
		dA3_4 = pCastParamD4->PtrA3[i];
		dA4_4 = pCastParamD4->PtrA4[i];
		dB1_4 = pCastParamD4->PtrB1[i];
		dB2_4 = pCastParamD4->PtrB2[i];
		dB3_4 = pCastParamD4->PtrB3[i];
		dB4_4 = pCastParamD4->PtrB4[i];
		dB5_4 = pCastParamD4->PtrB5[i];
		PhaseBase_4 = pCastParamD4->ZeroPhasePtr[i];
		if (NULL != pCastParamD4->HeightFactorPtr) { KValue_4 = pCastParamD4->HeightFactorPtr[i]; }

		if (true == bUseGamma)
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dA3_1 = CalcCudaGamma_Kernel(dA3_1, Gamma_1);
			dA4_1 = CalcCudaGamma_Kernel(dA4_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);
			dB4_1 = CalcCudaGamma_Kernel(dB4_1, Gamma_1);
			dB5_1 = CalcCudaGamma_Kernel(dB5_1, Gamma_1);

			dA1_2 = CalcCudaGamma_Kernel(dA1_2, Gamma_2);
			dA2_2 = CalcCudaGamma_Kernel(dA2_2, Gamma_2);
			dA3_2 = CalcCudaGamma_Kernel(dA3_2, Gamma_2);
			dA4_2 = CalcCudaGamma_Kernel(dA4_2, Gamma_2);
			dB1_2 = CalcCudaGamma_Kernel(dB1_2, Gamma_2);
			dB2_2 = CalcCudaGamma_Kernel(dB2_2, Gamma_2);
			dB3_2 = CalcCudaGamma_Kernel(dB3_2, Gamma_2);
			dB4_2 = CalcCudaGamma_Kernel(dB4_2, Gamma_2);
			dB5_2 = CalcCudaGamma_Kernel(dB5_2, Gamma_2);

			dA1_3 = CalcCudaGamma_Kernel(dA1_3, Gamma_3);
			dA2_3 = CalcCudaGamma_Kernel(dA2_3, Gamma_3);
			dA3_3 = CalcCudaGamma_Kernel(dA3_3, Gamma_3);
			dA4_3 = CalcCudaGamma_Kernel(dA4_3, Gamma_3);
			dB1_3 = CalcCudaGamma_Kernel(dB1_3, Gamma_3);
			dB2_3 = CalcCudaGamma_Kernel(dB2_3, Gamma_3);
			dB3_3 = CalcCudaGamma_Kernel(dB3_3, Gamma_3);
			dB4_3 = CalcCudaGamma_Kernel(dB4_3, Gamma_3);
			dB5_3 = CalcCudaGamma_Kernel(dB5_3, Gamma_3);

			dA1_4 = CalcCudaGamma_Kernel(dA1_4, Gamma_4);
			dA2_4 = CalcCudaGamma_Kernel(dA2_4, Gamma_4);
			dA3_4 = CalcCudaGamma_Kernel(dA3_4, Gamma_4);
			dA4_4 = CalcCudaGamma_Kernel(dA4_4, Gamma_4);
			dB1_4 = CalcCudaGamma_Kernel(dB1_4, Gamma_4);
			dB2_4 = CalcCudaGamma_Kernel(dB2_4, Gamma_4);
			dB3_4 = CalcCudaGamma_Kernel(dB3_4, Gamma_4);
			dB4_4 = CalcCudaGamma_Kernel(dB4_4, Gamma_4);
			dB5_4 = CalcCudaGamma_Kernel(dB5_4, Gamma_4);
		}
		
		Threshold_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;
		Threshold_1=(float)(Threshold_1*ExpTimeRatio_1);
		Threshold_2=(dA1_2+dA2_2+dA3_2+dA4_2)/4.0f;
		Threshold_2=(float)(Threshold_2*ExpTimeRatio_2);
		Threshold_3=(dA1_3+dA2_3+dA3_3+dA4_3)/4.0f;
		Threshold_3=(float)(Threshold_3*ExpTimeRatio_3);
		Threshold_4=(dA1_4+dA2_4+dA3_4+dA4_4)/4.0f;
		Threshold_4=(float)(Threshold_4*ExpTimeRatio_4);

		CalcCuda5GrayCodeParam_kernel(dB1_1, dB2_1, dB3_1, dB4_1, dB5_1, Threshold_1, CodeMap1, CodeMap2, k1_1, k2_1);
		CalcCuda5GrayCodeParam_kernel(dB1_2, dB2_2, dB3_2, dB4_2, dB5_2, Threshold_2, CodeMap1, CodeMap2, k1_2, k2_2);
		CalcCuda5GrayCodeParam_kernel(dB1_3, dB2_3, dB3_3, dB4_3, dB5_3, Threshold_3, CodeMap1, CodeMap2, k1_3, k2_3);
		CalcCuda5GrayCodeParam_kernel(dB1_4, dB2_4, dB3_4, dB4_4, dB5_4, Threshold_4, CodeMap1, CodeMap2, k1_4, k2_4);
		
		CalcCuda4PhaseParamMask_kernel(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_2, MaskA_2, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_3, MaskA_3, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_4, dA2_4, dA3_4, dA4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_4, MaskA_4, PhaseNoiseDefMode);		

		//Cast 1
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_1, Period, MaxN, k1_1, k2_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		Mask_1 = MaskA_1;

		//Cast 2		
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_2, Period, MaxN, k1_2, k2_2);
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_2, KValue_2_2, Space_2);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		Mask_2 = MaskA_2;

		//Cast 3
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_3, Period, MaxN, k1_3, k2_3);
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_3, KValue_3_2, Space_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		Mask_3 = MaskA_3;

		//Cast 4
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_4, Period, MaxN, k1_4, k2_4);
		DeductBasePhase_Kernel(PhaseBase_4, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_4, KValue_4_2, Space_4);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);
		Mask_4 = MaskA_4;

		if ( MULTI_CAST_MERGE_MODE_JOE_1 == CastMergeMode )
		{
			Raw_1[0]=dA1_1;	Raw_1[1]=dA2_1;	Raw_1[2]=dA3_1;	Raw_1[3]=dA4_1;
			Raw_2[0]=dA1_2;	Raw_2[1]=dA2_2;	Raw_2[2]=dA3_2;	Raw_2[3]=dA4_2;
			Raw_3[0]=dA1_3;	Raw_3[1]=dA2_3;	Raw_3[2]=dA3_3;	Raw_3[3]=dA4_3;
			Raw_4[0]=dA1_4;	Raw_4[1]=dA2_4;	Raw_4[2]=dA3_4;	Raw_4[3]=dA4_4;
			MergeCuda4SpaceData_Joe_Kernel(NoiseParam, Raw_1, Mask_1, Space_1, Raw_2, Mask_2, Space_2, Raw_3, Mask_3, Space_3, Raw_4, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]);
		}
		else
		{
			//CompareCuda4OppositeGray_Kernel(NoiseParam, cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);		
			if (CompareCuda4SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]) == false)
			{	MergeCuda4SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]);	}
		}
		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;
		pCastParamD2->PtrMask[i] = Mask_2;	pCastParamD2->PtrSpace[i] = Space_2;
		pCastParamD3->PtrMask[i] = Mask_3;	pCastParamD3->PtrSpace[i] = Space_3;
		pCastParamD4->PtrMask[i] = Mask_4;	pCastParamD4->PtrSpace[i] = Space_4;
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSolveSpace4Frames2Period4Cast_4_6GC_Kernel(TCastParam *pCastParamD1, TCastParam *pCastParamD2, TCastParam *pCastParamD3, TCastParam *pCastParamD4, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//4步+6GC雙相位-4投光
{
	unsigned int i = 0, j = 0;

	//Cast 1
	int   PhaseBase_1 = 0;
	int   k1_1 =0, k2_1 = 0;
	int   dA1_1 = 0, dA2_1 = 0, dA3_1 = 0, dA4_1 = 0;
	int   dB1_1 = 0, dB2_1 = 0, dB3_1 = 0, dB4_1 = 0, dB5_1 = 0, dB6_1 = 0;

	float Space_1 = 0;
	float KValue_1 = 0.0f;
	float KValue_1_2 = 0.0f;
	int   phaseA_1 = 0, phaseB_1 = 0;
	float dRatio1_1 = 0;//, dRatio2_1=0;
	unsigned char Mask_1 = 0, MaskA_1 = 0, MaskB_1 = 0;
	const float P1_1 = (float)(pCastParamD1->PerA);
	const float P2_1 = (float)(pCastParamD1->PerB);
	const float Gamma_1 = (float)(pCastParamD1->Gamma);

	//Cast 2 
	int   PhaseBase_2 = 0;
	int   k1_2 = 0, k2_2 = 0;
	int   dA1_2 = 0, dA2_2 = 0, dA3_2 = 0, dA4_2 = 0;
	int   dB1_2 = 0, dB2_2 = 0, dB3_2 = 0, dB4_2 = 0, dB5_2 = 0, dB6_2 = 0;

	float Space_2 = 0;
	float KValue_2 = 0.0f;
	float KValue_2_2 = 0.0f;
	int   phaseA_2 = 0, phaseB_2 = 0;
	float dRatio1_2 = 0;//, dRatio2_2=0;
	unsigned char Mask_2, MaskA_2 = 0, MaskB_2 = 0;
	const float P1_2 = (float)(pCastParamD2->PerA);
	const float P2_2 = (float)(pCastParamD2->PerB);
	const float Gamma_2 = (float)(pCastParamD1->Gamma);

	//Cast 3
	int   PhaseBase_3 = 0;
	int   k1_3 = 0, k2_3 = 0;
	int   dA1_3 = 0, dA2_3 = 0, dA3_3 = 0, dA4_3 = 0;
	int   dB1_3 = 0, dB2_3 = 0, dB3_3 = 0, dB4_3 = 0, dB5_3 = 0, dB6_3 = 0;

	float Space_3 = 0;
	float KValue_3 = 0.0f;
	float KValue_3_2 = 0.0f;
	int   phaseA_3 = 0, phaseB_3 = 0;
	float dRatio1_3 = 0;//, dRatio2_3=0;
	unsigned char Mask_3, MaskA_3 = 0, MaskB_3 = 0;
	const float P1_3 = (float)(pCastParamD3->PerA);
	const float P2_3 = (float)(pCastParamD3->PerB);
	const float Gamma_3 = (float)(pCastParamD3->Gamma);

	//Cast 4
	int   PhaseBase_4 = 0;
	int   k1_4 = 0, k2_4 = 0;
	int   dA1_4 = 0, dA2_4 = 0, dA3_4 = 0, dA4_4 = 0;
	int   dB1_4 = 0, dB2_4 = 0, dB3_4 = 0, dB4_4 = 0, dB5_4 = 0, dB6_4 = 0;

	float Space_4 = 0;
	float KValue_4 = 0.0f;
	float KValue_4_2 = 0.0f;
	int   phaseA_4 = 0, phaseB_4 = 0;
	float dRatio1_4 = 0;//, dRatio2_4=0;
	unsigned char Mask_4, MaskA_4 = 0, MaskB_4 = 0;
	const float P1_4 = (float)(pCastParamD4->PerA);
	const float P2_4 = (float)(pCastParamD4->PerB);
	const float Gamma_4 = (float)(pCastParamD4->Gamma);

	int Phase1 = 0;
	int Phase2 = 0;
	int PhaseM = 0;
	int Raw_1[4], Raw_2[4], Raw_3[4], Raw_4[4];
	float Threshold_1=0.0f, Threshold_2=0.0f, Threshold_3=0.0f, Threshold_4=0.0f;
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;	
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用

	const int MaxN = 32;//最多32個16週期			
	const int CodeMapSize = 64;	
	const int Period = PHASE_PERIOD;		
	__shared__ unsigned char CodeMap1[CodeMapSize];
	__shared__ unsigned char CodeMap2[CodeMapSize];
	for (i = 0; i<CodeMapSize; i++)
	{	CodeMap1[i] = CodeMap2[i] = 0;	}
	BuildCudaGrayCodeMapTable_Kernel(5, CodeMap1, CodeMapSize);
	BuildCudaGrayCodeMapTable_Kernel(6, CodeMap2, CodeMapSize);

	const float ExpTimeRatio_1 = (float)(pCastParamD1->ExpTimeB*1.0f/pCastParamD1->ExpTimeA);
	const float ExpTimeRatio_2 = (float)(pCastParamD2->ExpTimeB*1.0f/pCastParamD2->ExpTimeA);
	const float ExpTimeRatio_3 = (float)(pCastParamD3->ExpTimeB*1.0f/pCastParamD3->ExpTimeA);
	const float ExpTimeRatio_4 = (float)(pCastParamD4->ExpTimeB*1.0f/pCastParamD4->ExpTimeA);

	const int ImageStep = pCastParamD1->ImageStep;
	const int FactorCnt = sizeof(pCastParamD1->HeightFactor0) / (sizeof(pCastParamD1->HeightFactor0[0]));
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_2[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_3[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_4[CUDA_HEIGHT_FACTOR_SIZE];
	for (i = 0; i<CUDA_HEIGHT_FACTOR_SIZE; i++)
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;
		HeightFactor0_2[i] = HeightFactor1_2[i] = HeightFactor2_2[i] = 0;
		HeightFactor0_3[i] = HeightFactor1_3[i] = HeightFactor2_3[i] = 0;
		HeightFactor0_4[i] = HeightFactor1_4[i] = HeightFactor2_4[i] = 0;
	}
	for (i = 0; i<FactorCnt; i++)
	{
		if (i >= CUDA_HEIGHT_FACTOR_SIZE) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];
		HeightFactor0_2[i] = pCastParamD2->HeightFactor0[i];	HeightFactor1_2[i] = pCastParamD2->HeightFactor1[i];	HeightFactor2_2[i] = pCastParamD2->HeightFactor2[i];
		HeightFactor0_3[i] = pCastParamD3->HeightFactor0[i];	HeightFactor1_3[i] = pCastParamD3->HeightFactor1[i];	HeightFactor2_3[i] = pCastParamD3->HeightFactor2[i];
		HeightFactor0_4[i] = pCastParamD4->HeightFactor0[i];	HeightFactor1_4[i] = pCastParamD4->HeightFactor1[i];	HeightFactor2_4[i] = pCastParamD4->HeightFactor2[i];
	}
	__syncthreads();//同1個Block多個Thread同步化	

	//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
	//  gridDim		網格大小   (網格包含的區塊數目)	
	for (i = (blockIdx.x*blockDim.x) + threadIdx.x; i < ImageSize; i += blockDim.x*gridDim.x)
	{
		if (i >= ImageSize) { continue; }
		const int x = i%ImageStep;
		const int y = i / ImageStep;

		dA1_1 = pCastParamD1->PtrA1[i];
		dA2_1 = pCastParamD1->PtrA2[i];
		dA3_1 = pCastParamD1->PtrA3[i];
		dA4_1 = pCastParamD1->PtrA4[i];
		dB1_1 = pCastParamD1->PtrB1[i];
		dB2_1 = pCastParamD1->PtrB2[i];
		dB3_1 = pCastParamD1->PtrB3[i];
		dB4_1 = pCastParamD1->PtrB4[i];
		dB5_1 = pCastParamD1->PtrB5[i];
		dB6_1 = pCastParamD1->PtrB6[i];
		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if (NULL != pCastParamD1->HeightFactorPtr) { KValue_1 = pCastParamD1->HeightFactorPtr[i]; }

		dA1_2 = pCastParamD2->PtrA1[i];
		dA2_2 = pCastParamD2->PtrA2[i];
		dA3_2 = pCastParamD2->PtrA3[i];
		dA4_2 = pCastParamD2->PtrA4[i];
		dB1_2 = pCastParamD2->PtrB1[i];
		dB2_2 = pCastParamD2->PtrB2[i];
		dB3_2 = pCastParamD2->PtrB3[i];
		dB4_2 = pCastParamD2->PtrB4[i];
		dB5_2 = pCastParamD2->PtrB5[i];
		dB6_2 = pCastParamD2->PtrB6[i];
		PhaseBase_2 = pCastParamD2->ZeroPhasePtr[i];
		if (NULL != pCastParamD2->HeightFactorPtr) { KValue_2 = pCastParamD2->HeightFactorPtr[i]; }

		dA1_3 = pCastParamD3->PtrA1[i];
		dA2_3 = pCastParamD3->PtrA2[i];
		dA3_3 = pCastParamD3->PtrA3[i];
		dA4_3 = pCastParamD3->PtrA4[i];
		dB1_3 = pCastParamD3->PtrB1[i];
		dB2_3 = pCastParamD3->PtrB2[i];
		dB3_3 = pCastParamD3->PtrB3[i];
		dB4_3 = pCastParamD3->PtrB4[i];
		dB5_3 = pCastParamD3->PtrB5[i];
		dB6_3 = pCastParamD3->PtrB6[i];
		PhaseBase_3 = pCastParamD3->ZeroPhasePtr[i];
		if (NULL != pCastParamD3->HeightFactorPtr) { KValue_3 = pCastParamD3->HeightFactorPtr[i]; }

		dA1_4 = pCastParamD4->PtrA1[i];
		dA2_4 = pCastParamD4->PtrA2[i];
		dA3_4 = pCastParamD4->PtrA3[i];
		dA4_4 = pCastParamD4->PtrA4[i];
		dB1_4 = pCastParamD4->PtrB1[i];
		dB2_4 = pCastParamD4->PtrB2[i];
		dB3_4 = pCastParamD4->PtrB3[i];
		dB4_4 = pCastParamD4->PtrB4[i];
		dB5_4 = pCastParamD4->PtrB5[i];
		dB6_4 = pCastParamD4->PtrB6[i];
		PhaseBase_4 = pCastParamD4->ZeroPhasePtr[i];
		if (NULL != pCastParamD4->HeightFactorPtr) { KValue_4 = pCastParamD4->HeightFactorPtr[i]; }

		if (true == bUseGamma)
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dA3_1 = CalcCudaGamma_Kernel(dA3_1, Gamma_1);
			dA4_1 = CalcCudaGamma_Kernel(dA4_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);
			dB4_1 = CalcCudaGamma_Kernel(dB4_1, Gamma_1);
			dB5_1 = CalcCudaGamma_Kernel(dB5_1, Gamma_1);
			dB6_1 = CalcCudaGamma_Kernel(dB6_1, Gamma_1);

			dA1_2 = CalcCudaGamma_Kernel(dA1_2, Gamma_2);
			dA2_2 = CalcCudaGamma_Kernel(dA2_2, Gamma_2);
			dA3_2 = CalcCudaGamma_Kernel(dA3_2, Gamma_2);
			dA4_2 = CalcCudaGamma_Kernel(dA4_2, Gamma_2);
			dB1_2 = CalcCudaGamma_Kernel(dB1_2, Gamma_2);
			dB2_2 = CalcCudaGamma_Kernel(dB2_2, Gamma_2);
			dB3_2 = CalcCudaGamma_Kernel(dB3_2, Gamma_2);
			dB4_2 = CalcCudaGamma_Kernel(dB4_2, Gamma_2);
			dB5_2 = CalcCudaGamma_Kernel(dB5_2, Gamma_2);
			dB6_2 = CalcCudaGamma_Kernel(dB6_2, Gamma_2);

			dA1_3 = CalcCudaGamma_Kernel(dA1_3, Gamma_3);
			dA2_3 = CalcCudaGamma_Kernel(dA2_3, Gamma_3);
			dA3_3 = CalcCudaGamma_Kernel(dA3_3, Gamma_3);
			dA4_3 = CalcCudaGamma_Kernel(dA4_3, Gamma_3);
			dB1_3 = CalcCudaGamma_Kernel(dB1_3, Gamma_3);
			dB2_3 = CalcCudaGamma_Kernel(dB2_3, Gamma_3);
			dB3_3 = CalcCudaGamma_Kernel(dB3_3, Gamma_3);
			dB4_3 = CalcCudaGamma_Kernel(dB4_3, Gamma_3);
			dB5_3 = CalcCudaGamma_Kernel(dB5_3, Gamma_3);
			dB6_3 = CalcCudaGamma_Kernel(dB6_3, Gamma_3);

			dA1_4 = CalcCudaGamma_Kernel(dA1_4, Gamma_4);
			dA2_4 = CalcCudaGamma_Kernel(dA2_4, Gamma_4);
			dA3_4 = CalcCudaGamma_Kernel(dA3_4, Gamma_4);
			dA4_4 = CalcCudaGamma_Kernel(dA4_4, Gamma_4);
			dB1_4 = CalcCudaGamma_Kernel(dB1_4, Gamma_4);
			dB2_4 = CalcCudaGamma_Kernel(dB2_4, Gamma_4);
			dB3_4 = CalcCudaGamma_Kernel(dB3_4, Gamma_4);
			dB4_4 = CalcCudaGamma_Kernel(dB4_4, Gamma_4);
			dB5_4 = CalcCudaGamma_Kernel(dB5_4, Gamma_4);
			dB6_4 = CalcCudaGamma_Kernel(dB6_4, Gamma_4);
		}
		
		Threshold_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;
		Threshold_1=(float)(Threshold_1*ExpTimeRatio_1);
		Threshold_2=(dA1_2+dA2_2+dA3_2+dA4_2)/4.0f;
		Threshold_2=(float)(Threshold_2*ExpTimeRatio_2);
		Threshold_3=(dA1_3+dA2_3+dA3_3+dA4_3)/4.0f;
		Threshold_3=(float)(Threshold_3*ExpTimeRatio_3);
		Threshold_4=(dA1_4+dA2_4+dA3_4+dA4_4)/4.0f;
		Threshold_4=(float)(Threshold_4*ExpTimeRatio_4);

		CalcCuda6GrayCodeParam_kernel(dB1_1, dB2_1, dB3_1, dB4_1, dB5_1, dB6_1, Threshold_1, CodeMap1, CodeMap2, k1_1, k2_1);
		CalcCuda6GrayCodeParam_kernel(dB1_2, dB2_2, dB3_2, dB4_2, dB5_2, dB6_2, Threshold_2, CodeMap1, CodeMap2, k1_2, k2_2);
		CalcCuda6GrayCodeParam_kernel(dB1_3, dB2_3, dB3_3, dB4_3, dB5_3, dB6_3, Threshold_3, CodeMap1, CodeMap2, k1_3, k2_3);
		CalcCuda6GrayCodeParam_kernel(dB1_4, dB2_4, dB3_4, dB4_4, dB5_4, dB6_4, Threshold_4, CodeMap1, CodeMap2, k1_4, k2_4);
		
		CalcCuda4PhaseParamMask_kernel(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_2, MaskA_2, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_3, MaskA_3, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_4, dA2_4, dA3_4, dA4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_4, MaskA_4, PhaseNoiseDefMode);		

		//Cast 1
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_1, Period, MaxN, k1_1, k2_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		Mask_1 = MaskA_1;

		//Cast 2		
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_2, Period, MaxN, k1_2, k2_2);
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_2, KValue_2_2, Space_2);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		Mask_2 = MaskA_2;

		//Cast 3
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_3, Period, MaxN, k1_3, k2_3);
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_3, KValue_3_2, Space_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		Mask_3 = MaskA_3;

		//Cast 4
		PhaseM = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_4, Period, MaxN, k1_4, k2_4);
		DeductBasePhase_Kernel(PhaseBase_4, PhaseM);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_4, KValue_4_2, Space_4);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);
		Mask_4 = MaskA_4;

		if ( MULTI_CAST_MERGE_MODE_JOE_1 == CastMergeMode )
		{
			Raw_1[0]=dA1_1;	Raw_1[1]=dA2_1;	Raw_1[2]=dA3_1;	Raw_1[3]=dA4_1;
			Raw_2[0]=dA1_2;	Raw_2[1]=dA2_2;	Raw_2[2]=dA3_2;	Raw_2[3]=dA4_2;
			Raw_3[0]=dA1_3;	Raw_3[1]=dA2_3;	Raw_3[2]=dA3_3;	Raw_3[3]=dA4_3;
			Raw_4[0]=dA1_4;	Raw_4[1]=dA2_4;	Raw_4[2]=dA3_4;	Raw_4[3]=dA4_4;
			MergeCuda4SpaceData_Joe_Kernel(NoiseParam, Raw_1, Mask_1, Space_1, Raw_2, Mask_2, Space_2, Raw_3, Mask_3, Space_3, Raw_4, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]);
		}
		else
		{
			//CompareCuda4OppositeGray_Kernel(NoiseParam, cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);		
			if (CompareCuda4SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]) == false)
			{	MergeCuda4SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]);	}
		}
		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;
		pCastParamD2->PtrMask[i] = Mask_2;	pCastParamD2->PtrSpace[i] = Space_2;
		pCastParamD3->PtrMask[i] = Mask_3;	pCastParamD3->PtrSpace[i] = Space_3;
		pCastParamD4->PtrMask[i] = Mask_4;	pCastParamD4->PtrSpace[i] = Space_4;
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSolveSpace221Frames2Period1Cast2Exp_2_2_Kernel(TCastParam *pCastParamD, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//2+2步雙相位-單投光2曝光
{
	unsigned int i=0, j=0;	
	int PhaseM = 0;	
	float Mean_AB_1=0.0f;
	float Mean_CD_1=0.0f;
	const float ZeroSpace = 3000;
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;		
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用	
	const int ShortPeriod = PHASE_MAX;

	#pragma region Cast 1 - param
	int   PhaseM_AB_1 = 0;
	int   PhaseM_CD_1 = 0;
	int   PhaseBase_1 = 0;
	int   PhaseZero_1 = 0;	
	int   dA1_1=0, dA2_1=0;
	int   dB1_1=0, dB2_1=0, dB3_1=0;
	int   dC1_1=0, dC2_1=0;
	int   dD1_1=0, dD2_1=0, dD3_1=0;

	float Space_1=0;
	float KValue_1=0.0f;
	float KValue_1_2=0.0f;
	int   phaseA_1=0, phaseB_1=0;
	int   phaseC_1=0, phaseD_1=0;
	float dRatio1_1=0;//, dRatio2_1=0;
	float SpaceAB_1=0, SpaceCD_1=0;
	unsigned char MaskC_1=0, MaskD_1=0;
	unsigned char MaskAB_1=0, MaskCD_1=0;
	unsigned char Mask_1=0, MaskA_1=0, MaskB_1=0;	
	const float P1_1 = (float)(pCastParamD->PerA);
	const float P2_1 = (float)(pCastParamD->PerB);	
	const float Gamma_1=(float)(pCastParamD->Gamma);	
	
	const int ImageStep = pCastParamD->ImageStep;	
	const int FactorCnt=sizeof(pCastParamD->HeightFactor0)/(sizeof(pCastParamD->HeightFactor0[0]));	
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];	
	for ( i=0; i<CUDA_HEIGHT_FACTOR_SIZE; i++ )
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;		
	}
	for ( i=0; i<FactorCnt; i++ )
	{
		if ( i>=CUDA_HEIGHT_FACTOR_SIZE ) { break; }
		HeightFactor0_1[i] = pCastParamD->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD->HeightFactor2[i];		
	}	
	__syncthreads();//同1個Block多個Thread同步化

	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_1, P2_1, dRatio1_1);
#pragma endregion

//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{		
		if ( i >= ImageSize ) { continue; }
		const int x = i%ImageStep;
		const int y = i/ImageStep;		

		#pragma region dA_1
		dA1_1 = pCastParamD->PtrA1[i];
		dA2_1 = pCastParamD->PtrA2[i];
		dB1_1 = pCastParamD->PtrB1[i];
		dB2_1 = pCastParamD->PtrB2[i];
		dB3_1 = pCastParamD->PtrB3[i]; 
		dC1_1 = pCastParamD->PtrC1[i];
		dC2_1 = pCastParamD->PtrC2[i];
		dD1_1 = pCastParamD->PtrD1[i];
		dD2_1 = pCastParamD->PtrD2[i];
		dD3_1 = pCastParamD->PtrD3[i]; 
		PhaseBase_1 = pCastParamD->ZeroPhasePtr[i];
		if ( NULL != pCastParamD->HeightFactorPtr ) { KValue_1    = pCastParamD->HeightFactorPtr[i]; }
		if ( true == bUseGamma )
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);

			dC1_1 = CalcCudaGamma_Kernel(dC1_1, Gamma_1);
			dC2_1 = CalcCudaGamma_Kernel(dC2_1, Gamma_1);
			dD1_1 = CalcCudaGamma_Kernel(dD1_1, Gamma_1);
			dD2_1 = CalcCudaGamma_Kernel(dD2_1, Gamma_1);
			dD3_1 = CalcCudaGamma_Kernel(dD3_1, Gamma_1);
		}
#pragma endregion

		#pragma region Cast_1 - Phase
		//First Exposure
		CalcCuda21PhaseParamMask_kernel(dA1_1, dB3_1, dA2_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1);
		CalcCuda21PhaseParamMask_kernel(dB1_1, dB3_1, dB2_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_1, MaskB_1);
		//Second Exposure
		CalcCuda21PhaseParamMask_kernel(dC1_1, dD3_1, dC2_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseC_1, MaskC_1);
		CalcCuda21PhaseParamMask_kernel(dD1_1, dD3_1, dD2_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseD_1, MaskD_1);
		
		if ( P1_1 < P2_1 )
		{	
			PhaseM_AB_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseA_1, phaseB_1, dRatio1_1);
			PhaseM_CD_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseC_1, phaseD_1, dRatio1_1);
		}
		else
		{	
			PhaseM_AB_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseB_1, phaseA_1, dRatio1_1);//注意相位次序
			PhaseM_CD_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseD_1, phaseC_1, dRatio1_1);//注意相位次序			 
		}
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM_AB_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM_CD_1);
		MaskAB_1 = CombineCudaPhaseMask_Kernel(MaskA_1, MaskB_1);
		MaskCD_1 = CombineCudaPhaseMask_Kernel(MaskC_1, MaskD_1);
		//MergeCuda2ExpPhaseData_Kernel(MaskAB_1, PhaseM_AB_1, MaskCD_1, PhaseM_CD_1, Mask_1, PhaseM);		
		ConvertSpaceToPhase_Kernel(PhaseConvertHeightMode, ZeroSpace, KValue_1, KValue_1_2, PhaseZero_1);
		ConvertSpaceToPhaseMapFunc_Kernel(PhaseConvertHeightMode, x, y, ZeroSpace, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, PhaseZero_1);
		MergeCuda2ExpPhaseData_Kernel_II(MaskAB_1, PhaseM_AB_1, MaskCD_1, PhaseM_CD_1, Mask_1, PhaseM, PhaseZero_1);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_AB_1, KValue_1, KValue_1_2, SpaceAB_1);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_CD_1, KValue_1, KValue_1_2, SpaceCD_1);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_AB_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, SpaceAB_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_CD_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, SpaceCD_1);
#pragma endregion		

		pCastParamD->PtrMask[i] = Mask_1;	pCastParamD->PtrSpace[i] = Space_1;
		MaskPtrD[i] = Mask_1;
		SpacePtrD[i] = Space_1;
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSolveSpace4Frames2Period1Cast2Exp_4_2_Kernel(TCastParam *pCastParamD1, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//4+2步雙相位-單投光2曝光
{
	unsigned int i=0, j=0;	
	
	//Cast 1
	int   PhaseM_AB_1 = 0;
	int   PhaseM_CD_1 = 0;
	int   PhaseBase_1 = 0;
	int   PhaseZero_1 = 0;	
	int   dA1_1=0, dA2_1=0, dA3_1=0, dA4_1=0;
	int   dB1_1=0, dB2_1=0, dB3_1=0;
	int   dC1_1=0, dC2_1=0, dC3_1=0, dC4_1=0;
	int   dD1_1=0, dD2_1=0, dD3_1=0;

	float Space_1=0;
	float KValue_1=0.0f;
	float KValue_1_2=0.0f;
	int   phaseA_1=0, phaseB_1=0;
	int   phaseC_1=0, phaseD_1=0;
	float dRatio1_1=0;//, dRatio2_1=0;
	float SpaceAB_1=0, SpaceCD_1=0;
	unsigned char MaskC_1=0, MaskD_1=0;
	unsigned char MaskAB_1=0, MaskCD_1=0;
	unsigned char Mask_1=0, MaskA_1=0, MaskB_1=0;	
	const float P1_1 = (float)(pCastParamD1->PerA);
	const float P2_1 = (float)(pCastParamD1->PerB);	
	const float Gamma_1=(float)(pCastParamD1->Gamma);

	int PhaseM = 0;	
	float Mean_AB_1=0.0f;
	float Mean_CD_1=0.0f;
	const float ZeroSpace = 3000;
	const bool bUseGamma = USE_GAMMA_CALIBRATION;		
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;		
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	
	const int IntensityMergeMode = NoiseParam.SpaceMultiIntensityMergeMode;
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用	
	const int ShortPeriod = PHASE_MAX;
	const float ExpTimeRatioAB_1 = (float)(pCastParamD1->ExpTimeB*1.0f/pCastParamD1->ExpTimeA);
	const float ExpTimeRatioCD_1 = (float)(pCastParamD1->ExpTimeD*1.0f/pCastParamD1->ExpTimeC);	
	
	const int ImageStep = pCastParamD1->ImageStep;	
	const int FactorCnt=sizeof(pCastParamD1->HeightFactor0)/(sizeof(pCastParamD1->HeightFactor0[0]));	
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];
	for ( i=0; i<CUDA_HEIGHT_FACTOR_SIZE; i++ )
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;		
	}
	for ( i=0; i<FactorCnt; i++ )
	{
		if ( i>=CUDA_HEIGHT_FACTOR_SIZE ) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];		
	}	
	__syncthreads();//同1個Block多個Thread同步化

	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_1, P2_1, dRatio1_1);
//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{		
		if ( i >= ImageSize ) { continue; }
		const int x = i%ImageStep;
		const int y = i/ImageStep;

		dA1_1 = pCastParamD1->PtrA1[i];
		dA2_1 = pCastParamD1->PtrA2[i];
		dA3_1 = pCastParamD1->PtrA3[i]; 
		dA4_1 = pCastParamD1->PtrA4[i];
		dB1_1 = pCastParamD1->PtrB1[i];
		dB3_1 = pCastParamD1->PtrB2[i];
		dB2_1 = (dA1_1+dA2_1+dA3_1+dA4_1)>>2; 
		dB2_1 = (int)((ExpTimeRatioAB_1*dB2_1)+0.5f);
		
		dC1_1 = pCastParamD1->PtrC1[i];
		dC2_1 = pCastParamD1->PtrC2[i];
		dC3_1 = pCastParamD1->PtrC3[i]; 
		dC4_1 = pCastParamD1->PtrC4[i];
		dD1_1 = pCastParamD1->PtrD1[i];
		dD3_1 = pCastParamD1->PtrD2[i];
		dD2_1 = (dC1_1+dC2_1+dC3_1+dC4_1)>>2; 
		dD2_1 = (int)((ExpTimeRatioCD_1*dD2_1)+0.5f);

		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if ( NULL != pCastParamD1->HeightFactorPtr ) { KValue_1    = pCastParamD1->HeightFactorPtr[i]; }
		if ( true == bUseGamma )
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dA3_1 = CalcCudaGamma_Kernel(dA3_1, Gamma_1);
			dA4_1 = CalcCudaGamma_Kernel(dA4_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);			
			//---
			dC1_1 = CalcCudaGamma_Kernel(dC1_1, Gamma_1);
			dC2_1 = CalcCudaGamma_Kernel(dC2_1, Gamma_1);
			dC3_1 = CalcCudaGamma_Kernel(dC3_1, Gamma_1);
			dC4_1 = CalcCudaGamma_Kernel(dC4_1, Gamma_1);
			dD1_1 = CalcCudaGamma_Kernel(dD1_1, Gamma_1);
			dD2_1 = CalcCudaGamma_Kernel(dD2_1, Gamma_1);
			dD3_1 = CalcCudaGamma_Kernel(dD3_1, Gamma_1);
		}
		
		CalcCuda4PhaseParamMask_kernel(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dB1_1, dB2_1, dB3_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_1, MaskB_1);		

		//Second Exposure		
		CalcCuda4PhaseParamMask_kernel(dC1_1, dC2_1, dC3_1, dC4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseC_1, MaskC_1, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dD1_1, dD2_1, dD3_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseD_1, MaskD_1);

		//Cast 1		
		if ( P1_1 < P2_1 )
		{	
			PhaseM_AB_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseA_1, phaseB_1, dRatio1_1);
			PhaseM_CD_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseC_1, phaseD_1, dRatio1_1);
		}
		else
		{	
			PhaseM_AB_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseB_1, phaseA_1, dRatio1_1);//注意相位次序
			PhaseM_CD_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseD_1, phaseC_1, dRatio1_1);//注意相位次序			 
		}
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM_AB_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM_CD_1);
		MaskAB_1 = CombineCudaPhaseMask_Kernel(MaskA_1, MaskB_1);
		MaskCD_1 = CombineCudaPhaseMask_Kernel(MaskC_1, MaskD_1);
		//MergeCuda2ExpPhaseData_Kernel(MaskAB_1, PhaseM_AB_1, MaskCD_1, PhaseM_CD_1, Mask_1, PhaseM);		
		ConvertSpaceToPhase_Kernel(PhaseConvertHeightMode, ZeroSpace, KValue_1, KValue_1_2, PhaseZero_1);
		ConvertSpaceToPhaseMapFunc_Kernel(PhaseConvertHeightMode, x, y, ZeroSpace, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, PhaseZero_1);
		//MergeCuda2ExpPhaseData_Kernel_II(MaskAB_1, PhaseM_AB_1, MaskCD_1, PhaseM_CD_1, Mask_1, PhaseM, PhaseZero_1);
		if ( MULTI_INTENSITY_MERGE_MODE_MEAN != IntensityMergeMode )
		{
			float A_AB=0.0f, B_AB=0.0f, CV_AB=0.0f, A_CD=0.0f, B_CD=0.0f, CV_CD=0.0f;
			CalcCuda4PhaseMeanContrastRatio_Kernel(dA1_1, dA2_1, dA3_1, dA4_1, A_AB, B_AB, CV_AB);
			CalcCuda4PhaseMeanContrastRatio_Kernel(dC1_1, dC2_1, dC3_1, dC4_1, A_CD, B_CD, CV_CD);
			if ( MULTI_INTENSITY_MERGE_MODE_MAXB == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxB_Kernel(MaskAB_1, PhaseM_AB_1, A_AB, B_AB, MaskCD_1, PhaseM_CD_1, A_CD, B_CD, Mask_1, PhaseM); }
			else if ( MULTI_INTENSITY_MERGE_MODE_MAXCV == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxCV_Kernel(MaskAB_1, PhaseM_AB_1, A_AB, B_AB, MaskCD_1, PhaseM_CD_1, A_CD, B_CD, Mask_1, PhaseM); }			
		}
		else
		{
			Mean_AB_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;
			Mean_CD_1=(dC1_1+dC2_1+dC3_1+dC4_1)/4.0f;
			MergeCuda2ExpPhaseDataByMean_Kernel(MaskAB_1, PhaseM_AB_1, Mean_AB_1, MaskCD_1, PhaseM_CD_1, Mean_CD_1, Mask_1, PhaseM);
		}
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_AB_1, KValue_1, KValue_1_2, SpaceAB_1);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_CD_1, KValue_1, KValue_1_2, SpaceCD_1);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_AB_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, SpaceAB_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_CD_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, SpaceCD_1);

		MaskPtrD[i] = Mask_1;
		SpacePtrD[i] = Space_1;
		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;		
	}
}
