	//Cast 3
	int   PhaseM_AB_3 = 0;
	int   PhaseM_CD_3 = 0;
	int   PhaseBase_3 = 0;
	int   PhaseZero_3 = 0;	
	int   dA1_3=0, dA2_3=0, dA3_3=0, dA4_3=0;
	int   dB1_3=0, dB2_3=0, dB3_3=0;
	int   dC1_3=0, dC2_3=0, dC3_3=0, dC4_3=0;
	int   dD1_3=0, dD2_3=0, dD3_3=0;

	float Space_3=0;
	float KValue_3=0.0f;
	float KValue_3_2=0.0f;
	int   phaseA_3=0, phaseB_3=0;		
	int   phaseC_3=0, phaseD_3=0;		
	float dRatio1_3=0;	
	float SpaceAB_3=0, SpaceCD_3=0;
	unsigned char MaskC_3=0, MaskD_3=0;
	unsigned char MaskAB_3=0, MaskCD_3=0;
	unsigned char Mask_3, MaskA_3=0, MaskB_3=0;
	const float P1_3 = (float)(pCastParamD3->PerA);
	const float P2_3 = (float)(pCastParamD3->PerB);	
	const float Gamma_3=(float)(pCastParamD3->Gamma);
	
	//Cast 4
	int   PhaseM_AB_4 = 0;
	int   PhaseM_CD_4 = 0;
	int   PhaseBase_4 = 0;
	int   PhaseZero_4 = 0;	
	int   dA1_4=0, dA2_4=0, dA3_4=0, dA4_4=0;
	int   dB1_4=0, dB2_4=0, dB3_4=0;
	int   dC1_4=0, dC2_4=0, dC3_4=0, dC4_4=0;
	int   dD1_4=0, dD2_4=0, dD3_4=0;

	float Space_4=0;
	float KValue_4=0.0f;
	float KValue_4_2=0.0f;
	int   phaseA_4=0, phaseB_4=0;		
	int   phaseC_4=0, phaseD_4=0;		
	float dRatio1_4=0;
	float SpaceAB_4=0, SpaceCD_4=0;
	unsigned char MaskC_4=0, MaskD_4=0;
	unsigned char MaskAB_4=0, MaskCD_4=0;
	unsigned char Mask_4, MaskA_4=0, MaskB_4=0;
	const float P1_4 = (float)(pCastParamD4->PerA);
	const float P2_4 = (float)(pCastParamD4->PerB);	
	const float Gamma_4=(float)(pCastParamD4->Gamma);
	
	int PhaseM = 0;	
	float Mean_AB_1=0.0f, Mean_AB_2=0.0f, Mean_AB_3=0.0f, Mean_AB_4=0.0f;
	float Mean_CD_1=0.0f, Mean_CD_2=0.0f, Mean_CD_3=0.0f, Mean_CD_4=0.0f;
	const float ZeroSpace = 3000;
	const bool bUseGamma = USE_GAMMA_CALIBRATION;			
	const int   CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;		
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int LowContrastB = NoiseParam.PhaseLowContrastB;
	const int LowPotentialB = NoiseParam.PhaseLowPotentialB;
	const int SaturationB = NoiseParam.PhaseOverSaturatedB;	
	const int IntensityMergeMode = NoiseParam.SpaceMultiIntensityMergeMode;
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用	
	const int ShortPeriod = PHASE_MAX;
	const float ExpTimeRatioAB_1 = (float)(pCastParamD1->ExpTimeB*1.0f/pCastParamD1->ExpTimeA);
	const float ExpTimeRatioCD_1 = (float)(pCastParamD1->ExpTimeD*1.0f/pCastParamD1->ExpTimeC);
	const float ExpTimeRatioAB_2 = (float)(pCastParamD2->ExpTimeB*1.0f/pCastParamD2->ExpTimeA);
	const float ExpTimeRatioCD_2 = (float)(pCastParamD2->ExpTimeD*1.0f/pCastParamD2->ExpTimeC);
	const float ExpTimeRatioAB_3 = (float)(pCastParamD3->ExpTimeB*1.0f/pCastParamD3->ExpTimeA);
	const float ExpTimeRatioCD_3 = (float)(pCastParamD3->ExpTimeD*1.0f/pCastParamD3->ExpTimeC);
	const float ExpTimeRatioAB_4 = (float)(pCastParamD4->ExpTimeB*1.0f/pCastParamD4->ExpTimeA);
	const float ExpTimeRatioCD_4 = (float)(pCastParamD4->ExpTimeD*1.0f/pCastParamD4->ExpTimeC);	
	
	const int ImageStep = pCastParamD1->ImageStep;	
	const int FactorCnt=sizeof(pCastParamD1->HeightFactor0)/(sizeof(pCastParamD1->HeightFactor0[0]));	
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_2[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_3[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_4[CUDA_HEIGHT_FACTOR_SIZE];		
	for ( i=0; i<CUDA_HEIGHT_FACTOR_SIZE; i++ )
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;
		HeightFactor0_2[i] = HeightFactor1_2[i] = HeightFactor2_2[i] = 0;
		HeightFactor0_3[i] = HeightFactor1_3[i] = HeightFactor2_3[i] = 0;
		HeightFactor0_4[i] = HeightFactor1_4[i] = HeightFactor2_4[i] = 0;
	}
	for ( i=0; i<FactorCnt; i++ )
	{
		if ( i>=CUDA_HEIGHT_FACTOR_SIZE ) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];
		HeightFactor0_2[i] = pCastParamD2->HeightFactor0[i];	HeightFactor1_2[i] = pCastParamD2->HeightFactor1[i];	HeightFactor2_2[i] = pCastParamD2->HeightFactor2[i];
		HeightFactor0_3[i] = pCastParamD3->HeightFactor0[i];	HeightFactor1_3[i] = pCastParamD3->HeightFactor1[i];	HeightFactor2_3[i] = pCastParamD3->HeightFactor2[i];
		HeightFactor0_4[i] = pCastParamD4->HeightFactor0[i];	HeightFactor1_4[i] = pCastParamD4->HeightFactor1[i];	HeightFactor2_4[i] = pCastParamD4->HeightFactor2[i];
	}	
	__syncthreads();//同1個Block多個Thread同步化

	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_1, P2_1, dRatio1_1);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_2, P2_2, dRatio1_2);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_3, P2_3, dRatio1_3);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_4, P2_4, dRatio1_4);

//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{		
		if ( i >= ImageSize ) { continue; }
		const int x = i%ImageStep;
		const int y = i/ImageStep;

		dA1_1 = pCastParamD1->PtrA1[i];
		dA2_1 = pCastParamD1->PtrA2[i];
		dA3_1 = pCastParamD1->PtrA3[i]; 
		dA4_1 = pCastParamD1->PtrA4[i];
		dB1_1 = pCastParamD1->PtrB1[i];
		dB3_1 = pCastParamD1->PtrB2[i];		
		dB2_1 = (dA1_1+dA2_1+dA3_1+dA4_1)>>2; 
		dB2_1 = (int)((ExpTimeRatioAB_1*dB2_1)+0.5f);
		dC1_1 = pCastParamD1->PtrC1[i];
		dC2_1 = pCastParamD1->PtrC2[i];
		dC3_1 = pCastParamD1->PtrC3[i]; 
		dC4_1 = pCastParamD1->PtrC4[i];
		dD1_1 = pCastParamD1->PtrD1[i];
		dD3_1 = pCastParamD1->PtrD2[i];
		dD2_1 = (dC1_1+dC2_1+dC3_1+dC4_1)>>2; 
		dD2_1 = (int)((ExpTimeRatioCD_1*dD2_1)+0.5f);
		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if ( NULL != pCastParamD1->HeightFactorPtr ) { KValue_1    = pCastParamD1->HeightFactorPtr[i]; }

		dA1_2 = pCastParamD2->PtrA1[i];
		dA2_2 = pCastParamD2->PtrA2[i];
		dA3_2 = pCastParamD2->PtrA3[i]; 
		dA4_2 = pCastParamD2->PtrA4[i];
		dB1_2 = pCastParamD2->PtrB1[i];
		dB3_2 = pCastParamD2->PtrB2[i];
		dB2_2 = (dA1_2+dA2_2+dA3_2+dA4_2)>>2; 
		dB2_2 = (int)((ExpTimeRatioAB_2*dB2_2)+0.5f);
		dC1_2 = pCastParamD2->PtrC1[i];
		dC2_2 = pCastParamD2->PtrC2[i];
		dC3_2 = pCastParamD2->PtrC3[i]; 
		dC4_2 = pCastParamD2->PtrC4[i];
		dD1_2 = pCastParamD2->PtrD1[i];
		dD3_2 = pCastParamD2->PtrD2[i];
		dD2_2 = (dC1_2+dC2_2+dC3_2+dC4_2)>>2; 
		dD2_2 = (int)((ExpTimeRatioCD_2*dD2_2)+0.5f);
		PhaseBase_2 = pCastParamD2->ZeroPhasePtr[i];
		if ( NULL != pCastParamD2->HeightFactorPtr ) { KValue_2    = pCastParamD2->HeightFactorPtr[i]; }

		dA1_3 = pCastParamD3->PtrA1[i];
		dA2_3 = pCastParamD3->PtrA2[i];
		dA3_3 = pCastParamD3->PtrA3[i]; 
		dA4_3 = pCastParamD3->PtrA4[i];
		dB1_3 = pCastParamD3->PtrB1[i];
		dB3_3 = pCastParamD3->PtrB2[i];
		dB2_3 = (dA1_3+dA2_3+dA3_3+dA4_3)>>2; 
		dB2_3 = (int)((ExpTimeRatioAB_3*dB2_3)+0.5f);
		dC1_3 = pCastParamD3->PtrC1[i];
		dC2_3 = pCastParamD3->PtrC2[i];
		dC3_3 = pCastParamD3->PtrC3[i]; 
		dC4_3 = pCastParamD3->PtrC4[i];
		dD1_3 = pCastParamD3->PtrD1[i];
		dD3_3 = pCastParamD3->PtrD2[i];
		dD2_3 = (dC1_3+dC2_3+dC3_3+dC4_3)>>2; 
		dD2_3 = (int)((ExpTimeRatioCD_3*dD2_3)+0.5f);
		PhaseBase_3 = pCastParamD3->ZeroPhasePtr[i];
		if ( NULL != pCastParamD3->HeightFactorPtr ) { KValue_3    = pCastParamD3->HeightFactorPtr[i]; }
		
		dA1_4 = pCastParamD4->PtrA1[i];
		dA2_4 = pCastParamD4->PtrA2[i];
		dA3_4 = pCastParamD4->PtrA3[i]; 
		dA4_4 = pCastParamD4->PtrA4[i];
		dB1_4 = pCastParamD4->PtrB1[i];
		dB3_4 = pCastParamD4->PtrB2[i];
		dB2_4 = (dA1_4+dA2_4+dA3_4+dA4_4)>>2; 
		dB2_4 = (int)((ExpTimeRatioAB_4*dB2_4)+0.5f);
		dC1_4 = pCastParamD4->PtrC1[i];
		dC2_4 = pCastParamD4->PtrC2[i];
		dC3_4 = pCastParamD4->PtrC3[i]; 
		dC4_4 = pCastParamD4->PtrC4[i];
		dD1_4 = pCastParamD4->PtrD1[i];
		dD3_4 = pCastParamD4->PtrD2[i];
		dD2_4 = (dC1_4+dC2_4+dC3_4+dC4_4)>>2; 
		dD2_4 = (int)((ExpTimeRatioCD_4*dD2_4)+0.5f);
		PhaseBase_4 = pCastParamD4->ZeroPhasePtr[i];
		if ( NULL != pCastParamD4->HeightFactorPtr ) { KValue_4    = pCastParamD4->HeightFactorPtr[i]; }
		if ( true == bUseGamma )
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dA3_1 = CalcCudaGamma_Kernel(dA3_1, Gamma_1);
			dA4_1 = CalcCudaGamma_Kernel(dA4_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);			

			dA1_2 = CalcCudaGamma_Kernel(dA1_2, Gamma_2);
			dA2_2 = CalcCudaGamma_Kernel(dA2_2, Gamma_2);
			dA3_2 = CalcCudaGamma_Kernel(dA3_2, Gamma_2);
			dA4_2 = CalcCudaGamma_Kernel(dA4_2, Gamma_2);
			dB1_2 = CalcCudaGamma_Kernel(dB1_2, Gamma_2);
			dB2_2 = CalcCudaGamma_Kernel(dB2_2, Gamma_2);
			dB3_2 = CalcCudaGamma_Kernel(dB3_2, Gamma_2);

			dA1_3 = CalcCudaGamma_Kernel(dA1_3, Gamma_3);
			dA2_3 = CalcCudaGamma_Kernel(dA2_3, Gamma_3);
			dA3_3 = CalcCudaGamma_Kernel(dA3_3, Gamma_3);
			dA4_3 = CalcCudaGamma_Kernel(dA4_3, Gamma_3);
			dB1_3 = CalcCudaGamma_Kernel(dB1_3, Gamma_3);
			dB2_3 = CalcCudaGamma_Kernel(dB2_3, Gamma_3);
			dB3_3 = CalcCudaGamma_Kernel(dB3_3, Gamma_3);

			dA1_4 = CalcCudaGamma_Kernel(dA1_4, Gamma_4);
			dA2_4 = CalcCudaGamma_Kernel(dA2_4, Gamma_4);
			dA3_4 = CalcCudaGamma_Kernel(dA3_4, Gamma_4);
			dA4_4 = CalcCudaGamma_Kernel(dA4_4, Gamma_4);
			dB1_4 = CalcCudaGamma_Kernel(dB1_4, Gamma_4);
			dB2_4 = CalcCudaGamma_Kernel(dB2_4, Gamma_4);
			dB3_4 = CalcCudaGamma_Kernel(dB3_4, Gamma_4);
			//---
			dC1_1 = CalcCudaGamma_Kernel(dC1_1, Gamma_1);
			dC2_1 = CalcCudaGamma_Kernel(dC2_1, Gamma_1);
			dC3_1 = CalcCudaGamma_Kernel(dC3_1, Gamma_1);
			dC4_1 = CalcCudaGamma_Kernel(dC4_1, Gamma_1);
			dD1_1 = CalcCudaGamma_Kernel(dD1_1, Gamma_1);
			dD2_1 = CalcCudaGamma_Kernel(dD2_1, Gamma_1);
			dD3_1 = CalcCudaGamma_Kernel(dD3_1, Gamma_1);

			dC1_2 = CalcCudaGamma_Kernel(dC1_2, Gamma_2);
			dC2_2 = CalcCudaGamma_Kernel(dC2_2, Gamma_2);
			dC3_2 = CalcCudaGamma_Kernel(dC3_2, Gamma_2);
			dC4_2 = CalcCudaGamma_Kernel(dC4_2, Gamma_2);
			dD1_2 = CalcCudaGamma_Kernel(dD1_2, Gamma_2);
			dD2_2 = CalcCudaGamma_Kernel(dD2_2, Gamma_2);
			dD3_2 = CalcCudaGamma_Kernel(dD3_2, Gamma_2);

			dC1_3 = CalcCudaGamma_Kernel(dC1_3, Gamma_3);
			dC2_3 = CalcCudaGamma_Kernel(dC2_3, Gamma_3);
			dC3_3 = CalcCudaGamma_Kernel(dC3_3, Gamma_3);
			dC4_3 = CalcCudaGamma_Kernel(dC4_3, Gamma_3);
			dD1_3 = CalcCudaGamma_Kernel(dD1_3, Gamma_3);
			dD2_3 = CalcCudaGamma_Kernel(dD2_3, Gamma_3);
			dD3_3 = CalcCudaGamma_Kernel(dD3_3, Gamma_3);

			dC1_4 = CalcCudaGamma_Kernel(dC1_4, Gamma_4);
			dC2_4 = CalcCudaGamma_Kernel(dC2_4, Gamma_4);
			dC3_4 = CalcCudaGamma_Kernel(dC3_4, Gamma_4);
			dC4_4 = CalcCudaGamma_Kernel(dC4_4, Gamma_4);
			dD1_4 = CalcCudaGamma_Kernel(dD1_4, Gamma_4);
			dD2_4 = CalcCudaGamma_Kernel(dD2_4, Gamma_4);
			dD3_4 = CalcCudaGamma_Kernel(dD3_4, Gamma_4);
		}

		CalcCuda4PhaseParamMask_kernel(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dB1_1, dB2_1, dB3_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_1, MaskB_1);
		CalcCuda4PhaseParamMask_kernel(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_2, MaskA_2, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dB1_2, dB2_2, dB3_2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_2, MaskB_2);
		CalcCuda4PhaseParamMask_kernel(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_3, MaskA_3, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dB1_3, dB2_3, dB3_3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_3, MaskB_3);
		CalcCuda4PhaseParamMask_kernel(dA1_4, dA2_4, dA3_4, dA4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_4, MaskA_4, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dB1_4, dB2_4, dB3_4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_4, MaskB_4);

		//Second Exposure
		CalcCuda4PhaseParamMask_kernel(dC1_1, dC2_1, dC3_1, dC4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseC_1, MaskC_1, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dD1_1, dD2_1, dD3_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseD_1, MaskD_1);
		CalcCuda4PhaseParamMask_kernel(dC1_2, dC2_2, dC3_2, dC4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseC_2, MaskC_2, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dD1_2, dD2_2, dD3_2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseD_2, MaskD_2);
		CalcCuda4PhaseParamMask_kernel(dC1_3, dC2_3, dC3_3, dC4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseC_3, MaskC_3, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dD1_3, dD2_3, dD3_3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseD_3, MaskD_3);
		CalcCuda4PhaseParamMask_kernel(dC1_4, dC2_4, dC3_4, dC4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseC_4, MaskC_4, PhaseNoiseDefMode);
		CalcCuda21PhaseParamMask_kernel(dD1_4, dD2_4, dD3_4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseD_4, MaskD_4);
		
		//Cast 1		
		if ( P1_1 < P2_1 )
		{	
			PhaseM_AB_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseA_1, phaseB_1, dRatio1_1);
			PhaseM_CD_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseC_1, phaseD_1, dRatio1_1);
		}
		else
		{	
			PhaseM_AB_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseB_1, phaseA_1, dRatio1_1);//注意相位次序
			PhaseM_CD_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseD_1, phaseC_1, dRatio1_1);//注意相位次序			 
		}
