		//CompareCuda4OppositeGray_Kernel(NoiseParam, cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);

		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;
		pCastParamD2->PtrMask[i] = Mask_2;	pCastParamD2->PtrSpace[i] = Space_2;
		pCastParamD3->PtrMask[i] = Mask_3;	pCastParamD3->PtrSpace[i] = Space_3;
		pCastParamD4->PtrMask[i] = Mask_4;	pCastParamD4->PtrSpace[i] = Space_4;
		if ( CompareCuda4SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]) == false )		
		{	MergeCuda4SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]);		}
	}
