		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;
		HeightFactor0_2[i] = HeightFactor1_2[i] = HeightFactor2_2[i] = 0;
		HeightFactor0_3[i] = HeightFactor1_3[i] = HeightFactor2_3[i] = 0;
		HeightFactor0_4[i] = HeightFactor1_4[i] = HeightFactor2_4[i] = 0;
	}
	for ( i=0; i<FactorCnt; i++ )
	{
		if ( i>=CUDA_HEIGHT_FACTOR_SIZE ) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];
		HeightFactor0_2[i] = pCastParamD2->HeightFactor0[i];	HeightFactor1_2[i] = pCastParamD2->HeightFactor1[i];	HeightFactor2_2[i] = pCastParamD2->HeightFactor2[i];
		HeightFactor0_3[i] = pCastParamD3->HeightFactor0[i];	HeightFactor1_3[i] = pCastParamD3->HeightFactor1[i];	HeightFactor2_3[i] = pCastParamD3->HeightFactor2[i];
		HeightFactor0_4[i] = pCastParamD4->HeightFactor0[i];	HeightFactor1_4[i] = pCastParamD4->HeightFactor1[i];	HeightFactor2_4[i] = pCastParamD4->HeightFactor2[i];
	}	
	__syncthreads();//同1個Block多個Thread同步化

	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_1, P2_1, dRatio1_1);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_2, P2_2, dRatio1_2);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_3, P2_3, dRatio1_3);
	CalcCudaCombinePhasePeriodRatio_Kernel(CombinePeriodMode, P1_4, P2_4, dRatio1_4);

//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{		
		if ( i >= ImageSize ) { continue; }
		const int x = i%ImageStep;
		const int y = i/ImageStep;		

		dA1_1 = pCastParamD1->PtrA1[i];
		dA2_1 = pCastParamD1->PtrA2[i];
		dA3_1 = pCastParamD1->PtrA3[i]; 
		dA4_1 = pCastParamD1->PtrA4[i];
		dB1_1 = pCastParamD1->PtrB1[i];
		dB2_1 = pCastParamD1->PtrB2[i];
		dB3_1 = pCastParamD1->PtrB3[i]; 
		dB4_1 = pCastParamD1->PtrB4[i];
		dC1_1 = pCastParamD1->PtrC1[i];
		dC2_1 = pCastParamD1->PtrC2[i];
		dC3_1 = pCastParamD1->PtrC3[i]; 
		dC4_1 = pCastParamD1->PtrC4[i];
		dD1_1 = pCastParamD1->PtrD1[i];
		dD2_1 = pCastParamD1->PtrD2[i];
		dD3_1 = pCastParamD1->PtrD3[i]; 
		dD4_1 = pCastParamD1->PtrD4[i];
		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if ( NULL != pCastParamD1->HeightFactorPtr ) { KValue_1    = pCastParamD1->HeightFactorPtr[i]; }

		dA1_2 = pCastParamD2->PtrA1[i];
		dA2_2 = pCastParamD2->PtrA2[i];
		dA3_2 = pCastParamD2->PtrA3[i]; 
		dA4_2 = pCastParamD2->PtrA4[i];
		dB1_2 = pCastParamD2->PtrB1[i];
		dB2_2 = pCastParamD2->PtrB2[i];
		dB3_2 = pCastParamD2->PtrB3[i]; 
		dB4_2 = pCastParamD2->PtrB4[i];
		dC1_2 = pCastParamD2->PtrC1[i];
		dC2_2 = pCastParamD2->PtrC2[i];
		dC3_2 = pCastParamD2->PtrC3[i]; 
		dC4_2 = pCastParamD2->PtrC4[i];
		dD1_2 = pCastParamD2->PtrD1[i];
		dD2_2 = pCastParamD2->PtrD2[i];
		dD3_2 = pCastParamD2->PtrD3[i]; 
		dD4_2 = pCastParamD2->PtrD4[i];
		PhaseBase_2 = pCastParamD2->ZeroPhasePtr[i];
		if ( NULL != pCastParamD2->HeightFactorPtr ) { KValue_2    = pCastParamD2->HeightFactorPtr[i]; }

		dA1_3 = pCastParamD3->PtrA1[i];
		dA2_3 = pCastParamD3->PtrA2[i];
		dA3_3 = pCastParamD3->PtrA3[i]; 
		dA4_3 = pCastParamD3->PtrA4[i];
		dB1_3 = pCastParamD3->PtrB1[i];
		dB2_3 = pCastParamD3->PtrB2[i];
		dB3_3 = pCastParamD3->PtrB3[i]; 
		dB4_3 = pCastParamD3->PtrB4[i];
		dC1_3 = pCastParamD3->PtrC1[i];
		dC2_3 = pCastParamD3->PtrC2[i];
		dC3_3 = pCastParamD3->PtrC3[i]; 
		dC4_3 = pCastParamD3->PtrC4[i];
		dD1_3 = pCastParamD3->PtrD1[i];
		dD2_3 = pCastParamD3->PtrD2[i];
		dD3_3 = pCastParamD3->PtrD3[i]; 
		dD4_3 = pCastParamD3->PtrD4[i];
		PhaseBase_3 = pCastParamD3->ZeroPhasePtr[i];
		if ( NULL != pCastParamD3->HeightFactorPtr ) { KValue_3    = pCastParamD3->HeightFactorPtr[i]; }
		
		dA1_4 = pCastParamD4->PtrA1[i];
		dA2_4 = pCastParamD4->PtrA2[i];
		dA3_4 = pCastParamD4->PtrA3[i]; 
		dA4_4 = pCastParamD4->PtrA4[i];
		dB1_4 = pCastParamD4->PtrB1[i];
		dB2_4 = pCastParamD4->PtrB2[i];
		dB3_4 = pCastParamD4->PtrB3[i]; 
		dB4_4 = pCastParamD4->PtrB4[i];
		dC1_4 = pCastParamD4->PtrC1[i];
		dC2_4 = pCastParamD4->PtrC2[i];
		dC3_4 = pCastParamD4->PtrC3[i]; 
		dC4_4 = pCastParamD4->PtrC4[i];
		dD1_4 = pCastParamD4->PtrD1[i];
		dD2_4 = pCastParamD4->PtrD2[i];
		dD3_4 = pCastParamD4->PtrD3[i]; 
		dD4_4 = pCastParamD4->PtrD4[i];
		PhaseBase_4 = pCastParamD4->ZeroPhasePtr[i];
		if ( NULL != pCastParamD4->HeightFactorPtr ) { KValue_4    = pCastParamD4->HeightFactorPtr[i]; }
		
		if ( true == bUseGamma )
		{
			dA1_1 = CalcCudaGamma_Kernel(dA1_1, Gamma_1);
			dA2_1 = CalcCudaGamma_Kernel(dA2_1, Gamma_1);
			dA3_1 = CalcCudaGamma_Kernel(dA3_1, Gamma_1);
			dA4_1 = CalcCudaGamma_Kernel(dA4_1, Gamma_1);
			dB1_1 = CalcCudaGamma_Kernel(dB1_1, Gamma_1);
			dB2_1 = CalcCudaGamma_Kernel(dB2_1, Gamma_1);
			dB3_1 = CalcCudaGamma_Kernel(dB3_1, Gamma_1);
			dB4_1 = CalcCudaGamma_Kernel(dB4_1, Gamma_1);

			dA1_2 = CalcCudaGamma_Kernel(dA1_2, Gamma_2);
			dA2_2 = CalcCudaGamma_Kernel(dA2_2, Gamma_2);
			dA3_2 = CalcCudaGamma_Kernel(dA3_2, Gamma_2);
			dA4_2 = CalcCudaGamma_Kernel(dA4_2, Gamma_2);
			dB1_2 = CalcCudaGamma_Kernel(dB1_2, Gamma_2);
			dB2_2 = CalcCudaGamma_Kernel(dB2_2, Gamma_2);
			dB3_2 = CalcCudaGamma_Kernel(dB3_2, Gamma_2);
			dB4_2 = CalcCudaGamma_Kernel(dB4_2, Gamma_2);

			dA1_3 = CalcCudaGamma_Kernel(dA1_3, Gamma_3);
			dA2_3 = CalcCudaGamma_Kernel(dA2_3, Gamma_3);
			dA3_3 = CalcCudaGamma_Kernel(dA3_3, Gamma_3);
			dA4_3 = CalcCudaGamma_Kernel(dA4_3, Gamma_3);
			dB1_3 = CalcCudaGamma_Kernel(dB1_3, Gamma_3);
			dB2_3 = CalcCudaGamma_Kernel(dB2_3, Gamma_3);
			dB3_3 = CalcCudaGamma_Kernel(dB3_3, Gamma_3);
			dB4_3 = CalcCudaGamma_Kernel(dB4_3, Gamma_3);

			dA1_4 = CalcCudaGamma_Kernel(dA1_4, Gamma_4);
			dA2_4 = CalcCudaGamma_Kernel(dA2_4, Gamma_4);
			dA3_4 = CalcCudaGamma_Kernel(dA3_4, Gamma_4);
			dA4_4 = CalcCudaGamma_Kernel(dA4_4, Gamma_4);
			dB1_4 = CalcCudaGamma_Kernel(dB1_4, Gamma_4);
			dB2_4 = CalcCudaGamma_Kernel(dB2_4, Gamma_4);
			dB3_4 = CalcCudaGamma_Kernel(dB3_4, Gamma_4);
			dB4_4 = CalcCudaGamma_Kernel(dB4_4, Gamma_4);
			//---
			dC1_1 = CalcCudaGamma_Kernel(dC1_1, Gamma_1);
			dC2_1 = CalcCudaGamma_Kernel(dC2_1, Gamma_1);
			dC3_1 = CalcCudaGamma_Kernel(dC3_1, Gamma_1);
			dC4_1 = CalcCudaGamma_Kernel(dC4_1, Gamma_1);
			dD1_1 = CalcCudaGamma_Kernel(dD1_1, Gamma_1);
			dD2_1 = CalcCudaGamma_Kernel(dD2_1, Gamma_1);
			dD3_1 = CalcCudaGamma_Kernel(dD3_1, Gamma_1);
			dD4_1 = CalcCudaGamma_Kernel(dD4_1, Gamma_1);

			dC1_2 = CalcCudaGamma_Kernel(dC1_2, Gamma_2);
			dC2_2 = CalcCudaGamma_Kernel(dC2_2, Gamma_2);
			dC3_2 = CalcCudaGamma_Kernel(dC3_2, Gamma_2);
			dC4_2 = CalcCudaGamma_Kernel(dC4_2, Gamma_2);
			dD1_2 = CalcCudaGamma_Kernel(dD1_2, Gamma_2);
			dD2_2 = CalcCudaGamma_Kernel(dD2_2, Gamma_2);
			dD3_2 = CalcCudaGamma_Kernel(dD3_2, Gamma_2);
			dD4_2 = CalcCudaGamma_Kernel(dD4_2, Gamma_2);

			dC1_3 = CalcCudaGamma_Kernel(dC1_3, Gamma_3);
			dC2_3 = CalcCudaGamma_Kernel(dC2_3, Gamma_3);
			dC3_3 = CalcCudaGamma_Kernel(dC3_3, Gamma_3);
			dC4_3 = CalcCudaGamma_Kernel(dC4_3, Gamma_3);
			dD1_3 = CalcCudaGamma_Kernel(dD1_3, Gamma_3);
			dD2_3 = CalcCudaGamma_Kernel(dD2_3, Gamma_3);
			dD3_3 = CalcCudaGamma_Kernel(dD3_3, Gamma_3);
			dD4_3 = CalcCudaGamma_Kernel(dD4_3, Gamma_3);

			dC1_4 = CalcCudaGamma_Kernel(dC1_4, Gamma_4);
			dC2_4 = CalcCudaGamma_Kernel(dC2_4, Gamma_4);
			dC3_4 = CalcCudaGamma_Kernel(dC3_4, Gamma_4);
			dC4_4 = CalcCudaGamma_Kernel(dC4_4, Gamma_4);
			dD1_4 = CalcCudaGamma_Kernel(dD1_4, Gamma_4);
			dD2_4 = CalcCudaGamma_Kernel(dD2_4, Gamma_4);
			dD3_4 = CalcCudaGamma_Kernel(dD3_4, Gamma_4);
			dD4_4 = CalcCudaGamma_Kernel(dD4_4, Gamma_4);
		}		

		CalcCuda4PhaseParamMask_kernel(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dB1_1, dB2_1, dB3_1, dB4_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_1, MaskB_1, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_2, MaskA_2, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dB1_2, dB2_2, dB3_2, dB4_2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_2, MaskB_2, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_3, MaskA_3, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dB1_3, dB2_3, dB3_3, dB4_3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_3, MaskB_3, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dA1_4, dA2_4, dA3_4, dA4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_4, MaskA_4, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dB1_4, dB2_4, dB3_4, dB4_4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseB_4, MaskB_4, PhaseNoiseDefMode);

		//Second Exposure
		CalcCuda4PhaseParamMask_kernel(dC1_1, dC2_1, dC3_1, dC4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseC_1, MaskC_1, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dD1_1, dD2_1, dD3_1, dD4_1, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseD_1, MaskD_1, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dC1_2, dC2_2, dC3_2, dC4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseC_2, MaskC_2, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dD1_2, dD2_2, dD3_2, dD4_2, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseD_2, MaskD_2, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dC1_3, dC2_3, dC3_3, dC4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseC_3, MaskC_3, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dD1_3, dD2_3, dD3_3, dD4_3, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseD_3, MaskD_3, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dC1_4, dC2_4, dC3_4, dC4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseC_4, MaskC_4, PhaseNoiseDefMode);
		CalcCuda4PhaseParamMask_kernel(dD1_4, dD2_4, dD3_4, dD4_4, PhaseNoiseDef, LowContrastB, LowPotentialB, SaturationB, phaseD_4, MaskD_4, PhaseNoiseDefMode);
		
		//Cast 1		
		if ( P1_1 < P2_1 )
		{	
			PhaseM_AB_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseA_1, phaseB_1, dRatio1_1);
			PhaseM_CD_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseC_1, phaseD_1, dRatio1_1);
		}
		else
		{	
			PhaseM_AB_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseB_1, phaseA_1, dRatio1_1);//注意相位次序
			PhaseM_CD_1 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseD_1, phaseC_1, dRatio1_1);//注意相位次序			 
		}
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM_AB_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM_CD_1);
		MaskAB_1 = CombineCudaPhaseMask_Kernel(MaskA_1, MaskB_1);
		MaskCD_1 = CombineCudaPhaseMask_Kernel(MaskC_1, MaskD_1);
		//MergeCuda2ExpPhaseData_Kernel(MaskAB_1, PhaseM_AB_1, MaskCD_1, PhaseM_CD_1, Mask_1, PhaseM);		
		ConvertSpaceToPhase_Kernel(PhaseConvertHeightMode, ZeroSpace, KValue_1, KValue_1_2, PhaseZero_1);
		ConvertSpaceToPhaseMapFunc_Kernel(PhaseConvertHeightMode, x, y, ZeroSpace, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, PhaseZero_1);
		//MergeCuda2ExpPhaseData_Kernel_II(MaskAB_1, PhaseM_AB_1, MaskCD_1, PhaseM_CD_1, Mask_1, PhaseM, PhaseZero_1);
		if ( MULTI_INTENSITY_MERGE_MODE_MEAN != IntensityMergeMode )
		{
			float A_AB=0.0f, B_AB=0.0f, CV_AB=0.0f, A_CD=0.0f, B_CD=0.0f, CV_CD=0.0f;
			CalcCuda4PhaseMeanContrastRatio_Kernel(dA1_1, dA2_1, dA3_1, dA4_1, A_AB, B_AB, CV_AB);
			CalcCuda4PhaseMeanContrastRatio_Kernel(dC1_1, dC2_1, dC3_1, dC4_1, A_CD, B_CD, CV_CD);
			if ( MULTI_INTENSITY_MERGE_MODE_MAXB == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxB_Kernel(MaskAB_1, PhaseM_AB_1, A_AB, B_AB, MaskCD_1, PhaseM_CD_1, A_CD, B_CD, Mask_1, PhaseM); }
			else if ( MULTI_INTENSITY_MERGE_MODE_MAXCV == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxCV_Kernel(MaskAB_1, PhaseM_AB_1, A_AB, B_AB, MaskCD_1, PhaseM_CD_1, A_CD, B_CD, Mask_1, PhaseM); }			
		}
		else
		{
			Mean_AB_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;
			Mean_CD_1=(dC1_1+dC2_1+dC3_1+dC4_1)/4.0f;
			MergeCuda2ExpPhaseDataByMean_Kernel(MaskAB_1, PhaseM_AB_1, Mean_AB_1, MaskCD_1, PhaseM_CD_1, Mean_CD_1, Mask_1, PhaseM);
		}
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_1, KValue_1_2, Space_1);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_AB_1, KValue_1, KValue_1_2, SpaceAB_1);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_CD_1, KValue_1, KValue_1_2, SpaceCD_1);		
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_AB_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, SpaceAB_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_CD_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, SpaceCD_1);

		//Cast 2		
		if ( P1_2 < P2_2 )
		{	
			PhaseM_AB_2 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseA_2, phaseB_2, dRatio1_2);
			PhaseM_CD_2 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseC_2, phaseD_2, dRatio1_2);
		}
		else
		{	
			PhaseM_AB_2 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseB_2, phaseA_2, dRatio1_2);//注意相位次序
			PhaseM_CD_2 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseD_2, phaseC_2, dRatio1_2);//注意相位次序			
		}
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM_AB_2);
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM_CD_2);		
		MaskAB_2 = CombineCudaPhaseMask_Kernel(MaskA_2, MaskB_2);
		MaskCD_2 = CombineCudaPhaseMask_Kernel(MaskC_2, MaskD_2);
		//MergeCuda2ExpPhaseData_Kernel(MaskAB_2, PhaseM_AB_2, MaskCD_2, PhaseM_CD_2, Mask_2, PhaseM);		
		ConvertSpaceToPhase_Kernel(PhaseConvertHeightMode, ZeroSpace, KValue_2, KValue_2_2, PhaseZero_2);
		ConvertSpaceToPhaseMapFunc_Kernel(PhaseConvertHeightMode, x, y, ZeroSpace, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, PhaseZero_2);
		//MergeCuda2ExpPhaseData_Kernel_II(MaskAB_2, PhaseM_AB_2, MaskCD_2, PhaseM_CD_2, Mask_2, PhaseM, PhaseZero_2);		
		if ( MULTI_INTENSITY_MERGE_MODE_MEAN != IntensityMergeMode )
		{
			float A_AB=0.0f, B_AB=0.0f, CV_AB=0.0f, A_CD=0.0f, B_CD=0.0f, CV_CD=0.0f;
			CalcCuda4PhaseMeanContrastRatio_Kernel(dA1_2, dA2_2, dA3_2, dA4_2, A_AB, B_AB, CV_AB);
			CalcCuda4PhaseMeanContrastRatio_Kernel(dC1_2, dC2_2, dC3_2, dC4_2, A_CD, B_CD, CV_CD);
			if ( MULTI_INTENSITY_MERGE_MODE_MAXB == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxB_Kernel(MaskAB_2, PhaseM_AB_2, A_AB, B_AB, MaskCD_2, PhaseM_CD_2, A_CD, B_CD, Mask_2, PhaseM); }
			else if ( MULTI_INTENSITY_MERGE_MODE_MAXCV == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxCV_Kernel(MaskAB_2, PhaseM_AB_2, A_AB, B_AB, MaskCD_2, PhaseM_CD_2, A_CD, B_CD, Mask_2, PhaseM); }			
		}
		else
		{
			Mean_AB_2=(dA1_2+dA2_2+dA3_2+dA4_2)/4.0f;
			Mean_CD_2=(dC1_2+dC2_2+dC3_2+dC4_2)/4.0f;
			MergeCuda2ExpPhaseDataByMean_Kernel(MaskAB_2, PhaseM_AB_2, Mean_AB_2, MaskCD_2, PhaseM_CD_2, Mean_CD_2, Mask_2, PhaseM);
		}
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_2, KValue_2_2, Space_2);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_AB_2, KValue_2, KValue_2_2, SpaceAB_2);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_CD_2, KValue_2, KValue_2_2, SpaceCD_2);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_AB_2, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, SpaceAB_2);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_CD_2, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, SpaceCD_2);

		//Cast 3
		if ( P1_3 < P2_3 )
		{	
			PhaseM_AB_3 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseA_3, phaseB_3, dRatio1_3);
			PhaseM_CD_3 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseC_3, phaseD_3, dRatio1_3);
		}
		else
		{	
			PhaseM_AB_3 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseB_3, phaseA_3, dRatio1_3);//注意相位次序
			PhaseM_CD_3 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseD_3, phaseC_3, dRatio1_3);//注意相位次序
		}
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM_AB_3);
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM_CD_3);		
		MaskAB_3 = CombineCudaPhaseMask_Kernel(MaskA_3, MaskB_3);
		MaskCD_3 = CombineCudaPhaseMask_Kernel(MaskC_3, MaskD_3);
		//MergeCuda2ExpPhaseData_Kernel(MaskAB_3, PhaseM_AB_3, MaskCD_3, PhaseM_CD_3, Mask_3, PhaseM);		
		ConvertSpaceToPhase_Kernel(PhaseConvertHeightMode, ZeroSpace, KValue_3, KValue_3_2, PhaseZero_3);
		ConvertSpaceToPhaseMapFunc_Kernel(PhaseConvertHeightMode, x, y, ZeroSpace, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, PhaseZero_3);
		//MergeCuda2ExpPhaseData_Kernel_II(MaskAB_3, PhaseM_AB_3, MaskCD_3, PhaseM_CD_3, Mask_3, PhaseM, PhaseZero_3);		
		if ( MULTI_INTENSITY_MERGE_MODE_MEAN != IntensityMergeMode )
		{
			float A_AB=0.0f, B_AB=0.0f, CV_AB=0.0f, A_CD=0.0f, B_CD=0.0f, CV_CD=0.0f;
			CalcCuda4PhaseMeanContrastRatio_Kernel(dA1_3, dA2_3, dA3_3, dA4_3, A_AB, B_AB, CV_AB);
			CalcCuda4PhaseMeanContrastRatio_Kernel(dC1_3, dC2_3, dC3_3, dC4_3, A_CD, B_CD, CV_CD);
			if ( MULTI_INTENSITY_MERGE_MODE_MAXB == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxB_Kernel(MaskAB_3, PhaseM_AB_3, A_AB, B_AB, MaskCD_3, PhaseM_CD_3, A_CD, B_CD, Mask_3, PhaseM); }
			else if ( MULTI_INTENSITY_MERGE_MODE_MAXCV == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxCV_Kernel(MaskAB_3, PhaseM_AB_3, A_AB, B_AB, MaskCD_3, PhaseM_CD_3, A_CD, B_CD, Mask_3, PhaseM); }			
		}
		else
		{
			Mean_AB_3=(dA1_3+dA2_3+dA3_3+dA4_3)/4.0f;
			Mean_CD_3=(dC1_3+dC2_3+dC3_3+dC4_3)/4.0f;
			MergeCuda2ExpPhaseDataByMean_Kernel(MaskAB_3, PhaseM_AB_3, Mean_AB_3, MaskCD_3, PhaseM_CD_3, Mean_CD_3, Mask_3, PhaseM);
		}
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_3, KValue_3_2, Space_3);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_AB_3, KValue_3, KValue_3_2, SpaceAB_3);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_CD_3, KValue_3, KValue_3_2, SpaceCD_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_AB_3, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, SpaceAB_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_CD_3, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, SpaceCD_3);

		//Cast 4
		if ( P1_4 < P2_4 )
		{	
			PhaseM_AB_4 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseA_4, phaseB_4, dRatio1_4);
			PhaseM_CD_4 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseC_4, phaseD_4, dRatio1_4);
		}
		else
		{	
			PhaseM_AB_4 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseB_4, phaseA_4, dRatio1_4);//注意相位次序
			PhaseM_CD_4 = CombineCudaPhasePeriod_Kernel(CombinePeriodMode, phaseD_4, phaseC_4, dRatio1_4);//注意相位次序
		}
		DeductBasePhase_Kernel(PhaseBase_4, PhaseM_AB_4);
		DeductBasePhase_Kernel(PhaseBase_4, PhaseM_CD_4);		
		MaskAB_4 = CombineCudaPhaseMask_Kernel(MaskA_4, MaskB_4);
		MaskCD_4 = CombineCudaPhaseMask_Kernel(MaskC_4, MaskD_4);
		
		//MergeCuda2ExpPhaseData_Kernel(MaskAB_4, PhaseM_AB_4, MaskCD_4, PhaseM_CD_4, Mask_4, PhaseM);		
		ConvertSpaceToPhase_Kernel(PhaseConvertHeightMode, ZeroSpace, KValue_4, KValue_4_2, PhaseZero_4);
		ConvertSpaceToPhaseMapFunc_Kernel(PhaseConvertHeightMode, x, y, ZeroSpace, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, PhaseZero_4);
		//MergeCuda2ExpPhaseData_Kernel_II(MaskAB_4, PhaseM_AB_4, MaskCD_4, PhaseM_CD_4, Mask_4, PhaseM, PhaseZero_4);
		if ( MULTI_INTENSITY_MERGE_MODE_MEAN != IntensityMergeMode )
		{
			float A_AB=0.0f, B_AB=0.0f, CV_AB=0.0f, A_CD=0.0f, B_CD=0.0f, CV_CD=0.0f;
			CalcCuda4PhaseMeanContrastRatio_Kernel(dA1_4, dA2_4, dA3_4, dA4_4, A_AB, B_AB, CV_AB);
			CalcCuda4PhaseMeanContrastRatio_Kernel(dC1_4, dC2_4, dC3_4, dC4_4, A_CD, B_CD, CV_CD);
			if ( MULTI_INTENSITY_MERGE_MODE_MAXB == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxB_Kernel(MaskAB_4, PhaseM_AB_4, A_AB, B_AB, MaskCD_4, PhaseM_CD_4, A_CD, B_CD, Mask_4, PhaseM); }
			else if ( MULTI_INTENSITY_MERGE_MODE_MAXCV == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxCV_Kernel(MaskAB_4, PhaseM_AB_4, A_AB, B_AB, MaskCD_4, PhaseM_CD_4, A_CD, B_CD, Mask_4, PhaseM); }			
		}
		else
		{
			Mean_AB_4=(dA1_4+dA2_4+dA3_4+dA4_4)/4.0f;
			Mean_CD_4=(dC1_4+dC2_4+dC3_4+dC4_4)/4.0f;
			MergeCuda2ExpPhaseDataByMean_Kernel(MaskAB_4, PhaseM_AB_4, Mean_AB_4, MaskCD_4, PhaseM_CD_4, Mean_CD_4, Mask_4, PhaseM);
		}
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM, KValue_4, KValue_4_2, Space_4);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_AB_4, KValue_4, KValue_4_2, SpaceAB_4);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_CD_4, KValue_4, KValue_4_2, SpaceCD_4);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_AB_4, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, SpaceAB_4);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_CD_4, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, SpaceCD_4);
		//CompareCuda4OppositeGray_Kernel(NoiseParam, cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);

		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;
		pCastParamD2->PtrMask[i] = Mask_2;	pCastParamD2->PtrSpace[i] = Space_2;
		pCastParamD3->PtrMask[i] = Mask_3;	pCastParamD3->PtrSpace[i] = Space_3;
		pCastParamD4->PtrMask[i] = Mask_4;	pCastParamD4->PtrSpace[i] = Space_4;
		if ( CompareCuda4SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]) == false )		
		{	MergeCuda4SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]);		}
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSolveSpace4Frames2Period4Cast2Exp_4_4GC_Kernel(TCastParam *pCastParamD1, TCastParam *pCastParamD2, TCastParam *pCastParamD3, TCastParam *pCastParamD4, unsigned int ImageSize, TPhaseNoiseParam NoiseParam, MASK_PTR MaskPtrD, SPACE_PTR SpacePtrD)//4步+4GC雙相位-4投光2曝光
{
	unsigned int i = 0, j = 0;

	//Cast 1
	int   PhaseM_AB_1 = 0;
	int   PhaseM_CD_1 = 0;
	int   PhaseBase_1 = 0;
	int   PhaseZero_1 = 0;	
	int   k1_AB_1 =0, k2_AB_1 = 0;
	int   k1_CD_1 =0, k2_CD_1 = 0;
	int   dA1_1 = 0, dA2_1 = 0, dA3_1 = 0, dA4_1 = 0;
	int   dB1_1 = 0, dB2_1 = 0, dB3_1 = 0, dB4_1 = 0;
	int   dC1_1 = 0, dC2_1 = 0, dC3_1 = 0, dC4_1 = 0;
	int   dD1_1 = 0, dD2_1 = 0, dD3_1 = 0, dD4_1 = 0;

	float Space_1 = 0;
	float Space_AB_1 = 0, Space_CD_1;
	float KValue_1 = 0.0f;
	float KValue_1_2 = 0.0f;
	int   phaseA_1=0, phaseC_1=0, PhaseM_1=0;
	float dRatio1_1 = 0;//, dRatio2_1=0;
	float SpaceAB_1=0, SpaceCD_1=0;
	unsigned char Mask_AB_1=0, Mask_CD_1=0;
	unsigned char Mask_1 = 0, MaskA_1 = 0, MaskC_1 = 0;
	const float P1_1 = (float)(pCastParamD1->PerA);
	const float P2_1 = (float)(pCastParamD1->PerB);
	const float Gamma_1 = (float)(pCastParamD1->Gamma);

	//Cast 2 
	int   PhaseM_AB_2 = 0;
	int   PhaseM_CD_2 = 0;
	int   PhaseBase_2 = 0;
	int   PhaseZero_2 = 0;	
	int   k1_AB_2 =0, k2_AB_2 = 0;
	int   k1_CD_2 =0, k2_CD_2 = 0;
	int   dA1_2 = 0, dA2_2 = 0, dA3_2 = 0, dA4_2 = 0;
	int   dB1_2 = 0, dB2_2 = 0, dB3_2 = 0, dB4_2 = 0;
	int   dC1_2 = 0, dC2_2 = 0, dC3_2 = 0, dC4_2 = 0;
	int   dD1_2 = 0, dD2_2 = 0, dD3_2 = 0, dD4_2 = 0;

	float Space_2 = 0;
	float Space_AB_2 = 0, Space_CD_2;
	float KValue_2 = 0.0f;
	float KValue_2_2 = 0.0f;
	int   phaseA_2=0, phaseC_2=0, PhaseM_2=0;
	float dRatio1_2 = 0;//, dRatio2_2=0;
	unsigned char Mask_AB_2=0, Mask_CD_2=0;
	unsigned char Mask_2, MaskA_2 = 0, MaskC_2 = 0;
	const float P1_2 = (float)(pCastParamD2->PerA);
	const float P2_2 = (float)(pCastParamD2->PerB);
	const float Gamma_2 = (float)(pCastParamD1->Gamma);

	//Cast 3
	int   PhaseM_AB_3 = 0;
	int   PhaseM_CD_3 = 0;
	int   PhaseBase_3 = 0;	
	int   PhaseZero_3 = 0;	
	int   k1_AB_3 =0, k2_AB_3 = 0;
	int   k1_CD_3 =0, k2_CD_3 = 0;
	int   dA1_3 = 0, dA2_3 = 0, dA3_3 = 0, dA4_3 = 0;
	int   dB1_3 = 0, dB2_3 = 0, dB3_3 = 0, dB4_3 = 0;
	int   dC1_3 = 0, dC2_3 = 0, dC3_3 = 0, dC4_3 = 0;
	int   dD1_3 = 0, dD2_3 = 0, dD3_3 = 0, dD4_3 = 0;

	float Space_3 = 0;
	float Space_AB_3 = 0, Space_CD_3;
	float KValue_3 = 0.0f;
	float KValue_3_2 = 0.0f;
	int   phaseA_3=0, phaseC_3=0, PhaseM_3=0;
	float dRatio1_3 = 0;//, dRatio2_3=0;
	unsigned char Mask_AB_3=0, Mask_CD_3=0;
	unsigned char Mask_3, MaskA_3 = 0, MaskC_3 = 0;
	const float P1_3 = (float)(pCastParamD3->PerA);
	const float P2_3 = (float)(pCastParamD3->PerB);
	const float Gamma_3 = (float)(pCastParamD3->Gamma);

	//Cast 4
	int   PhaseM_AB_4 = 0;
	int   PhaseM_CD_4 = 0;
	int   PhaseBase_4 = 0;
	int   PhaseZero_4 = 0;	
	int   k1_AB_4 =0, k2_AB_4 = 0;
	int   k1_CD_4 =0, k2_CD_4 = 0;
	int   dA1_4 = 0, dA2_4 = 0, dA3_4 = 0, dA4_4 = 0;
	int   dB1_4 = 0, dB2_4 = 0, dB3_4 = 0, dB4_4 = 0;
	int   dC1_4 = 0, dC2_4 = 0, dC3_4 = 0, dC4_4 = 0;
	int   dD1_4 = 0, dD2_4 = 0, dD3_4 = 0, dD4_4 = 0;

	float Space_4 = 0;
	float Space_AB_4 = 0, Space_CD_4;
	float KValue_4 = 0.0f;
	float KValue_4_2 = 0.0f;
	int   phaseA_4=0, phaseC_4=0, PhaseM_4=0;
	float dRatio1_4 = 0;//, dRatio2_4=0;
	unsigned char Mask_AB_4=0, Mask_CD_4=0;
	unsigned char Mask_4, MaskA_4 = 0, MaskC_4 = 0;
	const float P1_4 = (float)(pCastParamD4->PerA);
	const float P2_4 = (float)(pCastParamD4->PerB);
	const float Gamma_4 = (float)(pCastParamD4->Gamma);

	int Phase1 = 0;
	int Phase2 = 0;
	int PhaseM = 0;
	int Raw_1[4], Raw_2[4], Raw_3[4], Raw_4[4];
	float Mean_AB_1=0.0f, Mean_AB_2=0.0f, Mean_AB_3=0.0f, Mean_AB_4=0.0f;
	float Mean_CD_1=0.0f, Mean_CD_2=0.0f, Mean_CD_3=0.0f, Mean_CD_4=0.0f;
	float Threshold_AB_1=0.0f, Threshold_AB_2=0.0f, Threshold_AB_3=0.0f, Threshold_AB_4=0.0f;
	float Threshold_CD_1=0.0f, Threshold_CD_2=0.0f, Threshold_CD_3=0.0f, Threshold_CD_4=0.0f;
	const bool bUseGamma = USE_GAMMA_CALIBRATION;
	const int  CombinePeriodMode = NoiseParam.PhaseCombinePeriodMode;
	const int  PhaseConvertHeightMode = NoiseParam.PhaseConvertHeightMode;
	const int PhaseNoiseDef = NoiseParam.PhaseNoiseDef;
	const int PhaseNoiseDefMode=NoiseParam.PhaseNoiseDefMode;
	const int CastMergeMode = NoiseParam.SpaceMultiCastMergeMode;
	const int LowContrastA = NoiseParam.PhaseLowContrastA;
	const int LowPotentialA = NoiseParam.PhaseLowPotentialA;
	const int SaturationA = NoiseParam.PhaseOverSaturatedA;
	const int IntensityMergeMode = NoiseParam.SpaceMultiIntensityMergeMode;
	//以周期越短越好, 因為又要壓回unsigned char周期， 所以這個係數無用

	const int MaxN = 8;//最多8個16週期			
	const int CodeMapSize = 16;	
	const int Period = PHASE_PERIOD;		
	__shared__ unsigned char CodeMap1[CodeMapSize];
	__shared__ unsigned char CodeMap2[CodeMapSize];
	for (i = 0; i<CodeMapSize; i++)
	{	CodeMap1[i] = CodeMap2[i] = 0;	}
	BuildCudaGrayCodeMapTable_Kernel(3, CodeMap1, CodeMapSize);
	BuildCudaGrayCodeMapTable_Kernel(4, CodeMap2, CodeMapSize);

	const float ExpTimeRatio_1_AB = (float)(pCastParamD1->ExpTimeB*1.0f/pCastParamD1->ExpTimeA);
	const float ExpTimeRatio_2_AB = (float)(pCastParamD2->ExpTimeB*1.0f/pCastParamD2->ExpTimeA);
	const float ExpTimeRatio_3_AB = (float)(pCastParamD3->ExpTimeB*1.0f/pCastParamD3->ExpTimeA);
	const float ExpTimeRatio_4_AB = (float)(pCastParamD4->ExpTimeB*1.0f/pCastParamD4->ExpTimeA);

	const float ExpTimeRatio_1_CD = (float)(pCastParamD1->ExpTimeD*1.0f/pCastParamD1->ExpTimeC);
	const float ExpTimeRatio_2_CD = (float)(pCastParamD2->ExpTimeD*1.0f/pCastParamD2->ExpTimeC);
	const float ExpTimeRatio_3_CD = (float)(pCastParamD3->ExpTimeD*1.0f/pCastParamD3->ExpTimeC);
	const float ExpTimeRatio_4_CD = (float)(pCastParamD4->ExpTimeD*1.0f/pCastParamD4->ExpTimeC);

	const int ImageStep = pCastParamD1->ImageStep;
	const int FactorCnt = sizeof(pCastParamD1->HeightFactor0) / (sizeof(pCastParamD1->HeightFactor0[0]));
	__shared__ double HeightFactor0_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_1[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_1[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_2[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_2[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_3[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_3[CUDA_HEIGHT_FACTOR_SIZE];
	__shared__ double HeightFactor0_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor1_4[CUDA_HEIGHT_FACTOR_SIZE], HeightFactor2_4[CUDA_HEIGHT_FACTOR_SIZE];
	for (i = 0; i<CUDA_HEIGHT_FACTOR_SIZE; i++)
	{
		HeightFactor0_1[i] = HeightFactor1_1[i] = HeightFactor2_1[i] = 0;
		HeightFactor0_2[i] = HeightFactor1_2[i] = HeightFactor2_2[i] = 0;
		HeightFactor0_3[i] = HeightFactor1_3[i] = HeightFactor2_3[i] = 0;
		HeightFactor0_4[i] = HeightFactor1_4[i] = HeightFactor2_4[i] = 0;
	}
	for (i = 0; i<FactorCnt; i++)
	{
		if (i >= CUDA_HEIGHT_FACTOR_SIZE) { break; }
		HeightFactor0_1[i] = pCastParamD1->HeightFactor0[i];	HeightFactor1_1[i] = pCastParamD1->HeightFactor1[i];	HeightFactor2_1[i] = pCastParamD1->HeightFactor2[i];
		HeightFactor0_2[i] = pCastParamD2->HeightFactor0[i];	HeightFactor1_2[i] = pCastParamD2->HeightFactor1[i];	HeightFactor2_2[i] = pCastParamD2->HeightFactor2[i];
		HeightFactor0_3[i] = pCastParamD3->HeightFactor0[i];	HeightFactor1_3[i] = pCastParamD3->HeightFactor1[i];	HeightFactor2_3[i] = pCastParamD3->HeightFactor2[i];
		HeightFactor0_4[i] = pCastParamD4->HeightFactor0[i];	HeightFactor1_4[i] = pCastParamD4->HeightFactor1[i];	HeightFactor2_4[i] = pCastParamD4->HeightFactor2[i];
	}
	__syncthreads();//同1個Block多個Thread同步化	

	//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
	//  gridDim		網格大小   (網格包含的區塊數目)	
	for (i = (blockIdx.x*blockDim.x) + threadIdx.x; i < ImageSize; i += blockDim.x*gridDim.x)
	{
		if (i >= ImageSize) { continue; }
		const int x = i%ImageStep;
		const int y = i / ImageStep;

		dA1_1 = pCastParamD1->PtrA1[i];	dA2_1 = pCastParamD1->PtrA2[i];	dA3_1 = pCastParamD1->PtrA3[i];	dA4_1 = pCastParamD1->PtrA4[i];
		dB1_1 = pCastParamD1->PtrB1[i];	dB2_1 = pCastParamD1->PtrB2[i];	dB3_1 = pCastParamD1->PtrB3[i];	dB4_1 = pCastParamD1->PtrB4[i];		
		dC1_1 = pCastParamD1->PtrC1[i];	dC2_1 = pCastParamD1->PtrC2[i];	dC3_1 = pCastParamD1->PtrC3[i];	dC4_1 = pCastParamD1->PtrC4[i];
		dD1_1 = pCastParamD1->PtrD1[i];	dD2_1 = pCastParamD1->PtrD2[i];	dD3_1 = pCastParamD1->PtrD3[i];	dD4_1 = pCastParamD1->PtrD4[i];		
		PhaseBase_1 = pCastParamD1->ZeroPhasePtr[i];
		if (NULL != pCastParamD1->HeightFactorPtr) { KValue_1 = pCastParamD1->HeightFactorPtr[i]; }

		dA1_2 = pCastParamD2->PtrA1[i];	dA2_2 = pCastParamD2->PtrA2[i];	dA3_2 = pCastParamD2->PtrA3[i];	dA4_2 = pCastParamD2->PtrA4[i];
		dB1_2 = pCastParamD2->PtrB1[i];	dB2_2 = pCastParamD2->PtrB2[i];	dB3_2 = pCastParamD2->PtrB3[i];	dB4_2 = pCastParamD2->PtrB4[i];
		dC1_2 = pCastParamD2->PtrC1[i];	dC2_2 = pCastParamD2->PtrC2[i];	dC3_2 = pCastParamD2->PtrC3[i];	dC4_2 = pCastParamD2->PtrC4[i];
		dD1_2 = pCastParamD2->PtrD1[i];	dD2_2 = pCastParamD2->PtrD2[i];	dD3_2 = pCastParamD2->PtrD3[i];	dD4_2 = pCastParamD2->PtrD4[i];
		PhaseBase_2 = pCastParamD2->ZeroPhasePtr[i];
		if (NULL != pCastParamD2->HeightFactorPtr) { KValue_2 = pCastParamD2->HeightFactorPtr[i]; }

		dA1_3 = pCastParamD3->PtrA1[i];	dA2_3 = pCastParamD3->PtrA2[i];	dA3_3 = pCastParamD3->PtrA3[i];	dA4_3 = pCastParamD3->PtrA4[i];
		dB1_3 = pCastParamD3->PtrB1[i];	dB2_3 = pCastParamD3->PtrB2[i];	dB3_3 = pCastParamD3->PtrB3[i];	dB4_3 = pCastParamD3->PtrB4[i];
		dC1_3 = pCastParamD3->PtrC1[i];	dC2_3 = pCastParamD3->PtrC2[i];	dC3_3 = pCastParamD3->PtrC3[i];	dC4_3 = pCastParamD3->PtrC4[i];
		dD1_3 = pCastParamD3->PtrD1[i];	dD2_3 = pCastParamD3->PtrD2[i];	dD3_3 = pCastParamD3->PtrD3[i];	dD4_3 = pCastParamD3->PtrD4[i];
		PhaseBase_3 = pCastParamD3->ZeroPhasePtr[i];
		if (NULL != pCastParamD3->HeightFactorPtr) { KValue_3 = pCastParamD3->HeightFactorPtr[i]; }

		dA1_4 = pCastParamD4->PtrA1[i];	dA2_4 = pCastParamD4->PtrA2[i];	dA3_4 = pCastParamD4->PtrA3[i];	dA4_4 = pCastParamD4->PtrA4[i];
		dB1_4 = pCastParamD4->PtrB1[i];	dB2_4 = pCastParamD4->PtrB2[i];	dB3_4 = pCastParamD4->PtrB3[i];	dB4_4 = pCastParamD4->PtrB4[i];
		dC1_4 = pCastParamD4->PtrC1[i];	dC2_4 = pCastParamD4->PtrC2[i];	dC3_4 = pCastParamD4->PtrC3[i];	dC4_4 = pCastParamD4->PtrC4[i];
