		if ( MULTI_CAST_MERGE_MODE_JOE_1 == CastMergeMode )
		{
			if ( PhaseM_CD_1 == PhaseM_1 )
			{	Raw_1[0]=dC1_1;	Raw_1[1]=dC2_1;	Raw_1[2]=dC3_1;	Raw_1[3]=dC4_1; }
			else
			{	Raw_1[0]=dA1_1;	Raw_1[1]=dA2_1;	Raw_1[2]=dA3_1;	Raw_1[3]=dA4_1; }

