			dD4_3 = CalcCudaGamma_Kernel(dD4_3, Gamma_3);	
			dD5_3 = CalcCudaGamma_Kernel(dD5_3, Gamma_3);	
			dD6_3 = CalcCudaGamma_Kernel(dD6_3, Gamma_3);	

			dA1_4 = CalcCudaGamma_Kernel(dA1_4, Gamma_4);
			dA2_4 = CalcCudaGamma_Kernel(dA2_4, Gamma_4);
			dA3_4 = CalcCudaGamma_Kernel(dA3_4, Gamma_4);
			dA4_4 = CalcCudaGamma_Kernel(dA4_4, Gamma_4);
			dB1_4 = CalcCudaGamma_Kernel(dB1_4, Gamma_4);
			dB2_4 = CalcCudaGamma_Kernel(dB2_4, Gamma_4);
			dB3_4 = CalcCudaGamma_Kernel(dB3_4, Gamma_4);
			dB4_4 = CalcCudaGamma_Kernel(dB4_4, Gamma_4);
			dB5_4 = CalcCudaGamma_Kernel(dB5_4, Gamma_4);
			dB6_4 = CalcCudaGamma_Kernel(dB6_4, Gamma_4);
			dC1_4 = CalcCudaGamma_Kernel(dC1_4, Gamma_4);
			dC2_4 = CalcCudaGamma_Kernel(dC2_4, Gamma_4);
			dC3_4 = CalcCudaGamma_Kernel(dC3_4, Gamma_4);
			dC4_4 = CalcCudaGamma_Kernel(dC4_4, Gamma_4);
			dD1_4 = CalcCudaGamma_Kernel(dD1_4, Gamma_4);
			dD2_4 = CalcCudaGamma_Kernel(dD2_4, Gamma_4);
			dD3_4 = CalcCudaGamma_Kernel(dD3_4, Gamma_4);
			dD4_4 = CalcCudaGamma_Kernel(dD4_4, Gamma_4);	
			dD5_4 = CalcCudaGamma_Kernel(dD5_4, Gamma_4);	
			dD6_4 = CalcCudaGamma_Kernel(dD6_4, Gamma_4);	
		}

		Mean_AB_1=(dA1_1+dA2_1+dA3_1+dA4_1)/4.0f;
		Threshold_AB_1=(float)(Mean_AB_1*ExpTimeRatio_1_AB);
		Mean_AB_2=(dA1_2+dA2_2+dA3_2+dA4_2)/4.0f;
		Threshold_AB_2=(float)(Mean_AB_2*ExpTimeRatio_2_AB);
		Mean_AB_3=(dA1_3+dA2_3+dA3_3+dA4_3)/4.0f;
		Threshold_AB_3=(float)(Mean_AB_3*ExpTimeRatio_3_AB);
		Mean_AB_4=(dA1_4+dA2_4+dA3_4+dA4_4)/4.0f;
		Threshold_AB_4=(float)(Mean_AB_4*ExpTimeRatio_4_AB);

		Mean_CD_1=(dC1_1+dC2_1+dC3_1+dC4_1)/4.0f;
		Threshold_CD_1=(float)(Mean_CD_1*ExpTimeRatio_1_CD);
		Mean_CD_2=(dC1_2+dC2_2+dC3_2+dC4_2)/4.0f;
		Threshold_CD_2=(float)(Mean_CD_2*ExpTimeRatio_2_CD);
		Mean_CD_3=(dC1_3+dC2_3+dC3_3+dC4_3)/4.0f;
		Threshold_CD_3=(float)(Mean_CD_3*ExpTimeRatio_3_CD);
		Mean_CD_4=(dC1_4+dC2_4+dC3_4+dC4_4)/4.0f;
		Threshold_CD_4=(float)(Mean_CD_4*ExpTimeRatio_4_CD);

		CalcCuda6GrayCodeParam_kernel(dB1_1, dB2_1, dB3_1, dB4_1, dB5_1, dB6_1, Threshold_AB_1, CodeMap1, CodeMap2, k1_AB_1, k2_AB_1);
		CalcCuda6GrayCodeParam_kernel(dB1_2, dB2_2, dB3_2, dB4_2, dB5_2, dB6_2, Threshold_AB_2, CodeMap1, CodeMap2, k1_AB_2, k2_AB_2);
		CalcCuda6GrayCodeParam_kernel(dB1_3, dB2_3, dB3_3, dB4_3, dB5_3, dB6_3, Threshold_AB_3, CodeMap1, CodeMap2, k1_AB_3, k2_AB_3);
		CalcCuda6GrayCodeParam_kernel(dB1_4, dB2_4, dB3_4, dB4_4, dB5_4, dB6_4, Threshold_AB_4, CodeMap1, CodeMap2, k1_AB_4, k2_AB_4);

		CalcCuda6GrayCodeParam_kernel(dD1_1, dD2_1, dD3_1, dD4_1, dD5_1, dD6_1, Threshold_CD_1, CodeMap1, CodeMap2, k1_CD_1, k2_CD_1);
		CalcCuda6GrayCodeParam_kernel(dD1_2, dD2_2, dD3_2, dD4_2, dD5_2, dD6_2, Threshold_CD_2, CodeMap1, CodeMap2, k1_CD_2, k2_CD_2);
		CalcCuda6GrayCodeParam_kernel(dD1_3, dD2_3, dD3_3, dD4_3, dD5_3, dD6_3, Threshold_CD_3, CodeMap1, CodeMap2, k1_CD_3, k2_CD_3);
		CalcCuda6GrayCodeParam_kernel(dD1_4, dD2_4, dD3_4, dD4_4, dD5_4, dD6_4, Threshold_CD_4, CodeMap1, CodeMap2, k1_CD_4, k2_CD_4);

		CalcCuda4PhaseParamMask_kernel(dA1_1, dA2_1, dA3_1, dA4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_1, MaskA_1, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_2, dA2_2, dA3_2, dA4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_2, MaskA_2, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_3, dA2_3, dA3_3, dA4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_3, MaskA_3, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dA1_4, dA2_4, dA3_4, dA4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseA_4, MaskA_4, PhaseNoiseDefMode);		

		CalcCuda4PhaseParamMask_kernel(dC1_1, dC2_1, dC3_1, dC4_1, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseC_1, MaskC_1, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dC1_2, dC2_2, dC3_2, dC4_2, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseC_2, MaskC_2, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dC1_3, dC2_3, dC3_3, dC4_3, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseC_3, MaskC_3, PhaseNoiseDefMode);		
		CalcCuda4PhaseParamMask_kernel(dC1_4, dC2_4, dC3_4, dC4_4, PhaseNoiseDef, LowContrastA, LowPotentialA, SaturationA, phaseC_4, MaskC_4, PhaseNoiseDefMode);	

		//Cast 1
		PhaseM_AB_1 = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_1, Period, MaxN, k1_AB_1, k2_AB_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM_AB_1);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_AB_1, KValue_1, KValue_1_2, Space_AB_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_AB_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_AB_1);		
		Mask_AB_1 = MaskA_1;

		PhaseM_CD_1 = CombineCudaPhasePeriod_GrayCode_Kernel(phaseC_1, Period, MaxN, k1_CD_1, k2_CD_1);
		DeductBasePhase_Kernel(PhaseBase_1, PhaseM_CD_1);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_CD_1, KValue_1, KValue_1_2, Space_CD_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_CD_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_CD_1);		
		Mask_CD_1 = MaskC_1;

		//MergeCuda2ExpPhaseData_Kernel_II(Mask_AB_1, PhaseM_AB_1, Mask_CD_1, PhaseM_CD_1, Mask_1, PhaseM, PhaseZero_1);
		if ( MULTI_INTENSITY_MERGE_MODE_MEAN != IntensityMergeMode )
		{
			float A_AB=0.0f, B_AB=0.0f, CV_AB=0.0f, A_CD=0.0f, B_CD=0.0f, CV_CD=0.0f;
			CalcCuda4PhaseMeanContrastRatio_Kernel(dA1_1, dA2_1, dA3_1, dA4_1, A_AB, B_AB, CV_AB);
			CalcCuda4PhaseMeanContrastRatio_Kernel(dC1_1, dC2_1, dC3_1, dC4_1, A_CD, B_CD, CV_CD);
			if ( MULTI_INTENSITY_MERGE_MODE_MAXB == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxB_Kernel(Mask_AB_1, PhaseM_AB_1, A_AB, B_AB, Mask_CD_1, PhaseM_CD_1, A_CD, B_CD, Mask_1, PhaseM_1); }
			else if ( MULTI_INTENSITY_MERGE_MODE_MAXCV == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxCV_Kernel(Mask_AB_1, PhaseM_AB_1, A_AB, B_AB, Mask_CD_1, PhaseM_CD_1, A_CD, B_CD, Mask_1, PhaseM_1); }			
		}
		else
		{	MergeCuda2ExpPhaseDataByMean_Kernel(Mask_AB_1, PhaseM_AB_1, Mean_AB_1, Mask_CD_1, PhaseM_CD_1, Mean_CD_1, Mask_1, PhaseM_1); }
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_1, KValue_1, KValue_1_2, Space_1);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_1, HeightFactor0_1, HeightFactor1_1, HeightFactor2_1, Space_1);		

		//Cast 2		
		PhaseM_AB_2 = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_2, Period, MaxN, k1_AB_2, k2_AB_2);
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM_AB_2);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_AB_2, KValue_2, KValue_2_2, Space_AB_2);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_AB_2, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_AB_2);		
		Mask_AB_2 = MaskA_2;

		PhaseM_CD_2 = CombineCudaPhasePeriod_GrayCode_Kernel(phaseC_2, Period, MaxN, k1_CD_2, k2_CD_2);
		DeductBasePhase_Kernel(PhaseBase_2, PhaseM_CD_2);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_CD_2, KValue_2, KValue_2_2, Space_CD_2);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_CD_2, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_CD_2);		
		Mask_CD_2 = MaskC_2;

		//MergeCuda2ExpPhaseData_Kernel_II(Mask_AB_2, PhaseM_AB_2, Mask_CD_2, PhaseM_CD_2, Mask_2, PhaseM, PhaseZero_2);
		if ( MULTI_INTENSITY_MERGE_MODE_MEAN != IntensityMergeMode )
		{
			float A_AB=0.0f, B_AB=0.0f, CV_AB=0.0f, A_CD=0.0f, B_CD=0.0f, CV_CD=0.0f;
			CalcCuda4PhaseMeanContrastRatio_Kernel(dA1_2, dA2_2, dA3_2, dA4_2, A_AB, B_AB, CV_AB);
			CalcCuda4PhaseMeanContrastRatio_Kernel(dC1_2, dC2_2, dC3_2, dC4_2, A_CD, B_CD, CV_CD);
			if ( MULTI_INTENSITY_MERGE_MODE_MAXB == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxB_Kernel(Mask_AB_2, PhaseM_AB_2, A_AB, B_AB, Mask_CD_2, PhaseM_CD_2, A_CD, B_CD, Mask_2, PhaseM_2); }
			else if ( MULTI_INTENSITY_MERGE_MODE_MAXCV == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxCV_Kernel(Mask_AB_2, PhaseM_AB_2, A_AB, B_AB, Mask_CD_2, PhaseM_CD_2, A_CD, B_CD, Mask_2, PhaseM_2); }			
		}
		else
		{	MergeCuda2ExpPhaseDataByMean_Kernel(Mask_AB_2, PhaseM_AB_2, Mean_AB_2, Mask_CD_2, PhaseM_CD_2, Mean_CD_2, Mask_2, PhaseM_2); }
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_2, KValue_2, KValue_2_2, Space_2);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_2, HeightFactor0_2, HeightFactor1_2, HeightFactor2_2, Space_2);		

		//Cast 3
		PhaseM_AB_3 = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_3, Period, MaxN, k1_AB_3, k2_AB_3);
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM_AB_3);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_AB_3, KValue_3, KValue_3_2, Space_AB_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_AB_3, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_AB_3);		
		Mask_AB_3 = MaskA_3;

		PhaseM_CD_3 = CombineCudaPhasePeriod_GrayCode_Kernel(phaseC_3, Period, MaxN, k1_CD_3, k2_CD_3);
		DeductBasePhase_Kernel(PhaseBase_3, PhaseM_CD_3);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_CD_3, KValue_3, KValue_3_2, Space_CD_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_CD_3, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_CD_3);		
		Mask_CD_3 = MaskC_3;

		//MergeCuda2ExpPhaseData_Kernel_II(Mask_AB_3, PhaseM_AB_3, Mask_CD_3, PhaseM_CD_3, Mask_3, PhaseM, PhaseZero_3);
		if ( MULTI_INTENSITY_MERGE_MODE_MEAN != IntensityMergeMode )
		{
			float A_AB=0.0f, B_AB=0.0f, CV_AB=0.0f, A_CD=0.0f, B_CD=0.0f, CV_CD=0.0f;
			CalcCuda4PhaseMeanContrastRatio_Kernel(dA1_3, dA2_3, dA3_3, dA4_3, A_AB, B_AB, CV_AB);
			CalcCuda4PhaseMeanContrastRatio_Kernel(dC1_3, dC2_3, dC3_3, dC4_3, A_CD, B_CD, CV_CD);
			if ( MULTI_INTENSITY_MERGE_MODE_MAXB == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxB_Kernel(Mask_AB_3, PhaseM_AB_3, A_AB, B_AB, Mask_CD_3, PhaseM_CD_3, A_CD, B_CD, Mask_3, PhaseM_3); }
			else if ( MULTI_INTENSITY_MERGE_MODE_MAXCV == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxCV_Kernel(Mask_AB_3, PhaseM_AB_3, A_AB, B_AB, Mask_CD_3, PhaseM_CD_3, A_CD, B_CD, Mask_3, PhaseM_3); }			
		}
		else
		{	MergeCuda2ExpPhaseDataByMean_Kernel(Mask_AB_3, PhaseM_AB_3, Mean_AB_3, Mask_CD_3, PhaseM_CD_3, Mean_CD_3, Mask_3, PhaseM_3); }
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_3, KValue_3, KValue_3_2, Space_3);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_3, HeightFactor0_3, HeightFactor1_3, HeightFactor2_3, Space_3);		

		//Cast 4
		PhaseM_AB_4 = CombineCudaPhasePeriod_GrayCode_Kernel(phaseA_4, Period, MaxN, k1_AB_4, k2_AB_4);
		DeductBasePhase_Kernel(PhaseBase_4, PhaseM_AB_4);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_AB_4, KValue_4, KValue_4_2, Space_AB_4);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_AB_4, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_AB_4);		
		Mask_AB_4 = MaskA_4;

		PhaseM_CD_4 = CombineCudaPhasePeriod_GrayCode_Kernel(phaseC_4, Period, MaxN, k1_CD_4, k2_CD_4);
		DeductBasePhase_Kernel(PhaseBase_4, PhaseM_CD_4);
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_CD_4, KValue_4, KValue_4_2, Space_CD_4);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_CD_4, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_CD_4);		
		Mask_CD_4 = MaskC_4;

		//MergeCuda2ExpPhaseData_Kernel_II(Mask_AB_4, PhaseM_AB_4, Mask_CD_4, PhaseM_CD_4, Mask_4, PhaseM, PhaseZero_4);
		if ( MULTI_INTENSITY_MERGE_MODE_MEAN != IntensityMergeMode )
		{
			float A_AB=0.0f, B_AB=0.0f, CV_AB=0.0f, A_CD=0.0f, B_CD=0.0f, CV_CD=0.0f;
			CalcCuda4PhaseMeanContrastRatio_Kernel(dA1_4, dA2_4, dA3_4, dA4_4, A_AB, B_AB, CV_AB);
			CalcCuda4PhaseMeanContrastRatio_Kernel(dC1_4, dC2_4, dC3_4, dC4_4, A_CD, B_CD, CV_CD);
			if ( MULTI_INTENSITY_MERGE_MODE_MAXB == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxB_Kernel(Mask_AB_4, PhaseM_AB_4, A_AB, B_AB, Mask_CD_4, PhaseM_CD_4, A_CD, B_CD, Mask_4, PhaseM_4); }
			else if ( MULTI_INTENSITY_MERGE_MODE_MAXCV == IntensityMergeMode )
			{	MergeCuda2ExpPhaseDataByMaxCV_Kernel(Mask_AB_4, PhaseM_AB_4, A_AB, B_AB, Mask_CD_4, PhaseM_CD_4, A_CD, B_CD, Mask_4, PhaseM_4); }			
		}
		else
		{	MergeCuda2ExpPhaseDataByMean_Kernel(Mask_AB_4, PhaseM_AB_4, Mean_AB_4, Mask_CD_4, PhaseM_CD_4, Mean_CD_4, Mask_4, PhaseM_4);	}
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhaseM_4, KValue_4, KValue_4_2, Space_4);
		ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM_4, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, Space_4);		

		if ( MULTI_CAST_MERGE_MODE_JOE_1 == CastMergeMode )
		{
			if ( PhaseM_CD_1 == PhaseM_1 )
			{	Raw_1[0]=dC1_1;	Raw_1[1]=dC2_1;	Raw_1[2]=dC3_1;	Raw_1[3]=dC4_1; }
			else
			{	Raw_1[0]=dA1_1;	Raw_1[1]=dA2_1;	Raw_1[2]=dA3_1;	Raw_1[3]=dA4_1; }

			if ( PhaseM_CD_2 == PhaseM_2 )
			{	Raw_2[0]=dC1_2;	Raw_2[1]=dC2_2;	Raw_2[2]=dC3_2;	Raw_2[3]=dC4_2; }
			else
			{	Raw_2[0]=dA1_2;	Raw_2[1]=dA2_2;	Raw_2[2]=dA3_2;	Raw_2[3]=dA4_2; }

			if ( PhaseM_CD_3 == PhaseM_3 )
			{	Raw_3[0]=dC1_3;	Raw_3[1]=dC2_3;	Raw_3[2]=dC3_3;	Raw_3[3]=dC4_3; }
			else
			{	Raw_3[0]=dA1_3;	Raw_3[1]=dA2_3;	Raw_3[2]=dA3_3;	Raw_3[3]=dA4_3; }

			if ( PhaseM_CD_4 == PhaseM_4 )
			{	Raw_4[0]=dC1_4;	Raw_4[1]=dC2_4;	Raw_4[2]=dC3_4;	Raw_4[3]=dC4_4; }
			else
			{	Raw_4[0]=dA1_4;	Raw_4[1]=dA2_4;	Raw_4[2]=dA3_4;	Raw_4[3]=dA4_4; }
			MergeCuda4SpaceData_Joe_Kernel(NoiseParam, Raw_1, Mask_1, Space_1, Raw_2, Mask_2, Space_2, Raw_3, Mask_3, Space_3, Raw_4, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]);
		}
		else
		{
			//CompareCuda4OppositeGray_Kernel(NoiseParam, cA_1, cA_2, cA_3, cA_4, Mask_1, Mask_2, Mask_3, Mask_4);		
			if (CompareCuda4SpaceHeight_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]) == false)
			{	MergeCuda4SpaceData_Kernel(NoiseParam, Mask_1, Space_1, Mask_2, Space_2, Mask_3, Space_3, Mask_4, Space_4, MaskPtrD[i], SpacePtrD[i]);	}
		}
		pCastParamD1->PtrMask[i] = Mask_1;	pCastParamD1->PtrSpace[i] = Space_1;
		pCastParamD2->PtrMask[i] = Mask_2;	pCastParamD2->PtrSpace[i] = Space_2;
		pCastParamD3->PtrMask[i] = Mask_3;	pCastParamD3->PtrSpace[i] = Space_3;
		pCastParamD4->PtrMask[i] = Mask_4;	pCastParamD4->PtrSpace[i] = Space_4;
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaContentAwareFilter_Kernel(unsigned int ImageW, unsigned int ImageH, unsigned int ImageStep, const SPACE_PTR pSpace, const MASK_PTR pMask, const IMAGE_PTR GuidedImagePtr, int KerSize, int UseSize, bool FilterSearchOn, int FilterAlphaF, int FilterAlphaS, int FilterAlphaM, int FilterAlphaI, int FilterThresdhold_Outlier, SPACE_PTR pDst)//影像濾波
{
	const size_t ImageSize = ImageStep*ImageH;
	const size_t Size_KerW = KerSize;
	const size_t Size_KerWR = Size_KerW / 2;
	const size_t Size_UseSize = UseSize;
	const bool SearchOn = FilterSearchOn;
	const float alpha_F = FilterAlphaF > 0 ? FilterAlphaF : 1;
	const float alpha_S = FilterAlphaS > 0 ? FilterAlphaS : 1;
	const float alpha_M = FilterAlphaM > 0 ? FilterAlphaM : 1;
	const float alpha_I = FilterAlphaI > 0 ? FilterAlphaI : 1;
	const float Thresdhold_Outlier = FilterThresdhold_Outlier / 100.f;
	bool AllUse = Size_UseSize == 0 ? true : false;

	size_t idx_Buf = 0, idx_X = 0, idx_Y = 0;
	size_t idx_Ker = 0, idx_KerX = 0, idx_KerY = 0;
	size_t min_KerX = 0, min_KerY = 0, max_KerX = 0, max_KerY = 0;
	size_t min_UseX = 0, min_UseY = 0, max_UseX = 0, max_UseY = 0;
	float tmpV = 0.0;
	float coefficientS = 0;
	float coefficientM = 0;
	float coefficientI = 0;
	float weightSum = 0;
	float weightSumAvg = 0;
	float similarity = 0;
	float SpaceSum = 0;
	float SpaceDifferSum = 0;
	float SpaceSimilar = 0;
	float SpaceDifferAvg = 0;
	float SpaceAvg = 0;
	float Percentage_inlier = 0;
	float SpaceMid = 0;//近似中間值
	float tmpD_Mean = 0;
	float MinDistanceMean = 0;
	size_t SpaceCnt = 0;

	for (idx_Buf = (blockIdx.x*blockDim.x) + threadIdx.x; idx_Buf < ImageSize; idx_Buf += blockDim.x*gridDim.x)
	{
		idx_X = idx_Buf >= ImageStep ? idx_Buf % ImageStep : idx_Buf;
		idx_Y = idx_Buf / ImageStep;

		min_KerX = idx_X >= Size_KerWR ? idx_X - Size_KerWR : 0;
		min_KerY = idx_Y >= Size_KerWR ? idx_Y - Size_KerWR : 0;
		max_KerX = idx_X + Size_KerWR < ImageW ? idx_X + Size_KerWR : ImageW;
		max_KerY = idx_Y + Size_KerWR < ImageH ? idx_Y + Size_KerWR : ImageH;
		min_UseX = min_KerX + Size_UseSize;
		min_UseY = min_KerY + Size_UseSize;
		max_UseX = max_KerX - Size_UseSize;
		max_UseY = max_KerY - Size_UseSize;

		SpaceCnt = 0;
		tmpV = 0;
		weightSum = 0; //weightSumAvg = 0;
		SpaceSum = 0; //SpaceDifferSum = 0;		
		for (idx_KerY = min_KerY; idx_KerY < max_KerY; idx_KerY++)
		{
			for (idx_KerX = min_KerX; idx_KerX < max_KerX; idx_KerX++)
			{
				if (AllUse || ((idx_KerX < min_UseX || idx_KerX > max_UseX) && (idx_KerY < min_UseY || idx_KerY > max_UseY)))
				{
					idx_Ker = idx_KerY * ImageStep + idx_KerX;					
					if (idx_Ker != idx_Buf)
					{
						if (SearchOn)
						{
							//coefficientS = -1 * abs(SpacePtr[idx_Ker] - SpacePtr[idx_Buf]) / (2 * alpha_F * alpha_F);
							coefficientS = -1 * abs(pSpace[idx_Ker] - pSpace[idx_Buf]) / (alpha_F);
							similarity = expf(coefficientS);
							tmpV += similarity * pSpace[idx_Ker];
							weightSum += similarity;
							//weightSumAvg += (1 - similarity);
							//SpaceDifferSum += (1 - similarity) * SpacePtr[idx_Ker];
						}
						SpaceSum += pSpace[idx_Ker];
						SpaceCnt++;
					}
				}
			}
		}
		if (SearchOn)
		{
			SpaceSimilar = weightSum > 0 ? tmpV / weightSum : pSpace[idx_Buf];
			//Percentage_inlier = weightSum / SpaceCnt;
			//SpaceDifferAvg = SpaceSum / weightSumAvg;//與中間值最不相似的區域平均值
		}

		SpaceAvg = SpaceCnt > 0 ? SpaceSum / SpaceCnt : 0;
		tmpV = 0;
		weightSum = 0;
		SpaceSum = 0;
		SpaceCnt = 0;
		for (idx_KerY = min_KerY; idx_KerY < max_KerY; idx_KerY++)
		{
			for (idx_KerX = min_KerX; idx_KerX < max_KerX; idx_KerX++)
			{
				//if (AllUse || ((idx_KerX < min_UseX || idx_KerX > max_UseX) && (idx_KerY < min_UseY || idx_KerY > max_UseY)))
				{
					idx_Ker = idx_KerY * ImageStep + idx_KerX;
					
					//coefficientS = SearchOn ? -1 * abs(SpacePtr[idx_Ker] - SpaceSimilar) / (2 * alpha_S * alpha_S) : 0;
					//coefficientM = -1 * abs(SpacePtr[idx_Ker] - SpacePtr[idx_Buf]) / (2 * alpha_M * alpha_M);
					//coefficientI = -1 * abs(GuidedImagePtr[idx_Ker] - GuidedImagePtr[idx_Buf]) / (2 * alpha_I * alpha_I);
					coefficientS = SearchOn ? abs(pSpace[idx_Ker] - SpaceSimilar) / (alpha_S) : 0;
					coefficientM = abs(pSpace[idx_Ker] - pSpace[idx_Buf]) / (alpha_M);
					coefficientI = abs(GuidedImagePtr[idx_Ker] - GuidedImagePtr[idx_Buf]) / (alpha_I);
					similarity = expf(-1 * (coefficientS + coefficientM + coefficientI));

					tmpV += similarity * pSpace[idx_Ker];
					weightSum += similarity;
					SpaceCnt++;

					tmpD_Mean = abs(pSpace[idx_Ker] - SpaceAvg);
					if (idx_KerX == min_KerX && idx_KerY == min_KerY)
					{
						MinDistanceMean = tmpD_Mean;
						SpaceMid = pSpace[idx_Ker];
					}
					else
					{
						if (tmpD_Mean < MinDistanceMean)
						{
							MinDistanceMean = tmpD_Mean;
							SpaceMid = pSpace[idx_Ker];
						}
					}
				}
			}
		}
		Percentage_inlier = SpaceCnt > 0 ? weightSum / SpaceCnt : 0;

		if (Percentage_inlier < Thresdhold_Outlier) { pDst[idx_Buf] = SpaceMid; }
		else { pDst[idx_Buf] = weightSum > 0 ? tmpV / weightSum : SpaceMid; }
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaMedianFilter_Kernel(unsigned int ImageW, unsigned int ImageH, unsigned int ImageStep, const SPACE_PTR pSpace, const MASK_PTR pMask, int KerSize, int UseSize, SPACE_PTR pDst)
{
	int i=0;
	int u=0, v=0;
	int KerIndex=0;
	int ImageX=0, ImageY=0;	
	int KerMinX=0, KerMinY=0;	
	int KerMaxX=0, KerMaxY=0;	
	int MskMinX=0, MskMinY=0;
	int MskMaxX=0, MskMaxY=0;
	int KerRealSizeW=0, KerRealSizeH=0;
	int KerRealSizeW2=0, KerRealSizeH2=0;
	int SpaceCnt=0;
	int SpaceIdx=0;	
	bool  BypassX=false;
	bool  BypassY=false;
	bool  BypassRealX=false;
	bool  BypassRealY=false;		
	float SpaceMid=0;
	int   KerTotalSize=0;
	const size_t Shift = 0;
	const size_t Pitch = 1;	
	const size_t KerSize2 = KerSize/2;
	const size_t MskSize = UseSize;
	const size_t ImageSize=ImageStep*ImageH;
	SPACE_DATA   SpaceData=0.0f;
	SPACE_DATA   SpaceData2=0.0f;
	SPACE_DATA   SpacePivot=0.0f;
	const int    KerBufferSize = 164;
	SPACE_DATA   SpaceList[KerBufferSize];//指標創建需要更多時間, 所以使用陣列	
	//SPACE_DATA  *SpaceList = new SPACE_DATA[KerBufferSize];
	//if ( NULL == SpaceList ) { return; }
	for ( i=0; i<KerBufferSize; i++ )
	{	SpaceList[i] = 0.0f;	}
	if ( 0==UseSize || UseSize>KerSize2 )
	{	KerTotalSize = KerSize*KerSize;	}
	else
	{
		int HorCount = 2*(KerSize*UseSize);
		int VerCount = 2*(KerSize-2*UseSize);
		KerTotalSize = HorCount+VerCount;
	}
	if ( KerTotalSize >= KerBufferSize )
	{	
		for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
		{	pDst[i] = pSpace[i];	}
		//delete SpaceList; SpaceList = NULL;	
		return;	
	}	
//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{
		pDst[i] = pSpace[i];
		ImageX = i%ImageStep;
		ImageY = i/ImageStep;		
		if ( Pitch > 1 ) 
		{
			if ( Shift!=(ImageX%Pitch) || Shift!=(ImageY%Pitch) )
			{	continue;	}
		}

		BypassY=false;
		if ( ImageX<KerSize2 ) { KerMinX=0; }
		else { KerMinX=ImageX-KerSize2; }
		if ( ImageY<KerSize2 ) { KerMinY=0; }
		else { KerMinY=ImageY-KerSize2; }
		KerMaxX = ImageX+KerSize2+1;				
		KerMaxY = ImageY+KerSize2+1;
		if ( KerMaxX>ImageW ) { KerMaxX=ImageW; }
		if ( KerMaxY>ImageH ) { KerMaxY=ImageH; }
		KerRealSizeW = KerMaxX-KerMinX;
		KerRealSizeH = KerMaxY-KerMinY;
		KerRealSizeW2 = KerRealSizeW/2;
		KerRealSizeH2 = KerRealSizeH/2;

		if ( 0==MskSize || MskSize>=KerRealSizeW2 ) 
		{	BypassX = true;	}
		else
		{	
			BypassX = false;	
			MskMinX = KerMinX+MskSize;
			MskMaxX = KerMaxX-MskSize-1;
		}	

		if ( 0==MskSize || MskSize>=KerRealSizeH2 ) 
		{	BypassY = true;	}
		else
		{	
			BypassY = false;	
			MskMinY = KerMinY+MskSize;
			MskMaxY = KerMaxY-MskSize-1;
		}
		BypassRealY = BypassY;
			
		SpaceCnt = 0;
		for ( v=KerMinY; v<KerMaxY; v++ )
		{
			if ( v<MskMinY || v>MskMaxY || true==BypassRealY )
			{	BypassRealX = true;	}
			else
			{	BypassRealX = BypassX; }
			for ( u=KerMinX; u<KerMaxX; u++ )
			{
				if ( u<MskMinX || u>MskMaxX || true==BypassRealX )
				{					
					KerIndex = v*ImageStep+u;
					if ( CheckCudaSpaceMaskValid_Kernel(pMask[KerIndex])==false )
					{	continue; }					
					if ( SpaceCnt < KerBufferSize )
					{	SpaceList[SpaceCnt++]=(pSpace[KerIndex]); }
				}
			}
		}		
		if ( SpaceCnt < 2 )
		{	continue; }

		SpaceIdx = (SpaceCnt>>1);
		//SpaceIdx = (SpaceCnt-1)/2;
		//排序
		for ( u=0; u<SpaceIdx+1; u++ )
		{
			SpacePivot = SpaceList[u];
			for ( v=u+1; v<SpaceCnt; v++ )
			{	
				if ( SpacePivot < SpaceList[v] )
				{	
					SpaceData = SpacePivot;
					SpacePivot = SpaceList[v];
					SpaceList[v]=SpaceData; 
				}
			}
			SpaceList[u] = SpacePivot;
		}		
		SpaceMid = SpaceList[SpaceIdx];		
		pDst[i] = SpaceMid;
	}	
	//delete SpaceList; SpaceList = NULL;	
	return;
}
