#define AutoCreateMedianFilterFunc_WithUseSize(fName, kSize, wSize) \
__global__ void fName(const float* input, float* dst, const unsigned char* mask, int width, int height, bool skipValid) { \
	const int dataSize = width * height; \
	const int windowSize = wSize; \
	const int useSize = 1; \
	const int radiusW = kSize >> 1; \
	const int radiusH = kSize >> 1; \
	float w[windowSize]; \
	memset(w, 9999999.f, sizeof(float) * windowSize); \
	for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < dataSize; i += blockDim.x * gridDim.x) { \
		if (skipValid && (mask[i] == PHASE_MASK_VALID || mask[i] == PHASE_MASK_VALID_BEST)) { dst[i] = input[i]; continue; } \
		int x = i % width; \
		int y = i / width; \
		int count = 0; \
		int gcount = 0; \
		for (int dy = -radiusH; dy < (-radiusH + useSize); ++dy) { \
			for (int dx = -radiusW; dx <= radiusW; ++dx) { \
				int nx = min(max(x + dx, 0), width - 1); \
				int ny = min(max(y + dy, 0), height - 1); \
				int idx = ny * width + nx; \
				int vmask = (!mask[idx] | (mask[idx] >> 7)); \
				w[count++] = vmask * input[idx]; \
				gcount += vmask; \
			} \
		} \
		for (int dy = (radiusH - useSize + 1); dy <= radiusH; ++dy) { \
			for (int dx = -radiusW; dx <= radiusW; ++dx) { \
				int nx = min(max(x + dx, 0), width - 1); \
				int ny = min(max(y + dy, 0), height - 1); \
				int idx = ny * width + nx; \
				int vmask = (!mask[idx] | (mask[idx] >> 7)); \
				w[count++] = vmask * input[idx]; \
				gcount += vmask; \
			} \
		} \
		for (int dx = -radiusW; dx < (-radiusW + useSize); ++dx) { \
			for (int dy = (-radiusH + useSize); dy <= (radiusH - useSize); ++dy) { \
				int nx = min(max(x + dx, 0), width - 1); \
				int ny = min(max(y + dy, 0), height - 1); \
				int idx = ny * width + nx; \
				int vmask = (!mask[idx] | (mask[idx] >> 7)); \
				w[count++] = vmask * input[idx]; \
				gcount += vmask; \
			} \
		} \
		for (int dx = (radiusW - useSize + 1); dx <= radiusW; ++dx) { \
			for (int dy = (-radiusH + useSize); dy <= (radiusH - useSize); ++dy) { \
				int nx = min(max(x + dx, 0), width - 1); \
				int ny = min(max(y + dy, 0), height - 1); \
				int idx = ny * width + nx; \
				int vmask = (!mask[idx] | (mask[idx] >> 7)); \
				w[count++] = vmask * input[idx]; \
				gcount += vmask; \
			} \
		} \
		FastSort_##wSize(w); \
		w[0] = input[i]; \
		dst[i] = w[(gcount > 0) * ((gcount / 2) + (count - gcount))]; \
	} \
}
