__global__ void averageFilter(const float* input, float* dst, int kSize, int width, int height) {
	const int dataSize = width * height;
	const int radiusW = kSize >> 1;
	const int radiusH = kSize >> 1;
	for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < dataSize; i += blockDim.x * gridDim.x) {
		int x = i % width;
		int y = i / width;
		int count = 0;
		float tmpV = 0;
		for (int dy = -radiusH; dy <= radiusH; ++dy) {
			for (int dx = -radiusW; dx <= radiusW; ++dx) {
				int nx = min(max(x + dx, 0), width - 1);
				int ny = min(max(y + dy, 0), height - 1);
				int idx = ny * width + nx;
				tmpV += input[idx];
				count++;
			}
		}
		dst[i] = tmpV / count;
	}
}

#define MAX_EDGEPRESERVE_KERNELSIZE 31		
#define MAX_GAUSSIANTABLE_SPATIAL_SIZE MAX_EDGEPRESERVE_KERNELSIZE*MAX_EDGEPRESERVE_KERNELSIZE
__device__ float __align__(32) LT_GaussianTable_Spatial[MAX_GAUSSIANTABLE_SPATIAL_SIZE]; // idx = (dy + MAX_EDGEPRESERVE_KERNELSIZE >> 1) * MAX_EDGEPRESERVE_KERNELSIZE + (dx + MAX_EDGEPRESERVE_KERNELSIZE >> 1)
bool BuildGaussianTable_Spatial(float sigma_s) {
	bool isok = false;
	int size = MAX_EDGEPRESERVE_KERNELSIZE;
	int radius = size >> 1;
	int totalSize = size * size;
	float* table = new float[totalSize]; {
		for (int y = -radius; y <= radius; y++) {
			for (int x = -radius; x <= radius; x++) {
				float distance = sqrtf(x * x + y * y);
				table[(y + radius) * size + (x + radius)] = expf(-distance * distance / (2 * sigma_s * sigma_s));
			}
		}
		cudaError err = cudaMemcpyToSymbol(LT_GaussianTable_Spatial, table, size * size * sizeof(float));
		isok = err == cudaSuccess;
	}
	delete[] table;
	return isok;
}

#define MAX_GAUSSIANTABLE_VALUE_SIZE 512
#define MAX_GAUSSIANTABLE_VALUE_DIFFERVALUE MAX_GAUSSIANTABLE_VALUE_SIZE - 1
__device__ float __align__(32) LT_GaussianTable_Value[MAX_GAUSSIANTABLE_VALUE_SIZE]; // idx = min(MAX_GAUSSIANTABLE_VALUE_DIFFERVALUE, abs(nv - cv))
bool BuildGaussianTable_Value(float sigma_v) {
	bool isok = false;
	float* table = new float[MAX_GAUSSIANTABLE_VALUE_SIZE]; {
		for (int i = 0; i < MAX_GAUSSIANTABLE_VALUE_SIZE; i++) {
			float distance = sqrtf(i * i);
			table[i] = expf(-distance * distance / (2 * sigma_v * sigma_v));
		}
		cudaError err = cudaMemcpyToSymbol(LT_GaussianTable_Value, table, MAX_GAUSSIANTABLE_VALUE_SIZE * sizeof(float));
		isok = err == cudaSuccess;
	}
	delete[] table;
	return isok;
}

// Smooth Filter : maximum kSize : 31
__global__ void edgePreserveFilter(const float* input, float* dst, int kSize, int width, int height) {
		const int dataSize = width * height;
		kSize = min(MAX_EDGEPRESERVE_KERNELSIZE, kSize);
		const int radiusLT = MAX_EDGEPRESERVE_KERNELSIZE >> 1;
		const int radius = kSize >> 1;

		// shared memory total : 48kb = 49152 bytes
		// total shared memory element(float) 49152 / sizeof(float) = 12288
		__shared__ float smem_Gaussian_spatial[MAX_GAUSSIANTABLE_SPATIAL_SIZE]; //961
		__shared__ float smem_Gaussian_value[MAX_GAUSSIANTABLE_VALUE_SIZE];		//512
		// load data into shared memory
		for (int i = 0; i < MAX_GAUSSIANTABLE_SPATIAL_SIZE; i++) { smem_Gaussian_spatial[i] = LT_GaussianTable_Spatial[i]; }
		for (int i = 0; i < MAX_GAUSSIANTABLE_VALUE_SIZE; i++) { smem_Gaussian_value[i] = LT_GaussianTable_Value[i]; }
		__syncthreads();

		for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < dataSize; i += blockDim.x * gridDim.x) {
			int x = i % width;
			int y = i / width;
			float cv = input[i];
			float sumV = 0.f;
			float sumW = 0.f;
			for (int dy = -radius; dy <= radius; ++dy) {
				for (int dx = -radius; dx <= radius; ++dx) {
					int nx = min(max(x + dx, 0), width - 1);
					int ny = min(max(y + dy, 0), height - 1);
					int idx = ny * width + nx;
					float nv = input[idx];

					int distanceIdx = (dy + radiusLT) * MAX_EDGEPRESERVE_KERNELSIZE + (dx + radiusLT);
					//float spaceWeight = expf(-(dx * dx + dy * dy) / (2 * sSize * sSize));
					//float spaceWeight = LT_GaussianTable_Spatial[distanceIdx];
					float spaceWeight = smem_Gaussian_spatial[distanceIdx];

					int diffV = min((int)fabs(cv - nv), MAX_GAUSSIANTABLE_VALUE_DIFFERVALUE);
					//float valueWeight = expf(-(cv - nv) * (cv - nv) / (2 * vSize * vSize));
					//float valueWeight = LT_GaussianTable_Value[min(MAX_GAUSSIANTABLE_VALUE_DIFFERVALUE, diffV)];
					float valueWeight = smem_Gaussian_value[diffV];

					float weight = spaceWeight * valueWeight;
					sumV += nv * weight;
					sumW += weight;
				}
			}
			dst[i] = sumV / sumW;
		}
	}
#pragma endregion
