__global__ void ExecCudaPhaseToSpace_Kernel(unsigned int ImageSize, const short *PhasePtrD, const float* KPtrD, float *DstPtrD)
{	
	unsigned int i=0;	
	const int PhaseConvertHeightMode = PHASE_CONVERT_HEIGHT_SCALE;
	if ( NULL == KPtrD ) { return; }
//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{	
		if ( i >= ImageSize ) { continue; }
		ConvertPhaseToSpace_Kernel(PhaseConvertHeightMode, PhasePtrD[i], KPtrD[i], 0.0f, DstPtrD[i]);
		//ConvertPhaseToSpaceMapFunc_Kernel(PhaseConvertHeightMode, x, y, PhaseM, HeightFactor0_4, HeightFactor1_4, HeightFactor2_4, DstPtrD[i]);
	}
}
