	{
		d1 = ImgD1[i];
		d2 = ImgD2[i];
		d3 = ImgD3[i]; 
		d4 = ImgD4[i];
		d5 = ImgD5[i];

		MergeValue = (d1+d2+d3+d4)>>2;
		MergeValue = MergeValue - pFFCBaseD[i];
		MergeValue = MergeValue * pFFCGainD[i];
		if( MergeValue > 255 )	{ MergeValue = 255; }
		if( MergeValue < 0 )	{ MergeValue = 0; }
		pMergeD[i] = MergeValue;
		
		a = 2.0f * (d2-d4);
		b = 2.0f*d3 - d5 - d1;
		if( IsUsePotentialValue == true )
		{
			if( (abs(a)+abs(b)) < PotentialValue )
			{ pMaskD[i] = PHASE_MASK_LOW_POTENTIAL; }
			else
			{ pMaskD[i] = PHASE_MASK_VALID; }
		}
		else	
		{
			if( d1>SaturationValue || d2>SaturationValue || d3>SaturationValue || d4>SaturationValue  )	//過飽合
			{
				pMaskD[i] = PHASE_MASK_OVER_SATURATED;		//標記無效點
			}	
			else if(abs(d2-d4)<LowContrastValue && abs(d3-d5)<LowContrastValue)	//對比太差
			{
				pMaskD[i] = PHASE_MASK_LOW_CONTRAST;		//標記無效點
			}
			else
			{ pMaskD[i] = PHASE_MASK_VALID; }	
		}

		phase = atan2f(a, b);
		if( phase < 0 )
		{ phase = PERIOD_RAD+phase; }

		pPhaseD[i] = phase * PHASE_RAD2SHORT;
	}
}
//------------------------------------------------------------------------------//
__global__ void DoCudaSolvePhaseAndFFCTexture_Three_Kernel(unsigned char *pMergeD, short *pPhaseD, unsigned char *pMaskD, const unsigned int ImageSize, unsigned char SaturationValue, unsigned char LowContrastValue, unsigned char PotentialValue, bool IsUsePotentialValue)
{
#ifdef _CUDA_TEXTURE_USED_
	unsigned int i=0;
	
	short d1=0, d2=0, d3=0;
	short a=0, b=0;
	short MergeValue;
	float phase=0;
//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	

    for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < ImageSize; i += blockDim.x*gridDim.x) 
	{
		d1 = tex1Dfetch( texRefImgD1, i);
		d2 = tex1Dfetch( texRefImgD2, i);
		d3 = tex1Dfetch( texRefImgD3, i);

		MergeValue = (d1+d3)>>1;
		MergeValue -= tex1Dfetch( texRefFFCBaseD, i);
		MergeValue *= tex1Dfetch( texRefFFCGainD, i);

		if( MergeValue > 255 )	{ MergeValue = 255; }
		if( MergeValue < 0 )	{ MergeValue = 0; }
		pMergeD[i] = MergeValue;
		
		a=d3-d2;
		b=d1-d2;
		if( IsUsePotentialValue == true )
		{
			if( (abs(a)+abs(b)) < PotentialValue )
			{ pMaskD[i] = PHASE_MASK_LOW_POTENTIAL; }
			else
			{ pMaskD[i] = PHASE_MASK_VALID; }
		}
		else	
		{
			if( d1>SaturationValue || d2>SaturationValue || d3>SaturationValue )	//過飽合
			{
				pMaskD[i] = PHASE_MASK_OVER_SATURATED;		//標記無效點
			}
			else if(abs(d1-d2)<LowContrastValue && abs(d3-d2)<LowContrastValue)	//對比太差
			{
				pMaskD[i] = PHASE_MASK_LOW_CONTRAST;		//標記無效點
			}
			else
			{ pMaskD[i] = PHASE_MASK_VALID; }
		}

		phase = atan2f(a, b);
		if( phase < 0 )
		{ phase = PERIOD_RAD+phase; }
		pPhaseD[i] = phase * PHASE_RAD2SHORT;
	}
#endif//_CUDA_TEXTURE_USED_
}
