//------------------------------------------------------------------------------//
__global__ void DoCudaSubtractBasePhasePlane_Kernel(short *pPhaseD, short *pBasePhaseD, const unsigned int DataSize)
{
	unsigned int i=0;
	int PhaseData=0;
//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)	
   for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i < DataSize; i += blockDim.x*gridDim.x) 
	{
		PhaseData = pPhaseD[i] - pBasePhaseD[i];
		if( PhaseData < 0 )
		{
		//	PhaseData = PHASE_MAX+PhaseData;
			pPhaseD[i] = PHASE_MAX + PhaseData;
		}
		else
		{
			pPhaseD[i] = (short)PhaseData;
		}
		
	}
}
//------------------------------------------------------------------------------//
__global__ void ExecCudaSubtractBasePhasePlane_Kernel(const short *pBasePhaseD, unsigned int ImageSize, short *pPhaseD)
{
	unsigned int i=0;
	int PhaseData=0;
	const int ShortPeriod = PHASE_PERIOD;
//	blockDim	區塊大小   (每個區塊包含的執行緒數目)
//  gridDim		網格大小   (網格包含的區塊數目)		
	for(i = (blockIdx.x*blockDim.x)+threadIdx.x ; i <ImageSize; i += blockDim.x*gridDim.x) 
	{
		PhaseData = pPhaseD[i] - pBasePhaseD[i];		
		if( PhaseData < 0 )
		{	pPhaseD[i] = ShortPeriod + PhaseData;	}
		else
		{	pPhaseD[i] = (short)PhaseData;	}		
	}
}
