}
//------------------------------------------------------------------------------//

//PhaseSmooth-----------------------------------------------------------------//
//相位資料
// -PI ~ +PI
//轉為0~2^15
//使用short資型態 
//short範圍 2^16

/*
#define PHASE_MAX			32767	//2^15
#define PHASE_RAD2SHORT		((double)PHASE_MAX/(double)(2.0*3.141592))
#define PHASE_SHORT2ONE		1.0/(double)PHASE_MAX*/
//------------------------------------------------------------------------------//
__global__ void DoCudaPhaseSmoothRowsKernel(short *pSrcD, unsigned char *pMaskD, float *pSinDestD, float *pCosDestD, unsigned char *pTempMaskBufferD, unsigned int DataW, unsigned int DataH, unsigned int pitch, int Kernel_Radius)
{
    __shared__ float s_SinData[ROWS_BLOCKDIM_Y][(ROWS_RESULT_STEPS + 2 * ROWS_HALO_STEPS) * ROWS_BLOCKDIM_X];
    __shared__ float s_CosData[ROWS_BLOCKDIM_Y][(ROWS_RESULT_STEPS + 2 * ROWS_HALO_STEPS) * ROWS_BLOCKDIM_X];
    __shared__ unsigned char s_MaskData[ROWS_BLOCKDIM_Y][(ROWS_RESULT_STEPS + 2 * ROWS_HALO_STEPS) * ROWS_BLOCKDIM_X];

    //Offset to the left halo edge
    const int baseX = (blockIdx.x * ROWS_RESULT_STEPS - ROWS_HALO_STEPS) * ROWS_BLOCKDIM_X + threadIdx.x;
    const int baseY = blockIdx.y * ROWS_BLOCKDIM_Y + threadIdx.y;
		
	int temp;
	
	if ( baseY >= DataH )
	{
		//超出邊界
	}
	else
	{
		int AddressPitch = 0;

		unsigned char MaskValue = 0;
		float TempF = 0.0f;
		float SinValue = 0.0f, CosValue = 0.0f;
		float SinLeftValue = 0.0f, SinRightValue = 0.0f;
		float CosLeftValue = 0.0f, CosRightValue = 0.0f;
		unsigned char LeftMaskValue = 0, RightMaskValue = 0;

		AddressPitch = baseY * pitch;
		//LeftValue
		TempF = pSrcD[ AddressPitch ] * PHASE_SHORT2ONE * PERIOD_RAD;
		SinLeftValue = sin(TempF);
		CosLeftValue = cos(TempF);
		MaskValue = pMaskD[ AddressPitch ];
//		LeftMaskValue = PHASE_MASK_VALID;
		if( MaskValue&PHASE_MASK_LOW_CONTRAST )			{ LeftMaskValue = PHASE_MASK_LOW_CONTRAST; }
		else if( MaskValue&PHASE_MASK_LOW_POTENTIAL )	{ LeftMaskValue = PHASE_MASK_LOW_POTENTIAL; }
		else if( MaskValue&PHASE_MASK_OVER_SATURATED )	{ LeftMaskValue = PHASE_MASK_OVER_SATURATED; }
		else { LeftMaskValue = PHASE_MASK_VALID; }
		
		AddressPitch = baseY * pitch + (DataW-1);
		//RightValue
		TempF = pSrcD[ AddressPitch ] * PHASE_SHORT2ONE * PERIOD_RAD;		 
		SinRightValue = sin(TempF);
		CosRightValue = cos(TempF);
		MaskValue = pMaskD[ AddressPitch ];
//		RightMaskValue = PHASE_MASK_VALID;
		if( MaskValue&PHASE_MASK_LOW_CONTRAST )			{ RightMaskValue = PHASE_MASK_LOW_CONTRAST; }
		else if( MaskValue&PHASE_MASK_LOW_POTENTIAL )	{ RightMaskValue = PHASE_MASK_LOW_POTENTIAL; }
		else if( MaskValue&PHASE_MASK_OVER_SATURATED )	{ RightMaskValue = PHASE_MASK_LOW_CONTRAST; }
		else { RightMaskValue = PHASE_MASK_VALID; }

		AddressPitch = baseY * pitch + baseX;
		pSrcD += AddressPitch;
		pMaskD += AddressPitch;
		pSinDestD += AddressPitch;
		pCosDestD += AddressPitch;		
		pTempMaskBufferD += AddressPitch;
		for(int i = 0 ; i < ROWS_HALO_STEPS + ROWS_RESULT_STEPS + ROWS_HALO_STEPS; i++)
		{
			temp = (i * ROWS_BLOCKDIM_X) + baseX ;
			if( temp < 0 )
			{
				s_SinData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = SinLeftValue;
				s_CosData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = CosLeftValue;
				s_MaskData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = LeftMaskValue;
			}
			else if( temp >= DataW )
			{
				s_SinData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = SinRightValue;
				s_CosData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = CosRightValue;
				s_MaskData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = RightMaskValue;
			}
			else
			{
				TempF = pSrcD[i * ROWS_BLOCKDIM_X] * PHASE_SHORT2ONE * PERIOD_RAD;
				SinValue = sin(TempF);
				CosValue = cos(TempF);
				s_SinData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = SinValue;
				s_CosData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = CosValue;

				MaskValue = pMaskD[i * ROWS_BLOCKDIM_X];
				if( MaskValue&PHASE_MASK_LOW_CONTRAST )
				{
					s_MaskData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = PHASE_MASK_LOW_CONTRAST;
				}
				else if( MaskValue&PHASE_MASK_LOW_POTENTIAL )
				{
					s_MaskData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = PHASE_MASK_LOW_POTENTIAL;
				}
				else if( MaskValue&PHASE_MASK_OVER_SATURATED )
				{
					s_MaskData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = PHASE_MASK_OVER_SATURATED;
				}
				else
				{
					s_MaskData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = PHASE_MASK_VALID;
				}
			}
		}
	}
    //Compute and store results
    __syncthreads();
	if ( baseY >= DataH )
	{
		//超出邊界
	}
	else
	{
		for(int i = ROWS_HALO_STEPS; i < ROWS_HALO_STEPS + ROWS_RESULT_STEPS; i++){
			float SinSum = 0.0f;
			float CosSum = 0.0f;
			unsigned char TempMask = 0;
			temp = (i * ROWS_BLOCKDIM_X) + baseX ;
			if( (temp >= 0) && (temp < (DataW ) ))
			{
				pTempMaskBufferD[i * ROWS_BLOCKDIM_X] = 0;
				for(int j = -Kernel_Radius; j <= Kernel_Radius; j++)
				{
					SinSum += s_SinData[threadIdx.y][threadIdx.x + i *  ROWS_BLOCKDIM_X + j];
					CosSum += s_CosData[threadIdx.y][threadIdx.x + i *  ROWS_BLOCKDIM_X + j];
					TempMask |= s_MaskData[threadIdx.y][threadIdx.x + i *  ROWS_BLOCKDIM_X + j];
				}
				pSinDestD[i * ROWS_BLOCKDIM_X] = SinSum;	
				pCosDestD[i * ROWS_BLOCKDIM_X] = CosSum;
				pTempMaskBufferD[i * ROWS_BLOCKDIM_X] = TempMask;
			}
		}
	}
}
//------------------------------------------------------------------------------//
//------------------------------------------------------------------------------//
__global__ void DoCudaPhaseSmoothColumnsKernel(float *pSinSrcD, float *pCosSrcD, unsigned char *pTempMaskBufferD, short *pDestD, unsigned char *pMaskD, unsigned int DataW, unsigned int DataH, unsigned int pitch, int Kernel_Radius)
{
    __shared__ float s_SinData[COLUMNS_BLOCKDIM_X][(COLUMNS_RESULT_STEPS + 2 * COLUMNS_HALO_STEPS) * COLUMNS_BLOCKDIM_Y + 1];
    __shared__ float s_CosData[COLUMNS_BLOCKDIM_X][(COLUMNS_RESULT_STEPS + 2 * COLUMNS_HALO_STEPS) * COLUMNS_BLOCKDIM_Y + 1];
    __shared__ unsigned char s_MaskData[COLUMNS_BLOCKDIM_X][(COLUMNS_RESULT_STEPS + 2 * COLUMNS_HALO_STEPS) * COLUMNS_BLOCKDIM_Y + 1];

    //Offset to the upper halo edge
    const int baseX = blockIdx.x * COLUMNS_BLOCKDIM_X + threadIdx.x;
    const int baseY = (blockIdx.y * COLUMNS_RESULT_STEPS - COLUMNS_HALO_STEPS) * COLUMNS_BLOCKDIM_Y + threadIdx.y;

	int temp;

	if( baseX >= DataW )
	{
		//超出邊界
	}
	else
	{
		float SinUpValue = 0.0f, SinDownValue = 0.0f;
		float CosUpValue = 0.0f, CosDownValue = 0.0f;
		unsigned char MaskUpValue = 0, MaskDownValue = 0;
		//UpValue
		SinUpValue = pSinSrcD[baseX];
		CosUpValue = pCosSrcD[baseX];
		MaskUpValue = pTempMaskBufferD[baseX];
		//DownValue
		SinDownValue = pSinSrcD[ (DataH-1)*pitch+baseX ];
		CosDownValue = pCosSrcD[ (DataH-1)*pitch+baseX ];
		MaskDownValue = pTempMaskBufferD[ (DataH-1)*pitch+baseX ];

		pSinSrcD += baseY * pitch + baseX;
		pCosSrcD += baseY * pitch + baseX;
		pDestD += baseY * pitch + baseX;
		pMaskD += baseY * pitch + baseX;
		pTempMaskBufferD += baseY * pitch + baseX;
		#pragma unroll
		for(int i = 0 ; i < COLUMNS_HALO_STEPS + COLUMNS_RESULT_STEPS + COLUMNS_HALO_STEPS; i++)
		{
			temp = (i * COLUMNS_BLOCKDIM_Y) + baseY ;
			if( (temp >= 0) && (temp < (DataH ) ))
			{
				s_SinData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = pSinSrcD[i * COLUMNS_BLOCKDIM_Y * pitch];
				s_CosData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = pCosSrcD[i * COLUMNS_BLOCKDIM_Y * pitch];
				s_MaskData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = pTempMaskBufferD[i * COLUMNS_BLOCKDIM_Y * pitch];
			}
			else if( temp < 0 )
			{
				s_SinData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = SinUpValue;
				s_CosData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = CosUpValue;
				s_MaskData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = MaskUpValue;
			}
			else if( temp >= DataH )
			{
				s_SinData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = SinDownValue;
				s_CosData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = CosDownValue;
				s_MaskData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = MaskDownValue;
			}
		}
	}
    //Compute and store results
    __syncthreads();
	if( baseX >= DataW )
	{
		//超出邊界
	}
	else
	{
		#pragma unroll
		for(int i = COLUMNS_HALO_STEPS; i < COLUMNS_HALO_STEPS + COLUMNS_RESULT_STEPS; i++){
			float SinSum = 0;
			float CosSum = 0;
			unsigned char TempMask = 0;
			float newarcTan = 0.0f;
			temp = (i * COLUMNS_BLOCKDIM_Y) + baseY ;
			if( (temp >= 0) && (temp < (DataH ) ))
			{
				#pragma unroll
				for(int j = -Kernel_Radius; j <= Kernel_Radius; j++)
				{
					SinSum += s_SinData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y + j];
					CosSum += s_CosData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y + j];
					TempMask |= s_MaskData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y + j];
				}

				newarcTan = atan2f(SinSum, CosSum);
				if( newarcTan < 0 )
				{ newarcTan = PERIOD_RAD+newarcTan; }
				newarcTan *= PHASE_RAD2SHORT;
				pDestD[i * COLUMNS_BLOCKDIM_Y * pitch] = newarcTan;

				if( TempMask & PHASE_MASK_VALID )//遮罩中有包含有效點
				{
					pMaskD[i * COLUMNS_BLOCKDIM_Y * pitch] = PHASE_MASK_VALID;	//替換成有效點
					//pMaskD[i * COLUMNS_BLOCKDIM_Y * pitch] |= PHASE_MASK_VALID;
					//pMaskD[i * COLUMNS_BLOCKDIM_Y * pitch] &= ~PHASE_MASK_LOW_CONTRAST;	//清除掉低對比標記
					//pMaskD[i * COLUMNS_BLOCKDIM_Y * pitch] &= ~PHASE_MASK_LOW_POTENTIAL;	//清除掉低對比標記					
					//pMaskD[i * COLUMNS_BLOCKDIM_Y * pitch] &= ~PHASE_MASK_OVER_SATURATED;	//清除掉過飽和標記
				}
			}
		}
	}
}
//------------------------------------------------------------------------------//
__global__ void DoCudaPhaseSmoothRowsTextureKernel(float *pSinDestD, float *pCosDestD, unsigned char *pTempMaskBufferD, unsigned int DataW, unsigned int DataH, unsigned int pitch, int Kernel_Radius)
{
#ifdef _CUDA_TEXTURE_USED_
    __shared__ float s_SinData[ROWS_BLOCKDIM_Y][(ROWS_RESULT_STEPS + 2 * ROWS_HALO_STEPS) * ROWS_BLOCKDIM_X];
    __shared__ float s_CosData[ROWS_BLOCKDIM_Y][(ROWS_RESULT_STEPS + 2 * ROWS_HALO_STEPS) * ROWS_BLOCKDIM_X];
    __shared__ unsigned char s_MaskData[ROWS_BLOCKDIM_Y][(ROWS_RESULT_STEPS + 2 * ROWS_HALO_STEPS) * ROWS_BLOCKDIM_X];

	#define TSrcPhase(k) tex1Dfetch(texRefPhaseSrcD, k)
	#define TSrcMask(k) tex1Dfetch(texRefPhaseMaskD, k)

    //Offset to the left halo edge
    const int baseX = (blockIdx.x * ROWS_RESULT_STEPS - ROWS_HALO_STEPS) * ROWS_BLOCKDIM_X + threadIdx.x;
    const int baseY = blockIdx.y * ROWS_BLOCKDIM_Y + threadIdx.y;
		
	int temp;
	int AddressPitch = 0;	

	float TempF = 0.0f;
	unsigned char MaskValue = 0;
	float SinValue = 0.0f, CosValue = 0.0f;
	float SinLeftValue = 0.0f, SinRightValue = 0.0f;
	float CosLeftValue = 0.0f, CosRightValue = 0.0f;
	unsigned char LeftMaskValue = 0, RightMaskValue = 0;

	if ( baseY >= DataH )
	{
		//超出邊界
	}
	else
	{
		AddressPitch = baseY*pitch;

		//LeftValue
		//TempF = pSrcD[ baseY * pitch ] * PHASE_SHORT2ONE * PERIOD_RAD;
		TempF = TSrcPhase(AddressPitch) * PHASE_SHORT2ONE * PERIOD_RAD;
		SinLeftValue = sin(TempF);
		CosLeftValue = cos(TempF);
		//MaskValue = pMaskD[baseY * pitch];
		MaskValue = TSrcMask(AddressPitch);
		if( MaskValue&PHASE_MASK_LOW_CONTRAST )			{ LeftMaskValue = PHASE_MASK_LOW_CONTRAST; }
		else if( MaskValue&PHASE_MASK_LOW_POTENTIAL )	{ LeftMaskValue = PHASE_MASK_LOW_POTENTIAL; }
		else if( MaskValue&PHASE_MASK_OVER_SATURATED )	{ LeftMaskValue = PHASE_MASK_OVER_SATURATED; }		
		else { LeftMaskValue = PHASE_MASK_VALID; }

		AddressPitch = baseY*pitch+(DataW-1);
		//RightValue
		//TempF = pSrcD[ baseY * pitch + (DataW-1) ];
		TempF = TSrcPhase(AddressPitch) * PHASE_SHORT2ONE * PERIOD_RAD;
		SinRightValue = sin(TempF);
		CosRightValue = cos(TempF);
		//MaskValue = pMaskD[baseY * pitch + (DataW-1)];
		MaskValue = TSrcMask(AddressPitch);
		if( MaskValue&PHASE_MASK_LOW_CONTRAST )			{ RightMaskValue = PHASE_MASK_LOW_CONTRAST; }
		else if( MaskValue&PHASE_MASK_LOW_POTENTIAL )	{ RightMaskValue = PHASE_MASK_LOW_POTENTIAL; }
		else if( MaskValue&PHASE_MASK_OVER_SATURATED )	{ RightMaskValue = PHASE_MASK_LOW_CONTRAST; }		
		else { RightMaskValue = PHASE_MASK_VALID; }

		AddressPitch = baseY * pitch + baseX;
		pSinDestD += AddressPitch;
		pCosDestD += AddressPitch;		
		pTempMaskBufferD += AddressPitch;
		#pragma unroll
		for(int i = 0 ; i < ROWS_HALO_STEPS + ROWS_RESULT_STEPS + ROWS_HALO_STEPS; i++)
		{
			temp = (i * ROWS_BLOCKDIM_X) + baseX ;
			if( temp < 0 )
			{
				s_SinData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = SinLeftValue;
				s_CosData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = CosLeftValue;
				s_MaskData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = LeftMaskValue;
			}
			else if( temp >= DataW )
			{
				s_SinData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = SinRightValue;
				s_CosData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = CosRightValue;
				s_MaskData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = RightMaskValue;
			}
			else
			{
				//TempF = pSrcD[i * ROWS_BLOCKDIM_X] * PHASE_SHORT2ONE * PERIOD_RAD;
				TempF = TSrcPhase(AddressPitch + i*ROWS_BLOCKDIM_X) * PHASE_SHORT2ONE * PERIOD_RAD;
				SinValue = sin(TempF);
				CosValue = cos(TempF);
				s_SinData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = SinValue;
				s_CosData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = CosValue;

				//MaskValue = pMaskD[i * ROWS_BLOCKDIM_X];
				MaskValue = TSrcMask(AddressPitch + i * ROWS_BLOCKDIM_X);				
				if( MaskValue&PHASE_MASK_LOW_CONTRAST )
				{
					s_MaskData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = PHASE_MASK_LOW_CONTRAST;
				}
				else if( MaskValue&PHASE_MASK_LOW_POTENTIAL )
				{
					s_MaskData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = PHASE_MASK_LOW_POTENTIAL;
				}
				else if( MaskValue&PHASE_MASK_OVER_SATURATED )
				{
					s_MaskData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = PHASE_MASK_OVER_SATURATED;
				}
				else
				{
					s_MaskData[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = PHASE_MASK_VALID;
				}

			}
		}
	}
    //Compute and store results
    __syncthreads();
	if ( baseY >= DataH )
	{
		//超出邊界
	}
	else
	{
		#pragma unroll
		for(int i = ROWS_HALO_STEPS; i < ROWS_HALO_STEPS + ROWS_RESULT_STEPS; i++){
			SinValue = 0.0f;
			CosValue = 0.0f;
			MaskValue = 0;
			temp = (i * ROWS_BLOCKDIM_X) + baseX ;
			if( temp < 0 )				{			}
			else if( temp >= DataW )	{			}
			else
			{
				#pragma unroll
				for(int j = -Kernel_Radius; j <= Kernel_Radius; j++)
				{
					SinValue += s_SinData[threadIdx.y][threadIdx.x + i *  ROWS_BLOCKDIM_X + j];
					CosValue += s_CosData[threadIdx.y][threadIdx.x + i *  ROWS_BLOCKDIM_X + j];
					MaskValue |= s_MaskData[threadIdx.y][threadIdx.x + i *  ROWS_BLOCKDIM_X + j];
				}
				pSinDestD[i * ROWS_BLOCKDIM_X] = SinValue;	
				pCosDestD[i * ROWS_BLOCKDIM_X] = CosValue;
				pTempMaskBufferD[i * ROWS_BLOCKDIM_X] = MaskValue;
			}
		}
	}
#endif//_CUDA_TEXTURE_USED_
}
//------------------------------------------------------------------------------//
__global__ void DoCudaPhaseSmoothColumnsTextureKernel(short *pDestD, unsigned char *pMaskD, unsigned int DataW, unsigned int DataH, unsigned int pitch, int Kernel_Radius)
{
#ifdef _CUDA_TEXTURE_USED_
    __shared__ float s_SinData[COLUMNS_BLOCKDIM_X][(COLUMNS_RESULT_STEPS + 2 * COLUMNS_HALO_STEPS) * COLUMNS_BLOCKDIM_Y + 1];
    __shared__ float s_CosData[COLUMNS_BLOCKDIM_X][(COLUMNS_RESULT_STEPS + 2 * COLUMNS_HALO_STEPS) * COLUMNS_BLOCKDIM_Y + 1];
    __shared__ unsigned char s_MaskData[COLUMNS_BLOCKDIM_X][(COLUMNS_RESULT_STEPS + 2 * COLUMNS_HALO_STEPS) * COLUMNS_BLOCKDIM_Y + 1];

    //Offset to the upper halo edge
    const unsigned int baseX = blockIdx.x * COLUMNS_BLOCKDIM_X + threadIdx.x;
    const unsigned int baseY = (blockIdx.y * COLUMNS_RESULT_STEPS - COLUMNS_HALO_STEPS) * COLUMNS_BLOCKDIM_Y + threadIdx.y;


	#define TSinSrc(k) tex1Dfetch(texRefSinSrcD, k)
	#define TCosSrc(k) tex1Dfetch(texRefCosSrcD, k)
	#define TTempMaskBuffer(k) tex1Dfetch(texRefTempMaskD, k)

	int temp;
	int AddressPitch = 0;	
	float SinUpValue = 0.0f, SinDownValue = 0.0f;
	float CosUpValue = 0.0f, CosDownValue = 0.0f;
	unsigned char MaskUpValue = 0, MaskDownValue = 0;

	if( baseX >= DataW )
	{
		//超出邊界
	}
	else
	{
		//UpValue
		SinUpValue = TSinSrc(baseX);
		CosUpValue = TCosSrc(baseX);
		MaskUpValue = TTempMaskBuffer(baseX);

		//DownValue
		AddressPitch = (DataH-1)*pitch+baseX;
		SinDownValue = TSinSrc(AddressPitch);
		CosDownValue = TCosSrc(AddressPitch);
		MaskDownValue = TTempMaskBuffer(AddressPitch);

		AddressPitch = baseY * pitch + baseX;
		//pSinSrcD += baseY * pitch + baseX;
		//pCosSrcD += baseY * pitch + baseX;
		//pTempMaskBufferD += baseY * pitch + baseX;
		pDestD += AddressPitch;
		pMaskD += AddressPitch;	
		#pragma unroll
		for(unsigned int i = 0 ; i < COLUMNS_HALO_STEPS + COLUMNS_RESULT_STEPS + COLUMNS_HALO_STEPS; i++)
		{
			temp = (i * COLUMNS_BLOCKDIM_Y) + baseY ;
			if( temp < 0 )
			{
				s_SinData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = SinUpValue;
				s_CosData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = CosUpValue;
				s_MaskData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = MaskUpValue;
			}
			else if( temp >= DataH )
			{
				s_SinData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = SinDownValue;
				s_CosData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = CosDownValue;
				s_MaskData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = MaskDownValue;
			}
			else
			{
				s_SinData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = TSinSrc( AddressPitch + i * COLUMNS_BLOCKDIM_Y * pitch );
				s_CosData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = TCosSrc( AddressPitch + i * COLUMNS_BLOCKDIM_Y * pitch );
				s_MaskData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = TTempMaskBuffer( AddressPitch + i * COLUMNS_BLOCKDIM_Y * pitch );
			}
		}
	}
    //Compute and store results
    __syncthreads();
	if( baseX >= DataW )
	{
		//超出邊界
	}
	else
	{
		float newarcTan = 0.0f;

		#pragma unroll
		for(unsigned int i = COLUMNS_HALO_STEPS; i < COLUMNS_HALO_STEPS + COLUMNS_RESULT_STEPS; i++){
/*			float SinSum = 0;
			float CosSum = 0;
			unsigned char TempMask = 0;*/

			SinUpValue = 0.0f;
			CosUpValue = 0.0f;
			MaskUpValue = 0;
//			newarcTan = 0.0f;
			temp = (i * COLUMNS_BLOCKDIM_Y) + baseY ;
			if( temp < 0 )				{  }
			else if( temp >= DataH )	{  }
			else//( (temp >= 0) && (temp < (DataH ) ))
			{
				#pragma unroll
				for(int j = -Kernel_Radius; j <= Kernel_Radius; j++)
				{
					SinUpValue += s_SinData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y + j];
					CosUpValue += s_CosData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y + j];
					MaskUpValue |= s_MaskData[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y + j];
				}

				newarcTan = atan2f(SinUpValue, CosUpValue);
				if( newarcTan < 0 )
				{ newarcTan += PERIOD_RAD; }
				//newarcTan *= PHASE_RAD2SHORT;
				pDestD[i * COLUMNS_BLOCKDIM_Y * pitch] = newarcTan * PHASE_RAD2SHORT;

				if( MaskUpValue & PHASE_MASK_VALID )//遮罩中有包含有效點
				{
					pMaskD[i * COLUMNS_BLOCKDIM_Y * pitch] = PHASE_MASK_VALID;	//替換成有效點
					//pMaskD[i * COLUMNS_BLOCKDIM_Y * pitch] |= PHASE_MASK_VALID;
					//pMaskD[i * COLUMNS_BLOCKDIM_Y * pitch] &= ~PHASE_MASK_LOW_CONTRAST;		//清除掉低對比標記
					//pMaskD[i * COLUMNS_BLOCKDIM_Y * pitch] &= ~PHASE_MASK_LOW_POTENTIAL;		//清除掉低對比標記					
					//pMaskD[i * COLUMNS_BLOCKDIM_Y * pitch] &= ~PHASE_MASK_OVER_SATURATED;	//清除掉過飽和標記
				}
			}
		}
	}
#endif//_CUDA_TEXTURE_USED_
}
