//------------------------------------------------------------------------------//
__global__ void DoCudaFFCProcessKernel(unsigned char *pSrc, unsigned char *pDest, float *pGain ,unsigned char *pBase,unsigned int ImageSize)
{
	unsigned int i=0;
    const int tid = threadIdx.x;
    const int bid = blockIdx.x;

	int TempD = 0;
	
    for(i = bid * 96 + tid; i < ImageSize; i += 768) 
	{
		TempD = pSrc[i] - pBase[i];
		TempD = TempD * pGain[i];
		if( TempD > 255 ) { TempD = 255; }
		if( TempD < 0 ) { TempD = 0; }
		pDest[i] = TempD;
	}
	
}
//------------------------------------------------------------------------------//
#define CLAMP_TO_EDGE 1
//------------------------------------------------------------------------------//
__global__ void DoCudaRecursiveGaussianKernel(unsigned char *pSrc, unsigned char *pDest,const unsigned int W, const unsigned int H,  float a0, float a1, float a2, float a3, float b1, float b2, float coefp, float coefn)
{
	unsigned int x = blockIdx.x*blockDim.x + threadIdx.x;
	if (x >= W) return;

    pSrc += x;    // advance pointers to correct column
    pDest += x;

    // forward pass
    float xp = 0.0f;  // previous input
    float yp = 0.0f;  // previous output
    float yb = 0.0f;  // previous output by 2

#if CLAMP_TO_EDGE
    xp = (*pSrc) / 255.0f;
	yb = coefp*xp; 
	yp = yb;
#endif

    for (int y = 0; y < H; y++) 
	{
        float xc = (*pSrc) / 255.0f;
        float yc = a0*xc + a1*xp - b1*yp - b2*yb;
		*pDest = yc * 255;
        pSrc += W; pDest += W;    // move to next row
        xp = xc; yb = yp; yp = yc; 
    }

	pSrc -= W;
    pDest -= W;


    // reverse pass
    // ensures response is symmetrical
    float xn = 0.0f;
    float xa = 0.0f;
    float yn = 0.0f;
    float ya = 0.0f;


#if CLAMP_TO_EDGE
    xn = xa = (*pSrc)/255.0f; 
	yn = coefn*xn; 
	ya = yn;
#endif
	float tempF = 0.0f;
    for (int y = H-1; y >= 0; y--) 
	{
		float xc = (*pSrc)/255.0f; 
        float yc = a2*xn + a3*xa - b1*yn - b2*ya;
        xa = xn; xn = xc; ya = yn; yn = yc;
		tempF = (*pDest)/255.0f;
		*pDest = (tempF + yc) * 255;
		pSrc -= W; pDest -= W;  // move to previous row
    }
	//__syncthreads();

}
//------------------------------------------------------------------------------//
__global__ void DoTransposeKernel(unsigned char *pDest, unsigned char *pSrc, unsigned int width, unsigned int height)
{
	//nThread=16
    __shared__ unsigned char block[16][16+1];
    
    // read the matrix tile into shared memory
    unsigned int xIndex = blockIdx.x * 16 + threadIdx.x;
    unsigned int yIndex = blockIdx.y * 16 + threadIdx.y;
    if((xIndex < width) && (yIndex < height))
    {
        unsigned int index_in = yIndex * width + xIndex;
        block[threadIdx.y][threadIdx.x] = pSrc[index_in];
    }

    __syncthreads();

    // write the transposed matrix tile to global memory
    xIndex = blockIdx.y * 16 + threadIdx.x;
    yIndex = blockIdx.x * 16 + threadIdx.y;
    if((xIndex < height) && (yIndex < width))
    {
        unsigned int index_out = yIndex * height + xIndex;
        pDest[index_out] = block[threadIdx.x][threadIdx.y];
    }
}
//------------------------------------------------------------------------------//
//AverageSmooth-----------------------------------------------------------------//
//------------------------------------------------------------------------------//
__global__ void DoCudaAverageSmoothRowsKernel(unsigned short *d_Dst, const unsigned char *d_Src,unsigned int imageW,unsigned int imageH,unsigned int pitch,int Kernel_Radius)
{
    __shared__ unsigned short s_Data[ROWS_BLOCKDIM_Y][(ROWS_RESULT_STEPS + 2 * ROWS_HALO_STEPS) * ROWS_BLOCKDIM_X];

    //Offset to the left halo edge
    const unsigned int baseX = (blockIdx.x * ROWS_RESULT_STEPS - ROWS_HALO_STEPS) * ROWS_BLOCKDIM_X + threadIdx.x;
    const unsigned int baseY = blockIdx.y * ROWS_BLOCKDIM_Y + threadIdx.y;
		
	unsigned int temp;
	
	if ( baseY >= imageH )
	{
		//超出邊界
	}
	else
	{
		unsigned char leftValue,rightValue;
		leftValue = d_Src[ baseY * pitch ];
		rightValue = d_Src[ baseY * pitch + (imageW-1) ];
		d_Src += baseY * pitch + baseX;
		d_Dst += baseY * pitch + baseX;
		#pragma unroll
		for(unsigned int i = 0 ; i < ROWS_HALO_STEPS + ROWS_RESULT_STEPS + ROWS_HALO_STEPS; i++)
		{
			temp = (i * ROWS_BLOCKDIM_X) + baseX ;
			if( (temp >= 0) && (temp < (imageW ) ))
			{
				 s_Data[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = d_Src[i * ROWS_BLOCKDIM_X];
			}
			else if( temp < 0 )
			{
				s_Data[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = leftValue;
			}
			else if( temp >= imageW )
			{
				s_Data[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = rightValue;
			}
		}
	}
    //Compute and store results
    __syncthreads();
	if ( baseY >= imageH )
	{
		//超出邊界
	}
	else
	{
		#pragma unroll
		for(unsigned int i = ROWS_HALO_STEPS; i < ROWS_HALO_STEPS + ROWS_RESULT_STEPS; i++){
			unsigned short sum = 0;
			temp = (i * ROWS_BLOCKDIM_X) + baseX ;
			if( (temp >= 0) && (temp < (imageW ) ))
			{
				#pragma unroll
				for(int j = -Kernel_Radius; j <= Kernel_Radius; j++)
					sum += s_Data[threadIdx.y][threadIdx.x + i *  ROWS_BLOCKDIM_X + j];
//					sum += Cuda2DFilterRow[Kernel_Radius - j] * s_Data[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X + j];
				d_Dst[i * ROWS_BLOCKDIM_X] = sum;
			}
		}
	}
}
