//------------------------------------------------------------------------------//
__global__ void DoCudaAverageSmoothColumnsKernel(unsigned char *d_Dst, const unsigned short *d_Src,unsigned int imageW,unsigned int imageH, unsigned int pitch,int Kernel_Radius,int SumNumber)
{
    __shared__ unsigned short s_Data[COLUMNS_BLOCKDIM_X][(COLUMNS_RESULT_STEPS + 2 * COLUMNS_HALO_STEPS) * COLUMNS_BLOCKDIM_Y + 1];

    //Offset to the upper halo edge
    const unsigned int baseX = blockIdx.x * COLUMNS_BLOCKDIM_X + threadIdx.x;
    const unsigned int baseY = (blockIdx.y * COLUMNS_RESULT_STEPS - COLUMNS_HALO_STEPS) * COLUMNS_BLOCKDIM_Y + threadIdx.y;

	unsigned int temp;

	if( baseX >= imageW )
	{
		//超出邊界
	}
	else
	{
		unsigned char UpValue,DownValue;
		UpValue = d_Src[ baseX ];
		DownValue = d_Src[ (imageH-1) * pitch + baseX ];
		d_Src += baseY * pitch + baseX;
		d_Dst += baseY * pitch + baseX;
		#pragma unroll
		for(unsigned int i = 0 ; i < COLUMNS_HALO_STEPS + COLUMNS_RESULT_STEPS + COLUMNS_HALO_STEPS; i++)
		{
			temp = (i * COLUMNS_BLOCKDIM_Y) + baseY ;
			if( (temp >= 0) && (temp < (imageH ) ))
			{
				s_Data[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = d_Src[i * COLUMNS_BLOCKDIM_Y * pitch];
			}
			else if( temp < 0 )
			{
				s_Data[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = UpValue;
			}
			else if( temp >= imageH )
			{
				s_Data[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = DownValue;
			}
		}
	}
    //Compute and store results
    __syncthreads();
	if( baseX >= imageW )
	{
		//超出邊界
	}
	else
	{
		#pragma unroll
		for(unsigned int i = COLUMNS_HALO_STEPS; i < COLUMNS_HALO_STEPS + COLUMNS_RESULT_STEPS; i++){
			unsigned short sum = 0;
			temp = (i * COLUMNS_BLOCKDIM_Y) + baseY ;
			if( (temp >= 0) && (temp < (imageH ) ))
			{
				#pragma unroll
				for(int j = -Kernel_Radius; j <= Kernel_Radius; j++)
					sum += s_Data[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y + j];
//					sum += Cuda2DFilterCol[Kernel_Radius - j] * s_Data[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y + j];
				d_Dst[i * COLUMNS_BLOCKDIM_Y * pitch] = sum / SumNumber ;
			}
		}
	}
}
