//2DFilter Convolution
__global__ void DoDataConvolutionRowsKernel(float *d_Dst,float *d_Src,unsigned int imageW,unsigned int imageH,unsigned int pitch,int Kernel_Radius)
{
	__shared__ float s_Data[ROWS_BLOCKDIM_Y][(ROWS_RESULT_STEPS + 2 * ROWS_HALO_STEPS) * ROWS_BLOCKDIM_X];

	//Offset to the left halo edge
	const int baseX = (blockIdx.x * ROWS_RESULT_STEPS - ROWS_HALO_STEPS) * ROWS_BLOCKDIM_X + threadIdx.x;
	const int baseY = blockIdx.y * ROWS_BLOCKDIM_Y + threadIdx.y;

	int temp;

	if ( baseY >= imageH )
	{
		//超出邊界
	}
	else
	{
		unsigned char leftValue,rightValue;
		leftValue = d_Src[ baseY * pitch ];
		rightValue = d_Src[ baseY * pitch + (imageW-1) ];
		d_Src += baseY * pitch + baseX;
		d_Dst += baseY * pitch + baseX;
	#pragma unroll
		for(int i = 0 ; i < ROWS_HALO_STEPS + ROWS_RESULT_STEPS + ROWS_HALO_STEPS; i++)
		{
			temp = (i * ROWS_BLOCKDIM_X) + baseX ;
			if( (temp >= 0) && (temp < (imageW ) ))
			{
				s_Data[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = d_Src[i * ROWS_BLOCKDIM_X];
			}
			else if( temp < 0 )
			{
				s_Data[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = leftValue;
			}
			else if( temp >= imageW )
			{
				s_Data[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X] = rightValue;
			}
		}
	}
	//Compute and store results
	__syncthreads();
	if ( baseY >= imageH )
	{
		//超出邊界
	}
	else
	{
		#pragma unroll
		for(int i = ROWS_HALO_STEPS; i < ROWS_HALO_STEPS + ROWS_RESULT_STEPS; i++){
			float sum = 0;
			temp = (i * ROWS_BLOCKDIM_X) + baseX ;
			if( (temp >= 0) && (temp < (imageW ) ))
			{
				#pragma unroll
				for(int j = -Kernel_Radius; j <= Kernel_Radius; j++)
					sum += Cuda2DFilterRow[Kernel_Radius - j] * s_Data[threadIdx.y][threadIdx.x + i * ROWS_BLOCKDIM_X + j];
				d_Dst[i * ROWS_BLOCKDIM_X] = sum;
			}
		}
	}
}
//------------------------------------------------------------------------------//
__global__ void DoDataConvolutionColumnsKernel(float *d_Dst,float *d_Src,unsigned int imageW,unsigned int imageH, unsigned int pitch,int Kernel_Radius)
{
	__shared__ float s_Data[COLUMNS_BLOCKDIM_X][(COLUMNS_RESULT_STEPS + 2 * COLUMNS_HALO_STEPS) * COLUMNS_BLOCKDIM_Y + 1];

	//Offset to the upper halo edge
	const int baseX = blockIdx.x * COLUMNS_BLOCKDIM_X + threadIdx.x;
	const int baseY = (blockIdx.y * COLUMNS_RESULT_STEPS - COLUMNS_HALO_STEPS) * COLUMNS_BLOCKDIM_Y + threadIdx.y;

	int temp;

	if( baseX >= imageW )
	{
		//超出邊界
	}
	else
	{
		unsigned char UpValue,DownValue;
		UpValue = d_Src[ baseX ];
		DownValue = d_Src[ (imageH-1) * pitch + baseX ];
		d_Src += baseY * pitch + baseX;
		d_Dst += baseY * pitch + baseX;
		#pragma unroll
		for(int i = 0 ; i < COLUMNS_HALO_STEPS + COLUMNS_RESULT_STEPS + COLUMNS_HALO_STEPS; i++)
		{
			temp = (i * COLUMNS_BLOCKDIM_Y) + baseY ;
			if( (temp >= 0) && (temp < (imageH ) ))
			{
				s_Data[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = d_Src[i * COLUMNS_BLOCKDIM_Y * pitch];
			}
			else if( temp < 0 )
			{
				s_Data[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = UpValue;
			}
			else if( temp >= imageH )
			{
				s_Data[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y] = DownValue;

			}
		}
	}
	//Compute and store results
	__syncthreads();
	if( baseX >= imageW )
	{
		//超出邊界
	}
	else
	{
		#pragma unroll
		for(int i = COLUMNS_HALO_STEPS; i < COLUMNS_HALO_STEPS + COLUMNS_RESULT_STEPS; i++){
			float sum = 0;
			temp = (i * COLUMNS_BLOCKDIM_Y) + baseY ;
			if( (temp >= 0) && (temp < (imageH ) ))
			{
				#pragma unroll
				for(int j = -Kernel_Radius; j <= Kernel_Radius; j++)
					sum += Cuda2DFilterCol[Kernel_Radius - j] * s_Data[threadIdx.x][threadIdx.y + i * COLUMNS_BLOCKDIM_Y + j];
				d_Dst[i * COLUMNS_BLOCKDIM_Y * pitch] = sum ;
			}
		}
	}
}
