extern "C" void DoCudaSolvePhaseAndBasePhase_Four(unsigned char *ImgD1, unsigned char *ImgD2, unsigned char *ImgD3, unsigned char *ImgD4, unsigned char *pMergeD, short *pPhaseD, unsigned char *pMaskD, short *pBasePhaseD, const int ImageSize, unsigned char SaturationValue, unsigned char LowContrastValue, unsigned char PotentialValue, bool IsUsePotentialValue, const bool IsUseTexture, const int ThreadNumber, const int BlockNumber)
{
	if( IsUseTexture )
	{
#ifdef _CUDA_TEXTURE_USED_
		cudaBindTexture(0, texRefImgD1, ImgD1, ImageSize*sizeof(unsigned char));
		cudaBindTexture(0, texRefImgD2, ImgD2, ImageSize*sizeof(unsigned char));
		cudaBindTexture(0, texRefImgD3, ImgD3, ImageSize*sizeof(unsigned char));
		cudaBindTexture(0, texRefImgD4, ImgD4, ImageSize*sizeof(unsigned char));
		
		if( pBasePhaseD == NULL ) 
		{
			DoCudaSolvePhaseTexture_Four_Kernel2<<<BlockNumber, ThreadNumber>>>(pMergeD, pPhaseD, pMaskD, ImageSize, SaturationValue, LowContrastValue, PotentialValue, IsUsePotentialValue);
		}
		else
		{
			cudaBindTexture(0, texRefPhaseBaseD, pBasePhaseD, ImageSize*sizeof(short));
			DoCudaSolvePhaseAndBasePhaseTexture_Four_Kernel2<<<BlockNumber, ThreadNumber>>>(pMergeD, pPhaseD, pMaskD, ImageSize, SaturationValue, LowContrastValue, PotentialValue, IsUsePotentialValue);
		}
#else
		if (pBasePhaseD == NULL)
		{
			DoCudaSolvePhase_Four_Kernel2 << <BlockNumber, ThreadNumber >> >(ImgD1, ImgD2, ImgD3, ImgD4, pMergeD, pPhaseD, pMaskD, ImageSize, SaturationValue, LowContrastValue, PotentialValue, IsUsePotentialValue);
		}
		else
		{
			DoCudaSolvePhaseAndBasePhase_Four_Kernel2 << <BlockNumber, ThreadNumber >> >(ImgD1, ImgD2, ImgD3, ImgD4, pMergeD, pPhaseD, pMaskD, pBasePhaseD, ImageSize, SaturationValue, LowContrastValue, PotentialValue, IsUsePotentialValue);
		}
#endif
			
	}
	else
	{
		if( pBasePhaseD == NULL ) 
		{ DoCudaSolvePhase_Four_Kernel2<<<BlockNumber, ThreadNumber>>>(ImgD1, ImgD2, ImgD3, ImgD4, pMergeD, pPhaseD, pMaskD, ImageSize, SaturationValue, LowContrastValue, PotentialValue, IsUsePotentialValue); }
		else	
		{ DoCudaSolvePhaseAndBasePhase_Four_Kernel2<<<BlockNumber, ThreadNumber>>>(ImgD1, ImgD2, ImgD3, ImgD4, pMergeD, pPhaseD, pMaskD, pBasePhaseD, ImageSize, SaturationValue, LowContrastValue, PotentialValue, IsUsePotentialValue); }
	
	}
}
//------------------------------------------------------------------------------//
extern "C" void DoCudaSolveMultiPhase(int P1, int P2, short *pPhaseData1, unsigned char *pMaskMap1, short *pPhaseData2, unsigned char *pMaskMap2, int W, int H, const bool IsUseTexture, const int ThreadNumber, const int BlockNumber )
{	
	int ImageSize = W*H;
	double TempRatio1 = P2/abs((P2-P1));
	double TempRatio2 = P1/abs((P2-P1));
	double TempRatio = 1;		
	bool UsePhase1 = true;
	if( UsePhase1 == true ) 
	{ TempRatio = TempRatio2; }
	else
	{ TempRatio = TempRatio1; }

	TempRatio = 6;

	
	DoCudaSolveMultiPhase_Kernel2<<<BlockNumber, ThreadNumber>>>(TempRatio, pPhaseData1, pMaskMap1, pPhaseData2, pMaskMap2, ImageSize);	//計算結果回存到Phase1, Mask1
	
	DoCudaSolveMultiPhase_Smooth_Kernel2<<<BlockNumber, ThreadNumber>>>(pPhaseData1, pMaskMap1, pPhaseData2, pMaskMap2, ImageSize, W, H);	//phase1 Smooth 到phase2
	DoCudaSolveMultiPhase_Smooth_Kernel2<<<BlockNumber, ThreadNumber>>>(pPhaseData2, pMaskMap2, pPhaseData1, pMaskMap1, ImageSize, W, H);	//phase2 再Smooth 到phase1
}
