//------------------------------------------------------------------------------//
extern "C"
void ExecCudaMedianFilter_Joe(unsigned int ImageW, unsigned int ImageH, unsigned int ImageStep, const float *pSpace, const unsigned char *pMask, int KerSize, int UseSize, float *pDst, const bool IsUseTexture, const int ThreadNumber, const int BlockNumber) {
	int kSize = KerSize;
	if (kSize < 3) { kSize = 3; }
	if (kSize > 11) { kSize = 11; }
	switch (kSize)
	{
	case 3:
	case 4:
		medianFilter_3 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH);
		break;
	default:
	case 5:
	case 6:
		medianFilter_5 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH);
		break;
	case 7:
	case 8:
		medianFilter_7 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH);
		break;
	case 9:
	case 10:
		medianFilter_9 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH);
		break;
	case 11:
		medianFilter_11 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH);
		break;
	}
}
//------------------------------------------------------------------------------//
extern "C"
void ExecCudaSpaceFilter_Joe(unsigned int ImageW, unsigned int ImageH, unsigned int ImageStep, float *pSpace, const unsigned char *pMask, int Mode, int KerSize, int UseSize, float *pDst, const bool IsUseTexture, const int ThreadNumber, const int BlockNumber) {	
	bool LTReady = false;
	if (Mode != CAST_SPACE_FILTER_MODE_DEFAULT) {
		LTReady = BuildGaussianTable_Spatial(max(3, KerSize));
		LTReady &= BuildGaussianTable_Value(min(max(1, UseSize), 200));
	}

	switch (Mode)
	{
	default:
	case CAST_SPACE_FILTER_MODE_DEFAULT: {
		ExecCudaMedianFilter_Joe(ImageW, ImageH, ImageStep, pSpace, pMask, KerSize, UseSize, pDst, IsUseTexture, ThreadNumber, BlockNumber);
		break;
	}
	case CAST_SPACE_FILTER_MODE_SPOT: {
		//medianFilter_UseSize1_3 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH, false);
		medianFilter_3 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH);
		cudaMemcpy(pSpace, pDst, ImageStep * ImageH * sizeof(float), cudaMemcpyKind::cudaMemcpyDeviceToDevice);
		medianFilter_UseSize1_7 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH, true);
		cudaMemcpy(pSpace, pDst, ImageStep * ImageH * sizeof(float), cudaMemcpyKind::cudaMemcpyDeviceToDevice);
		medianFilter_3 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, ImageW, ImageH);
		cudaMemcpy(pSpace, pDst, ImageStep * ImageH * sizeof(float), cudaMemcpyKind::cudaMemcpyDeviceToDevice);
		if (LTReady) { edgePreserveFilter << < BlockNumber, ThreadNumber >> > (pSpace, pDst, KerSize, ImageW, ImageH); }
		else { averageFilter << < BlockNumber, ThreadNumber >> > (pSpace, pDst, 3, ImageW, ImageH); }
		break;
	}
	case CAST_SPACE_FILTER_MODE_SMALL: {
		//medianFilter_UseSize1_5 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH, false);
		medianFilter_5 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH);
		cudaMemcpy(pSpace, pDst, ImageStep * ImageH * sizeof(float), cudaMemcpyKind::cudaMemcpyDeviceToDevice);
		medianFilter_UseSize1_13 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH, true);
		cudaMemcpy(pSpace, pDst, ImageStep * ImageH * sizeof(float), cudaMemcpyKind::cudaMemcpyDeviceToDevice);
		medianFilter_5 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, ImageW, ImageH);
		cudaMemcpy(pSpace, pDst, ImageStep * ImageH * sizeof(float), cudaMemcpyKind::cudaMemcpyDeviceToDevice);
		if (LTReady) { edgePreserveFilter << < BlockNumber, ThreadNumber >> > (pSpace, pDst, KerSize, ImageW, ImageH); }
		else { averageFilter << < BlockNumber, ThreadNumber >> > (pSpace, pDst, 3, ImageW, ImageH); }
		break;
	}
	case CAST_SPACE_FILTER_MODE_MEDIUM: {
		medianFilter_UseSize1_7 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH, false);
		//medianFilter_7 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH);
		cudaMemcpy(pSpace, pDst, ImageStep * ImageH * sizeof(float), cudaMemcpyKind::cudaMemcpyDeviceToDevice);
		medianFilter_UseSize1_23 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH, true);
		cudaMemcpy(pSpace, pDst, ImageStep * ImageH * sizeof(float), cudaMemcpyKind::cudaMemcpyDeviceToDevice);
		medianFilter_5 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, ImageW, ImageH);
		cudaMemcpy(pSpace, pDst, ImageStep * ImageH * sizeof(float), cudaMemcpyKind::cudaMemcpyDeviceToDevice);
		if (LTReady) { edgePreserveFilter << < BlockNumber, ThreadNumber >> > (pSpace, pDst, KerSize, ImageW, ImageH); }
		else { averageFilter << < BlockNumber, ThreadNumber >> > (pSpace, pDst, 3, ImageW, ImageH); }
		break;
	}
	case CAST_SPACE_FILTER_MODE_LARGE: {
		//medianFilter_UseSize1_9 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH, false);
		medianFilter_7 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH);
		cudaMemcpy(pSpace, pDst, ImageStep * ImageH * sizeof(float), cudaMemcpyKind::cudaMemcpyDeviceToDevice);
		medianFilter_UseSize1_33 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, pMask, ImageW, ImageH, true);
		cudaMemcpy(pSpace, pDst, ImageStep * ImageH * sizeof(float), cudaMemcpyKind::cudaMemcpyDeviceToDevice);
		medianFilter_7 << < BlockNumber, ThreadNumber >> > (pSpace, pDst, ImageW, ImageH);
		cudaMemcpy(pSpace, pDst, ImageStep * ImageH * sizeof(float), cudaMemcpyKind::cudaMemcpyDeviceToDevice);
		if (LTReady) { edgePreserveFilter << < BlockNumber, ThreadNumber >> > (pSpace, pDst, KerSize, ImageW, ImageH); }
		else { averageFilter << < BlockNumber, ThreadNumber >> > (pSpace, pDst, 5, ImageW, ImageH); }
		break;
	}
	}
}
