extern "C" 
void ExecCudaSolve2PhasePeriod(double PA, const short *pPhaseDA, const unsigned char *pMaskDA, double PB, const short *pPhaseDB, const unsigned char *pMaskDB, const short *pBasePhaseD, unsigned char *pMaskD, short *pPhaseD, unsigned int ImageSize, int  CombineMode, const bool IsUseTexture, const int ThreadNumber, const int BlockNumber)
{
	if( IsUseTexture )
	{
