		cudaBindTexture(0, texRefImgD1, ImgD1, ImageSize*sizeof(unsigned char));
		cudaBindTexture(0, texRefImgD2, ImgD2, ImageSize*sizeof(unsigned char));
		cudaBindTexture(0, texRefImgD3, ImgD3, ImageSize*sizeof(unsigned char));
		cudaBindTexture(0, texRefImgD4, ImgD4, ImageSize*sizeof(unsigned char));
		DoCudaSolvePhaseTexture_Four_Kernel<<<BlockNumber, ThreadNumber>>>(pMergeD, pPhaseD, pMaskD, ImageSize, SaturationValue, LowContrastValue, PotentialValue, IsUsePotentialValue);
#else
		ExecCudaSolve2PhasePeriod_Kernel << <BlockNumber, ThreadNumber >> >(PA, pPhaseDA, pMaskDA, PB, pPhaseDB, pMaskDB, pBasePhaseD, pMaskD, pPhaseD, ImageSize, CombineMode);
#endif//_CUDA_TEXTURE_USED_
	}
	else
