//PhaseSmooth-----------------------------------------------------------------//
extern "C" void DoCudaPhaseSmoothRows(short *pSrcD, unsigned char *pMaskD, float *pSinDestD, float *pCosDestD, unsigned char *pTempMaskBufferD, int DataW,int DataH, int DataSmoothMask, const bool IsUseTexture)
{
	int Kernel_Radius = (DataSmoothMask - 1) / 2;

	int BlockW = 0, BlockH = 0;
	BlockW = iDivUp(DataW , (ROWS_RESULT_STEPS * ROWS_BLOCKDIM_X));
	BlockH = iDivUp(DataH , ROWS_BLOCKDIM_Y);
 
	dim3 blocks(BlockW, BlockH);
    dim3 threads(ROWS_BLOCKDIM_X, ROWS_BLOCKDIM_Y);

	if( IsUseTexture )
	{
#ifdef _CUDA_TEXTURE_USED_
		cudaBindTexture(0, texRefPhaseSrcD, pSrcD, DataW*DataH*sizeof(short));
		cudaBindTexture(0, texRefPhaseMaskD, pMaskD, DataW*DataH*sizeof(unsigned char));

		DoCudaPhaseSmoothRowsTextureKernel<<<blocks, threads>>>(pSinDestD, pCosDestD, pTempMaskBufferD, DataW, DataH, DataW, Kernel_Radius);
#else
		DoCudaPhaseSmoothRowsKernel << <blocks, threads >> >(pSrcD, pMaskD, pSinDestD, pCosDestD, pTempMaskBufferD, DataW, DataH, DataW, Kernel_Radius);
#endif//_CUDA_TEXTURE_USED_
	}
	else
	{
		DoCudaPhaseSmoothRowsKernel<<<blocks, threads>>>(pSrcD, pMaskD, pSinDestD, pCosDestD, pTempMaskBufferD, DataW, DataH, DataW, Kernel_Radius);
	}
}
