extern "C" void DoCudaPhaseSmoothColumns(float *pSinSrcD, float *pCosSrcD, unsigned char *pTempMaskBufferD, short *pDestD, unsigned char *pMaskD, int DataW, int DataH, int DataSmoothMask, const bool IsUseTexture)
{
	int Kernel_Radius = (DataSmoothMask - 1) / 2;

	int BlockW = 0, BlockH = 0;
	BlockW = iDivUp(DataW , COLUMNS_BLOCKDIM_X);
	BlockH = iDivUp(DataH , (COLUMNS_RESULT_STEPS * COLUMNS_BLOCKDIM_Y));

	dim3 blocks( BlockW , BlockH);
    dim3 threads(COLUMNS_BLOCKDIM_X, COLUMNS_BLOCKDIM_Y);
	
	if( IsUseTexture )
	{
#ifdef _CUDA_TEXTURE_USED_
		cudaBindTexture(0, texRefSinSrcD, pSinSrcD, DataW*DataH*sizeof(float));
		cudaBindTexture(0, texRefCosSrcD, pCosSrcD, DataW*DataH*sizeof(float));
		cudaBindTexture(0, texRefTempMaskD, pTempMaskBufferD, DataW*DataH*sizeof(unsigned char));

		DoCudaPhaseSmoothColumnsTextureKernel<<<blocks, threads>>>(pDestD, pMaskD, DataW, DataH, DataW, Kernel_Radius);
#else
		DoCudaPhaseSmoothColumnsKernel << <blocks, threads >> >(pSinSrcD, pCosSrcD, pTempMaskBufferD, pDestD, pMaskD, DataW, DataH, DataW, Kernel_Radius);
#endif//_CUDA_TEXTURE_USED_
	}
	else
	{
		DoCudaPhaseSmoothColumnsKernel<<<blocks, threads>>>(pSinSrcD, pCosSrcD, pTempMaskBufferD, pDestD, pMaskD, DataW, DataH, DataW, Kernel_Radius);
	}
    
}
