void DoCudaFFCProcess(unsigned char *pSrc, unsigned char *pDest, float *pGain ,unsigned char *pBase,const int ImageW, const int ImageH)
{
	int ThreadNumber = 96;
	int ImageSize = ImageW*ImageH;
	int BlockNumber = 8;

	dim3   DimGrid( BlockNumber );    
	dim3   DimBlock( ThreadNumber );   

	DoCudaFFCProcessKernel<<<DimGrid, DimBlock, 0>>>(pSrc,pDest, pGain ,pBase,ImageSize);
}
