extern "C" 
void DoTranspose(unsigned char *pSrc, unsigned char *pDest, int width, int height)
{
	int nThread = 16;
    dim3 grid(iDivUp(width, nThread), iDivUp(height, nThread), 1);
    dim3 threads(nThread, nThread, 1);
    DoTransposeKernel<<< grid, threads >>>(pDest, pSrc, width, height);
}
