extern "C" void DoCudaAverageSmoothRows(unsigned int ImageW,unsigned int ImageH, unsigned int ImageStep, const unsigned char *d_Src, unsigned short *d_Dst, int KernelSize)
{
	int Kernel_Radius = (KernelSize - 1) / 2;

	int BlockW,BlockH;
	BlockW = iDivUp(ImageW, (ROWS_RESULT_STEPS * ROWS_BLOCKDIM_X));
	BlockH = iDivUp(ImageH, ROWS_BLOCKDIM_Y);
 
	dim3 blocks(BlockW,BlockH);
    dim3 threads(ROWS_BLOCKDIM_X, ROWS_BLOCKDIM_Y);

    DoCudaAverageSmoothRowsKernel<<<blocks, threads>>>(d_Dst, d_Src, ImageW, ImageH, ImageStep, Kernel_Radius);
}
//------------------------------------------------------------------------------//
extern "C" void DoCudaAverageSmoothColumns(unsigned int ImageW,unsigned int ImageH, unsigned int ImageStep, const unsigned short *d_Src, unsigned char *d_Dst, int KernelSize)
{
	int Kernel_Radius = (KernelSize - 1) / 2;

	int BlockW,BlockH;
	BlockW = iDivUp(ImageW , COLUMNS_BLOCKDIM_X);
	BlockH = iDivUp(ImageH , (COLUMNS_RESULT_STEPS * COLUMNS_BLOCKDIM_Y));

	dim3 blocks( BlockW , BlockH);
    dim3 threads(COLUMNS_BLOCKDIM_X, COLUMNS_BLOCKDIM_Y);
	
	int SumNumber = KernelSize*KernelSize;    
	DoCudaAverageSmoothColumnsKernel<<<blocks, threads>>>(d_Dst, d_Src, ImageW, ImageH, ImageStep, Kernel_Radius,SumNumber);
}
